import{r as e}from"./react-SIfiwpqq.js";var t=e({blog:()=>u,default:()=>f,learn:()=>i,meditations:()=>a,muscles:()=>d,music:()=>o,poses:()=>n,pranayama:()=>l,progressions:()=>s,rewards:()=>c,routines:()=>r}),n=JSON.parse(`{"big-toe":{"name":"Big Toe Pose","goodFor":"Hamstring stretch with active hand-to-foot connection.","instructions":"Stand tall with feet parallel and legs straight. Fold forward from the hips and hook your index and middle fingers around the big toes. Press the chest forward so the spine stays long. Relax the neck and gaze softly forward. To exit, release the toes and rise up slowly.","breathCue":"Inhale to lift chest, exhale to fold deeper","modifications":["Use a strap around the feet","Bend the knees slightly","Hold the shins instead of the toes","Use a wall for support"],"props":["strap"],"muscleCue":"Notice the stretch in your hamstrings. Notice the contraction in your quadriceps.","drishti":"Nasagrai or Nasagre (nose)","muscles":["hamstrings","calves","forearms"]},"gorilla":{"name":"Gorilla Pose","goodFor":"Deep hamstring stretch and wrist extension.","instructions":"From a standing forward fold, bend the knees slightly and slide each palm under the foot, fingers pointing forward so the toes rest on the wrists. Straighten the legs and let the elbows bend out wide. Relax the head and neck and let the back fold down over the legs. Breathe slowly and let gravity deepen the stretch. To exit, slide the hands out and rise slowly.","breathCue":"Exhale as you fold and let the head hang","modifications":["Bend the knees slightly","Hold the backs of the ankles instead","Keep fingertips under the heels"],"props":[],"muscleCue":"Notice the stretch in your hamstrings. Notice the contraction in the front of your shoulders and your triceps.","drishti":"Nasagrai or Nasagre (nose)","modificationNote":"Hands are tucked under the feet instead of resting on the floor beside them.","muscles":["hamstrings","wrists","shoulders"]},"bird-of-paradise":{"name":"Bird of Paradise","goodFor":"Builds balance and hamstring flexibility with a straight-leg lift.","instructions":"Stand tall and shift your weight onto one foot. Hug the other knee in, then extend that leg straight up in front of you. Keep the standing knee soft and root down through the foot. Let the arms stay free, with one hand drifting lightly toward the lifted leg. Keep your gaze on a steady point and breathe smoothly. To exit, slowly lower the leg back down.","breathCue":"Exhale to settle and steady your balance.","modifications":["Lift the leg a little lower","Keep a hand on a wall for balance","Bend the lifted knee slightly","Shorten the hold and switch sides"],"props":["wall"],"muscleCue":"Notice the stretch in your hip flexors. Notice the contraction in your quadriceps and your outer hips.","drishti":"Forward, at a steady point","modificationNote":"Same standing leg lift as Bird of Paradise but performed without the hands binding behind the back.","muscles":["hamstrings","shoulders","standing-leg glutes","core"]},"revolved-bird-of-paradise":{"name":"Revolved Bird of Paradise Pose","goodFor":"Strengthens the standing leg and core while improving balance and spinal rotation.","instructions":"Stand tall and shift your weight onto one foot. Extend the other leg straight out to the side at about hip height. Clasp your hands together in front of your belly. On an exhale, rotate your chest and turn your gaze to the side. Keep the standing knee soft and hips level as you hold. To exit, lower the leg with control and release the hands.","breathCue":"Inhale to lengthen, exhale to deepen the twist","modifications":["Bend the lifted knee and hold it closer in","Rest a hand on a wall or chair for balance","Keep hands on hips instead of clasping"],"props":[],"muscleCue":"Notice the stretch in your chest and the front of your shoulders. Notice the contraction in your quadriceps and your outer hips.","drishti":"Parshva Drishti (to the side)","modificationNote":"A no-bind, twisted take on bird of paradise: the hands clasp in front of the body instead of wrapping around the lifted leg.","muscles":["core","legs","postural muscles"]},"upward-salute":{"name":"Upward Salute","goodFor":"Length through the side body; energizing start.","instructions":"From mountain pose, inhale and sweep both arms up overhead about shoulder-width apart. Keep the elbows long and straight without locking them. Stay tall through the spine and keep the neck neutral, gazing forward. Draw the navel in and relax the shoulders away from the ears. Root down through both feet as you reach up. Exhale to lower the arms back to your sides.","breathCue":"Inhale to reach up; keep shoulders soft.","modifications":["Back against wall","Tuck chin slightly"],"alignmentCues":["Biceps beside the ears","Tailbone heavy"],"props":["Wall"],"drishti":"Forward","modificationNote":"arms shoulder width apart","muscles":["shoulders","core","postural back"]},"chair":{"name":"Chair Pose","goodFor":"Leg strength, ankle stability, and heat-building.","instructions":"Stand with feet together or hip-width. Bend the knees deeply and sit the hips back and down into a low squat, keeping weight in the heels. Reach both arms up and slightly forward, palms facing each other. Keep the chest lifted and the spine long. Breathe steadily. To exit, press into the feet and stand up.","breathCue":"Steady breath in the belly and ribs.","modifications":["Hands on thighs","Bend knees less","Sit on a chair","Back to a wall"],"deepen":["Sit lower only while knees track toes"],"commonMistakes":["Knees past toes unchecked","Chest collapsing"],"props":["Chair"],"muscleCue":"Notice the stretch in your calves. Notice the contraction in your quadriceps.","drishti":"Angushtamadhye or Angushta Ma Dyai (thumbs)","modificationNote":"deep low squat with arms reaching up and forward, palms apart","muscles":["quads","glutes","core","shoulders"]},"high-lunge":{"name":"High Lunge","goodFor":"Leg strength, hip flexor stretch, and balance.","instructions":"Step one foot forward into a long stance and keep the whole back foot on the floor. Back leg stays strong and straight with the heel grounded. Front knee bends over the ankle as the hips square forward. Arms reach overhead with the palms pressing together and shoulders soft. Balance the weight evenly between both feet and lengthen the spine. To exit, lower the hands and step the back foot forward.","breathCue":"Inhale lift; exhale root through the feet.","modifications":["Shorten the stance","Bend front knee more","Step back foot closer","Hands on hips instead of overhead"],"commonMistakes":["Front knee collapsing inward"],"props":[],"muscleCue":"Notice the stretch in your hip flexors and your calves. Notice the contraction in your quadriceps.","drishti":"forward","modificationNote":"Back heel stays grounded on the floor instead of lifting onto the toes","muscles":["quads","hip flexors","glutes","core"]},"low-lunge":{"name":"Low Lunge","goodFor":"Deep hip-flexor opening and gentle backbend preparation.","instructions":"From Down Dog or standing, step one foot forward between the hands. Lower the back knee to the floor and let the top of the back foot rest down. Keep the front knee stacked over the ankle and square the hips forward. Inhale and sweep both arms straight overhead, keeping the shoulders relaxed. Lift the chest into a light backbend and breathe here. To exit, plant the hands and step back to Down Dog.","breathCue":"Exhale to ease hips forward gently.","modifications":["Keep hands on the front thigh instead of reaching up","Pad the back knee with a blanket","Stay more upright with a smaller backbend"],"deepen":["Reach arms up when stable"],"avoidIf":["Knee cushioning needed — always pad"],"props":["blanket under back knee"],"muscleCue":"Notice the stretch in your shins and the tops of your feet. Notice the contraction in your quadriceps.","drishti":"forward, or up toward the hands","modificationNote":"back knee rests on the floor with both arms reaching straight overhead in a gentle backbend","muscles":["hip flexors","quads","glutes","psoas"]},"eagle":{"name":"Eagle Pose","goodFor":"Balance, leg strength, and steady shoulders.","instructions":"Stand on one leg and keep the knee soft. Cross the other thigh over and hook the foot behind the calf. Raise both arms in front with elbows bent and hands open. Keep the hips square and the spine tall. Gaze forward and breathe steadily. To exit, release the foot and stand tall.","breathCue":"Steady breath through the nose.","modifications":["Keep the toes on the floor instead of hooking","Use a wall for balance","Lower the arms if the shoulders tire","Bend the standing knee more"],"props":["wall"],"muscleCue":"Notice the stretch in your outer hips and the back of your shoulders.","drishti":"forward","modificationNote":"arms raised in front with open hands instead of the wrapped eagle arms, shallower stance","muscles":["quads","glutes","shoulders","ankles"]},"standing-foot-behind-the-head":{"name":"Standing Foot Behind the Head Pose","goodFor":"Builds one-legged balance, hip flexibility, and core strength.","instructions":"Stand tall and shift your weight onto one leg. Lift the other leg and hold the ankle with both hands. Carefully draw the foot up and behind the head, letting the leg rest over the shoulder. Keep the standing leg engaged and your gaze on a steady point. To exit, support the leg with both hands and lower it slowly.","breathCue":"Exhale as you lift the foot, then breathe steadily while balancing.","modifications":["Practice foot-behind-head while seated first","Stand near a wall for balance","Hold the ankle without taking the foot behind the head"],"props":["wall"],"muscleCue":"Notice the stretch in your quadriceps and your hip flexors. Notice the contraction in your glutes and your outer hips.","drishti":"forward","modificationNote":"Standing version of foot-behind-the-head, balancing on one leg instead of sitting.","muscles":["core","legs","postural muscles"]},"standing-foot-to-head":{"name":"Standing Foot to Head Pose","goodFor":"Builds single-leg balance, hamstring flexibility, and steady focus.","instructions":"Stand tall on one leg and root down through the foot. Lift the other leg straight up in front of you toward the side of your head. Reach the same-side arm up and take hold of the foot. Keep the lifted leg as straight as you can while the free arm reaches out for balance. Keep the hips level and the standing leg firm as you breathe. To exit, release the foot and lower the leg with control.","breathCue":"Inhale to lift, exhale to settle and hold","modifications":["Loop a strap around the foot","Keep the leg lower and hold the knee","Stand near a wall for support"],"props":["yoga strap","wall"],"muscleCue":"Notice the stretch in your hamstrings. Notice the contraction in your outer hips.","drishti":"forward, eyes soft","modificationNote":"The leg stays straight up beside the ear with one hand holding the foot, rather than placing the foot behind the head.","muscles":["standing leg glutes and quads","core","hamstrings","shoulders and arms","ankles"]},"standing-foot-behind-the-head-forward-bend":{"name":"Standing Foot Behind the Head Forward Bend Pose","goodFor":"Builds mobility, strength, and awareness for Standing Foot Behind the Head Forward Bend Pose.","instructions":"From foot-behind-the-head standing prep, hinge forward carefully with support. Soften the standing knee. Keep the breath smooth. To exit, lift the torso and release the bound foot.","muscles":["hamstrings","calves","spinal erectors"]},"half-standing-forward-bend":{"name":"Half Standing Forward Bend Pose","goodFor":"Stretches the hamstrings and lengthens the whole back body.","instructions":"Stand with feet about hip width apart. Hinge forward from the hips halfway, keeping the back long and flat. Let the arms hang and rest your fingertips on the floor in front of your feet. Keep the neck in line with the spine and gaze softly down. Press the heels down and lift the kneecaps as you hold. Rise back up on an inhale.","breathCue":"Breathe evenly through nose, inhale to lift, exhale to fold","modifications":["Hands on the shins","Blocks under the hands","Feet wider for balance","Soft bend in the knees"],"alignmentCues":["Fingertips under shoulders","Lengthen crown forward"],"props":["Floor"],"muscleCue":"Notice the stretch in your hamstrings. Notice the contraction in your quadriceps.","drishti":"toward the floor","modificationNote":"Fingertips rest on the floor instead of the shins or blocks.","muscles":["hamstrings","calves","spinal erectors"]},"standing-forward-bend":{"name":"Standing Forward Bend Pose","goodFor":"Great for stretching tight hamstrings, calves, and the whole back line of the body.","instructions":"From standing, hinge at the hips and fold the torso over the legs. Soften the knees as much as you need so the spine can lengthen. Let the head hang; hold elbows, shins, or the floor. Shift weight slightly into the balls of the feet. Breathe into the back body. To exit, bend the knees, engage the belly, and roll or rise with a long spine.","breathCue":"Exhale to fold; inhale to lengthen the spine slightly.","modifications":["Use blocks under hands","Feet slightly apart for balance","Keep knees slightly bent","Hands on blocks or floor"],"deepen":["Straighten legs only if the spine stays long"],"avoidIf":["Acute low-back disc flare (keep knees bent)"],"commonMistakes":["Rounding hard from the low back","Locking knees"],"alignmentCues":["Hinge from the hips","Let the head hang heavy"],"props":["Blocks"],"muscleCue":"Notice the stretch in your hamstrings. Notice the contraction in the front of your shoulders and your triceps.","drishti":"Nasagrai or Nasagre (nose)","muscles":["hamstrings","calves","spinal erectors"]},"standing-half-bound-lotus-forward-bend":{"name":"Standing Half Bound Lotus Forward Bend Pose","goodFor":"Builds balance and leg strength while stretching the hamstrings, hips, and shoulders.","instructions":"Stand tall and place one foot into half lotus on the opposite upper thigh. Reach the same-side arm behind your back and clasp the big toe or foot. Exhale and fold forward over the straight standing leg, bringing the free hand to the floor in line with the toes. Keep the hips level and the standing-leg kneecap lifted. Breathe steadily for a few rounds, then inhale to lengthen and slowly rise back to standing.","breathCue":"Exhale as you fold forward, then breathe slowly and steadily.","modifications":["Rest the free hand on a block or the shin","Hold the lotus foot with the free hand if the bind is out of reach","Keep the bent foot lower on the thigh","Stand near a wall for balance"],"props":["Yoga block under the free hand","Wall for balance"],"muscleCue":"Notice the stretch in your hamstrings. Notice the contraction in the back of your shoulders.","drishti":"Nasagrai or Nasagre (nose)","modificationNote":"A bound half-lotus variation of the standing forward bend — one leg folds onto the opposite thigh and one hand reaches behind the back to hold that foot.","muscles":["hamstrings","calves","spinal erectors"]},"goddess":{"name":"Goddess Pose","goodFor":"Inner-thigh strength, hip opening, and heat.","instructions":"Step the feet wide and turn the toes out. Bend the knees and sink the hips down until the thighs are near parallel to the floor. Press the palms together at the chest in prayer. Keep the spine tall and the shoulders relaxed. Let the knees open in line with the toes. To exit, press the feet down and straighten the legs.","breathCue":"Inhale lift the heart; exhale bend the knees.","modifications":["Rest hands on thighs instead of prayer","Stay higher if hips are tight","Widen the stance to ease the knees"],"props":[],"muscleCue":"Notice the stretch in your inner thighs. Notice the contraction in your quadriceps.","drishti":"forward","modificationNote":"Palms in prayer at the chest instead of cactus arms","muscles":["quads","glutes","adductors","shoulders"]},"revolved-half-moon":{"name":"Revolved Half Moon","goodFor":"Balance with a detoxifying twist.","instructions":"From a forward fold or revolved triangle, reach the opposite hand down toward the floor and lift the back leg high. Rotate the chest open toward the standing-leg side and let the top arm reach up. Keep both legs straight and hips square to the floor. Press evenly into the standing foot and push out through the lifted heel. Gaze up toward the top hand. To exit, lower the lifted foot and unwind slowly.","breathCue":"Exhale as you twist the chest open","modifications":["Rest the lower hand on a block","Keep back toes on the floor for support","Practice near a wall for balance"],"props":["yoga block"],"muscleCue":"Notice the stretch in your hamstrings and your inner thighs. Notice the contraction in your glutes and your outer hips.","drishti":"up toward the top fingertips","modificationNote":"Twisting version of half moon: the opposite hand reaches down while the chest rotates open.","muscles":["standing-leg glutes","obliques","hamstrings","core"]},"extended-standing-hand-to-big-toe":{"name":"Extended Standing Hand to Big Toe Pose","goodFor":"Builds single-leg balance, hip mobility, and steady focus.","instructions":"Stand tall and shift your weight onto one foot. Hook the big toe of the other leg with your index and middle fingers, or use a strap. Extend that leg out to the side as high as mobility allows, keeping it straight. Reach the free arm straight out to the side at about shoulder height. Keep the pelvis level, chest lifted, and gaze softly upward. To exit, bring the leg back to center and release the toe.","breathCue":"Inhale to lengthen the leg and arm, exhale to steady the balance.","modifications":["Loop a strap around the foot","Rest the free hand on the waist","Keep the raised leg at hip height","Bend the raised knee slightly"],"props":["strap","yoga mat"],"muscleCue":"Notice the stretch in your hamstrings and your hip flexors. Notice the contraction in your outer hips.","drishti":"Urdhva Drishti (upward)","modificationNote":"Unlike the base pose where the leg extends forward, here the leg opens out to the side and the free arm reaches straight out instead of resting on the waist.","muscles":["core","legs","postural muscles"]},"revolved-standing-hand-to-big-toe":{"name":"Revolved Standing Hand to Big Toe Pose","goodFor":"Builds balance and hip flexibility while wringing out the spine.","instructions":"Stand tall and shift your weight onto one foot. Lift the other knee and hold its big toe with the same-side hand. Straighten that leg out in front of you. Twist your chest around and swing the free arm back. Keep the standing leg strong and breathe steadily, then repeat on the other side.","breathCue":"Inhale to lengthen, exhale to deepen the twist","modifications":["bend the lifted knee if hamstrings are tight","loop a strap around the foot instead of holding the toe","stand near a wall for extra balance"],"props":["wall for balance","strap around the foot"],"muscleCue":"Notice the stretch in your hamstrings and your inner thighs. Notice the contraction in your outer hips.","drishti":"forward at eye level","modificationNote":"Adds a spinal twist to the classic standing hand to big toe balance, rotating the chest while the free arm reaches back.","muscles":["core","legs","postural muscles"]},"standing-hand-to-big-toe":{"name":"Standing Hand to Big Toe Pose","goodFor":"Builds balance, leg strength, and hamstring flexibility.","instructions":"Stand tall and shift your weight onto one leg. Lift the other knee and hook your index and middle fingers around its big toe. Straighten the lifted leg forward and up as high as you can. Keep the standing leg firm and the chest lifted. Hold and breathe steadily, then release with control.","breathCue":"Breathe deeply, hold steady","modifications":["Hand on hip for stability","Use strap to hold big toe","Slightly bend standing leg","Keep raised knee bent"],"props":["strap","wall for balance"],"muscleCue":"Notice the stretch in your hamstrings. Notice the contraction in your outer hips.","drishti":"Forward, straight ahead","muscles":["core","legs","postural muscles"]},"mountain":{"name":"Mountain Pose","goodFor":"Posture, grounding, and body awareness.","instructions":"Stand with feet parallel, hip-width or together, weight even on both feet. Soften the knees slightly and lengthen the spine as if a string lifts the crown. Roll the shoulders back and down; arms rest by the sides with palms open. Gaze soft and forward. Breathe steadily through the nose. To exit, simply step into your next shape or bend the knees and fold.","breathCue":"Breathe evenly, inhale to lift, exhale to ground","modifications":["Stand with feet fist-width apart","Bend knees slightly for comfort"],"deepen":["Close the eyes for 3 breaths"],"commonMistakes":["Locking the knees","Ribs thrusting forward"],"alignmentCues":["Root through all four corners of the feet","Soften knees and lift the crown"],"props":["Mat"],"drishti":"soft gaze forward at eye level","muscles":["quads","calves","core","postural back"]},"pyramid":{"name":"Pyramid Pose","goodFor":"Intense hamstring stretch with hip squaring.","instructions":"Step one foot back into a wide stance, front toes forward and back foot turned out about 45 degrees. Keep both legs straight and square your hips to the front. Hinge at the hips and fold over the front leg. Let your hands frame the front foot or rest on blocks. Lengthen the spine with each inhale and fold a little deeper on each exhale. To come out, lift the chest and step the feet together.","breathCue":"Breathe into hamstring","modifications":["Rest hands on blocks","Soften the front knee","Take a shorter stance"],"props":["Blocks","Mat"],"muscleCue":"Notice the stretch in your hamstrings. Notice the contraction in the front of your shoulders and your triceps.","drishti":"Padayoragrai (toes)","muscles":["hamstrings","calves","hip stabilizers"]},"extended-side-angle":{"name":"Extended Side Angle","goodFor":"Deep hip and side-body opening with leg strength.","instructions":"From Warrior II, tip the torso over the bent front leg and reach the lower hand down to the floor inside the front foot. Keep the front knee bent over the ankle and the back leg strong and straight. Extend the top arm up and over the ear, making one long line from the back foot through the fingertips. Let the head follow the arm and gaze down toward the floor. To exit, press into the feet and rise back to Warrior II.","breathCue":"Breathe steadily, lengthen the side body with each inhale","modifications":["Rest forearm on the front thigh instead","Use a block under the lower hand","Shorten the stance","Keep a soft bend in the back knee"],"props":["Block","Mat"],"muscleCue":"Notice the stretch in your inner thighs. Notice the contraction in your quadriceps.","drishti":"Down toward the floor or front foot","muscles":["quads","obliques","adductors","lats"]},"standing-splits":{"name":"Standing Splits Pose","goodFor":"A deep hamstring stretch and balance practice in one calm, steady hold.","instructions":"Begin in a standing forward fold with fingertips resting on the floor. Shift your weight into one foot and let the torso drape over that leg. Lift the other leg up behind you until it feels tall and straight. Press the floor away and keep the standing leg strong. To exit, lower the lifted leg slowly and roll up to standing.","breathCue":"Exhale as the leg lifts, then breathe slowly and evenly","modifications":["Keep both hands flat on the floor for support","Rest hands on yoga blocks","Bend the standing knee slightly if hamstrings feel tight"],"props":["Yoga blocks under the hands"],"muscleCue":"Notice the stretch in your hamstrings and your hip flexors. Notice the contraction in the front of your shoulders and your triceps.","drishti":"Toward the toes or the floor beneath you","muscles":["core","legs","postural muscles"]},"dancer":{"name":"Dancer Pose","goodFor":"Builds balance and stretches the legs, hips, and shoulders.","instructions":"Stand tall and hold the opposite foot behind you. Hinge forward at the hips until your torso is roughly parallel to the floor as the foot lifts up and back. Reach the free arm straight ahead. Keep the standing knee soft and hips level. To exit, rise back up and release the foot.","breathCue":"Exhale as you hinge forward, then breathe steadily.","modifications":["Hinge only halfway forward","Keep lifted leg bent","Use a strap around the lifted foot"],"props":["strap","wall"],"muscleCue":"Notice the stretch in your quadriceps and your hip flexors. Notice the contraction in your outer hips.","drishti":"Hastagrai or Hastagre (hands)","modificationNote":"torso hinged forward parallel to the floor with the back foot held high","muscles":["standing-leg glutes","quads","hip flexors","shoulders"]},"tree":{"name":"Tree Pose","goodFor":"Balance, focus, and hip opening on the lifted leg.","instructions":"Stand tall on one leg. Bend the other knee and place the sole of that foot against your inner thigh, never on the knee. Press the foot and thigh into each other and keep both hips facing forward. Inhale and sweep your arms overhead, bringing your palms together. Keep your spine long, core engaged, and gaze at one steady point. To exit, lower the foot with control and switch sides.","breathCue":"Breathe evenly and deeply through nose","modifications":["Place foot on calf instead of thigh","Keep hands at hips for stability","Hold hands in prayer position"],"deepen":["Gaze up when steady"],"commonMistakes":["Foot pressing into the knee joint"],"props":["wall nearby"],"muscleCue":"Notice the stretch in your quadriceps and your inner thighs. Notice the contraction in your glutes and your outer hips.","drishti":"Forward at eye level","modificationNote":"Arms reach straight overhead with palms together instead of prayer at the chest.","muscles":["standing-leg glutes","ankles","core","hip external rotators"]},"triangle":{"name":"Triangle Pose","goodFor":"Side-body length, hamstring stretch, and spinal mobility.","instructions":"From a wide stance, straighten the front leg and tip the torso over it. Front hand rests on shin, ankle, block, or floor; top arm reaches skyward. Keep both sides of the waist long; avoid collapsing into the front hip. Soften the knees slightly if needed. Gaze up, forward, or down. To exit, engage the core and rise with a long spine.","breathCue":"Inhale lengthen; exhale hinge without collapsing.","modifications":["Place hand on shin or ankle","Bend front knee slightly","Keep back foot flat","Use strap to reach"],"deepen":["Top arm stacks only when chest is open"],"commonMistakes":["Rounding forward","Hyperextending front knee"],"props":["yoga mat"],"muscleCue":"Notice the stretch in your hamstrings and your inner thighs. Notice the contraction in your quadriceps and your shoulders.","drishti":"top hand","muscles":["hamstrings","obliques","adductors","shoulders"]},"revolved-triangle":{"name":"Revolved Triangle","goodFor":"Stretches the hamstrings and spine while giving the belly organs a gentle twisting massage.","instructions":"Stand with feet wide, front toes forward and back foot turned out 45 degrees, heels in line. Hinge forward from the hips over the front leg. Place your bottom hand on the floor or a block outside the front foot. Twist your torso toward the front leg and reach your top arm up to the ceiling. Keep kneecaps lifted and hips fairly level as you breathe. To exit, untwist and rise with a long flat back.","breathCue":"Breathe deeply into your belly as you twist.","modifications":["Use a block under bottom hand","Rest bottom hand on front shin","Shorten stance for balance","Gaze down instead of up"],"avoidIf":["Late pregnancy","Acute disc issues — keep twists mild"],"commonMistakes":["Forcing the twist from the neck"],"props":["block"],"muscleCue":"Notice the stretch in your outer hips and your inner thighs. Notice the contraction in the sides of your waist.","drishti":"up toward the top hand","modificationNote":"Twisting variation of Triangle - the torso rotates toward the front leg instead of opening to the side.","muscles":["hamstrings","obliques","spinal rotators","hips"]},"warrior-i":{"name":"Warrior I Pose","goodFor":"Builds leg strength and hip stability while opening the chest and shoulders.","instructions":"Step one foot forward and bend the front knee over the ankle. Keep the back leg straight and turn the back heel down at an angle. Square your hips forward and lift the chest. Reach both arms up overhead with shoulders relaxed. Gaze forward or softly up toward your hands. To exit, lower the arms and step back.","breathCue":"Inhale lift the chest; exhale root the back heel.","modifications":["Bend the front knee less","Shorten the stance for balance","Hands on hips instead of overhead","Practice near a wall for support"],"commonMistakes":["Front knee collapsing","Overarching lumbar"],"alignmentCues":["Front knee over ankle","Back foot angled ~45°"],"props":[],"muscleCue":"Notice the stretch in your hip flexors and your calves. Notice the contraction in your quadriceps.","drishti":"Forward, or softly up toward the hands","muscles":["core","legs","postural muscles"]},"warrior-ii":{"name":"Warrior II Pose","goodFor":"Leg strength, hip stability, and focused standing stamina; works core, legs, postural muscles.","instructions":"Take a wide stance with feet roughly one leg-length apart. Turn the front toes out 90° and the back foot in slightly. Bend the front knee over the ankle; arms reach to the sides at shoulder height. Gaze over the front hand. Hips open to the side wall. Soften the shoulders. To exit, straighten the front leg and lower the arms, or cartwheel the hands down.","breathCue":"Breathe into the side body; gaze soft over front fingers.","modifications":["Take a shorter stance","Bend the front knee a little less","Rest a hand on a chair for balance"],"deepen":["Bend front knee deeper when thigh is stable"],"alignmentCues":["Shoulders over hips","Front knee tracks second toe"],"props":["Chair","Mat"],"muscleCue":"Notice the stretch in your quadriceps and your hip flexors. Notice the contraction in your glutes.","drishti":"Hastagrai or Hastagre (hands)","muscles":["core","legs","postural muscles"]},"warrior-iii":{"name":"Warrior III Pose","goodFor":"Builds leg and core strength, balance, and focus.","instructions":"From standing, shift your weight onto one foot and hinge forward at the hips as the other leg lifts behind you. Keep hinging until your torso and lifted leg are roughly parallel to the floor. Reach both arms straight forward, in line with your torso. Keep the back leg active with toes pointing back. Let your gaze fall to the floor and breathe steadily. To exit, step the lifted foot down with control.","breathCue":"Steady breath; do not hold it for balance.","modifications":["Fingertips on a wall or chair for balance","Hands on hips instead of reaching forward","Back toes on the floor, hinge less far"],"avoidIf":["Acute ankle sprain on standing leg"],"commonMistakes":["Hips stacking open","Locking standing knee"],"props":["wall for toes or hands"],"muscleCue":"Notice the stretch in your hip flexors and the sides of your back. Notice the contraction in your glutes and your outer hips.","drishti":"Down toward the floor","muscles":["core","legs","postural muscles"]},"wide-legged-forward-bend-i":{"name":"Feet Spread Out Intense Stretch Pose 1","goodFor":"Opens the hamstrings, inner thighs, and back body while calming the mind.","instructions":"Stand with your feet wide apart and toes turned slightly in. Hinge at the hips and fold forward between your legs. Place your hands flat on the floor, shoulder-width apart, under your shoulders. Let your head hang heavy and relax your neck. Keep the weight even across both feet and press the palms down. To exit, engage your core and rise slowly with a long spine.","breathCue":"Exhale to fold, then breathe slow and steady as you hold.","modifications":["Bend the knees as much as needed","Rest hands on blocks or shins","Shorten the stance if balance wobbles"],"props":["Yoga blocks under the hands"],"muscleCue":"Notice the stretch in your hamstrings and your forearms. Notice the contraction in the front of your shoulders and your triceps.","drishti":"Nasagrai or Nasagre (nose)","modificationNote":"hands flat on the floor under the shoulders, crown of the head pointing down","muscles":["hamstrings","calves","spinal erectors"]},"wide-legged-forward-bend-ii":{"name":"Wide Legged Forward Bend II Pose","goodFor":"Stretches the inner thighs and hamstrings while opening the shoulders and releasing the back.","instructions":"Stand with the feet wide and parallel and the legs active. Place the hands on the hips. Hinge forward from the hips with a long spine, drawing the elbows back. Lower the crown of the head toward the floor between the feet. Keep the weight even in the feet and breathe steadily. To exit, inhale and come up slowly with a long back, hands staying on the hips.","breathCue":"Exhale as you fold with the hands on the hips and let the head settle down","modifications":["Bend the knees slightly if the hamstrings are tight","Place a block under the head for support","Rest the fingertips on the floor if balance feels shaky"],"props":[],"muscleCue":"Notice the stretch in your hamstrings.","drishti":"toward the floor","modificationNote":"Unlike the base pose, the hands stay on the hips with the elbows bent instead of resting on the floor, crown of the head toward the floor.","muscles":["hamstrings","calves","spinal erectors"]},"wide-legged-forward-bend-iii":{"name":"Wide Legged Forward Bend III Pose","goodFor":"Stretches the hamstrings, inner thighs, and shoulders while calming the mind.","instructions":"Stand with your feet wide apart and parallel, toes facing forward. Hinge forward from the hips, keeping the spine long. Reach your arms out wide and take hold of your big toes with your fingers. Let your head hang heavy as the crown draws toward the floor. Keep your legs active and your weight even across both feet. To come out, release the toes and roll up slowly with a flat back.","breathCue":"Exhale to fold deeper, inhale to lengthen","modifications":["Bend the knees slightly","Hold ankles or shins instead of toes","Rest hands on blocks if toes are out of reach"],"props":["yoga blocks"],"muscleCue":"Notice the stretch in your hamstrings and your forearms. Notice the contraction in the front of your shoulders and your triceps.","drishti":"toward the floor","modificationNote":"The hands hold the big toes with the fingers instead of placing the palms flat on the floor.","muscles":["hamstrings","calves","spinal erectors"]},"wide-legged-forward-bend-iv":{"name":"Wide Legged Forward Bend IV Pose","goodFor":"Deep hamstring and back-body stretch with a bonus shoulder opener.","instructions":"Step the feet wide and hinge forward from the hips. Reach both arms behind the back and lift the hands up toward the ceiling. Let the head hang heavy toward the floor. Keep the knees soft and the weight even across both feet. To exit, release the arms, lift the chest, and walk the feet in.","breathCue":"Exhale as you fold and let the head hang","modifications":["Bend the knees as much as needed","Rest hands on the floor or blocks instead","Shorten the stance"],"props":["block under the head"],"muscleCue":"Notice the stretch in your hamstrings.","drishti":"Nasagrai or Nasagre (nose)","modificationNote":"Arms reach up behind the back instead of hands resting on the floor.","muscles":["hamstrings","calves","spinal erectors"]},"revolved-wide-legged-forward-bend":{"name":"Revolved Wide Legged Forward Bend","goodFor":"Stretches the hamstrings and back body while the twist mobilizes the spine and shoulders.","instructions":"Stand with the feet wide and weight even. Fold forward from the hips with a long spine. Reach one hand across to the opposite ankle and let the other hand take the other ankle, letting the torso twist. Keep the knees soft and legs long. Let the head hang heavy and gaze down. To exit, release the ankles and rise slowly.","breathCue":"Exhale as you fold and twist","modifications":["Bend the knees more if hamstrings are tight","Hold the shins instead of the ankles","Rest the hands on yoga blocks"],"props":["yoga block under the hands"],"muscleCue":"Notice the stretch in your hamstrings. Notice the contraction in the front of your shoulders and your triceps.","drishti":"Downward, toward the floor","modificationNote":"Both hands cross to opposite ankles, adding a twist to the base wide-legged fold","muscles":["hamstrings","calves","spinal erectors"]},"side-wide-legged-forward-bend":{"name":"Side Wide Legged Forward Bend","goodFor":"Stretches the hamstrings and inner thighs while releasing the entire back body.","instructions":"Stand with the feet wide apart and parallel. Hinge forward from the hips keeping the spine long. Reach the arms forward and place the palms or fingertips on the floor ahead of you. Let the head hang and keep the legs active. Breathe steadily and hold the fold. To exit, walk the hands back and rise up slowly.","breathCue":"Exhale as you fold deeper","modifications":["bend the knees slightly","rest the hands on blocks","hands to shins if the floor feels far"],"props":["yoga blocks"],"muscleCue":"Notice the stretch in your hamstrings. Notice the contraction in the front of your shoulders and your triceps.","drishti":"toward the floor","modificationNote":"The arms reach forward with hands flat on the floor ahead of the head, instead of under the shoulders or clasped behind the back.","muscles":["hamstrings","calves","spinal erectors"]},"archers":{"name":"Archer Pose","goodFor":"Opens the hips and hamstrings while building core strength, leg flexibility, and focus.","instructions":"Sit up tall with both legs stretched out in front of you. Hold the big toe of one foot with your index and middle fingers, keeping that leg long on the floor. Bend the other leg and draw the foot up toward the ear, letting the elbow pull it gently back. Keep the spine long with a slight twist toward the lifted leg, both sit bones planted firmly. Breathe steadily, then release slowly and repeat on the other side.","breathCue":"Breathe evenly, inhale to lift, exhale to deepen","modifications":["Use strap over front toe","Bend knee slightly","Hold strap with hands","Keep foot lower"],"props":["strap"],"muscleCue":"Notice the stretch in your hamstrings and the deep muscles of your hips. Notice the contraction in your quadriceps and your forearms.","drishti":"Bhrumadhye or Ajna Chakra (third eye, between the eyebrows)","modificationNote":"foot to the ear","muscles":["hamstrings","hips","shoulders","core"]},"boat":{"name":"Boat Pose","goodFor":"Deep core strength and balance.","instructions":"Sit with knees bent and feet on the floor. Lean back onto your sit bones and tailbone, then lift and straighten your legs to about 45 degrees. Reach your arms forward and rest your hands on your legs. Keep your spine long and chest lifted. Breathe steadily and hold the balance.","breathCue":"Steady breath; do not brace by holding breath.","modifications":["Bend knees with shins parallel","Hold the backs of your thighs","Rest hands on floor behind hips for support"],"props":[],"muscleCue":"Notice the stretch in the back of your shoulders. Notice the contraction in your hip flexors and your abdominals.","drishti":"forward","muscles":["hip flexors","core","quads"]},"bound-angle":{"name":"Bound Angle","goodFor":"Hip and groin flexibility.","instructions":"Sit tall, bring the soles of the feet together, and let the knees fall open. Hold the feet or ankles. Sit on a blanket if the low back rounds. Fold forward only if the spine stays long. Soften the inner thighs. To exit, use the hands to close the knees and extend the legs.","breathCue":"Breathe evenly, inhale to lift chest, exhale to soften hips","modifications":["Sit on a blanket or bolster","Hold ankles instead of feet","Rest hands on thighs","Keep knees soft, not forced"],"props":["Blanket","Block","Bolster"],"muscleCue":"Notice the stretch in your inner thighs. Notice the contraction in your forearms and your hands.","drishti":"Forward, straight ahead","modificationNote":"fingertips touching the floor","muscles":["adductors","hips","groin"]},"both-feet-behind-the-head-i":{"name":"Both Feet Behind the Head I Pose","goodFor":"Deeply opens the hips and hamstrings while training a tall, steady seated posture.","instructions":"Lie back and tuck one foot behind your head, holding it in place with your arm. Ease the second foot behind your head the same way so both legs rest along the back of your neck. Roll up to sit tall on your sitting bones and bring the palms together in front of your chest. Lift the chest, keep the knees drawn in, and breathe slowly and evenly. To come out, lean back, release one leg at a time, and stretch both legs forward.","breathCue":"Inhale to lift the chest, exhale to settle the hips.","modifications":["Tuck one foot behind the head first","Sit on a folded blanket","Practice near a wall for support"],"props":["Folded blanket under the sit bones"],"muscleCue":"Notice the stretch in your hamstrings. Notice the contraction in your quadriceps and your hip flexors.","drishti":"forward","modificationNote":"Unlike the one-foot-behind-the-head version, both feet rest behind the head while the hands stay free in prayer at the chest.","muscles":["hips","hamstrings","core"]},"cow-face":{"name":"Cow Face Pose","goodFor":"Hip and shoulder opening together.","instructions":"Sit on the floor with your legs folded in front, knees soft and feet resting out to the sides. Reach one arm up and bend the elbow so the hand rests behind your head. Bend the other arm and bring the hand behind your lower back. Sit tall with the chest open and gaze forward. To exit, release both arms and switch sides.","breathCue":"Inhale to sit tall, exhale to soften the shoulders.","modifications":["Sit on a cushion to lift the hips","Keep the top hand behind the head if the reach is tight","Widen the legs if the knees complain","Lean on a wall for a taller spine"],"props":["cushion"],"muscleCue":"Notice the stretch in your shins and the tops of your feet.","drishti":"Straight ahead","modificationNote":"Legs folded loosely with the top hand resting behind the head instead of the hands clasping behind the back.","muscles":["hips","external rotators","shoulders","triceps"]},"easy":{"name":"Easy Seat","goodFor":"Grounding reset and joint-friendly support; settles hips, hamstrings, core.","instructions":"Sit cross-legged with a tall spine. If the knees are high, sit on a folded blanket. Hands rest on the thighs or in the lap. Soften the shoulders and jaw. Breathe steadily through the nose. To exit, uncross the legs slowly and stretch them forward.","breathCue":"Inhale for four counts, exhale for six","modifications":["Support lower back with folded blanket","Sit on a cushion to lift the hips","Lean against a wall for back support"],"props":["cushion"],"muscleCue":"Notice the stretch in the deep muscles of your hips and your inner thighs. Notice the contraction in your quadriceps.","drishti":"Nasagrai or Nasagre (nose)","muscles":["hips","hamstrings","core"]},"fire-log":{"name":"Fire Log Pose","goodFor":"Deeply stretches the outer hips and eases tension around the IT-band region.","instructions":"Sit tall on the floor with both sitting bones grounded. Lay one shin flat in front of you, parallel to the top of the mat. Stack the other shin on top so the top ankle rests on the bottom knee. Keep the spine long and upright as the hips soften. Rest the hands on the floor beside the hips or on the knees. To come out, gently unstack the legs.","breathCue":"Inhale to lengthen the spine, exhale to soften the hips","modifications":["Use block under top knee","Place blanket under hips"],"props":["Block","Blanket"],"muscleCue":"Notice the stretch in your shins and the tops of your feet. Notice the contraction in your quadriceps.","drishti":"Soft gaze forward, level with the eyes or slightly below","modificationNote":"Spine straight, fingertips resting on the floor beside the hips","muscles":["outer hips","glutes","piriformis"]},"embryo-in-womb":{"name":"Embryo in Womb Pose","goodFor":"Calms the nervous system while opening the hips and easing the lower back.","instructions":"Sit on the floor and cross your legs, drawing the feet in close. Let your knees drop wide and heavy toward the floor. Rest your forearms along your shins and bring your palms up to cradle your jaw and cheeks. Let your head sink into your hands as your back rounds gently forward. Stay and breathe slowly, then release the hands and uncross the legs.","breathCue":"Exhale and soften deeper into the curl","modifications":["Sit on a folded blanket if the hips are tight","Cross the legs simply instead of full lotus","Support the head with fingertips only"],"props":["folded blanket"],"muscleCue":"Notice the stretch in the deep muscles of your hips. Notice the contraction in your quadriceps and your hip flexors.","drishti":"Nasagrai (tip of the nose) or a soft downward gaze","modificationNote":"arms rest on top of the crossed legs instead of threading through them","muscles":["hips","hamstrings","core"]},"foot-behind-the-head-i":{"name":"Foot Behind the Head I Pose","goodFor":"Deeply opens the hips while building focus, balance, and core control.","instructions":"Sit tall with one leg extended straight in front of you. Bend the other knee and hold the foot with both hands. Open the knee out wide and lift the leg up and back. Guide the foot behind the head and let it rest there. Bring the palms together at the chest and sit up tall. Breathe steadily, then release the leg slowly when ready.","breathCue":"Inhale to lengthen up, exhale to soften the hips.","modifications":["Keep the foot at the chest or shoulder instead","Sit on a folded blanket","Loop a strap around the foot for support"],"props":["folded blanket","strap"],"muscleCue":"Notice the stretch in the deep muscles of your hips. Notice the contraction in your quadriceps and your hip flexors.","drishti":"forward","modificationNote":"Variation A: once the foot is behind the head, the hands come to prayer at the chest instead of supporting on the floor.","muscles":["hips","hamstrings","core"]},"foot-behind-the-head-ii":{"name":"Foot Behind the Head II Pose","goodFor":"Deeply stretches the hamstrings while opening the hips and building spinal flexibility.","instructions":"Sit with one leg extended straight in front of you. Bend the other leg and nestle the foot behind your head, letting the calf rest against your shoulder. Place your hands on the floor beside the extended leg. On an exhale, fold your torso forward over the straight leg. Keep the extended leg active and breathe steadily as you hold. To exit, lift your torso up, free the leg from behind your head, and straighten it slowly.","breathCue":"Exhale as you fold, then breathe slowly and steadily","modifications":["Rest the foot behind the neck instead of the head","Sit on a folded blanket to lift the hips","Use a strap around the extended foot","Keep the fold shallow with hands on the shin"],"props":["Folded blanket under the sit bones"],"muscleCue":"Notice the stretch in your inner thighs and the muscles along your spine. Notice the contraction in your quadriceps and your hip flexors.","drishti":"toward the extended foot","modificationNote":"Unlike the base pose where you sit upright with hands in prayer, here you fold your torso forward over the extended leg.","muscles":["hips","hamstrings","core"]},"seated-forward-bend-i":{"name":"Seated Forward Bend I Pose","goodFor":"A deep hamstring and back-body stretch that calms the nervous system.","instructions":"Sit with both legs stretched out in front. Inhale and lengthen the spine. Exhale and hinge forward from the hips over the legs. Reach forward and hold the feet, letting the torso settle toward the thighs. Keep the neck relaxed and breathe slowly. To come up, inhale and rise with a long spine.","breathCue":"Breathe deeply, exhale as you fold forward","modifications":["Soften the knees a little","Loop a strap around the feet","Walk the hands onto the shins","Let the forehead rest toward the knees"],"avoidIf":["Acute hamstring tear"],"props":["Belt"],"muscleCue":"Notice the stretch in your hamstrings. Notice the contraction in your forearms and your hands.","drishti":"Padayoragrai or Padayoragre (toes/feet), Nasagrai or Nasagre (nose)","muscles":["hamstrings","calves","spinal erectors"]},"seated-forward-bend-ii":{"name":"Seated Forward Bend II Pose","goodFor":"A deep stretch for the hamstrings, calves and the whole back of the body.","instructions":"Sit tall with both legs extended straight and feet flexed. Inhale to lengthen the spine, then exhale and hinge from the hips to fold forward. Slide the hands forward to hold the feet, or rest them on the floor beside the feet. Let the chest settle toward the thighs and the head hang heavy. Keep the legs straight and breathe into the stretch. To exit, release the hands and inhale up with a long spine.","breathCue":"Exhale and fold a little deeper","modifications":["Bend the knees slightly","Loop a strap around the feet","Rest hands on the shins","Sit on a folded blanket"],"props":["Yoga strap","Folded blanket"],"muscleCue":"Notice the stretch in your hamstrings and the muscles along your spine. Notice the contraction in your forearms and your hands.","drishti":"toward the feet","modificationNote":"Deeper than the base pose: the hands hold the feet with arms extended as the chest draws down toward the thighs.","muscles":["hamstrings","calves","spinal erectors"]},"seated-forward-bend-iii":{"name":"Seated Forward Bend III Pose","goodFor":"Gives the whole back of the body a long, deep stretch while calming the nervous system.","instructions":"Sit with both legs stretched out in front and flex the feet back toward you. Hinge forward from the hips and take hold of the feet with both hands. Let the belly come onto the thighs and keep the back of the neck long as the head drops toward the shins. Relax the neck and face and breathe slowly as you hold the fold. To exit, release the feet and inhale up with a long spine.","breathCue":"Exhale and soften deeper into the fold","modifications":["Bend the knees slightly","Loop a strap around the feet","Rest the hands on the shins","Sit on a folded blanket"],"props":["Strap around the feet","Folded blanket under the hips"],"muscleCue":"Notice the stretch in your hamstrings. Notice the contraction in your forearms and your hands.","drishti":"shins","modificationNote":"deepest variation of the seated forward bend — the whole torso rests along the legs, hands hold the feet and the forehead comes toward the shins","muscles":["hamstrings","calves","spinal erectors"]},"seated-forward-bend-iv":{"name":"Seated Forward Bend IV Pose","goodFor":"Builds mobility, strength, and awareness for Seated Forward Bend IV Pose.","instructions":"Sit tall on the sit bones — use a folded blanket if the low back rounds. Arrange the legs for Seated Forward Bend IV Pose, then lengthen the spine on an inhale before folding, twisting, or binding. Soften the shoulders away from the ears. Breathe steadily; ease out of any sharp sensation. To exit, release binds first, then uncross or straighten the legs slowly."},"seated-half-bound-lotus-forward-bend":{"name":"Seated Half Bound Lotus Forward Bend Pose","goodFor":"Opens tight hips and shoulders while giving a deep hamstring stretch and calming the mind.","instructions":"Sit tall on your sit bones with one leg extended straight and the other foot placed in half lotus on the opposite thigh. Reach the arm on the lotus side behind your back and hold the lotus foot. Lengthen the spine on an inhale, then fold forward over the extended leg and hold its foot. Keep the lotus knee heavy and the shoulders relaxed. Breathe steadily, then release the bind first and come up slowly.","breathCue":"Exhale as you fold forward and breathe steadily in the bind.","modifications":["Hand under knee to support the lotus leg","Hold the extended foot without the bind","Half fold with spine straight","Practice the fold without the lotus"],"props":["Folded blanket under the sit bones"],"muscleCue":"Notice the stretch in your inner thighs. Notice the contraction in your forearms and your hands.","drishti":"Padayoragre (toes of the extended foot)","modificationNote":"Adds a half lotus leg and a behind-the-back foot bind to the basic seated forward bend.","muscles":["hamstrings","calves","spinal erectors","hip external rotators","shoulders"]},"seated-three-limbed-forward-bend":{"name":"Seated Three Limbed Forward Bend Pose","goodFor":"Builds mobility, strength, and awareness for Seated Three Limbed Forward Bend Pose.","instructions":"Sit tall on the sit bones — use a folded blanket if the low back rounds. Arrange the legs for Seated Three Limbed Forward Bend Pose, then lengthen the spine on an inhale before folding, twisting, or binding. Soften the shoulders away from the ears. Breathe steadily; ease out of any sharp sensation. To exit, release binds first, then uncross or straighten the legs slowly.","muscleCue":"Notice the stretch in your hamstrings. Notice the contraction in your quadriceps.","muscles":["hamstrings","calves","spinal erectors"]},"garland":{"name":"Garland Pose","goodFor":"Hip opening, ankle mobility, and pelvic floor awareness.","instructions":"From standing, step the feet wider than the hips and turn the toes out. Bend the knees and lower the hips into a deep squat, keeping the heels down. Bring the palms together at the chest and let the elbows press the inner knees apart. Keep the spine long and the chest lifted. To exit, plant the hands on the floor and straighten the legs.","breathCue":"Breathe slowly and let the hips soften on each exhale","modifications":["Use blocks under the hands","Start with fingertips on the floor","Rise onto the toes if needed","Keep a soft forward gaze"],"props":["Yoga blocks","Rolled blanket under the heels"],"muscleCue":"Notice the stretch in your quadriceps and your inner thighs.","drishti":"Nasagrai or Nasagre (nose)","modificationNote":"Hands stay in Anjali Mudra (prayer) at the chest instead of wrapping the arms around the legs","muscles":["ankles","adductors","glutes","core"]},"seated-gate":{"name":"Seated Gate Pose","goodFor":"Opens the side body while stretching the hamstrings and hips.","instructions":"Sit tall with one leg stretched straight out to the side and the other knee bent, foot tucked back beside the hip. Ground both sitting bones and lengthen the spine. Lean sideways over the straight leg, letting the same-side hand slide toward the foot. Sweep the other arm up and overhead, reaching long. Keep the chest open and shoulders relaxed as you breathe into the side stretch. To exit, press down gently and rise back to center.","breathCue":"Inhale to lengthen, exhale to lean deeper.","modifications":["Sit on a folded blanket if the hips are tight","Rest the lower hand on a block","Bend the extended knee slightly"],"props":["folded blanket","yoga block"],"muscleCue":"Notice the stretch in your hamstrings and your inner thighs. Notice the contraction in your forearms and your hands.","drishti":"gently upward, past the raised arm","modificationNote":"practised seated on the floor instead of kneeling, with the bent leg folded out beside you","muscles":["obliques","intercostals","hamstrings","hips","core"]},"head-to-knee-i":{"name":"Head to Knee I Pose","goodFor":"Deeply stretches the hamstrings, calves, and lower back in a calming seated fold.","instructions":"Sit with one leg extended and the other foot to the inner thigh. Square the torso over the extended leg and fold. Hold the foot or a strap. Soften the extended knee if needed. Keep both sit bones grounded. To exit, lift the torso and switch legs when ready.","breathCue":"Exhale to fold deeper over the extended leg","modifications":["Use a strap around the foot","Rest the extended foot on blocks","Sit on a chair","Rest palms alongside the leg"],"props":["strap","blocks","chair"],"muscleCue":"Notice the stretch in your inner thighs. Notice the contraction in the front of your shoulders.","drishti":"along the extended leg toward the toes","muscles":["hamstrings","calves","spinal erectors"]},"head-to-knee-ii":{"name":"Head to Knee II Pose","goodFor":"Stretches the hamstrings, spine, and groins while calming the mind.","instructions":"Sit tall with one leg stretched forward and the other heel tucked under the perineum so you rest on that heel. Place a folded blanket under the hips if they need extra support. Inhale to lengthen the spine, then exhale and fold forward over the extended leg. Reach for the foot and let the head come down toward the leg. Keep the shoulders soft and breathe steadily. To exit, inhale the torso back up and slowly straighten the bent leg.","breathCue":"Breathe evenly as you fold forward","modifications":["Tuck heel into groin","Fold halfway","Use blanket under hips","Switch to Janu Sirsasana A"],"props":["folded blanket"],"muscleCue":"Notice the stretch in your inner thighs. Notice the contraction in your forearms and your hands.","drishti":"tip of the big toe","modificationNote":"Unlike Janu Sirsasana A, the bent leg's heel tucks under the perineum and you sit on the heel instead of the sit bones.","muscles":["hamstrings","calves","spinal erectors"]},"head-to-knee-iii":{"name":"Head to Knee III Pose","goodFor":"Stretches the spine, hamstrings and ankles, tones the abdominal organs and calms the mind.","instructions":"Sit tall on your sit bones with one leg extended and the other knee bent out to the side. Rotate the bent-leg foot so it rests against the inner thigh, heel pressing in toward the pubic bone. Inhale to lengthen the spine, then fold from the hips over the straight leg and hold the extended foot. Keep the spine long and shoulders soft, gazing toward the toes of the extended foot. Breathe steadily, then ease out slowly and straighten the bent leg last.","breathCue":"Inhale to lengthen, exhale to fold deeper.","modifications":["Use Janu Sirsasana A","Place heel tucked into hips","Keep ankle relaxed","Stay upright"],"props":["Folded blanket under sit bones"],"muscleCue":"Notice the stretch in your inner thighs. Notice the contraction in your forearms and your hands.","drishti":"Padhayoragrai or Padayoragre (toes/feet), Nasagrai or Nasagre (nose)","modificationNote":"The bent-leg foot is rotated so the toes point forward and the heel presses into the pubic bone, unlike the base head-to-knee fold.","muscles":["hamstrings","calves","spinal erectors"]},"hero":{"name":"Hero Pose","goodFor":"Quad stretch and meditation seat.","instructions":"Kneel with your knees together and your feet tucked in close behind you. Sit back so your sit bones settle onto your heels. Rest your hands on the tops of your thighs and sit up tall. On an inhale, lengthen the spine and let the shoulders soften away from the ears. Breathe steadily and ease out of any sharp feeling. To come out, lean forward and gently free the legs.","breathCue":"Inhale to grow tall, exhale to relax the shoulders.","modifications":["Sit on a block or blanket","Place a towel between thigh and calf","Use a bolster for back support"],"props":["block","blanket","towel"],"muscleCue":"Notice the stretch in your quadriceps and your shins.","drishti":"Nasagrai or Nasagre (nose)","modificationNote":"sits on top of the heels rather than between the feet, hands resting on the thighs","muscles":["quads","ankles","shin muscles"]},"heron":{"name":"Heron Pose","goodFor":"Intense hamstring stretch with core engagement.","instructions":"Sit with one leg bent, knee on the floor and heel beside the hip. Hold the other foot with both hands and extend that leg up as straight as comfortable. Keep the spine long and shoulders soft as you draw the leg gently toward you. To exit, bend the raised knee and release the foot.","breathCue":"Inhale to lengthen the spine, exhale to draw the leg in","modifications":["Keep the raised knee slightly bent","Loop a strap around the foot","Sit on a block or blanket","Hold the back of the thigh"],"props":["block","bolster","blanket"],"muscleCue":"Notice the stretch in your quadriceps and your hamstrings. Notice the contraction in your forearms and your hands.","drishti":"Straight ahead, or toward the toes of the raised foot","muscles":["hamstrings","hip flexors","core"]},"noose":{"name":"Noose Pose","goodFor":"Deep twist with ankle and shoulder mobility.","instructions":"Squat with the feet together and the heels down, knees pointing forward. Keep the knees hugging in as you exhale and twist to one side. Wrap one arm around both knees and reach the other arm behind the back to clasp hands. Lengthen the spine on each inhale and deepen the twist on each exhale. Keep the shoulders soft and the gaze gentle. To exit, release the bind first and rise up slowly.","breathCue":"Exhale to deepen the twist","modifications":["Skip the bind and hug the knees","Rest the heels on a folded blanket","Keep hands in prayer at the chest"],"props":["Blanket"],"muscleCue":"Notice the stretch in your chest and the front of your shoulders. Notice the contraction in the sides of your waist.","drishti":"Gaze softly down toward the floor","muscles":["ankles","obliques","shoulders","hips"]},"half-pigeon":{"name":"Half Pigeon","goodFor":"Accessible pigeon variation for hip opening.","instructions":"From Down Dog or a lunge, bring one shin forward across the mat (ankle near the opposite wrist as comfortable). Extend the back leg straight behind. Square the hips; use a blanket under the front hip if needed. Fold forward over the front leg or stay upright. To exit, tuck the back toes, lift, and step back.","breathCue":"Long soft exhales into the outer hip.","modifications":["Use block under hips","Place blanket under hips","Bring front heel closer to pelvis","Bend front knee less"],"avoidIf":["Sharp knee pain — switch to figure-four"],"commonMistakes":["Forcing the front shin parallel"],"props":["Block","Blanket"],"muscleCue":"Notice the stretch in your hip flexors and your calves. Notice the contraction in the muscles along your spine.","drishti":"straight ahead","modificationNote":"Gentler upright prep for full pigeon, with the front shin folded forward instead of a deep backbend.","muscles":["hip external rotators","hip flexors","glutes"]},"lotus":{"name":"Lotus Pose","goodFor":"Classic meditation seat; deep hip opening.","instructions":"Sit tall on the sit bones, on a folded blanket if the low back rounds. Bend one knee and place that foot on the opposite thigh, sole facing up. Bring the other foot onto the opposite thigh the same way. Rest the hands on the floor beside the hips and relax the shoulders down. Lengthen the spine with each inhale and breathe steadily. To exit, gently lift one foot off the thigh at a time.","breathCue":"Inhale to lengthen the spine, exhale to soften the shoulders","modifications":["Sit on a block or bolster","Keep hands on knees or in Gyan Mudra"],"props":["Block","Bolster"],"muscleCue":"Notice the stretch in your shins and the tops of your feet.","drishti":"Nasagrai or Nasagre (nose)","modificationNote":"hands rest on the floor beside the hips instead of on the knees","muscles":["hips","external rotators","ankles"]},"sage-marichis-i":{"name":"Sage Marichi's I Pose","goodFor":"Calms the mind, relieves stress, and stretches the hamstrings and hips.","instructions":"Sit with both legs extended forward. Bend one knee and place that foot close to your pelvis. Wrap the opposite arm around the bent knee and reach it behind your back. Bring your other arm behind your back and clasp hands or wrist. Hinge forward from the hips over the straight leg, keeping the spine long. Gaze softly down or rest the forehead near the leg.","breathCue":"Breathe deeply and slowly","modifications":["Hand outside bent foot","Hands-width gap between foot and leg","Use strap","Long spine, gentler fold"],"props":["strap"],"muscleCue":"Notice the stretch in the deep muscles of your hips and your chest. Notice the contraction in the sides of your waist.","drishti":"Toward the extended foot or the floor","muscles":["hamstrings","hips","shoulders","obliques"]},"side-lunge":{"name":"Side Lunge","goodFor":"Inner-thigh strength and lateral hip mobility.","instructions":"Start in a wide stance with toes angled slightly out. Bend one knee deeply and shift the hips back toward that heel, keeping the bent foot flat on the floor. Keep the other leg straight and long with the foot flexed and toes lifting up. Place both hands on the floor in front of you and keep the spine long. To exit, press into the bent foot and return to center, then switch sides.","breathCue":"Inhale to lengthen the spine, exhale to sink the hips","modifications":["Keep the bent heel on the floor","Place blocks under the hands","Shorten the stance"],"props":[],"muscleCue":"Notice the stretch in your hamstrings and your inner thighs. Notice the contraction in your quadriceps.","drishti":"Nasagrai or Nasagre (tip of the nose), or a soft forward gaze","muscles":["adductors","quads","glutes","ankles"]},"front-splits":{"name":"Front Splits","goodFor":"Full front-leg splits flexibility.","instructions":"Kneel and stretch one leg forward and the other back with both knees straight. Slide the hips down until both legs rest flat on the floor. Place your hands on the floor beside your hips for light support. Lift the chest and press it forward, letting the head tip back so the gaze turns upward. Keep the belly drawn in and the shoulders soft. To exit, press into the hands and slide the legs back together.","breathCue":"Exhale as you sink into the split","modifications":["Place hands on blocks","Fold a blanket under the back thigh","Stay higher with a soft back knee"],"props":[],"muscleCue":"Notice the stretch in your hamstrings and your hip flexors. Notice the contraction in your glutes and the sides of your waist.","drishti":"Urdhva (upward, toward the ceiling)","modificationNote":"hands rest on the floor beside the hips with the chest pushed forward and the head tipped back to gaze up","muscles":["hamstrings","hip flexors","quads"]},"half-splits":{"name":"Half Splits Pose","goodFor":"Deeply stretches the hamstrings and hips and prepares the body for full splits.","instructions":"Start in a low lunge with your hands on the floor. Slide the back knee down to the mat and shift your hips back. Straighten the front leg and flex the foot, keeping the heel grounded. Fold your torso forward over the straight leg, walking your hands ahead of you. Keep the spine long, let the neck relax, and breathe steadily as you hold.","breathCue":"Exhale to fold deeper over the front leg","modifications":["keep a small bend in the front knee","rest the hands on yoga blocks","stay high on the fingertips instead of folding deep"],"props":["yoga blocks under the hands"],"muscleCue":"Notice the stretch in your forearms. Notice the contraction in your quadriceps.","drishti":"down towards the front foot","modificationNote":"A gentler version of full splits (Hanumanasana) with the back knee resting on the floor instead of the back leg stretched out behind.","muscles":["core","legs","postural muscles"]},"wide-splits":{"name":"Wide Splits","goodFor":"Wide-leg flexibility and groin opening.","instructions":"Sit on the floor and spread the legs wide apart. Keep the spine tall and the chest lifted. Place the palms flat on the floor between the legs. Let the thighs roll outward so the kneecaps point up. Breathe steadily and let the hips release toward the floor. To exit, gently bring the legs back together.","breathCue":"Inhale to lengthen the spine, exhale to soften the hips","modifications":["Sit on a folded blanket to tilt the hips","Bend the knees slightly if tight","Use blocks under the hands"],"props":["Folded blanket","Yoga blocks"],"muscleCue":"Notice the stretch in your inner thighs. Notice the contraction in your quadriceps and your hip flexors.","drishti":"Bhrumadhye or Ajna Chakra (third eye, between the eyebrows)","modificationNote":"upright torso with hands on the floor between the legs, no forward fold","muscles":["adductors","hamstrings","hips"]},"staff":{"name":"Staff Pose","goodFor":"Strengthens the legs and arms while opening the chest in a supported seated lean.","instructions":"Sit with both legs extended straight in front and feet flexed. Place your palms on the floor just behind your hips, fingers pointing forward. Straighten the arms and lean your torso back a little. Keep the spine long and the chest lifted as you press the palms down. Reach out through the heels and gaze forward. To exit, bend the knees and sit back up.","breathCue":"Inhale to lift the chest, exhale to press the palms down.","modifications":["Sit on a folded blanket","Soften the knees if hamstrings are tight","Place hands on blocks for support"],"props":["mat"],"muscleCue":"Notice the stretch in your chest and the front of your shoulders.","drishti":"Nasagrai (tip of nose), gazing straight ahead","muscles":["core","hip flexors","quads","postural back"]},"thunderbolt":{"name":"Thunderbolt Pose","goodFor":"A digestion-friendly seat that also stretches the quads and tops of the feet.","instructions":"Kneel with your knees together and the tops of your feet on the floor. Sit back so your buttocks rest on your heels. Place your palms on the tops of your thighs. Inhale to lengthen the spine and reach the crown of your head up. Relax your shoulders down and gaze softly forward. To exit, lean slightly forward and gently straighten the legs.","breathCue":"Inhale to lengthen the spine, exhale to settle onto your heels.","modifications":["Sit on a block or bolster","Use folded blanket under hips","Keep knees slightly bent","Place hands on thighs"],"props":["block","bolster"],"muscleCue":"Notice the stretch in your quadriceps and your shins. Notice the contraction in your glutes.","drishti":"Nasagrai or a steady gaze forward at a fixed point","muscles":["quads","ankles","shins"]},"toe-stand":{"name":"Toe Stand","goodFor":"Ankle strength and intense balance.","instructions":"From standing, place one foot on top of the opposite thigh in half lotus. Bend the standing leg and lower your hips until they hover just above the heel. Shift your weight onto the toes and lift the heel high. Cross your arms over your chest with each hand resting on the opposite shoulder. Keep the spine tall and gaze steady, then rise out with control.","breathCue":"Exhale slowly and root into the toes as you balance.","modifications":["Keep fingertips on the floor for balance","Place hands on hips instead of crossed arms","Practice beside a wall for support"],"props":[],"muscleCue":"Notice the stretch in your quadriceps and the deep muscles of your hips. Notice the contraction in your outer hips and your hip flexors.","drishti":"forward","modificationNote":"balanced on the toes of one foot, the other foot folded into half lotus on the standing thigh","muscles":["ankles","calves","core","quads"]},"banana":{"name":"Banana Pose","goodFor":"Side-body stretch and restorative lateral release.","instructions":"Lie on your back. Walk both feet and both arms toward one side so the body makes a gentle banana curve. Soften the opposite side body. Rest the head comfortably. To exit, return to center and switch the curve.","breathCue":"Exhale and soften into the curve.","modifications":["make a smaller curve with hands and feet closer to center","rest the head on a folded blanket","bend the knees slightly for low back comfort","support the arms on the floor with palms up"],"props":["folded blanket under the head","bolster under the knees"],"muscleCue":"Notice the stretch in your calves and the back of your shoulders.","drishti":"eyes closed","modificationNote":"Same supine shape as a straight full-body stretch, but both hands and feet are walked to one side so the body curves into a crescent.","muscles":["obliques","IT band","side body"]},"bridge":{"name":"Bridge Pose","goodFor":"Glute strength, chest opening, and gentle inversion.","instructions":"Lie on your back, bend the knees, and place the feet hip-width apart under the knees. Keep the arms alongside the body with palms flat on the floor. Press into the feet and lift the hips. Draw the shoulder blades together and lift the chest. Keep the neck relaxed and gaze softly up. To exit, lower the spine back down slowly.","breathCue":"Breathe rhythmically, inhale to lift, exhale to release","modifications":["Place a block under the sacrum","Clasp hands under the back","Rest the neck on a folded blanket"],"avoidIf":["Acute neck issues — keep gaze neutral, no turning head"],"props":["mat","yoga block"],"muscleCue":"Notice the stretch in your chest and the front of your shoulders. Notice the contraction in your glutes.","drishti":"Bhrumadhye or Ajna Chakra (third eye, between the eyebrows)","muscles":["glutes","hamstrings","spinal extensors","core"]},"corpse":{"name":"Corpse Pose","goodFor":"Integration, rest, and nervous-system reset.","instructions":"Lie flat on your back with both legs extended and the feet close together. Rest your arms alongside your body with the hands near your thighs and the palms facing down. Keep the head in line with the spine and let the whole body settle. Close the eyes if that feels comfortable. Breathe naturally and stay here, letting go of all effort.","breathCue":"Natural breath; no control needed.","modifications":["Try legs up the wall","Bend knees with feet flat on floor","Place a blanket under the head"],"alignmentCues":["Palms soft","Feet fall open"],"props":["blanket under knees","eye pillow"],"drishti":"Bhrumadhye or Ajna Chakra (third eye, between the eyebrows)","muscles":["full-body release"]},"fish":{"name":"Fish Pose","goodFor":"Chest and throat opening; counterpose to forward folds.","instructions":"Lie on your back with your legs straight and together. Rest your arms alongside your body, hands on the floor by your hips. Press into the forearms and lift your chest, letting the crown of your head rest lightly on the mat. Keep your legs easy and breathe deeply. To come out, lift your head first, then lower your spine.","breathCue":"Breathe deeply while in the position","modifications":["Place a block under the shoulder blades","Rest the head on a block or blanket","Tuck the hands under the sit bones","Use a bolster along the spine"],"props":["Block","Bolster","Mat"],"muscleCue":"Notice the stretch in your chest and the front of your shoulders.","drishti":"Bhrumadhye or Ajna Chakra (third eye, between the eyebrows)","modificationNote":"hands rest on the floor beside the hips instead of tucked underneath","muscles":["chest","throat","spinal extensors","hip flexors"]},"supine-foot-to-head":{"name":"Supine Foot to Head Pose","goodFor":"Deeply opens the hamstrings and hips while building core control.","instructions":"Lie on your back with both legs long. Keep one leg heavy on the floor as you bend the other knee in. Clasp your hands behind that thigh or around the shin. On an exhale, gently draw the leg toward your head, letting the foot travel up and over. Keep both shoulders grounded and the neck soft. Hold for a few breaths, then switch sides.","breathCue":"Exhale as you draw the leg closer","modifications":["bend the lifted knee slightly","loop a strap around the foot","rest the head on a folded blanket"],"props":["strap","folded blanket"],"muscleCue":"Notice the stretch in your hip flexors. Notice the contraction in your forearms and your hands.","drishti":"toward the raised foot","modificationNote":"Deeper supine variation where one foot is drawn toward the head instead of lifted toward the ceiling.","muscles":["core","legs","postural muscles"]},"extended-supine-hand-to-big-toe":{"name":"Extended Supine Hand to Big Toe Pose","goodFor":"Great for loosening tight hamstrings and inner thighs and easing hip tension.","instructions":"Lie flat on your back with both legs stretched out. Bend one knee in, hold its big toe with the hand on the same side, and straighten the leg up toward the ceiling. Keeping the leg straight, lower it out to the side toward the floor. Rest the other hand on the opposite hip so that hip stays grounded and the other leg stays heavy on the mat. Keep the head and shoulders down and breathe slowly. To exit, bring the leg back up to center, then release the toe and lower the leg.","breathCue":"Inhale to lengthen the leg, exhale as it opens out to the side","modifications":["Loop a strap around the foot if the toe is out of reach","Rest the outer thigh on a block or bolster","Bend the bottom knee with the foot flat for back comfort"],"props":["yoga strap","folded blanket under the head"],"muscleCue":"Notice the stretch in your hamstrings and your calves. Notice the contraction in your glutes.","drishti":"eyes closed or a soft gaze straight up","modificationNote":"In this variation the held leg opens out to the side toward the floor instead of pointing up, with the other leg and the opposite hip staying grounded.","muscles":["hamstrings","calves","hip flexors","core","lower back"]},"supine-hand-to-big-toe":{"name":"Supine Hand to Big Toe Pose","goodFor":"Builds strength and mobility for Supine Hand to Big Toe Pose; emphasizes core, legs, postural muscles.","instructions":"Lie on your back with both legs long and your head resting down. Extend one leg straight up past vertical toward your head. Reach up with the hand on the same side to hold the big toe or foot. Keep the other leg active and flat on the floor. Hold and breathe, then bend the raised knee to come out.","breathCue":"Exhale as you draw the leg a little closer","modifications":["Loop a strap around the raised foot","Raise the leg only to 90 degrees","Bend the bottom knee slightly","Rest the bottom arm out to the side"],"props":["Strap"],"muscleCue":"Notice the stretch in your calves.","drishti":"Padayoragrai (toes of the raised foot)","muscles":["core","legs","postural muscles"]},"happy-baby":{"name":"Happy Baby","goodFor":"Hip opening and playful hamstring stretch.","instructions":"Lie on your back. Bend your knees toward your chest and grab the outer edges of your feet or your big toes. Let your ankles stack over your knees so your shins point straight up. Press your feet into your hands as your tailbone melts toward the floor. Rock gently side to side or stay still. To exit, let go of the feet and stretch your legs out.","breathCue":"Slow breaths, softening a little more with each exhale.","modifications":["Use a strap instead of hands","Support pelvis with a pillow","Rest head on a blanket","Bend knees more"],"props":["Strap","Blanket","Bolster"],"muscleCue":"Notice the contraction in your forearms and your hands.","muscles":["adductors","hamstrings","hips"]},"sleeping-yogi":{"name":"Sleeping Yogi Pose","goodFor":"Deeply opens the hips and hamstrings while folding the spine into a calm, rest-like shape.","instructions":"Lie flat on your back and hug both legs in toward the chest. Lift the hips slightly and sweep the legs up and behind the head. Cross the ankles behind the head and let the shoulders tuck under the calves. Rest the head against the foot behind it and keep the chest open. Breathe slowly in the fold, then unwrap the legs with control to exit.","breathCue":"Exhale as the legs settle behind your head","modifications":["Stack one ankle on top of the other","Keep knees softly bent","Support the legs with a folded blanket"],"props":["Folded blanket under the head"],"muscleCue":"Notice the stretch in the deep muscles of your hips.","drishti":"closed eyes","muscles":["core","spine","hamstrings","hips","inner thighs","shoulders"]},"supine-spinal-twist":{"name":"Supine Spinal Twist Pose","goodFor":"Improves spinal flexibility, gives digestion a gentle massage, and eases lower back tension.","instructions":"Lie on your back and hug one knee in toward your chest. Guide that knee across your body toward the floor on the opposite side. Keep the other leg long and easy on the mat. Stretch the opposite arm out at shoulder height. Let that hand rest on the bent knee for a gentle press, and turn your gaze away from the knees. Keep both shoulders heavy and breathe into the ribs before switching sides.","breathCue":"Inhale to stretch, exhale to deepen the twist","modifications":["Support the bent knee with a blanket or block","Anchor the thighs with one hand","Bend the bottom leg slightly to ease the back"],"props":["blanket","bolster","block"],"muscleCue":"Notice the stretch in your outer hips. Notice the contraction in your glutes.","drishti":"Over the shoulder of the extended arm, away from the knees","modificationNote":"One leg stays long on the floor while the opposite hand presses the bent knee across","muscles":["obliques","spinal rotators"]},"supine-straddle":{"name":"Supine Straddle","goodFor":"Gravity-assisted wide-leg stretch.","instructions":"Lie on your back with your head and shoulders resting on the floor. Lift both legs toward the ceiling and open them into a wide V. Reach up and hold the outer edges of your feet with each hand. Let gravity draw the legs wider and closer to the floor. Keep the lower back, shoulders, and head heavy and relaxed. To exit, release the feet and hug the knees in gently.","breathCue":"Exhale and let the legs sink a little wider","modifications":["bend the knees slightly","loop a strap around each foot","practice one leg at a time near a wall"],"props":["yoga strap","wall"],"muscleCue":"Notice the stretch in your hamstrings and your inner thighs. Notice the contraction in your forearms and your hands.","drishti":"up toward the ceiling","modificationNote":"Supine version of the wide-angle straddle, using gravity instead of an active fold.","muscles":["adductors","hamstrings","hips"]},"waterfall":{"name":"Waterfall Pose","goodFor":"Gentle inversion and leg drainage without a wall.","instructions":"Lie on your back and let your arms rest a little away from your sides, palms up. Lift both legs together until they point straight up, heels above the hips. Keep the legs long and active but let the feet stay soft. Let your head, shoulders, and lower back stay heavy on the floor. Soften the face and belly and breathe quietly. To exit, bend the knees and roll to one side before sitting up.","breathCue":"Long soft breaths; eyes soft.","avoidIf":["Glaucoma / unmanaged high ICP — keep legs lower"],"props":["Folded blanket under the hips","Thin cushion under the head"],"modifications":["Bend the knees slightly if hamstrings are tight","Rest the legs against a wall if holding them up gets tiring","Place a folded blanket under the hips"],"muscleCue":"Notice the contraction in your quadriceps and your hip flexors.","drishti":"up toward the toes","modificationNote":"Wall-free variation; the legs are held up by their own strength instead of resting against a wall.","muscles":["hamstrings","hip flexors","core (light)"]},"wind-removing":{"name":"Knees to Chest","goodFor":"Low-back relief and digestion support.","instructions":"Lie on your back with your head resting on the floor. Bend both knees and draw them in toward your chest. Wrap your hands around your shins and hold on. Let your feet relax and your shoulders stay soft. Breathe into your low back. To exit, release your feet down to the floor.","breathCue":"Exhale hug; inhale release slightly.","modifications":["Hold behind the thighs if the shins are out of reach","Work with one knee at a time","Rest your head on a folded blanket"],"props":[],"muscleCue":"Notice the stretch in your quadriceps and the muscles along your spine. Notice the contraction in your forearms and your hands.","drishti":"up at the ceiling","modificationNote":"A gentler take with knees drawn toward the chest rather than fully hugged in, and the head resting on the floor.","muscles":["hips","low back (passive)","core"]},"bow":{"name":"Bow Pose","goodFor":"Deep front-body stretch with back strength.","instructions":"Lie face-down with the forehead resting on the mat. Bend the knees and reach back to hold the feet or ankles. Press the feet into the hands to lift the chest and thighs off the mat. Lift the head and gaze forward, keeping the arms straight. Balance on the belly and breathe steadily. To exit, release the feet and lower down slowly.","breathCue":"Breathe deeply, inhale to lift, exhale to release","modifications":["Use a strap around the ankles","Hold one foot at a time for half bow","Keep thighs down, lift chest only"],"props":["yoga mat"],"muscleCue":"Notice the stretch in your quadriceps and your hip flexors. Notice the contraction in the muscles along your spine.","drishti":"Gaze forward, toward the tip of the nose","modificationNote":"hands grasp the tops of the feet rather than the ankles","muscles":["spinal extensors","quads","chest","hip flexors"]},"half-bow":{"name":"Half Bow","goodFor":"Stretches the quads and opens the chest while strengthening the back and glutes.","instructions":"Lie on your belly with your legs long and forehead down. Bend one knee and reach one hand back to hold the foot or ankle. Extend the other arm forward with the fingers active. On an inhale, lift your chest, the bent foot, and the extended leg. Keep the hips grounded and breathe steadily as you hold. To exit, release the foot slowly and lower down with control.","breathCue":"Inhale to lift, exhale to settle","modifications":["Keep the extended leg resting on the floor","Loop a strap around the ankle if the foot is out of reach","Stay low and lift only the chest and bent foot"],"props":["yoga strap"],"muscleCue":"Notice the stretch in your quadriceps. Notice the contraction in your glutes.","drishti":"forward and slightly down","modificationNote":"One hand holds a single bent foot while the other arm reaches forward, instead of gripping both feet as in full Bow.","muscles":["quads","spinal extensors","hip flexors"]},"childs":{"name":"Child's Pose","goodFor":"Rest, back release, and nervous-system downshift.","instructions":"Kneel with big toes touching and knees close together. Sit the hips back toward the heels and fold the torso forward over the thighs. Rest the forehead on the mat. Let the arms relax back along the sides with the hands near the feet. Soften the belly and jaw and breathe into the back ribs. To exit, walk the hands in and rise slowly to kneeling.","breathCue":"Breathe deeply into your belly","modifications":["Use block behind knees","Rest arms along sides","Keep hips on heels","Breathe deeply"],"props":["Block","Mat"],"muscleCue":"Notice the stretch in your quadriceps and your shins.","drishti":"Nasagrai or Nasagre (nose)","modificationNote":"arms extended to the back, palms up; toes pointed to the back","muscles":["hips","spinal erectors","shoulders (passive)"]},"cobra":{"name":"Cobra Pose","goodFor":"Back strength and chest opening.","instructions":"Lie face-down with the legs together and the tops of the feet on the floor. Place the hands beside the lower ribs, fingers spread. Press into the hands, straighten the arms, and lift the chest while the hips stay grounded. Roll the shoulders back and let the head tilt up, gazing forward. Breathe steadily, then lower the chest with control.","breathCue":"Inhale to lift, exhale to lower","modifications":["Use bolster under hips","Keep elbows bent","Lower onto the forearms","Lift only partway up"],"props":["Bolster"],"muscleCue":"Notice the stretch in your abdominals. Notice the contraction in the muscles along your spine.","drishti":"Forward and slightly upward","modificationNote":"palms on the floor, elbows bent","muscles":["spinal extensors","glutes","chest"]},"reverse-corpse":{"name":"Reverse Corpse","goodFor":"A calming full-body rest that eases the back and quiets the mind.","instructions":"Lie face-down on your mat with the legs stretched out behind you. Let the feet rest apart, heels dropping out with a little space between the calves. Open the arms out to the sides at a comfortable angle, palms facing down. Relax the shoulders, lower back, and neck, letting the head rest wherever it feels easy. Soften the face and belly and let the breath grow quiet and natural. To exit, roll gently to one side and pause before sitting up.","breathCue":"Breathe slowly and soften the belly with each exhale.","modifications":["Blanket under the chest or ankles for comfort","Folded blanket under the forehead for neck ease","Turn the head to one side if face-down feels awkward"],"props":["blanket"],"muscleCue":"Notice the contraction in the front of your shoulders and your triceps.","muscles":["full-body release"]},"puppy":{"name":"Puppy Pose","goodFor":"Shoulder and upper-back opening without a full child's pose.","instructions":"From all fours, walk the hands forward and let the chest sink toward the mat. Keep the hips lifted and let them drift back behind the knees instead of stacking. Rest the forehead on the mat. Arms stay long and straight with palms down. Soften the belly and breathe slowly. To exit, walk the hands back under the shoulders.","breathCue":"Exhale melt the chest; hips stay high.","props":["Mat","Blanket","Block"],"modifications":["Pad knees with a blanket","Rest forehead on a block","Keep hips lifted high"],"muscleCue":"Notice the stretch in your shins and the tops of your feet.","drishti":"Bhrumadhye or Ajna Chakra (third eye, between the eyebrows)","modificationNote":"Hips stay lifted and shift back behind the knees rather than stacking over them, with the arms held straight.","muscles":["shoulders","lats","spine","hips"]},"frog":{"name":"Frog Pose","goodFor":"Deep quad stretch and front-body opening.","instructions":"Lie on your belly and bend your knees. Reach back and press your hands down on the tops of your feet. Let your elbows lift as your chest rises forward and up. Keep your knees in line with your body and your hips pressing into the floor. Soften your neck, gaze forward and up, and breathe steadily.","breathCue":"Inhale to lift the chest, exhale to press the feet down","modifications":["Hold one foot at a time","Stay lower on your forearms","Use a strap if your hands cannot reach your feet"],"props":["Yoga mat"],"muscleCue":"Notice the stretch in your quadriceps and your shins. Notice the contraction in the muscles along your spine.","drishti":"forward and up","muscles":["quads","hip flexors","chest","shoulders"]},"locust-i":{"name":"Locust I Pose","goodFor":"Builds back-body strength and gently opens the chest.","instructions":"Lie face down with your forehead on the mat and your arms alongside your body, palms down. Point your toes and keep your feet together. On an inhale, lift your head, chest, and straight legs as high as feels good, keeping the pubic bone grounded. Reach back through your fingertips and keep your neck relaxed. Hold for a few breaths, then lower with control and rest.","breathCue":"Breathe deeply as you lift and lower","modifications":["Lift one leg at a time","Rest hands under thighs","Keep chest and legs lower","Move slowly with the breath"],"props":["Mat"],"muscleCue":"Notice the stretch in your chest and the front of your shoulders. Notice the contraction in your glutes and the muscles along your spine.","drishti":"forward","muscles":["spinal extensors","glutes","hamstrings","core","shoulders"]},"locust-ii":{"name":"Locust II Pose","goodFor":"Builds full back-body strength and opens the chest while lifting the chest and legs together.","instructions":"Lie face down with your palms on the floor under your shoulders and your legs stretched out behind you. Point your toes back and keep your feet together. On an inhale, press your hands down and lift your chest forward and up. At the same time, lift your straight legs back and up, hugging your thighs toward each other. Draw your shoulder blades down your back and keep your gaze forward. To exit, lower your chest and legs with control and rest.","breathCue":"Inhale to lift your chest and legs","modifications":["Lift chest only with legs down","Lift one leg at a time","Lower the legs slightly if the low back grips"],"props":[],"muscleCue":"Notice the stretch in your chest and the front of your shoulders. Notice the contraction in your glutes.","drishti":"forward","modificationNote":"Hands press into the floor under the shoulders while the chest and legs lift together","muscles":["spinal extensors","chest","shoulders"]},"locust-iii":{"name":"Locust III Pose","goodFor":"Builds gentle upper-back strength and opens the chest.","instructions":"Lie on your belly with your legs extended behind you and the tops of your feet resting on the mat. Stretch both arms forward past your head, about shoulder-width apart. On an inhale, gently lift your chest and arms off the floor while keeping the legs heavy. Lengthen through the crown of your head and keep your neck in line with your spine. Hold for a few easy breaths, then lower down with control.","breathCue":"Inhale to lift the chest, exhale to soften the shoulders","modifications":["Rest the forehead on the mat","Lift one arm at a time","Keep arms down and lift chest only"],"props":[],"muscleCue":"Notice the stretch in the sides of your back. Notice the contraction in your glutes and the muscles along your spine.","drishti":"Floor just ahead of you","modificationNote":"Unlike full locust, the legs stay resting on the mat here; only the chest and arms lift.","muscles":["spinal extensors","chest","shoulders"]},"sage-gherandas":{"name":"Sage Gheranda","goodFor":"Opens the chest, shoulders and thighs while building spinal and back strength.","instructions":"Lie face down with your forehead resting on the mat. Bend one knee out to the side and reach back with the same-side hand to hold that foot. Bend the other knee and lift that leg, reaching back with the other hand to grip the foot or ankle. Press the feet into the hands and lift the chest while keeping the hips grounded. Hold with steady breath, then release slowly and switch sides.","breathCue":"Inhale to lift the chest, exhale to settle into the hold","modifications":["Loop a strap around the foot if the toes are out of reach","Stay in half frog only and skip the bow leg","Rest the forehead on a folded blanket"],"props":["yoga strap","folded blanket"],"muscleCue":"Notice the stretch in your quadriceps and your hip flexors. Notice the contraction in your glutes and the muscles along your spine.","drishti":"forward on the floor ahead","modificationNote":"Unlike a plain bow or frog pose, one leg stays in a frog bend with the knee out wide while the other leg lifts in a bow, each hand holding its own foot.","muscles":["core","legs","postural muscles"]},"snake":{"name":"Snake Pose","goodFor":"Chest opening and upper-back strength without pressing into the hands.","instructions":"Lie face-down with the legs long and together and the tops of the feet on the mat. Reach both arms back alongside the hips with the palms turned toward each other. Rest the chin lightly on the floor to start. On an inhale, lift the chest and head using the back muscles and let the hands float back and up. Keep the legs grounded and the neck long as you hold. To exit, lower the chest slowly and rest a cheek on the mat.","breathCue":"Inhale to lift the chest, exhale to lower","modifications":["Lift only halfway","Rest the forehead down between breaths","Keep the hands lower if the shoulders pinch"],"props":["folded blanket under the hips for comfort"],"muscleCue":"Notice the stretch in your chest and the front of your shoulders. Notice the contraction in the muscles along your spine.","drishti":"forward","modificationNote":"Arms stay unclasped and reach back alongside the body instead of interlacing behind the back.","muscles":["spinal extensors","chest","shoulders","upper back"]},"sphinx":{"name":"Sphinx Pose","goodFor":"Gentle backbend; builds low-back awareness.","instructions":"Lie face-down with your legs long and together. Place your forearms on the floor with elbows under the shoulders, palms down and fingers spread. Press the forearms down to lift the chest gently. Keep the neck long and gaze forward. Soften the shoulders away from the ears. To exit, lower the chest and rest a cheek on the mat.","breathCue":"Easy inhale into the low belly and chest.","modifications":["Use a block under the chest or forearms","Lower the chest partway for less backbend","Move elbows slightly forward to ease the back"],"props":[],"muscleCue":"Notice the stretch in your abdominals. Notice the contraction in the muscles along your spine.","drishti":"Forward, level with the floor","muscles":["spinal extensors","chest","core"]},"tortoise":{"name":"Tortoise Pose","goodFor":"Deep forward fold and shoulder release.","instructions":"Sit with the legs spread wide apart and the feet flexed. Fold forward between the thighs, lengthening the spine on an inhale. Let the arms reach out to the sides, palms down, or slide them under the knees. Press the heels forward and straighten the knees fully. Rest the chin or forehead on the floor and soften the shoulders away from the ears. Breathe steadily, then bend the knees to ease out slowly.","breathCue":"Breathe rhythmically, inhale to lengthen, exhale to fold","modifications":["Support head with hands or a block","Bend knees and slide arms underneath","Sit on a folded blanket if hips are tight","Slide legs closer to ease arms out"],"props":[],"muscleCue":"Notice the stretch in your hamstrings.","drishti":"Down toward the floor","muscles":["hamstrings","adductors","shoulders","back"]},"table":{"name":"Table Pose","goodFor":"Grounding reset and joint-friendly support; settles core, legs, postural muscles.","instructions":"Come onto hands and knees with the hands flat under the shoulders. Rest the knees and shins on the floor, hips sitting a little behind the knees. Let the lower back keep a gentle dip and soften the elbows. Spread the fingers and press the floor away. Look forward and slightly down. Breathe steadily, then sit back to Child or move into your next pose.","breathCue":"Neutral steady breath.","modifications":["Use a folded blanket under knees","Use a bolster under hips for support","Bend knees slightly if hips are tight"],"props":["Folded blanket"],"muscleCue":"Notice the stretch in your shins and the tops of your feet. Notice the contraction in the front of your shoulders and your triceps.","drishti":"forward and slightly down","muscles":["core","legs","postural muscles"]},"camel":{"name":"Camel Pose","goodFor":"Deep front-body stretch and heart opening.","instructions":"Kneel with the knees hip-width apart and the tops of the feet on the floor, toes pointing straight back. Press the hips forward so they stack over the knees and lift the chest up high. Reach the hands down to the heels and let the head drop back if the neck feels fine. Keep the thighs engaged and breathe slowly. To exit, bring the hands to the low back and lift the chest to come upright.","breathCue":"Breathe in to lift chest, out as you deepen the backbend.","modifications":["Hands on low back","Use blocks beside feet","Tuck toes under","Keep head neutral"],"avoidIf":["Neck injury — keep chin slightly tucked, no dropping head"],"props":["Blocks","Wall"],"muscleCue":"Notice the stretch in your shins and the tops of your feet. Notice the contraction in your glutes and your forearms.","drishti":"Up toward the ceiling as the head drops back","muscles":["quads","hip flexors","spinal extensors","chest"]},"cat":{"name":"Cat Pose","goodFor":"Spinal mobility and breath-linked movement.","instructions":"Start on hands and knees, shoulders over wrists, hips over knees. On an exhale, round the spine toward the ceiling, tuck the tailbone, and let the head drop toward the navel. Press the floor away to spread the shoulder blades. In a routine, Cat alternates with Cow, one breath each. To exit, return to a neutral tabletop spine.","breathCue":"Breathe deeply and slowly","modifications":["Use blanket under knees","Use block under hands"],"props":[],"muscleCue":"Notice the stretch in your forearms. Notice the contraction in the front of your shoulders and your triceps.","drishti":"toward the navel","muscles":["core","spinal flexors"]},"cow":{"name":"Cow Pose","goodFor":"Spinal extension and chest opening paired with Cat.","instructions":"Start on hands and knees, shoulders over wrists, hips over knees. On an inhale, drop the belly, tip the tailbone up, and lift the chest and gaze slightly forward. Keep the shoulders wide and away from the ears and the back of the neck long. In a routine, Cow alternates with Cat, one breath each. To exit, return to a neutral tabletop spine.","breathCue":"Inhale deeply, gaze forward, exhale gently","modifications":["Use blocks under hands","Blanket under the knees","Keep the arch gentle"],"props":["Mat"],"muscleCue":"Notice the contraction in the front of your shoulders and your triceps.","drishti":"Forward, just above eyeline","muscles":["spinal extensors","chest"]},"dolphin":{"name":"Dolphin Pose","goodFor":"Builds shoulder and upper back strength while stretching the hamstrings.","instructions":"Start on all fours, then lower the elbows to the mat under the shoulders. Keep the forearms parallel with palms flat and fingers spread. Tuck the toes, lift the hips, and walk the feet in a little. Straighten the legs into an inverted V and let the heels reach toward the mat. Draw the navel in, relax the neck, and breathe steadily.","breathCue":"Long exhales; neck soft.","modifications":["Bend the knees if the hamstrings are tight","Come down to forearms and knees to rest","Clasp the hands for more stability"],"props":["yoga mat"],"muscleCue":"Notice the stretch in the sides of your back. Notice the contraction in the front of your shoulders and your triceps.","drishti":"toward the toes","modificationNote":"Same inverted V as downward dog but resting on the forearms instead of the hands.","muscles":["shoulders","core","hamstrings","upper back"]},"downward-facing-dog":{"name":"Downward-Facing Dog Pose","goodFor":"Upper-body and core load with long-line strength; works core, legs, postural muscles.","instructions":"From hands and knees, tuck the toes and lift the hips high into an inverted V. Walk the hands forward and stretch the arms long, letting the chest melt down. Straighten the legs and press the thighs back, feet hip-width apart. Let the head hang heavy between the arms, close to the floor. Press evenly into the palms and keep the belly drawn in. To exit, drop the knees.","breathCue":"Long soft breaths; jaw relaxed.","modifications":["Bend knees to keep back long","Keep feet hip-width apart","Microbend elbows for comfort","Gaze at navel to relax the neck"],"deepen":["Press thighs back; heels toward floor without forcing"],"avoidIf":["Uncontrolled high blood pressure — keep head higher"],"commonMistakes":["Rounded upper back","Dumping into shoulders"],"alignmentCues":["Hands shoulder-width","Hips reach up and back"],"props":["blocks under hands","blanket under heels"],"muscleCue":"Notice the stretch in your hamstrings and your calves.","drishti":"Navel or tops of the thighs","modificationNote":"Arms reach far forward so the chest and head sink lower toward the floor","muscles":["core","legs","postural muscles"]},"eight-point":{"name":"Eight-Point Pose","goodFor":"Gently builds upper-body strength and prepares you for low push-up and cobra.","instructions":"Start in a plank or on all fours with hands under the shoulders. Bend the elbows and lower the chest toward the floor. Let the knees, chest and chin touch down while the hips stay lifted. Keep the toes tucked and the elbows close to the ribs. Relax the neck and breathe steadily as you hold.","breathCue":"Exhale as you lower knees, chest and chin","modifications":["Slide a folded blanket under the knees","Lower knees and chest first, then the chin","Keep the chest a little higher if it feels too deep"],"props":["Folded blanket under the knees"],"muscleCue":"Notice the stretch in your forearms. Notice the contraction in the front of your shoulders and your triceps.","drishti":"floor slightly ahead","modificationNote":"A gentler version of low push-up (chaturanga) with knees, chest and chin resting down instead of hovering.","muscles":["chest","triceps","core","shoulders"]},"humble-flamingo":{"name":"Humble Flamingo Pose","goodFor":"Builds single-leg balance, hip mobility, and hamstring flexibility.","instructions":"Stand tall and shift your weight onto one foot. Hinge forward at the hips, letting your torso drape down along the standing leg. Reach both hands toward the floor and keep the standing knee soft. Lift the other leg behind you and bend the knee so the foot rises. Breathe steadily as you balance, then rise and lower the foot to exit.","breathCue":"Exhale as you fold, then breathe steadily as you balance.","modifications":["Rest fingertips on yoga blocks","Keep the back leg lower to the floor","Practice near a wall for balance support"],"props":["yoga blocks under the hands","wall nearby for support"],"muscleCue":"Notice the stretch in your hamstrings. Notice the contraction in your quadriceps and your hip flexors.","drishti":"floor beside the standing foot","modificationNote":"A gentler flamingo variation: hands reach to the floor instead of holding the lifted foot.","muscles":["core","hamstrings","glutes","ankles","postural muscles"]},"gate":{"name":"Gate Pose","goodFor":"Side-body length and breathing space.","instructions":"Kneel, then extend one leg out to the side with the foot grounded. Reach the same-side arm down the extended leg; top arm arcs overhead. Keep the hips square-ish to the front. Soften the side waist. To exit, bring the torso upright and draw the extended knee back in.","breathCue":"Breathe normally, inhale to lift, exhale to deepen","modifications":["Hand on hip or behind head","Rest hand on shin or a block","Use a block under the knee","Lean less far to the side"],"props":[],"muscleCue":"Notice the stretch in your hip flexors and your inner thighs. Notice the contraction in your quadriceps and the front of your shoulders.","drishti":"Up toward the raised hand","muscles":["obliques","adductors","lats","intercostals"]},"horse":{"name":"Horse Pose","goodFor":"Opens the hips and quads while building balance and focus.","instructions":"Kneel down and step one foot forward, placing it flat with the knee over the ankle. Let the back knee rest on the floor with the shin behind you. Square the hips and lift the chest tall. Cross the forearms in front of the face and press the palms together, then raise the hands overhead. Hold for a few steady breaths, then switch sides.","breathCue":"Inhale to lift the palms, exhale to settle the hips.","modifications":["Pad the back knee with a blanket","Hold a wall for balance","Keep the palms at the chest before lifting"],"props":["Blanket under the back knee","Wall nearby for support"],"muscleCue":"Notice the stretch in your shins and the tops of your feet. Notice the contraction in your quadriceps.","drishti":"Angushtamadhye or Angushta Ma Dyai (thumbs)","muscles":["quads","hips","ankles","core"]},"lizard":{"name":"Lizard Pose","goodFor":"Intense hip and groin opening.","instructions":"From a low lunge, place both hands on the floor inside the front foot. Lower onto your forearms with elbows under the shoulders. Let the front toes turn out slightly. Keep the back leg long and strong with the back knee lifted. Breathe into the inner hip. To exit, press into your hands and step back.","breathCue":"Exhale ease hips forward within comfort.","props":["blocks under hands","blanket under back knee"],"modifications":["Use forearms or hands for support","Place front foot beside forearm","Keep hips level and chest forward","Use blocks under hands if needed"],"muscleCue":"Notice the stretch in your calves and the soles of your feet. Notice the contraction in the front of your shoulders and your triceps.","drishti":"hands or the earth ahead","modificationNote":"Forearms rest on the mat instead of the hands for a deeper hip opening.","muscles":["hip flexors","adductors","hamstrings"]},"lunge":{"name":"Classic Lunge","goodFor":"Transitional lunge used in sun salutations.","instructions":"Step one foot forward between the hands with the back leg long and strong (heel up). Stack the front knee over the ankle. Hands frame the front foot or lift. Keep the hips level and the spine long. Breathe steadily. To exit, step the front foot back or rise to standing.","breathCue":"Inhale length; exhale settle the hips.","modifications":["Lower the back knee to the mat","Rest hands on blocks","Shorten the stance"],"alignmentCues":["Front knee tracks over ankle","Back heel stacked under toes"],"props":["mat"],"muscleCue":"Notice the stretch in your hip flexors and your inner thighs. Notice the contraction in your quadriceps.","drishti":"forward","muscles":["hip flexors","quads","glutes","hamstrings"]},"crooked-monkey":{"name":"Crooked Monkey Pose","goodFor":"Builds mobility, strength, and awareness for Crooked Monkey Pose.","instructions":"From a lunge or arm-balance prep, arrange the legs in the crooked-monkey bind and lean onto the hands to lift if available. Soften the elbows. To exit, lower and release the bind carefully.","muscles":["core","legs","postural muscles"]},"pigeon":{"name":"Pigeon Pose","goodFor":"Deep hip opening; prep for seated poses.","instructions":"Come onto the floor and slide one knee forward so the front shin folds under your chest with the heel near the groin. Extend the other leg straight behind you with the top of the thigh resting down and the toes pointed. Square both hips to the front of the mat. Rest your hands lightly on the floor or on the front leg and lift the chest. Lengthen the spine, keep the shoulders soft, and breathe deeply.","breathCue":"Breathe deeply through the pose, hips square forward","modifications":["Place a block under the front hip","Keep hands on the mat","Start from a low lunge","Keep the back leg resting on the mat"],"props":["mat","block"],"muscleCue":"Notice the stretch in your hip flexors and your shins.","drishti":"forward","modificationNote":"Upright prep version with the back leg resting on the floor and hands free, no foot hold or backbend.","muscles":["hip external rotators","hip flexors","glutes"]},"one-legged-king-pigeon":{"name":"One Legged King Pigeon Pose","goodFor":"Opens tight hips and quads while building a deeper, healthier backbend.","instructions":"From Half Pigeon, bend the back knee and reach for the foot with one or both hands (use a strap). Gently kick into the hand to open the chest. Keep the front hip supported. To exit, release the back foot first, then step back to Down Dog.","breathCue":"Inhale to lift the chest, exhale to draw the foot closer.","modifications":["Use strap behind heel","Place block under thigh","Place blocks under hands","Use wall for support"],"props":["strap","block","wall"],"muscleCue":"Notice the stretch in your quadriceps and your hip flexors. Notice the contraction in the sides of your waist.","drishti":"upward","modificationNote":"Deepens pigeon by bending the back knee and holding the lifted foot with the hands for a full backbend.","muscles":["hips","hamstrings","core"]},"plank":{"name":"Plank Pose","goodFor":"Core endurance and shoulder stability.","instructions":"From hands and knees or a push-up position, stack shoulders over wrists and step the feet back. Form one long line from heels to crown. Press the floor away; draw the navel gently in. Legs strong; heels reaching back. Soften the jaw and breathe steadily. To exit, lower the knees or move into Chaturanga or Down Dog.","breathCue":"Steady breath; do not hold the breath.","modifications":["Place hands on forearms","Drop the knees to the floor","Practice with hands on a wall or bench"],"deepen":["Push the floor away; one long line"],"avoidIf":["Acute wrist pain — use fists or forearms"],"commonMistakes":["Hips sagging","Shoulders dumping toward ears"],"alignmentCues":["Press mounds of the index fingers","Draw navel gently in"],"props":["Yoga mat"],"muscleCue":"Notice the stretch in the soles of your feet and your forearms. Notice the contraction in the front of your shoulders and your triceps.","drishti":"Down at the mat between the hands","muscles":["core","shoulders","quads","glutes"]},"upward-plank":{"name":"Upward Plank","goodFor":"Posterior-chain strength and front-body stretch.","instructions":"Sit with your legs extended and place your hands behind your hips, fingertips pointing toward your heels. Press into your palms and heels to lift the hips until shoulders, hips and heels form one line. Keep the heels grounded and let the toes pull up toward you. Let the head release back and gaze upward. Hold, then lower the hips and sit.","breathCue":"Inhale as you press down and lift the hips","modifications":["Bend the knees and place feet flat for reverse table","Keep the hips a little lower for less load","Turn fingertips away from the heels if wrists complain"],"props":[],"muscleCue":"Notice the stretch in your forearms. Notice the contraction in the front of your shoulders and your triceps.","drishti":"Upward, toward the sky","modificationNote":"heels stay down with toes pulled up instead of pointed feet","muscles":["glutes","hamstrings","shoulders","triceps","core"]},"four-limbed-staff":{"name":"Four Limbed Staff Pose","goodFor":"Builds strength and endurance through the arms, wrists and core.","instructions":"From plank, bend the elbows straight back along the ribs and lower until they reach about ninety degrees. Keep the whole body in one straight line from head to heels, hovering above the floor. Stay broad across the chest with the shoulders level with the elbows and away from the ears. Engage the core, legs and glutes and keep the head neutral, gaze down. Exhale as you lower. To exit, lower all the way down or press back up to plank or upward dog.","breathCue":"Exhale to lower with control.","modifications":["Knees on the floor","Lower only partway down","Loop a strap around the upper arms","Hands on blocks to raise the floor"],"avoidIf":["Shoulder impingement flare"],"commonMistakes":["Elbows winging out","Collapsing chest"],"alignmentCues":["Elbows hug ribs","Shoulders at elbow height"],"props":[],"muscleCue":"Notice the stretch in your forearms. Notice the contraction in the front of your shoulders and your triceps.","drishti":"Nasagrai or Nasagre (nose)","muscles":["hips","hamstrings","core"]},"flying-warrior":{"name":"Flying Warrior Pose","goodFor":"Deeply opens the hamstrings and hips while building side-body, core, and shoulder strength.","instructions":"From a wide stance, bend one knee and plant the same-side hand on the floor beside it. Let that knee sink toward the floor as the other leg reaches straight out to the side, foot planted. Sweep the far arm up and over your head to hold the lifted foot. Keep the planted arm long and let your torso fold heavy over the extended leg. To exit, release the foot and press back up to center.","breathCue":"Exhale slowly as you fold deeper over the extended leg","modifications":["Loop a strap around the foot to reach it","Keep the bent knee resting on the floor","Hold the shin or ankle instead of the foot","Bend the extended knee slightly if tight"],"props":["Mat"],"muscleCue":"Notice the stretch in your hamstrings. Notice the contraction in the sides of your waist and your forearms.","drishti":"Gaze down toward the floor past the extended leg","modificationNote":"knee on the floor, grabbing onto the outside edge of the foot","muscles":["core","legs","postural muscles"]},"side-plank":{"name":"Side Plank","goodFor":"Lateral core strength and shoulder stability.","instructions":"From plank, roll onto the outer edge of one foot and stack the other foot on top. Keep both legs straight as the hips lift into one long diagonal line. Plant the bottom hand firmly under the shoulder. Extend the top arm straight up toward the ceiling. Hold with steady breath, then return to plank to exit.","breathCue":"Exhale as you lift the hips","modifications":["Use wall for balance","Lower the bottom knee for support","Stagger the feet for extra stability"],"props":[],"muscleCue":"Notice the stretch in your forearms. Notice the contraction in your outer hips and the sides of your waist.","drishti":"Angushtamadhye or Angushta Ma Dyai (thumbs)","modificationNote":"both legs straight with feet stacked and top arm extended straight up","muscles":["obliques","shoulders","glutes","wrists"]},"extended-side-plank":{"name":"Extended Side Plank","goodFor":"Builds lateral core and shoulder strength while opening the side body.","instructions":"Come into a side plank with the bottom hand under the shoulder and both legs long and stacked. Press the floor away and lift the hips so the body forms one strong diagonal line. Reach the top arm up and overhead, extending the whole side body. Let the head follow the arm and gaze up. Hold with steady breath, then lower the arm and return to side plank or plank.","breathCue":"Inhale as you reach the top arm overhead","modifications":["Drop the bottom knee to the floor","Keep the top hand on the hip","Practice against a wall for balance"],"props":[],"muscleCue":"Notice the stretch in your forearms. Notice the contraction in your outer hips and the sides of your waist.","drishti":"up toward the top hand","modificationNote":"Top arm reaches overhead instead of pointing straight up, deepening the side-body stretch compared with regular side plank.","muscles":["obliques","shoulders","adductors","glutes"]},"inverted-staff":{"name":"Inverted Staff Pose","goodFor":"Opens the chest and shoulders while building back, leg, and core strength.","instructions":"Lie on your back with knees bent and feet flat near your hips. Press up into a bridge, then lower the crown of your head to the floor behind you. Bend your elbows and rest your forearms on the floor, cradling the back of your head. Walk the feet away and straighten the legs, lifting the hips and chest into a smooth arch. Press the forearms down and breathe steadily. To exit, bend the knees, lower the hips, and roll down slowly.","breathCue":"Inhale to lift the chest, exhale to press the forearms down.","modifications":["Stay in bridge pose with hips on a block","Rest the mid-back on a bolster for a supported version","Bend the knees to make the arch gentler"],"props":["Folded blanket under the head","Strap around the upper arms to hold elbow alignment"],"muscleCue":"Notice the stretch in your hip flexors and the front of your neck. Notice the contraction in the front of your shoulders and your triceps.","drishti":"Bhrumadhye or Ajna Chakra (third eye, between the eyebrows)","muscles":["hips","hamstrings","core"]},"little-thunderbolt":{"name":"Little Thunderbolt","goodFor":"Deep kneeling backbend.","instructions":"Come to the floor and set up Little Thunderbolt with even pressure in the hands, knees, or hips. Lengthen the spine before adding effort. Move into the shape on an exhale if it closes the body, or an inhale if it opens the chest. Keep the jaw and shoulders soft. To exit, lower with control and pause in a neutral rest before continuing.","muscles":["quads","hip flexors","spinal extensors","throat"]},"tiger":{"name":"Tiger Pose","goodFor":"Spinal mobility and glute activation.","instructions":"Start on hands and knees in a tabletop position. Spread the fingers and press evenly into both hands. On an inhale, arch the back down like in cow pose and bend one knee, lifting the foot up and back toward your head. Keep the hips level and stacked over the kneeling leg, with the shoulder lined up over the wrist. Let the gaze follow the curve of the spine, looking forward. Hold for a breath or two, then lower the leg with control back to tabletop.","breathCue":"Inhale as you arch and lift the foot, then breathe steadily.","modifications":["Keep the lifted foot lower","Lift less from the kneeling knee","Practice the arch in cat-cow first"],"props":["Mat","Hand towel"],"muscleCue":"Notice the stretch in your quadriceps and your hip flexors. Notice the contraction in your glutes.","drishti":"Forward, following the curve of the spine","muscles":["glutes","spinal extensors","shoulders","core"]},"upward-facing-dog":{"name":"Upward-Facing Dog Pose","goodFor":"Opens the chest and shoulders while strengthening the arms and the muscles along the spine.","instructions":"Lie on your front with the tops of your feet pressing into the mat and your hands under your shoulders. Press down and straighten your arms to lift your chest and head. Roll your shoulders back and down, away from your ears. Keep your hips, thighs and knees resting on the floor as you open the chest. Tilt your head back to gaze up if your neck is comfortable, and hold while breathing steadily.","breathCue":"Inhale to press up and open the chest","modifications":["bend the elbows and lower into cobra","keep the gaze forward if looking up strains the neck","come down and rest if the lower back pinches"],"avoidIf":["Acute lumbar pain — prefer cobra"],"commonMistakes":["Shoulders shrugged","Feet lazy"],"alignmentCues":["Tops of feet press down","Thighs lift"],"props":[],"muscleCue":"Notice the stretch in your forearms. Notice the contraction in the muscles along your spine.","drishti":"toward the ceiling","modificationNote":"The hips, thighs and knees stay resting on the floor instead of lifting off, so this works like a straight-arm high cobra rather than a full up dog.","muscles":["chest","shoulders","triceps","spine","abdomen","glutes"]},"wheel":{"name":"Wheel Pose","goodFor":"Deep backbend strength and chest opening.","instructions":"Lie on your back, bend the knees, place hands by the ears with fingers toward the shoulders. Press into hands and feet to lift into an arch. Soften the neck; keep weight even. Breathe steadily — do not hold the breath. To exit, tuck the chin slightly and lower with control onto the shoulders then back.","breathCue":"Breathe deeply and rhythmically through your nose","modifications":["Lift into bridge first, then add arms","Use a wall for support","Rest the crown of the head on the floor first"],"avoidIf":["Uncontrolled high blood pressure","Wrist injury","Pregnancy"],"props":["Mat"],"muscleCue":"Notice the stretch in your forearms and the front of your neck. Notice the contraction in your glutes.","drishti":"Toward the mat between the hands","muscles":["glutes","shoulders","spinal extensors","quads","wrists"]},"wild-thing":{"name":"Wild Thing","goodFor":"Heart opening with shoulder and hip strength.","instructions":"Come into a side plank and roll the chest open toward the sky. Step the free foot behind you and plant it flat on the floor, keeping the other foot planted as well. Press the supporting hand firmly down and let the hips rise into a backbend. Reach the free arm overhead and let the head hang back with no tension in the neck. Hold the open chest for a few breaths, then lower back to side plank with control.","breathCue":"Breathe deeply into the chest as you lift and open.","modifications":["Stay in side plank and skip the backbend","Bend the front knee more","Shorten the reach of the top arm","Look down toward the floor to ease the neck"],"props":["Wrist support"],"muscleCue":"Notice the stretch in your forearms. Notice the contraction in your quadriceps and your outer hips.","drishti":"Bhrumadhye or Ajna Chakra (third eye, between the eyebrows) or Hastagrai or Hastagre (hands)","modificationNote":"Back foot stays flat on the floor with the heel down instead of resting on the ball of the foot with the heel lifted","muscles":["shoulders","glutes","spinal extensors","hip flexors"]},"both-feet-behind-the-head-ii":{"name":"Both Feet Behind the Head II Pose","goodFor":"Develops deep hip and spinal flexibility while building core and arm strength.","instructions":"Sit on the floor and lean back slightly to lift both legs. Place one foot behind the head, then the other, using the hands for help. Press the palms into the floor beside the hips and straighten the arms to lift the chest. Balance on the sit bones and breathe steadily. To exit, release one foot at a time with the hands.","breathCue":"Inhale to lift the chest, exhale to soften the neck.","modifications":["Work with one foot behind the head first","Sit near a wall for support","Practice gentler hip openers until ready"],"props":[],"muscleCue":"Notice the stretch in your hip flexors. Notice the contraction in your glutes.","drishti":"forward","modificationNote":"In this variation the hands press into the floor beside the hips to support and lift the torso, instead of staying free as in the base pose.","muscles":["core","legs","postural muscles"]},"chin-stand":{"name":"Chin Stand Pose","goodFor":"Strengthens the back, neck, shoulders, and arms while building balance and deep backbend mobility.","instructions":"Start on all fours and place your chin on the mat with your hands flat beside your shoulders. Shift your weight forward so your hands and chin take the load. Engage your core and lift your legs up and overhead one at a time. Keep your shoulders drawn back and away from your ears. Point your toes and straighten your legs toward the ceiling. To exit, lower your legs slowly with control.","breathCue":"Exhale as you lift your legs, then breathe steadily while balancing","modifications":["Shoulders on blocks","Elbows on wrists","Bend knees, feet toward head","Engage hamstrings to pull feet low"],"props":["Blocks","Wrist support","Mat"],"muscleCue":"Notice the stretch in your hip flexors. Notice the contraction in the front of your shoulders and your triceps.","drishti":"Gaze forward along the mat","muscles":["back","neck","shoulders","triceps","wrists","core"]},"crane":{"name":"Crane Pose","goodFor":"Builds straight-arm strength and a steady forward lean on the path to the full crane balance.","instructions":"From a squat, plant the hands shoulder-width apart and straighten the arms. Rise onto the toes and wedge the knees high on the backs of the upper arms. Lean forward, letting the hips lift high and the back round gently. Keep the toes resting light on the mat behind and let the gaze drop to the floor. To exit, shift the weight back and lower the heels into a squat.","breathCue":"Steady, even breaths; gaze soft and down.","modifications":["Use blocks under the shoulders","Place the knees on the triceps","Rest a blanket under the head"],"avoidIf":["Wrist pain"],"props":["Blocks","Mat","Triceps"],"muscleCue":"Notice the stretch in your inner thighs. Notice the contraction in the front of your shoulders and your triceps.","drishti":"Down to the floor","modificationNote":"straight arms, deep forward lean with toes resting on the mat","muscles":["shoulders","core","wrists"]},"crow":{"name":"Crow Pose","goodFor":"Arm balance strength and focus.","muscles":["core","shoulders","wrists","hip flexors"]},"deaf-mans":{"name":"Deaf Man's Pose","goodFor":"Eases stress and fatigue while deeply stretching the spine, shoulders, and neck.","instructions":"Lie on your back and lift your hips up and over your head into plow pose. Bend both knees and lower them until they rest beside your ears. Place your feet flat on the floor behind your head. Stretch both arms straight along the floor above your head with hands open and relaxed. Let your weight rest on your shoulders and head while your gaze softens toward your nose. Breathe slowly and hold the fold.","breathCue":"Exhale as your knees settle beside your ears","modifications":["Use a blanket under the shoulders","Stay in plow pose with legs straight","Keep the knees higher, away from the ears","Rest the feet against a wall"],"props":["Mat"],"muscleCue":"Notice the stretch in the top of your shoulders.","drishti":"Nasagra or Nasikagra (tip of the nose)","muscles":["hamstrings","spinal erectors","shoulders"]},"eight-angle":{"name":"Eight Angle Pose","goodFor":"Builds arm, core and hip strength with a deep side-body twist.","instructions":"Plant the hands shoulder-width apart and bend the elbows slightly. Hook one thigh high across the upper arm and let the other leg reach straight out to the side. Twist through the torso and lower the chest and head toward the floor. Keep the top knee bent with the foot lifted and the bottom leg long and active. Press evenly through the palms and breathe steadily. To exit, lift the chest and swing both legs back down.","breathCue":"Exhale as you twist and lower, then breathe steadily.","modifications":["Keep a toe lightly touching the floor for support","Place a block under the hips to reduce load","Bend the bottom knee if the reach is too much"],"props":[],"muscleCue":"Notice the stretch in your hamstrings and your outer hips. Notice the contraction in your quadriceps and your hip flexors.","drishti":"Nasagrai (nose tip) or down to the floor","modificationNote":"Legs stay uncrossed in this variation: the top knee stays bent with the foot lifted while the bottom leg extends straight, and the hips sit lower with the head angled down.","muscles":["core","legs","postural muscles"]},"elbow-balance":{"name":"Elbow Balance Pose","goodFor":"Arm balance strength and focus; challenges spinal extensors, chest, shoulders.","instructions":"Kneel and place your forearms on the floor shoulder-width apart, then lift into a forearm balance, using a wall behind you if needed. Once steady, cup your chin in your hands so the weight rests on your elbows. Keep both legs straight and together as you reach the feet toward the ceiling. Press the elbows down and lift through the shoulders to stay light and steady. To exit, lower one foot at a time back to the floor.","breathCue":"Inhale to lengthen the legs, exhale to steady the elbows","modifications":["Practice against a wall for support","Lift one leg at a time before taking both up","Use a folded blanket under the forearms"],"props":["wall","folded blanket"],"muscleCue":"Notice the stretch in the front of your neck.","drishti":"Bhrumadhye or Ajna Chakra (third eye, between the eyebrows)","muscles":["spinal extensors","chest","shoulders"]},"elephant-trunk":{"name":"Elephant Trunk Pose","goodFor":"Builds deep core strength, balance, and focus while opening the hips.","instructions":"Sit tall and hook one leg as high over the upper arm as you can. Squeeze that leg into the arm and plant both hands on the floor. Press into the palms, engage the core, and lift the hips as the other leg reaches straight forward. Keep the gaze forward and let the straight leg hover just above the floor. To exit, lower the hips and release the leg.","breathCue":"Exhale as you press down and lift","modifications":["Place blocks under hands","Lift hips first with straight leg","Work leg up arm gradually"],"props":["Blocks","Mat"],"muscleCue":"Notice the stretch in your shins and the tops of your feet. Notice the contraction in your quadriceps and your hip flexors.","drishti":"Forward gaze, out over the straight leg","muscles":["core","legs","postural muscles"]},"firefly":{"name":"Firefly Pose","goodFor":"Builds arm and core strength while lengthening the hamstrings and hip flexors.","instructions":"From a squat, plant your hands on the mat and walk your shoulders under your thighs. Shift your weight into your palms and lift your hips off the floor. Straighten your legs out wide to the sides and straighten the arms. Press firmly through the palms and gaze forward. To exit, bend the knees and lower the feet back down.","breathCue":"Exhale as you lift your hips","modifications":["Walk feet in to tippy toes","Lower hips toward mat"],"props":["Mat"],"muscleCue":"Notice the stretch in your hamstrings and your forearms. Notice the contraction in your quadriceps and your hip flexors.","drishti":"Forward and slightly up","muscles":["shoulders","core","hip flexors","wrists"]},"floating-stick":{"name":"Floating Stick Pose","goodFor":"Builds arm and core strength while stretching the backs of the legs.","instructions":"Sit on the floor with both legs extended straight in front. Place the palms flat on the floor beside the hips. Press the hands down and lean the torso slightly forward, keeping the back long. Let the head relax and gaze softly down. Keep the legs active and breathe steadily as you hold.","breathCue":"Exhale as you press the hands down and lean forward","modifications":["bend the knees slightly","rest the fingertips on the floor only","sit on a folded blanket"],"props":["folded blanket under the hips"],"muscleCue":"Notice the contraction in your quadriceps and your hip flexors.","drishti":"Nasagrai or Nasagre (nose)","modificationNote":"grounded version with hips and legs resting on the floor while the hands press down","muscles":["core","legs","postural muscles"]},"flying-man":{"name":"Flying Man Pose","goodFor":"Builds arm, wrist, and core strength along with balance and focus.","instructions":"Come into a low squat and plant the hands shoulder width apart, fingers spread wide. Bend the elbows to about ninety degrees and hug them in toward each other. Hook one knee over the back of the upper arm and tip your weight forward into the hands. Reach the other leg straight back and up, squeezing the hips toward the midline. Keep the core engaged and the gaze steady forward as you breathe. To exit, lower the back leg and then the front foot down with control.","breathCue":"Exhale as you lean forward and lift the back leg.","modifications":["Set up from side crow with the knee on the arm","Keep the back toe on the floor at first","Bend the back knee if needed"],"props":["Mat"],"muscleCue":"Notice the stretch in your hamstrings and your hip flexors. Notice the contraction in your quadriceps and your glutes.","drishti":"forward","muscles":["core","legs","postural muscles"]},"revolved-flying-man":{"name":"Revolved Flying Man Pose","goodFor":"Builds mobility, strength, and awareness for Revolved Flying Man Pose.","instructions":"Come to the floor and set up Revolved Flying Man Pose with even pressure in the hands, knees, or hips. Lengthen the spine before adding effort. Move into the shape on an exhale if it closes the body, or an inhale if it opens the chest. Keep the jaw and shoulders soft. To exit, lower with control and pause in a neutral rest before continuing.","muscles":["core","legs","postural muscles"]},"two-legged-sage-koundinyas":{"name":"Two-Legged Koundinya's Pose","goodFor":"Builds mobility, strength, and awareness for Two-Legged Koundinya's Pose","instructions":"From a twisted arm-balance prep, plant the hands, hook both legs over one upper arm, and lean forward to lift. Gaze forward; elbows soft. To exit, lower the feet and untwist.","muscles":["core","legs","postural muscles"]},"side-crow":{"name":"Side Crow","goodFor":"Builds twisting core strength, shoulder stability and focus.","instructions":"From a low squat, twist your torso and plant both hands shoulder-width apart. Lean your weight forward and lift the hips. Stretch both legs out to one side and cross the ankles. Keep the arms straight and let the whole body hover. Gaze forward and breathe steadily. To exit, lower the feet back down with control.","breathCue":"Exhale as you lift and extend the legs","modifications":["Keep one big toe on the floor","Bend the knees toward one arm first","Use blocks under the hands"],"props":[],"muscleCue":"Notice the stretch in your outer hips and the deep muscles of your hips. Notice the contraction in the front of your shoulders and your triceps.","drishti":"forward","modificationNote":"Twisted Crow with legs extended straight to one side and ankles crossed instead of knees resting on the arms","muscles":["obliques","shoulders","wrists","core"]},"forearm-balance":{"name":"Forearm Balance","goodFor":"Inversion strength and shoulder stability.","instructions":"From hands and knees, place the elbows under the shoulders with the forearms parallel and the palms down. Tuck the toes, lift the hips, and walk the feet in toward the elbows. Reach one leg toward the ceiling, then kick up gently and draw the other leg up to meet it. Stack the shoulders over the elbows, engage the core, and reach both legs up in one straight line. Breathe steadily as you hold, then lower one leg at a time and rest.","breathCue":"Exhale as you press down, then keep the breath slow and steady as you hold","modifications":["Use a wall for support","Kick up one leg at a time","Hold with the feet resting on the wall"],"props":["Wall"],"muscleCue":"Notice the contraction in the front of your shoulders and your triceps.","drishti":"floor between the hands","muscles":["shoulders","core","upper back","glutes"]},"dragonfly":{"name":"Dragonfly Pose","goodFor":"Builds arm, wrist and core strength while opening the hips and stretching the inner legs.","instructions":"Sit with one leg extended out to the side and the other knee bent, ankle resting on the extended leg near the knee. Plant both hands on the floor shoulder-width apart with fingers spread. Bend the elbows and lean forward over the hands, letting the chest lower toward the floor as you press down to lift the hips. Keep the elbows hugging in and the head relaxed, gaze down at the floor. To exit, lower the hips back down with control.","breathCue":"Exhale as you press down and lift the hips","modifications":["Keep the hips lower and lift only partway","Slide the bent foot closer to the extended knee for support","Bend the extended knee slightly if the hamstring feels tight"],"props":[],"muscleCue":"Notice the stretch in your quadriceps and your hamstrings. Notice the contraction in your glutes and the front of your shoulders.","drishti":"down toward the floor","modificationNote":"The bent foot rests on the extended leg instead of hooking over the back of the upper arm, and the elbows bend to lower the chest toward the floor.","muscles":["core","legs","postural muscles"]},"handstand":{"name":"Handstand","goodFor":"Full inversion strength and proprioception.","instructions":"Start in Downward Dog with hands shoulder-width apart. Walk the feet in and kick one leg up, then bring the other to meet it. Stack the hips over the shoulders and squeeze the legs together. Keep the arms straight and press the floor away. Let the head hang between the arms and gaze down at the floor. To exit, lower one leg at a time with control.","breathCue":"Exhale as you kick up, then breathe steadily","modifications":["Practice heel pulls at a wall","Use a spotter for the hips","Try chest-to-wall handstand holds"],"props":["Wall for support","Mat for wrist comfort"],"muscleCue":"Notice the contraction in the front of your shoulders and your triceps.","drishti":"down at the floor between the hands","muscles":["shoulders","core","wrists","glutes"]},"supported-headstand":{"name":"Supported Headstand","goodFor":"Builds upper-body strength, balance, and focus.","instructions":"Kneel down and place your forearms on the floor with elbows about shoulder-width apart. Rest the crown of your head on the floor between your forearms. Walk your feet in until your hips come over your shoulders. Engage your core and lift both legs up together until they stack over your pelvis. Point your toes and reach up through the balls of your feet. Breathe steadily, then lower down with control when you're ready.","breathCue":"Exhale as you lift the legs, then breathe slowly and evenly.","modifications":["Use a wall for support","Try dolphin pose to build strength","Keep knees bent if balance feels shaky"],"props":[],"muscleCue":"Notice the contraction in the front of your shoulders and your triceps.","drishti":"tip of the nose","muscles":["shoulders","core","upper back","arms"]},"tripod-headstand":{"name":"Tripod Headstand","goodFor":"Builds upper-body and core strength, balance and calm focus.","instructions":"Kneel and place your palms flat on the mat in front of your knees. Set the crown of your head on the mat so your head and hands form a triangle. Tuck your toes, lift your hips and walk your feet in toward your chest. Rest your knees on the backs of your upper arms, or lift straight up if you feel steady. Extend your legs toward the sky and squeeze your inner thighs together. Stack hips over shoulders, press firmly into your hands and breathe steadily.","breathCue":"Inhale as you lift, then keep long slow breaths while you hold.","modifications":["keep knees bent and walk feet in","rest knees on the upper arms before lifting","practice near a wall for safety"],"props":["wall for support","folded blanket under the head"],"muscleCue":"Notice the stretch in your forearms. Notice the contraction in the front of your shoulders and your triceps.","drishti":"tip of the nose","modificationNote":"Unlike the classic supported headstand, the hands stay flat on the mat with elbows bent at right angles, so the head and hands form a triangle instead of the head being cradled by interlaced fingers.","muscles":["core","legs","postural muscles"]},"flying-lizard":{"name":"Flying Lizard Pose","goodFor":"Builds mobility, strength, and awareness for Flying Lizard Pose.","instructions":"Come to the floor and set up Flying Lizard Pose with even pressure in the hands, knees, or hips. Lengthen the spine before adding effort. Move into the shape on an exhale if it closes the body, or an inhale if it opens the chest. Keep the jaw and shoulders soft. To exit, lower with control and pause in a neutral rest before continuing.","muscles":["core","legs","postural muscles"]},"peacock":{"name":"Peacock Pose","goodFor":"Builds intense core and wrist strength while toning the abdominal organs.","instructions":"Kneel and sit between your heels, then place your palms on the floor just in front of your knees with fingers pointing forward. Bend your elbows and rest your upper abdomen on the backs of your upper arms. Lean forward and lower your head toward the floor, keeping your belly pressed firmly into the elbows. Stretch one leg out behind you, then the other, toes pointing back. Press through your hands to lift your whole body into one horizontal line, head hanging low with your gaze on the floor. Breathe steadily and hold.","breathCue":"Breathe deeply and rhythmically through the nose","modifications":["Knees down, sit between heels","Keep elbows wider apart if the belly won't reach","Rest forehead on the floor before lifting","Stretch one leg back at a time"],"props":["Mat"],"muscleCue":"Notice the stretch in your forearms. Notice the contraction in the front of your shoulders and your triceps.","drishti":"Downward, toward the floor","modificationNote":"1. feet lifted higher than the hip level","muscles":["core","wrists","shoulders","arms","back","legs"]},"pendant":{"name":"Pendant Pose","goodFor":"Builds arm and core strength while training steady focus under effort.","instructions":"Come onto hands and knees and cross your ankles, tucking the feet in behind you. Place the palms on the floor just wider than shoulder distance with fingers spread. Round the back slightly and draw the knees in toward the chest. Squeeze the core and press the floor away so the feet lift off the ground. Keep the neck long as an extension of the spine and hold with an easy breath. To exit, lower the feet back down with control.","breathCue":"Exhale to lift the feet, then breathe steady.","modifications":["Knees bent toward chest","Draw heels closer to hips","Keep feet on ground"],"props":[],"muscleCue":"Notice the stretch in your forearms. Notice the contraction in your hands.","drishti":"Nasagrai or Nasagre (nose)","modificationNote":"knees in front of chest, ankles crossed","muscles":["core","legs","postural muscles"]},"flying-pigeon":{"name":"Flying Pigeon Pose","goodFor":"Builds arm and core strength while opening the outer hips and sharpening focus.","instructions":"Start standing and cross one ankle over the opposite thigh in a figure four. Fold forward and hook that foot around your upper arm, squeezing it in place. Plant your hands on the floor and bend the elbows like a low push-up. Shift your weight into your palms as the back leg lifts up and back. Keep the core strong, elbows over wrists, and gaze at one spot on the mat. To exit, lower the back foot down with control.","breathCue":"Exhale as you lean in and lift the back leg.","modifications":["Use chair for support","Keep knee resting on elbow","Start with bent back knee","Use strap to assist foot grip"],"props":["Chair","Mat","Wrist pad"],"muscleCue":"Notice the stretch in your forearms. Notice the contraction in the front of your shoulders and your triceps.","drishti":"a fixed spot on the mat slightly ahead of the hands","muscles":["core","legs","postural muscles"]},"plow":{"name":"Plow Pose","goodFor":"Posterior stretch and calming inversion.","instructions":"Lie on your back with your arms flat on the floor beside you. Lift your legs over your head and lower your toes toward the floor behind you. Keep your knees straight and your legs together. Let your arms stay stretched out flat on the floor behind your back. Keep your neck soft and breathe slowly. To exit, roll down slowly with bent knees.","breathCue":"Breathe rhythmically and deeply into your abdomen","modifications":["Use elbows for support","Keep knees bent","Place hands on lower back","Keep legs close"],"avoidIf":["Neck injury","Glaucoma"],"props":["blanket under shoulders"],"muscleCue":"Notice the stretch in the muscles along your spine.","drishti":"Navel, or eyes closed softly","modificationNote":"arms extended flat on the floor behind the back","muscles":["hamstrings","spinal extensors","shoulders","core"]},"rooster":{"name":"Rooster Pose","goodFor":"Builds wrist, arm and core strength while sharpening balance and opening the hips.","instructions":"Sit in lotus with each foot resting on the opposite thigh. Thread your arms through the gap between thighs and calves until your palms reach the floor. Spread your fingers and press down firmly. Lean your chest forward and lift your crossed legs off the ground. Straighten the arms, keep back and head in one line, and gaze forward while balancing.","breathCue":"Exhale to lift, then breathe steadily while balancing","modifications":["Rest knees on the backs of the arms before lifting","Place blocks under the palms to raise the floor","Use half lotus if full lotus is not available"],"props":["yoga blocks"],"muscleCue":"Notice the stretch in the deep muscles of your hips and your forearms. Notice the contraction in your hands.","drishti":"forward on a fixed point","muscles":["wrists","forearms","shoulders","core","hip flexors"]},"scorpion":{"name":"Scorpion Pose","goodFor":"Inversion practice for orientation and shoulder strength; loads core, legs, postural muscles.","instructions":"Set up on the forearms with the hands shoulder-width apart and fingers spread. From a steady headstand base, bend the knees and arch the back, letting the feet travel over toward the head. Lower the crown of the head toward the floor and keep the gaze down. Keep the legs together with the toes pointed and breathe steadily. To exit, return to a straight headstand and lower down with control.","breathCue":"Breathe deeply and rhythmically through the nose","modifications":["Straight legs variation","Feet to head variation","Start with headstand step 8","Hold for shorter time"],"props":["Forearms","Fingers","Headstand base"],"muscleCue":"Notice the stretch in your quadriceps and your hip flexors. Notice the contraction in the front of your shoulders and your triceps.","drishti":"Down toward the floor between the hands","muscles":["core","legs","postural muscles"]},"shoulder-pressing":{"name":"Shoulder Pressing Pose","goodFor":"Arm balance: thighs squeeze the upper arms while the feet lift.","instructions":"From a deep squat with the knees wide, lean the chest forward between the thighs. Press the palms into the floor about shoulder-width apart and hook the backs of the thighs as high on the arms as you can. Bend the knees, lean forward, and shift the weight into the hands. Squeeze the thighs against the upper arms and lift the feet off the floor. Cross the ankles in front and point the toes. Keep the core tight and gaze down at the nose tip or the floor.","breathCue":"Exhale as you lift the feet","modifications":["Use blocks under the hands","Keep the toes lightly on the floor","Rest the knees lower on the arms"],"props":[],"muscleCue":"Notice the stretch in the deep muscles of your hips and your forearms. Notice the contraction in your quadriceps and your hip flexors.","drishti":"Tip of the nose (nasagrai) or the floor","muscles":["shoulders","wrists","arms","core","hips"]},"shoulder-stand-with-lotus-legs":{"name":"Shoulder Stand with Lotus Legs Pose","goodFor":"Builds mobility, strength, and awareness for Shoulder Stand with Lotus Legs Pose.","instructions":"Sit tall on the sit bones — use a folded blanket if the low back rounds. Arrange the legs for Shoulder Stand with Lotus Legs Pose, then lengthen the spine on an inhale before folding, twisting, or binding. Soften the shoulders away from the ears. Breathe steadily; ease out of any sharp sensation. To exit, release binds first, then uncross or straighten the legs slowly.","muscles":["hips","hamstrings","core"]},"supported-shoulder-stand":{"name":"Supported Shoulder Stand Pose","goodFor":"Calms the mind, boosts circulation, and builds core and shoulder strength while stretching the neck.","instructions":"Lie on your back with your arms alongside your body. Lift your legs up and over so your hips come off the floor, then support your lower back with your hands. Walk your elbows closer together and keep your weight on your shoulders and upper arms, not your neck. Straighten your legs toward the ceiling and press up through the balls of your feet. Tuck your chin slightly and keep your neck still while you breathe. To exit, lower your legs slowly with control.","breathCue":"Soft free breath; never turn the head.","modifications":["Use hands for support","Place hands on heels","Keep hips over shoulders"],"avoidIf":["Neck injury","Glaucoma","Menstruation (traditional caution)","Pregnancy"],"props":["Folded blanket","Wall"],"muscleCue":"Notice the stretch in the top of your shoulders and your chest.","drishti":"Toes or feet","muscles":["core","legs","postural muscles"]},"bound-revolved-chair":{"name":"Bound Revolved Chair Pose","goodFor":"Builds mobility, strength, and awareness for Bound Revolved Chair Pose.","instructions":"From Chair, bring hands to the heart and twist the torso to one side, hooking the opposite elbow outside the thigh. Press the arm into the leg to deepen the twist; lengthen the spine on each inhale. Soften the knees evenly. Gaze past the shoulder. To exit, untwist to center and straighten the legs.","muscleCue":"Notice the stretch in your chest and the front of your shoulders. Notice the contraction in your quadriceps.","drishti":"Urdhva or Antara Drishti (up to the sky)","modificationNote":"bottom arm wraps under both thighs and clasps the top hand behind the back","muscles":["core","legs","postural muscles"]},"forward-fold":{"name":"Standing Forward Fold","goodFor":"Hamstring length, calming the nervous system, gentle inversion.","muscles":["hamstrings","calves","spinal erectors"]},"halfway-lift":{"name":"Halfway Lift","goodFor":"Spinal length and preparing for folds or standing poses.","muscles":["hamstrings","back extensors","core"]},"warrior-1":{"name":"Warrior I","goodFor":"Hip opening, leg strength, and chest expansion.","muscles":["quads","glutes","hip flexors","shoulders"]},"warrior-2":{"name":"Warrior II","goodFor":"Stamina, hip mobility, and shoulder endurance.","muscles":["quads","adductors","glutes","shoulders"]},"warrior-3":{"name":"Warrior III","goodFor":"Balance, posterior-chain strength, and focus.","muscles":["standing-leg glutes","hamstrings","core","ankles"]},"reverse-warrior":{"name":"Reverse Warrior","goodFor":"Opens and stretches the side body while the legs keep working.","instructions":"From Warrior II, keep the front knee bent and slide the back hand down the back leg. Reach the front arm up and slightly back, opening the side body. Soften the neck; gaze up only if comfortable. Front knee stays tracking over the ankle. To exit, return the torso upright to Warrior II.","breathCue":"Breathe evenly, inhale to lift chest, exhale to deepen the pose","modifications":["Rest lower hand on back thigh","Keep gaze forward instead of up","Stay closer to Warrior II with a gentler lean"],"props":["Yoga mat"],"muscleCue":"Notice the stretch in your inner thighs. Notice the contraction in your quadriceps.","drishti":"Hastagrai or Hastagre (hands)","modificationNote":"A variation of Warrior II: torso leans back, top arm arcs overhead, lower hand slides down the back leg","muscles":["obliques","quads","shoulders","hip flexors"]},"wide-forward-fold":{"name":"Wide-Legged Forward Fold","goodFor":"Inner-thigh and hamstring stretch; calming forward fold.","muscles":["hamstrings","adductors","calves","spinal erectors"]},"standing-split":{"name":"Standing Split","goodFor":"Hamstring length, balance, and mild inversion.","muscles":["hamstrings","hip flexors","shoulders","core"]},"down-dog":{"name":"Downward-Facing Dog","goodFor":"Full-body reset, shoulder strength, and posterior-chain stretch.","muscles":["shoulders","hamstrings","calves","core"]},"up-dog":{"name":"Upward-Facing Dog","goodFor":"Back strength, chest opening, and counterpose to folds.","muscles":["spinal extensors","chest","triceps","glutes"]},"chaturanga":{"name":"Four-Limbed Staff","goodFor":"Arm and core strength for vinyasa transitions.","muscles":["triceps","chest","core","shoulders"]},"tabletop":{"name":"Tabletop","goodFor":"Neutral alignment base for floor work.","muscles":["core","shoulders","wrists"]},"thread-needle":{"name":"Thread the Needle","goodFor":"Upper-back release and gentle thoracic twist.","instructions":"From all fours, stretch one leg straight back behind you. Slide the opposite arm under your chest, palm facing up. Keep the other hand planted and turn your head to gaze out to the side. Let the twist open across the upper back. To come out, press into the supporting hand and untwist back to all fours.","breathCue":"Exhale thread the arm; inhale space between blades.","modifications":["Keep both knees down","Rest a bolster under the hips","Use a blanket under the knee"],"props":["Yoga mat"],"muscleCue":"Notice the stretch in your outer hips and your inner thighs. Notice the contraction in the front of your shoulders and your triceps.","drishti":"out to the side","modificationNote":"One leg stays stretched straight back instead of both knees resting down.","muscles":["rear shoulders","rhomboids","obliques"]},"locust":{"name":"Locust Pose","goodFor":"Posterior-chain strength for posture.","muscles":["spinal extensors","glutes","hamstrings","shoulders"]},"supine-twist":{"name":"Supine Twist","goodFor":"Spinal mobility and low-back release."},"knees-to-chest":{"name":"Knees to Chest","goodFor":"Low-back relief and digestion support.","muscles":["hips","low back (passive)"]},"figure-four":{"name":"Reclined Figure Four","goodFor":"Outer-hip and IT-band region release.","instructions":"Lie on your back. Cross one ankle over the opposite thigh. Thread the hands behind the uncrossed thigh (or over the shin) and draw the legs in. Keep the head and shoulders relaxed on the mat. Soften the jaw. To exit, release the legs and switch, or plant the feet.","breathCue":"Exhale soften the hips toward the floor.","modifications":["Keep the supporting foot on the floor if hips are tight","Use a strap behind the thigh to pull gently","Blanket under the head for comfort"],"props":["strap around shin"],"muscleCue":"Notice the stretch in the deep muscles of your hips and the muscles along your spine. Notice the contraction in your forearms and your hands.","drishti":"Bhrumadhye or Ajna Chakra (third eye, between the eyebrows)","muscles":["piriformis","glutes","outer hips"]},"butterfly":{"name":"Butterfly Pose","goodFor":"Inner-thigh stretch and hip mobility.","muscles":["adductors","hips","low back"]},"seated-forward-fold":{"name":"Seated Forward Fold","goodFor":"Hamstring length and calming forward fold."},"wide-seated-fold":{"name":"Wide-Angle Seated Fold","goodFor":"Wide-leg flexibility and inner-thigh stretch.","instructions":"Sit on the floor with your legs spread wide and feet flexed, toes pointing up. Inhale to lengthen your spine, then hinge forward from the hips. Walk your hands forward and lower your forearms to the floor, clasping your hands. Let your torso sink down between your legs and relax your head toward the floor. Keep your sit bones grounded and your legs active. To exit, walk your hands back and slowly roll up with a long spine.","breathCue":"Exhale as you fold forward and release down","modifications":["Rest your chest on blocks","Keep hands on the floor or shins","Sit on a folded blanket for tight hips"],"props":["Yoga mat","Blocks","Folded blanket"],"muscleCue":"Notice the stretch in your hamstrings and your inner thighs.","drishti":"toward the floor","muscles":["adductors","hamstrings","hips"]},"seated-twist":{"name":"Seated Twist","goodFor":"Spinal mobility and digestive massage.","instructions":"Sit on the floor with both legs extended. Bend one knee and cross that foot over the other leg, setting it flat on the floor outside the opposite thigh. Place the opposite hand on the floor behind you and press the other elbow against the outside of the bent knee. Inhale to lengthen the spine, then exhale and twist toward the bent knee, gazing over your back shoulder. Keep the sitting bones grounded and chest lifted as you hold.","breathCue":"Breathe deeply through nose, exhale as you twist","modifications":["Sit on a bolster or folded blanket","Hold the bent knee with the hand instead of pressing the elbow","Ease the twist and gaze forward"],"props":["bolster","blanket"],"muscleCue":"Notice the stretch in your outer hips and your inner thighs. Notice the contraction in the front of your shoulders and your triceps.","drishti":"Over the back shoulder, in the direction of the twist","modificationNote":"Bottom leg stays extended straight instead of bent with the heel by the opposite buttock","muscles":["obliques","spinal rotators","hips"]},"legs-up-wall":{"name":"Legs-Up-the-Wall","goodFor":"Great for recovery, easing tired legs, and calming the nervous system.","instructions":"Sit sideways next to a wall with one hip close to it. Lie back and swing your legs up so your heels rest against the wall. Scoot your hips close to the wall and let your arms relax out to the sides, palms facing up. Soften your neck and shoulders and let your whole back settle into the floor. Stay here breathing slowly and deeply into your belly. To come out, bend your knees, push gently off the wall, and roll onto your side.","breathCue":"Inhale into the belly, exhale and soften","modifications":["Place a folded blanket under the hips","Bend knees slightly and rest soles on the wall","Move hips further from the wall if hamstrings feel tight"],"props":["folded blanket","bolster","eye pillow"],"muscleCue":"Notice the contraction in your quadriceps and your hip flexors.","muscles":["hamstrings (passive)","pelvic floor (relax)"]},"reclining-butterfly":{"name":"Reclining Butterfly","goodFor":"Restorative hip opening and stress relief.","instructions":"Lie on your back. Bend the knees and bring the soles of the feet together, letting the knees fall open. Rest the arms a little away from the body with the palms facing up. Support the outer thighs with blankets if needed. Soften the belly and breathe slowly. To exit, use the hands to close the knees and roll to one side.","breathCue":"Breathe into any tension in the inner thighs","modifications":["Place a block under each knee","Roll a towel under the neck","Rest a bolster along the spine","Support outer thighs with blankets"],"props":["block","bolster","towel"],"muscleCue":"Notice the stretch in your inner thighs.","drishti":"Eyes closed, or a soft gaze up at the ceiling","modificationNote":"Reclined on the back instead of seated, with the arms relaxed away from the body and palms up","muscles":["adductors","hips","chest (passive)"]},"easy-seat":{"name":"Easy Seat","goodFor":"Meditation seat and gentle hip opening.","muscles":["hips","postural back","core"]},"half-split":{"name":"Half Splits","goodFor":"Targeted hamstring stretch with knee support.","muscles":["hamstrings","calves","hip flexors"]},"shoulder-stand":{"name":"Shoulder Stand","goodFor":"Inversion benefits, thyroid stimulation tradition, core strength.","muscles":["core","shoulders","spinal extensors","glutes"]},"revolved-chair":{"name":"Revolved Chair","goodFor":"Leg strength with detoxifying twist.","instructions":"Come into a deep chair squat with the hips low and the feet close. Bring the palms together in front of the chest. Twist to one side and hook the opposite elbow outside the other knee. Press the palms together and turn the chest up toward the sky. Keep the knees in line and level with each other. Breathe steadily, then return to center and repeat on the other side.","breathCue":"Exhale to twist deeper, inhale to lengthen the spine","modifications":["Stay higher in the squat with hands in prayer at the chest","Rest a hand on a wall for balance","Skip the twist and hold a plain chair pose"],"props":[],"muscleCue":"Notice the stretch in your outer hips and your inner thighs. Notice the contraction in your quadriceps.","drishti":"Urdhva or Antara Drishti (up to the sky)","modificationNote":"deep chair with the knees together, hands in prayer at the chest, opposite elbow hooked outside the knees, chest turning up","muscles":["quads","obliques","glutes","core"]},"supine-hand-to-toe":{"name":"Supine Hand to Big Toe","goodFor":"Controlled hamstring stretch with pelvic stability.","muscles":["hamstrings","calves","hip flexors"]},"crescent":{"name":"Crescent Lunge","goodFor":"Hip-flexor stretch with energizing lift.","muscles":["hip flexors","quads","glutes","shoulders"]},"hand-to-big-toe":{"name":"Standing Hand to Big Toe","goodFor":"Hamstring length with balance and focus."},"extended-hand-to-big-toe":{"name":"Extended Hand to Big Toe","goodFor":"Outer-hip opening with single-leg balance.","muscles":["hamstrings","adductors","standing-leg glutes","core"]},"head-to-knee":{"name":"Head to Knee","goodFor":"Stretches the hamstrings and hips while calming the body and mind.","instructions":"Sit on the floor with both legs stretched out in front of you. Bend one knee out to the side and tuck the foot in against the inner thigh of the straight leg. Lengthen your spine, then hinge from the hips to fold forward over the extended leg. Let your hands hold the foot or rest along the leg, keeping your torso square over the straight leg. Breathe slowly, hold for a few breaths, then gently rise back up to sit.","breathCue":"Inhale to lengthen, exhale to fold","modifications":["Hold shin or use a strap around foot","Rest extended foot on a block","Sit on a folded blanket to lift hips","Fold halfway with hands to shin"],"props":["strap","blocks","folded blanket"],"muscleCue":"Notice the stretch in your inner thighs. Notice the contraction in your forearms and your hands.","drishti":"toes of the extended foot","muscles":["hamstrings","low back","hips"]},"marichi":{"name":"Marichi's Forward Bend","goodFor":"Forward fold with a shoulder bind stretch."},"marichi-twist":{"name":"Marichi's Twist","goodFor":"Seated twist for spinal mobility and digestion."},"crow-kakasana":{"name":"Crow (Kakasana)","goodFor":"Builds arm and core strength while training balance and body awareness.","instructions":"Squat down and place the palms flat on the floor, shoulder-width apart with fingers spread. Bend the elbows and hook the knees onto the backs of the upper arms. Lean your weight forward into the hands and grip the floor. Engage the core and lift the feet off the floor, squeezing the knees in. Keep the gaze a few feet ahead and breathe steadily as you hold.","breathCue":"Exhale as you lift the feet off the floor","modifications":["rest toes on a block before lifting","place a cushion under the face","lift one foot at a time first"],"props":["block","blanket"],"muscleCue":"Notice the stretch in your forearms. Notice the contraction in the front of your shoulders and your triceps.","drishti":"the floor about three feet ahead","modificationNote":"arms straight and knees high near the armpits, unlike the classic bent-elbow crow","muscles":["core","shoulders","wrists","hip flexors"]},"wide-forward-side":{"name":"Side Wide-Legged Fold","goodFor":"Hamstring stretch with lateral body length.","muscles":["hamstrings","obliques","adductors"]},"revolved-wide-fold":{"name":"Revolved Wide-Legged Fold","goodFor":"Wide-leg fold with a twist.","muscles":["hamstrings","obliques","shoulders"]},"upward-plank-prep":{"name":"Upward Plank Prep","goodFor":"Builds toward full Upward Plank.","instructions":"Come to the floor and set up Upward Plank Prep with even pressure in the hands, knees, or hips. Lengthen the spine before adding effort. Move into the shape on an exhale if it closes the body, or an inhale if it opens the chest. Keep the jaw and shoulders soft. To exit, lower with control and pause in a neutral rest before continuing."},"sage-marichis-ii":{"name":"Sage Marichi's II Pose","goodFor":"Hip opening with a forward fold and bind.","description":"One foot in half lotus, the other foot planted. Fold forward, wrapping the arm around the bent shin.","instructions":"Sit tall on your sit bones, on a folded blanket if your low back rounds. Bend one knee and plant that foot close to your hip. Tuck the other foot into half lotus on top of the opposite thigh. Lengthen your spine, then fold forward over the planted foot. Wrap both arms around the bent leg and clasp your hands behind your back. Breathe steadily, then release the bind and unfold slowly.","breathCue":"Exhale as you fold, breathe steady in the bind.","modifications":["Bind the bent leg, other foot flat on the mat","Fold halfway, other foot flat on the mat","Hold the bent knee, other leg in half lotus","Bind the bent leg, other leg in half lotus"],"props":["Folded blanket under the sit bones"],"muscleCue":"Notice the stretch in your quadriceps and the deep muscles of your hips.","drishti":"Padagre (tip of the big toe)","modificationNote":"Adds a half lotus leg to the base Marichyasana forward fold; the other knee is bent with the foot planted by the hip.","muscles":["hips","hamstrings","shoulders"]},"sage-marichis-iii":{"name":"Sage Marichi's III Pose","goodFor":"Seated twist for spinal mobility and digestion.","description":"One leg extended, the other foot planted. Twist toward the bent knee, hugging it with the opposite arm.","instructions":"Sit with one leg extended and the other foot planted close to the pelvis. Inhale to lengthen the spine. Exhale and twist toward the bent knee, hooking the opposite arm around it. Reach the other arm behind the back. Keep both sit bones grounded and gaze over the back shoulder. To exit, untwist and switch sides.","breathCue":"Exhale to twist; inhale to lengthen the spine.","modifications":["Sit on a folded blanket","Hold the knee instead of wrapping the arm","Rest the back hand on the floor for support"],"avoidIf":["Late pregnancy — skip deep closed twists"],"props":[],"muscleCue":"Notice the stretch in your chest and the front of your shoulders. Notice the contraction in the sides of your waist.","drishti":"Parshva Drishti (to the left)","modificationNote":"Twisting variation of Sage Marichi's pose with one leg extended and the opposite arm wrapped around the bent knee.","muscles":["obliques","spinal rotators","hips"]},"sage-marichis-iv":{"name":"Sage Marichi's IV Pose","goodFor":"Advanced seated twist and hip opener.","description":"Combine half lotus with a deep seated twist and optional bind. Move slowly and keep both sit bones grounding.","instructions":"Sit tall on your sit bones, using a folded blanket if your low back rounds. Bend one knee and plant that foot close to your buttock, then tuck the other foot into half lotus on top of the opposite thigh. Inhale to lengthen the spine, then twist toward the bent knee. Wrap one arm around the bent knee and reach the other arm behind your back to clasp hands or a wrist. Keep the chest broad, shoulders soft, and breathe steadily for a few breaths. To exit, release the bind first, then slowly unfold the legs.","breathCue":"Inhale to lengthen, exhale to deepen twist","modifications":["Use a strap for the bind","Sit on a folded blanket","Hold knee instead of binding","Stay upright with a gentler twist"],"props":["Mat"],"muscleCue":"Notice the stretch in your chest and the front of your shoulders. Notice the contraction in your quadriceps and your hip flexors.","drishti":"Parshva Drishti (to the right), Parshva Drishti (to the left)","modificationNote":"Adds half lotus on one leg and a full arm bind to the base seated Marichyasana twist.","muscles":["hips","obliques","shoulders"]},"cross-legged-forward-fold":{"name":"Cross-Legged Forward Fold","goodFor":"Gentle hip and back release from a seated fold (Easy Seat without the fold stays as Easy Pose).","description":"Sit in a comfortable cross-legged position. Lengthen your spine as you inhale, then hinge at the hips to fold forward, walking your hands out in front of you.","muscleCue":"Notice the stretch in the muscles along your spine.","muscles":["hips","low back","outer hips","spinal erectors"]},"knee-lift":{"name":"Knee Lift","goodFor":"Simple standing balance and hip flexion warm-up.","description":"Stand with feet together. Lift one foot off the floor. Lock your hands around your shin as you lift your knee to your chest. Switch sides.","muscleCue":"Notice the stretch in your hip flexors. Notice the contraction in your outer hips.","muscles":["hip flexors","core","balance"]},"kneeling":{"name":"Kneeling","goodFor":"Neutral transition between floor and standing work.","description":"Kneel on the mat. Keep your back straight and roll your shoulders away from your ears. Hands on the hips.","instructions":"Kneel on the mat with your knees about hip-width apart and the tops of your feet flat on the floor behind you. Stack your hips over your knees and lengthen your spine into a tall, straight line. Roll your shoulders back and down, away from your ears. Reach both hands behind you and rest them on your lower back. Keep your gaze soft and forward as you breathe steadily. To come out, bring your hands forward and rise up or sit back down.","breathCue":"Inhale to grow tall, exhale to soften the shoulders.","modifications":["Rest hands on hips instead of the lower back","Place a cushion under the knees","Widen the knees slightly for comfort"],"props":[],"muscleCue":"Notice the stretch in your shins and the tops of your feet. Notice the contraction in your glutes.","drishti":"forward","muscles":["quads","core","postural back"]},"morning-stretch":{"name":"Morning Stretch","goodFor":"Gentle wake-up lengthening before or after floor work.","description":"Lie on your back. Place your arms on the mat above your head. Gently stretch your hands and fingers away from your feet and toes.","instructions":"Lie flat on your back with legs extended and arms resting on the floor overhead, palms up or down as comfortable. Keep the spine long and let the hips settle evenly into the mat. Soften the shoulders away from the ears and relax the back of the neck. Reach gently through the fingertips and the heels in opposite directions. Breathe deeply through the nose, letting each exhale release tension. To exit, lower the arms to the sides, roll onto your side, and push up to sit.","breathCue":"Inhale to lengthen, exhale to soften","modifications":["Bend the knees with feet flat if the back complains","Rest a folded blanket under the head","Take the arms a little wider if the shoulders strain"],"props":["Folded blanket under the head","Bolster under the knees"],"muscleCue":"Notice the contraction in your glutes.","muscles":["side body","shoulders","hip flexors","whole front line"]},"opened-knee-lift":{"name":"Opened Knee Lift","goodFor":"Balance with a mild standing hip opener.","description":"Stand with feet together. Lift one foot off the floor so your knee is in line with your hips. Grab that knee with the same-side hand and gently take the leg outwards. Place the opposite hand on the hip. Switch sides.","muscles":["outer hips","hip flexors","core"]},"reclined-bent-knees":{"name":"Reclined Bent Knees","goodFor":"Neutral rest that eases the low back more than flat-leg Corpse for many bodies.","description":"Lie flat on your back. Bend your knees and place the soles of your feet on the floor hip-width apart.","muscleCue":"Notice the stretch in your chest and the front of your shoulders. Notice the contraction in your quadriceps and your hip flexors.","muscles":["low back (passive)","hips","nervous system"]},"seated-cactus-arms":{"name":"Seated Cactus Arms","goodFor":"Seated chest and shoulder opener; pairs well with breath work.","description":"Sit tall with feet grounded or legs crossed. Raise arms to cactus, elbows at 90°, forearms vertical. Draw shoulders down as you broaden the chest.","instructions":"Sit on the floor with legs crossed and spine tall. Extend both arms out to the sides and lift them up into a wide V. Bend the elbows so the forearms angle upward and turn the palms forward. Draw the shoulders down away from the ears and broaden the chest. Keep the neck long and gaze forward. To exit, lower the arms slowly and relax the shoulders.","breathCue":"Inhale to lift the arms, exhale to soften the shoulders","modifications":["Sit on a folded blanket for hip comfort","Keep hands lower if shoulders are tight","Rest back against a wall for support"],"props":["Folded blanket under the hips","Wall for back support"],"muscleCue":"Notice the stretch in your shins and the tops of your feet. Notice the contraction in your shoulders.","drishti":"forward","modificationNote":"Seated cross-legged version of the classic cactus arms.","muscles":["chest","shoulders","upper back","postural muscles"]},"standing-back-bend":{"name":"Standing Back Bend","goodFor":"A deep standing backbend that opens the chest, shoulders, and front of the body.","description":"Stand tall with feet grounded. Place your hands together and reach overhead. Lift your chest and gently arch through your upper back while keeping your core engaged and legs strong.","instructions":"Stand with your feet together and legs strong. On a breath in, sweep your arms up overhead and let them reach back behind your head. Press your hips gently forward and arch through the whole spine, keeping your weight even in both feet. Lift your chest and let your head release back so your gaze floats upward. Breathe steadily and hold the arch without pinching the lower back. To come out, engage your core and sweep your arms down to stand tall.","breathCue":"Inhale as you reach up and arch back.","modifications":["Bend arms and place palms behind hips for support","Soften the knees a little","Stand near a wall for balance"],"props":[],"muscleCue":"Notice the stretch in the sides of your back.","drishti":"upward, toward the sky","muscles":["spinal extensors","chest","hip flexors","core"]},"standing-side-bend":{"name":"Standing Side Bend","goodFor":"Opens the side body and improves flexibility through the waist and ribs.","description":"Stand tall with feet hip-width apart. Raise both arms overhead and interlace your fingers. Slowly bend your upper body to one side, keeping your chest open and your hips square. Switch sides.","instructions":"Stand tall with your feet together and legs straight. Reach both arms overhead, keeping them about shoulder-width apart with palms facing each other. Lift your chest and let your head tilt back slightly, gazing gently upward. Keep your hips steady and bend your upper body softly to one side. Breathe slowly as you hold the stretch, then rise back to center.","breathCue":"Inhale to reach up, exhale to bend to the side.","modifications":["Rest one hand on your hip for a lighter stretch","Stand with feet hip-width apart for balance","Bend less and keep the head neutral"],"props":[],"muscleCue":"Notice the stretch in the sides of your waist and your lower back. Notice the contraction in your glutes.","drishti":"gaze gently upward","modificationNote":"A variation of Mountain Pose with the arms overhead and a bend to one side from the waist.","muscles":["obliques","side body","shoulders","intercostals"]},"breath-dirga":{"name":"Three-Part Breath","goodFor":"Calms the mind and body and prepares you for other breathing practices.","instructions":"Sit cross-legged on the floor with your spine tall and hands resting on your knees. Soften your shoulders, jaw, and belly. Inhale in one smooth wave from the belly into the ribs and then the upper chest. Exhale from the chest, then ribs, then belly. Keep the breath continuous and quiet, and stop if you feel dizzy.","breathCue":"Inhale chest, ribs, then belly; exhale chest, ribs, belly — one smooth wave.","props":["cushion or folded blanket under hips"],"modifications":["Sit on a cushion to lift the hips","Sit against a wall for back support","Practice lying down if sitting is uncomfortable"],"deepen":["Sit tall once the three parts feel easy"],"avoidIf":["Dizziness or acute respiratory distress — stop and rest"],"commonMistakes":["Forcing three separate gulps","Lifting the shoulders on every inhale"],"alignmentCues":["Soft belly","Jaw and face relaxed","Continuous wave of breath"],"drishti":"eyes closed","muscles":["diaphragm","intercostals","nervous system"]},"breath-belly":{"name":"Belly Breath","goodFor":"Soft diaphragmatic breathing that undoes upper-chest holding.","instructions":"Sit cross-legged on the floor with a tall, relaxed spine. Rest both hands on your belly, fingers spread below the navel. Inhale slowly through the nose and feel the belly expand into your hands. Exhale through the nose or a soft mouth and let the belly fall back in. Keep the chest quiet and shoulders relaxed. Continue for several easy cycles, then breathe naturally.","breathCue":"Inhale through the nose, belly expands; exhale, belly contracts.","props":["blanket under head"],"modifications":["Breathe through the mouth if the nose is blocked","Sit on a small cushion if the hips feel tight","Lie down if sitting is uncomfortable"],"avoidIf":["Dizziness — shorten the practice"],"commonMistakes":["Pushing the belly out","Holding the breath between cycles"],"alignmentCues":["Chest stays relatively quiet","Nose inhale and exhale when comfortable"],"muscles":["diaphragm","belly","nervous system"]},"breath-ujjayi":{"name":"Ocean Breath","goodFor":"Steady focus and gentle heat for seated practice or asana.","instructions":"Sit tall in an easy cross-legged seat with one hand on your chest and the other on your belly. Slightly constrict the back of your throat as if fogging a mirror, then close the mouth. Inhale and exhale through the nose with a soft ocean sound — quiet, never loud or scraping. Keep your face, jaw and shoulders soft. Stay for a few minutes, then release the throat constriction and breathe normally.","breathCue":"Soft ocean inhale and exhale — quiet, never scraping.","props":["Cushion or folded blanket","Chair"],"modifications":["Sit on a folded blanket or cushion","Practice on a chair instead of the floor","Rest both hands on the thighs"],"avoidIf":["Throat irritation","History of fainting with intense breath work — keep very mild"],"commonMistakes":["Loud scraping sound","Clenching the jaw"],"alignmentCues":["Sit tall","Shoulders soft","Mouth closed"],"drishti":"soft forward gaze","muscles":["throat (soft)","diaphragm","postural back"]},"breath-nadi-shodhana":{"name":"Alternate Nostril Breath","goodFor":"Balancing, settling breath; classic bridge into meditation.","instructions":"Sit tall in a comfortable cross-legged seat. Raise one hand to the nose in Vishnu mudra, folding the index and middle fingers into the palm. Use the thumb to gently close one nostril and inhale through the open one. Release, then close the other nostril with the ring finger and exhale before inhaling on that same side. Keep alternating nostrils with an even, unforced rhythm and no breath holds. To finish, lower the hand and breathe through both nostrils.","breathCue":"Inhale through left, exhale through right","props":["blanket to sit on"],"modifications":["Start with short rounds","Use vishnu mudra","Breathe slower"],"avoidIf":["Nasal congestion that forces hard sniffing"],"commonMistakes":["Forcing the sniff","Holding after inhale or exhale"],"alignmentCues":["Tall spine","Soft shoulders","Even, quiet breaths"],"muscles":["diaphragm","postural back","nervous system"]},"breath-bhramari":{"name":"Humming Bee Breath","goodFor":"Calming humming exhale; quiets mental chatter before rest.","instructions":"Sit cross-legged with the spine tall and shoulders soft. Bring both hands up and rest the fingers lightly over the closed eyes, letting the elbows drift out wide. Inhale slowly through the nose. Exhale with a low, gentle humming sound and feel the vibration in the face. Keep the sound soft and comfortable. After several rounds, lower the hands and breathe naturally.","breathCue":"Quiet inhale; long soft humming exhale.","props":["blanket to sit on"],"modifications":["Hum with hands resting in the lap","Cover only the ears with the palms","Sit on a cushion if the hips feel tight"],"avoidIf":["Ear infection or severe ear pain — skip ear covering"],"commonMistakes":["Humming so loud the throat strains","Clenching the jaw"],"alignmentCues":["Jaw soft","Gentle vibration in the face","Unhurried rounds"],"drishti":"eyes closed","modificationNote":"Hands are lifted to cover the eyes and face while humming, instead of resting in the lap.","muscles":["face","throat (soft)","nervous system"]},"breath-sheetali":{"name":"Cooling Breath","goodFor":"Cooling inhale through the tongue (or teeth); soothes heat.","instructions":"Sit tall. Curl the tongue into a tube if you can; inhale cool air through the tongue. Close the mouth and exhale through the nose. If you cannot curl the tongue, use Sheetkari: teeth gently together, lips parted, inhale with a soft hiss through the teeth, then exhale through the nose. Keep rounds short and stop if you feel chilled or lightheaded. To exit, close the mouth and return to ordinary nose breathing.","breathCue":"Inhale through curled tongue, exhale through nostrils","props":["blanket to sit on"],"modifications":["Hiss through the teeth instead (Sheetkari)","Sit on a cushion for tight hips","Shorten the rounds if you feel chilled"],"avoidIf":["Feeling chilled","Low blood pressure with lightheadedness — keep rounds short"],"commonMistakes":["Overlong rounds","Gasping between cycles"],"alignmentCues":["Sit tall","Soft face","Close the mouth to exhale through the nose"],"muscles":["tongue","diaphragm","nervous system"]},"breath-sama-vritti":{"name":"Equal Breath","goodFor":"Even inhale and exhale counts for steadiness and focus.","instructions":"Sit upright on the floor with your legs comfortably crossed and your hands resting on your knees. Lengthen the spine and soften the shoulders and face. Inhale through the nose for a slow, even count. Let a gentle pause follow without gripping. Exhale for the same count, then pause again. Keep both counts equal and shorten them if you strain.","breathCue":"Equal inhale and soft pause, equal exhale and soft pause — never strain.","props":["blanket to sit on"],"modifications":["Shorten the count to three","Breathe quietly through the nose","Sit near a wall for back support"],"avoidIf":["Urge to gasp — shorten the count or stop"],"commonMistakes":["Adding holds at the top or bottom","Counting longer than you can sustain"],"alignmentCues":["Soft belly","Honest equal counts","Face relaxed"],"drishti":"soft forward gaze","muscles":["diaphragm","nervous system"]},"breath-kapalabhati":{"name":"Skull-Shining Breath","goodFor":"Boosts energy and clears the head with quick, cleansing exhales.","instructions":"Sit on the floor with both legs extended straight ahead and rest your hands lightly on your legs. Sit tall with a long spine and soft shoulders. Take a normal inhale, then pump short, sharp exhales by snapping your belly in; let each inhale happen on its own. Keep your face, jaw, and neck relaxed. Practice in short rounds, then rest with easy, normal breathing. Stop right away if you feel dizzy or breathless.","breathCue":"Short, forceful exhale; long, passive inhale","props":["blanket to sit on"],"modifications":["Sit on a folded blanket or cushion for comfort","Slow the pumping rhythm down","Take longer rests between rounds"],"avoidIf":["Pregnancy","Uncontrolled hypertension or heart disease","Glaucoma or recent eye surgery","Hernia or recent abdominal surgery","Epilepsy or seizure history","Panic-prone or vertigo","Active ulcers or GERD flare","Menstruation — many teachers advise skip or soften"],"commonMistakes":["Continuous long sets without rest","Tensing the neck and face","Forcing the inhale"],"alignmentCues":["Sit tall","Passive inhale between pumps","Rest fully between rounds"],"muscles":["abdominals","diaphragm","nervous system"]},"breath-bhastrika":{"name":"Bellows Breath","goodFor":"Energizes the body and trains strong, controlled breathing.","instructions":"Sit cross-legged with a tall spine and hands resting on your knees. Bhastrika means bellows — breathe forcefully in and out through the nose like a blacksmith's bellows. Let the belly pump with each breath while the chest and face stay relaxed. Keep rounds short, then rest with natural breathing before another set. Practice in the morning or when alert, not right before sleep, and stop if you feel dizzy. To finish, return to soft natural breathing.","breathCue":"Forceful inhale and exhale through the nose in short rounds — stop if dizzy.","props":["Cushion or folded blanket under hips"],"modifications":["Sit on a cushion if hips are tight","Slow the pace to a gentle bellows","Use shorter rounds with longer rests"],"avoidIf":["Pregnancy","Uncontrolled hypertension or heart disease","Glaucoma or recent eye surgery","Hernia or recent abdominal surgery","Epilepsy or seizure history","Panic-prone or vertigo","Active ulcers or GERD flare","Menstruation — many teachers advise skip or soften"],"commonMistakes":["Skipping rest between rounds","Practicing right before sleep","Straining the throat"],"alignmentCues":["Seated only","Even forceful inhale and exhale","Full rest after each set"],"muscles":["abdominals","diaphragm","intercostals"]},"breath-kumbhaka":{"name":"Breath Retention","goodFor":"Introductory soft hold after inhale (antara) — never strain or compete on time.","instructions":"Sit cross-legged on the floor with your hands resting on your knees. Lengthen your spine and let your chin tip slightly up so your gaze drifts upward. Inhale comfortably through your nose. Pause and hold the breath softly for a few counts, staying relaxed. Exhale slowly and return to free breathing. Never force the hold or gasp afterward.","breathCue":"Inhale softly, pause without strain, then exhale slowly.","props":["Folded blanket or cushion under hips"],"modifications":["Shorten the pause to two or three counts","Sit on a cushion to ease the hips","Skip the hold and breathe steadily"],"avoidIf":["Pregnancy","Uncontrolled hypertension or heart disease","Glaucoma or recent eye surgery","Epilepsy or seizure history","Panic-prone","Urge to gasp after a hold — hold was too long"],"commonMistakes":["Long classical ratios","Empty-lung holds","Bandhas with retention"],"alignmentCues":["Comfortable inhale","Soft sealed pause","Easy exhale afterward"],"drishti":"upward","modificationNote":"Gentle intro version — hold after the inhale only, with no empty-lung holds or bandhas.","muscles":["diaphragm","intercostals","nervous system"]},"chair-mountain":{"name":"Seated Mountain","goodFor":"Arrive seated: feet grounded, spine tall, breath easy — foundation for chair yoga.","instructions":"Sit toward the front third of a sturdy chair with both feet flat on the floor, hip-width. Press evenly into the feet and sit bones. Lengthen the spine so the crown lifts and the shoulders soften. Hands rest on the thighs. Soften the jaw. Breathe steadily through the nose. To exit, stay seated or stand only when ready.","muscleCue":"Notice the stretch in the deep muscles of your hips. Notice the contraction in your quadriceps.","modificationNote":"chair adaptation","muscles":["postural back","core","hip flexors"]},"chair-hinge-fold":{"name":"Seated Forward Hinge","goodFor":"Soft hip hinge while seated — lengthen the spine, no forcing the fold.","instructions":"Sit tall with feet flat. Hinge forward from the hips with a long spine, sliding the hands down the thighs or toward the shins. Soften the neck. Fold only as far as the breath stays easy — this is a hinge from the waist/hips, not a collapse. To exit, engage the belly and rise vertebra by vertebra to seated mountain.","breathCue":"Exhale as you hinge forward","modifications":["Rest hands on thighs or knees","Sit on a folded blanket for tight hips","Keep the fold shallow and breathe easy"],"props":["chair"],"muscleCue":"Notice the contraction in your quadriceps.","drishti":"toward the floor","modificationNote":"forward fold done on a chair with knees bent and feet flat, instead of on the floor with legs extended","muscles":["hamstrings","low back","hips"]},"chair-figure-four":{"name":"Seated Figure-Four","goodFor":"Opens tight outer hips and stretches the glutes while seated comfortably.","instructions":"Sit tall on the chair with both feet flat on the floor. Cross one ankle over the opposite thigh and flex that foot. Keep both sit bones heavy and the grounded foot flat. Stay upright, or hinge a little forward from the hips if it feels comfortable. Soften the jaw and breathe steadily. To exit, uncross the leg and switch sides.","breathCue":"Inhale tall, exhale soften into the hip.","modifications":["Sit on a folded blanket to lift the hips","Keep the toes of the crossed foot lightly on the floor","Hold the chair sides for balance","Stay upright instead of hinging forward"],"props":["chair","folded blanket"],"muscleCue":"Notice the stretch in the deep muscles of your hips and your calves. Notice the contraction in your quadriceps.","drishti":"forward","modificationNote":"chair adaptation","muscles":["outer hips","glutes","hip rotators"]},"chair-eagle-arms":{"name":"Seated Eagle Arms","goodFor":"Crossed-arm shoulder stretch while seated; wrap as far as comfortable.","instructions":"Sit tall on a sturdy chair with feet flat on the floor. Stretch both arms forward and cross one elbow under the other. Bring the forearms together so the hands face each other in front of the face. Lift the elbows up to about chin height and let the shoulders relax down. Breathe steadily and hold. To exit, unwrap the arms and switch the cross.","breathCue":"Exhale as you lift the elbows","modifications":["hold opposite shoulders if the wrap feels too deep","keep the elbows lower for tight shoulders","sit on a folded blanket if the hips feel low"],"props":["chair"],"muscleCue":"Notice the stretch in the back of your shoulders. Notice the contraction in your quadriceps.","drishti":"forward","modificationNote":"chair adaptation","muscles":["shoulders","upper back","rhomboids"]},"seated-warrior-arms":{"name":"Seated Warrior Arms","goodFor":"Open the arms to a Warrior II line while staying seated and stable.","instructions":"Sit sideways on the chair with both feet grounded and the spine tall. Extend both arms straight out at shoulder height so they form one long line. Rotate the torso to face the side, keeping the chest open and the arms in line with the shoulders. Soften the shoulders down away from the ears. Gaze out over the front hand and breathe steadily. To exit, lower the arms and turn back to the front.","breathCue":"Inhale to open the arms, exhale to soften the shoulders.","modifications":["Lower the arms a little if the shoulders tire","Keep the gaze forward if the neck feels strained","Sit on a cushion if the hips sit low"],"props":["chair"],"muscleCue":"Notice the stretch in your inner thighs and your chest. Notice the contraction in your quadriceps.","drishti":"over the front hand","modificationNote":"chair adaptation: Warrior II arms","muscles":["shoulders","chest","upper back","arms"]},"chair-spine-twist":{"name":"Seated Spine Twist","goodFor":"Loosens the spine and waist after sitting, with the chair for support.","instructions":"Sit sideways on a chair with both feet flat and knees bent. Hold the back of the chair with the hand nearest it. Inhale to lengthen the spine; exhale to twist toward the chair back. Keep both sit bones down and soften the neck. Gaze gently over your shoulder and breathe steadily. To exit, unwind to center and switch sides.","breathCue":"Inhale to lengthen, exhale to twist","modifications":["Hold the chair seat instead of the back","Ease off the twist and keep the gaze forward","Sit on a folded blanket for height"],"props":["chair"],"muscleCue":"Notice the stretch in your outer hips. Notice the contraction in your quadriceps.","drishti":"over the back shoulder","modificationNote":"done on a chair instead of the floor","muscles":["obliques","spine","shoulders"]},"chair-pigeon":{"name":"Seated Pigeon","goodFor":"Milder hip opener than floor pigeon: ankle rests on opposite thigh in a chair.","instructions":"Sit tall on the chair with both feet grounded. Place one ankle on the opposite thigh just above the knee and flex the foot. Let the crossed knee relax out to the side. Keep the torso upright and rest your hands on your thighs or the crossed leg. Stay even on both sitting bones and breathe slowly. To exit, lift the ankle off and switch sides.","breathCue":"Inhale to sit tall, exhale to soften the hip","modifications":["Slide the ankle lower onto the thigh","Sit on a folded blanket to lift the hips","Hold the chair sides for extra balance"],"props":["chair","folded blanket"],"muscleCue":"Notice the stretch in the deep muscles of your hips and your calves. Notice the contraction in your quadriceps.","drishti":"forward","modificationNote":"chair adaptation","muscles":["outer hips","glutes","hip rotators"]},"chair-standing-hinge":{"name":"Supported Standing Hinge","goodFor":"Stand behind a sturdy chair, hands on the backrest, and hinge at the hips with support.","instructions":"Stand behind a sturdy chair and hold the backrest lightly with both hands. Feet hip-width. Soften the knees. Hinge at the hips to send the sit bones back while the spine stays long — a mild desk-style fold, not a deep ragdoll. Keep weight even in both feet. To exit, press the feet and rise to standing with a long spine.","modificationNote":"chair adaptation: hands on chair back","muscles":["hamstrings","glutes","low back","core"]},"supported-calf-raise":{"name":"Supported Calf Raise","goodFor":"Hold a chair back and rise onto the balls of the feet — strength and circulation.","instructions":"Stand beside a sturdy chair with one or both hands resting lightly on the top of the backrest. Bring your feet close together. Press into the balls of your feet and lift your heels as high as feels comfortable. Keep your ankles steady and stand tall at the top. Lower your heels slowly with control, then release the chair once you feel stable.","breathCue":"Inhale to lift your heels, exhale to lower","modifications":["lift heels only partway if calves are tight","use one hand on the chair for lighter support","keep fingertips on the chair for extra balance"],"props":["chair"],"muscleCue":"Notice the contraction in your calves.","drishti":"forward","modificationNote":"chair adaptation: hold chair back","muscles":["calves","ankles","feet"]},"chair-sit-to-stand":{"name":"Sit-to-Stand","goodFor":"Practice rising from and returning to a sturdy chair with control — functional strength.","instructions":"Sit at the front edge of a sturdy chair with feet flat on the floor under the knees. Lean the torso forward over the thighs and rest the hands on the knees. Press through the feet and rise to standing with control. To return, hinge forward and lower the hips slowly back to the seat. Move at a pace that feels safe and repeat if you like.","breathCue":"Exhale as you rise, inhale as you lower","modifications":["Use a higher seat or a cushion for easier rising","Hold a wall or the chair back for balance","Just lean and lift slightly if full standing is too much"],"props":["chair","cushion for seat height","wall for balance"],"muscleCue":"Notice the contraction in your quadriceps.","drishti":"forward and slightly down","modificationNote":"chair-only functional practice","muscles":["quads","glutes","core","hips"]},"seated-rest":{"name":"Seated Rest","goodFor":"Final rest without the floor: sit back into the chair, feet grounded, eyes soft, breath free.","instructions":"Sit back into the chair so the spine rests against the backrest. Feet flat or slightly wide. Hands soft in the lap. Soften the belly, jaw, and eyes (close them if comfortable). Breathe naturally with no control — this is rest, not tall seated mountain. Stay until you are ready to open the eyes and move slowly.","breathCue":"let the breath flow with no control","modifications":["sit on a cushion if the seat is hard","use a footrest if feet don't reach the floor","rest forearms on armrests if the back feels tired"],"props":["chair","cushion","footrest"],"muscleCue":"Notice the contraction in your quadriceps.","modificationNote":"chair-only rest","muscles":["nervous system","postural back (passive)"]},"ardha-chandrachapasana-prep":{"name":"Half Moon Bow Pose Prep","goodFor":"Balance plus a quad and hip-flexor stretch on the lifted leg.","instructions":"Start in a forward fold and walk your hands a little forward. Shift your weight onto one leg and float the other leg up behind you to about hip height. Keep the lower hand on the floor with fingertips pressing lightly for balance. Bend the lifted knee and reach the same-side hand back to hold the foot. Press the foot into the hand and let the chest open as the back gently arches, keeping the standing leg strong. To exit, release the foot, lower the leg, and return to standing.","breathCue":"Exhale as you press the foot into the hand","modifications":["Use a strap around the lifted foot","Rest fingertips on a block","Practice near a wall for balance"],"props":["strap","block"],"muscleCue":"Notice the stretch in your quadriceps. Notice the contraction in your outer hips and the sides of your waist.","drishti":"down toward the floor","modificationNote":"grabbing onto the back foot with the hand on the same side","muscles":["standing-leg glutes","quads","hip flexors","shoulders"]},"ardha-chandrasana-namaskar":{"name":"Half Moon Pose","goodFor":"One-legged balance that lengthens the standing-leg hamstrings while the back leg reaches high.","instructions":"From a forward fold, plant one hand on the floor a few inches in front of your foot and shift your weight into it and one foot. Sweep the other leg up behind you and let it climb high toward the sky. Let the chest turn toward the floor as the torso drapes down over the standing leg. Keep the standing leg strong and reach the free arm out long for balance. Gaze down at the floor, breathe steadily, then lower the back leg with control to come out.","breathCue":"Exhale as the leg sweeps up, then breathe steadily while balancing","modifications":["Use a block under the lower hand","Lift the leg only to hip height","Keep a soft bend in the standing knee","Practice near a wall"],"props":["yoga block","wall"],"muscleCue":"Notice the stretch in your hamstrings and your inner thighs. Notice the contraction in your glutes and your outer hips.","drishti":"Down at the floor","modificationNote":"Leg lifts high toward vertical with the chest facing down, unlike classic half moon's parallel leg and side-open chest.","muscles":["standing-leg glutes","hamstrings","core","shoulders"]},"seated-cow":{"name":"Seated Cow","goodFor":"Seated spinal extension on the inhale, hands on the thighs; pairs with Seated Cat.","instructions":"Sit tall toward the front of a sturdy chair, feet flat, hands on the thighs or knees. On an inhale, tip the pelvis forward, lift the chest, and look slightly up, keeping the neck long. Seated Cow alternates with Seated Cat, one breath each. To exit, return to a neutral tall sit.","breathCue":"Inhale to arch gently.","modifications":["Keep hands on thighs instead of knees","Slow the movement to match your breath","Sit on a folded blanket if the chair feels low"],"props":["Chair"],"muscleCue":"Notice the contraction in your quadriceps.","drishti":"upward","modificationNote":"chair adaptation","muscles":["spinal extensors","chest","shoulders"]},"seated-cat":{"name":"Seated Cat","goodFor":"Seated spinal rounding on the exhale, hands on the thighs; pairs with Seated Cow.","instructions":"Sit back on a sturdy chair so your spine rests against the chair back, feet flat on the floor. Rest your hands on your thighs. On an exhale, tip the pelvis back and round your whole spine, letting the shoulders curl forward. Tuck your chin and gaze down toward your knees. Hold the rounded shape for a breath or two. Seated Cat alternates with Seated Cow, one breath each; to exit, return to a neutral tall sit.","breathCue":"Exhale to round your spine.","modifications":["Round less deeply if the back feels tender","Rest hands higher on the thighs for a smaller reach","Add a cushion behind the back for support"],"props":["Chair"],"muscleCue":"Notice the contraction in your quadriceps.","drishti":"toward the knees","modificationNote":"chair adaptation","muscles":["core","spinal flexors","upper back"]},"utthita-trikonasana":{"name":"Extended Triangle Pose","goodFor":"Opens the side body and hamstrings while building leg strength and balance.","instructions":"Stand tall and step the feet wide, turning the front foot out and the back foot slightly in. Bend the front knee and hinge sideways over it, keeping the back leg strong and straight. Lower the bottom hand to the floor just inside the front foot. Reach the top arm up and overhead in line with the torso. Keep both sides of the waist long and let the gaze fall down or forward. Press through both feet to hold, then rise back up to exit.","breathCue":"Exhale as you hinge over the front leg","modifications":["Straighten the front leg","Place the bottom hand on a block","Rest the hand on the shin instead of the floor","Shorten the stance"],"props":["Mat","Block"],"muscleCue":"Notice the stretch in your hamstrings and your inner thighs. Notice the contraction in your outer hips and the sides of your waist.","drishti":"down toward the floor or the bottom hand","modificationNote":"Front knee is bent, bottom hand rests on the floor inside the front foot, top arm reaches overhead in line with the torso, gaze stays down","muscles":[]},"laghuvajrasana":{"name":"Little Thunderbolt Pose","goodFor":"Opens the chest and shoulders while stretching the thighs and deepening the backbend.","instructions":"Kneel with your knees about hip-width apart and the tops of your feet on the floor. Hold your calves with both hands. Inhale to lift the chest, then lean back on an exhale, letting the knees bend deeply so the thighs angle back toward your heels as you arch. Lower the crown of your head to the floor behind you and keep holding the calves. Spread the arch through the upper back and keep breathing steadily. To exit, press into the hands, lift the chest and come back up to kneeling.","breathCue":"Inhale to lift the chest, exhale to lean back and lower the head.","modifications":["Rest the head on a blanket","Keep the thighs upright, hold the knees and keep the head off the floor","Keep hands on the lower back for support"],"props":["Blanket under the head"],"muscleCue":"Notice the stretch in your quadriceps. Notice the contraction in your glutes and the front of your shoulders.","drishti":"Bhrumadhye or Ajna Chakra (third eye, between the eyebrows)","muscles":["quadriceps","hip flexors","spinal extensors","chest","shoulders","neck"]},"baddha-hasta-utthita-stiti-vayu-muktyasana-prep":{"name":"Hand Bound Rising Standing Wind Relieving Pose Prep","goodFor":"Builds single-leg balance and hip flexor strength while gently opening the hip.","instructions":"Stand tall and shift your weight onto one leg. Lift the other knee up high toward your chest. Wrap both arms around the raised knee and hug it in close to your body. Keep your standing leg engaged and your spine long as you hold. Breathe steadily, then release the foot back down and switch sides.","breathCue":"Inhale as you lift the knee, then breathe calmly while you balance","modifications":["keep the lifted knee a little lower","stand near a wall for support","place one hand under the thigh for help"],"props":["wall or sturdy chair nearby for balance"],"muscleCue":"Notice the stretch in your quadriceps and your hip flexors. Notice the contraction in your outer hips.","drishti":"forward","modificationNote":"prep variation: the standing leg stays slightly bent and the arms simply wrap around the lifted knee instead of a full bind","muscles":[]},"baddha-natarajasana":{"name":"Bound Lord of the Dance Pose","goodFor":"Builds balance while opening the chest and shoulders and stretching the hip flexors.","instructions":"Stand tall and shift your weight onto one leg. Bend the other knee and lift the foot up behind you. Reach both arms back and overhead to hold the raised foot. Draw the foot up as your chest lifts and your hips stay level. Keep the standing leg strong and your gaze steady. Release the foot slowly and return to standing.","breathCue":"inhale to lift the chest, exhale to draw the foot higher","modifications":["loop a strap around the foot if the hands cannot reach","hold the foot with one hand only","stand near a wall for extra balance"],"props":["strap","wall"],"muscleCue":"Notice the stretch in your quadriceps and your hip flexors. Notice the contraction in your outer hips.","drishti":"steady forward gaze at a fixed point","modificationNote":"both arms reach back to hold the lifted foot, making it a bound, deeper version of the one-handed dance pose","muscles":[]},"ardha-navasana":{"name":"Half Boat Pose","goodFor":"Builds core endurance and strengthens the spine and hip flexors.","instructions":"Sit on the floor with your knees bent and feet flat. Interlace your fingers behind your head and let the elbows point out wide. Lean back and lift your feet off the floor, straightening the legs to about a 45-degree angle. Balance on your sit bones and lower your torso halfway toward the floor. Keep the core braced and breathe steadily as you hold. To come out, bend the knees and lower the feet back down.","breathCue":"Exhale as you lift the legs, then breathe steadily while holding.","modifications":["Bend the knees to make it easier","Lift the legs only a few inches","Rest the head lightly into the hands"],"props":["Folded blanket under the sit bones"],"muscleCue":"Notice the contraction in your quadriceps and your hip flexors.","drishti":"Padayoragrai or Padayoragre (toes/feet)","modificationNote":"fingers interlocked behind the head","muscles":[]},"ardha-padmasana":{"name":"Half Lotus Pose","goodFor":"Opens the hips and calms the mind for seated meditation.","instructions":"Sit on the floor with both knees bent and wide apart. Place one foot on top of the opposite thigh, sole facing up, and tuck the other foot beneath the opposite knee. Rest your hands on your knees and sit up tall. Lengthen the spine, draw the shoulder blades back and down, and let the tailbone tuck slightly. Keep the crown of your head reaching up and gaze softly forward as you breathe steadily.","breathCue":"Inhale to lengthen the spine, exhale to settle the hips.","modifications":["Sit on a block or bolster","Rest the top foot on the calf instead of the thigh","Place hands on the knees or use Gyan Mudra"],"props":["block","bolster"],"muscleCue":"Notice the stretch in your shins and the tops of your feet.","drishti":"forward","muscles":[]},"eka-pada-indudalasana":{"name":"One-Legged Standing Crescent Pose","goodFor":"Builds single-leg balance and leg strength while stretching the side body and opening the hip.","instructions":"Stand tall and shift your weight onto one leg. Float the other leg out to the side, keeping it long and active. Sweep both arms overhead and let them arc toward the lifted leg, bending gently sideways from the waist. Hold one wrist with the other hand and press the palm away to lengthen the side body. Keep the standing leg firm, hips level, and gaze up toward your hands or the sky. To exit, unwind the arms back to center and lower the lifted foot down.","breathCue":"Inhale reach up, exhale bend a little deeper.","modifications":["Hold onto a wall for balance","Keep the lifted leg lower to the floor","Bend the standing knee slightly for stability","Keep hands apart instead of clasping"],"props":["Wall or chair nearby for balance support"],"muscleCue":"Notice the stretch in your inner thighs. Notice the contraction in your outer hips.","drishti":"Urdhva or Antara Drishti (up to the sky)","modificationNote":"grabbing onto the wrist","muscles":[]},"eka-pada-setu-bandhasana":{"name":"One-Legged Bridge Pose","goodFor":"Builds glute and leg strength while opening the chest and hip flexors.","instructions":"Lie on your back with knees bent and feet flat on the floor, hip-width apart, heels close to your sitting bones. Rest your arms alongside your body with palms facing down. Press your feet and shoulders into the floor and lift your hips up. Keeping the hips level, extend one leg straight up toward the ceiling. Hold and breathe steadily, then bend the lifted leg back down and slowly lower your hips to the floor.","breathCue":"Inhale to lift the hips, exhale to extend the leg up","modifications":["Keep arms by sides","Practice regular bridge with both feet down","Rest sacrum on a block","Keep the lifted leg lower"],"props":["mat"],"muscleCue":"Notice the stretch in your hip flexors and your chest. Notice the contraction in your quadriceps.","drishti":"Up toward the raised foot or straight up at the ceiling","modificationNote":"One leg reaches straight up while the arms stay alongside the body instead of clasping under the back","muscles":["glutes","hamstrings","quadriceps","core","lower back"]},"eka-hasta-parshvasana":{"name":"One Hand Side Stretch Pose","goodFor":"Great for stretching the side body, ribs, and shoulders.","instructions":"Stand with your feet together and legs straight. Reach one arm up and let it arc over your head toward the side you will bend toward. Rest the other hand on the same-side thigh and slide it down the leg as you go. Bend sideways from the waist, keeping both hips facing forward and the spine long. Let your head follow the arm and gaze up toward the sky. To come out, inhale back up to center and release both arms.","breathCue":"Inhale to lengthen up, exhale to bend a little deeper.","modifications":["Rest the hand on the thigh instead of sliding to the shin","Stand with your back near a wall for balance","Bend the top elbow slightly if the shoulder is tight"],"props":["Wall nearby for balance support"],"muscleCue":"Notice the stretch in your outer hips.","drishti":"Urdhva or Antara Drishti (up to the sky)","modificationNote":"one arm up over the head, other hand sliding down the leg","muscles":[]},"eka-pada-uttanasana-2":{"name":"One-Legged Intense Stretch Pose 2","goodFor":"Stretches the hamstrings and hips while building balance and focus.","instructions":"Stand tall on one leg with the other foot beside it. Shift your weight into the standing foot and hinge forward from the hips. Let the back leg float up and extend it straight behind you, reaching through the heel. Place your fingertips or palms on the floor beside or just past the standing foot. Keep both hips facing down and the standing knee soft. To exit, slowly lower the back leg and roll up to standing.","breathCue":"exhale as you fold and lengthen the back leg","modifications":["rest hands on a block","keep the lifted leg lower, near hip height","bend the standing knee slightly for balance"],"props":["yoga block under the hands"],"muscleCue":"Notice the stretch in your hamstrings. Notice the contraction in the front of your shoulders and your triceps.","drishti":"toward the standing leg or the mat","modificationNote":"one leg lifts and extends straight back behind you while you fold over the standing leg, instead of folding with both feet down","muscles":[]},"eka-padangushta-vasishtasana":{"name":"One Big Toe Pose Dedicated to Sage Vasishta","goodFor":"Builds side-body and arm strength, balance, and hamstring flexibility all at once.","instructions":"Come into a side plank with one hand planted under the shoulder and the feet stacked. Shift your weight firmly into the supporting hand and the outer edge of the bottom foot. Lift the top leg up toward the ceiling as high as you can. Reach the top arm up and take hold of the big toe with the first two fingers. Straighten both legs and open the chest toward the ceiling as you hold the balance. To exit, release the toe, lower the leg back onto the stack, and come out of the plank.","breathCue":"Exhale as you lift the leg, then breathe steadily while balancing","modifications":["bend the lifted knee and hold the knee instead of the toe","keep the top hand on the hip instead of reaching for the toe","drop the bottom knee to the floor for extra support"],"props":["yoga strap looped around the lifted foot if the toe is out of reach"],"muscleCue":"Notice the stretch in your inner thighs. Notice the contraction in your outer hips and the sides of your waist.","drishti":"down toward the floor beside the supporting hand","modificationNote":"top leg lifted straight up and held by the big toe","muscles":[]},"indudalasana":{"name":"Standing Crescent Pose","goodFor":"Stretches the side body, ribs, and shoulders while building standing balance.","instructions":"Stand tall with feet together and legs active. Reach both arms straight up beside the ears. Clasp the hands or hold the top wrist if that feels good. Keep the head up and gaze toward the sky as you lean gently to one side. Keep hips and shoulders in one line with both feet grounded. Hold for a few breaths, return to center, then repeat on the other side.","breathCue":"Inhale to lengthen up, exhale to lean to the side","modifications":["Grab top wrist for support","Keep the lean small at first","Rest a hand on a wall for balance"],"props":[],"muscleCue":"Notice the stretch in your outer hips.","drishti":"Urdhva or Antara Drishti (up to the sky)","modificationNote":"grabbing onto the wrist of the top hand","muscles":[]},"parivritta-sukhasana":{"name":"Revolved Easy Pose","goodFor":"Great for loosening the spine and hips and releasing built-up tension in the torso.","instructions":"Sit comfortably cross-legged on the floor with your sit bones grounded. Sit up tall and place one hand on the floor behind you for support. Rest the other hand on your opposite knee and gently turn your torso to that side. Let your head follow and look softly over your back shoulder. Keep the spine long and breathe steadily as you hold the twist. Slowly unwind and repeat on the other side.","breathCue":"Inhale to lengthen the spine, exhale to twist a little deeper.","modifications":["Sit on a folded blanket if the hips feel tight","Keep the gaze forward if the neck feels strained","Use a block under the back hand"],"props":["Folded blanket under the sit bones"],"muscleCue":"Notice the stretch in your calves. Notice the contraction in your quadriceps.","drishti":"Parshva Drishti (to the right), Parshva Drishti (to the left)","modificationNote":"A twisting variation of Easy Pose (Sukhasana) that adds rotation of the torso and a gaze over the shoulder.","muscles":[]},"parivritta-baddha-sukhasana":{"name":"Revolved Bound Easy Pose","goodFor":"Loosens the mid-back and hips and helps release tension from long periods of sitting.","instructions":"Sit cross-legged on the floor and rest your hands on your knees. Sit up tall and imagine lengthening the crown of your head toward the ceiling. On an exhale, twist your chest and shoulders gently to one side. Bring one hand to the opposite knee and let the other hand rest behind you for light support. Keep both sitting bones grounded and your neck relaxed as you gaze softly over your shoulder. Hold for a few breaths, then slowly unwind and repeat on the other side.","breathCue":"Inhale to lengthen, exhale to twist a little deeper","modifications":["Sit on a folded blanket to free up the hips","Keep the back hand on the floor for extra support","Ease the twist and simply turn the shoulders"],"props":["Folded blanket or cushion under the hips"],"muscleCue":"Notice the stretch in the deep muscles of your hips and your inner thighs. Notice the contraction in your quadriceps and the sides of your waist.","drishti":"Parsva Drishti (gaze to the side, over the shoulder)","modificationNote":"adds a gentle spinal twist to the cross-legged easy seat","muscles":[]},"hasta-pada-parivritta-ardha-chandrachapasana":{"name":"Hand to Foot Revolved Half Moon Bow Pose","goodFor":"Builds balance and leg strength while opening the chest, shoulders, and hips.","instructions":"Come into half moon balance with one hand on the floor and the other leg lifted behind you. Bend the lifted knee and reach the free hand back to hold the foot. Press the foot into the hand and let the back arch naturally as the chest opens. Keep the standing leg strong and root through all four corners of the foot. Gaze up toward the sky and breathe steadily while you hold. To exit, release the foot and return to half moon.","breathCue":"Inhale as you press the foot into the hand and lift the chest.","modifications":["Use a strap around the lifted foot","Rest the lower hand on a block","Keep the back toes near a wall for support"],"props":[],"muscleCue":"Notice the stretch in your quadriceps and your hip flexors. Notice the contraction in your forearms and your hands.","drishti":"Urdhva Drishti (up toward the sky)","modificationNote":"Adds a revolved twist to half moon bow pose, so the torso rotates and the opposite hand reaches back to hold the lifted foot.","muscles":[]},"parshva-sukhasana":{"name":"Sideways Easy Pose","goodFor":"Opens the side body and ribs and eases stiffness from long sitting.","instructions":"Sit cross-legged on the floor with your sit bones grounded and spine tall. Rest one palm on the floor beside you for support. Inhale and sweep the other arm up and over your head as you lean gently to the opposite side. Keep both sit bones heavy and let the ribs spread with each breath. Gaze up toward the raised hand while keeping the neck in line with the spine. To come out, press into the lower hand and rise back to center.","breathCue":"Inhale deeply to open intercostal muscles, keep back flat","modifications":["Sit on a block or bolster","Rest palm on the floor instead of forearm","Sit on a folded blanket if hips are tight"],"props":["block","bolster","blanket"],"muscleCue":"Notice the stretch in your quadriceps and the deep muscles of your hips. Notice the contraction in your hip flexors and the front of your shoulders.","drishti":"Hastagrai (up toward the raised hand)","modificationNote":"a side bend added to easy pose: one palm rests on the floor while the other arm reaches up and over the head","muscles":[]},"patan-vrikshasana":{"name":"Toppling Tree Pose","goodFor":"Builds balance, leg and core strength, and steady focus.","instructions":"Stand tall and shift your weight onto one foot. Tip forward from the hips as your other leg lifts and extends straight behind you. Let both arms reach back alongside the lifted leg. Keep the standing knee soft and your hips level. Gaze down at the floor and breathe steadily as you hold the balance. To exit, lower the back leg and rise back up to standing.","breathCue":"Exhale as you tip forward, then breathe slow and steady","modifications":["keep the back foot closer to the floor","rest fingertips on a wall or chair","bend the standing knee a little more"],"props":["wall","chair"],"muscleCue":"Notice the stretch in your quadriceps and your hip flexors. Notice the contraction in your glutes and your outer hips.","drishti":"Downward, at a spot on the floor in front of you","modificationNote":"torso tips forward with the back leg lifted behind and arms reaching back, unlike upright tree pose","muscles":[]},"parshvasana":{"name":"Side Stretch Pose","goodFor":"Stretches the side body, opens the ribs, and builds balance and standing awareness.","instructions":"Stand tall with your feet together or hip-width apart. Sweep both arms overhead, keeping them long and active. Slowly lean to one side, letting your torso curve sideways while your hips stay steady. Keep both feet grounded and your spine long as you breathe into the stretch. Let your head follow the spine and gaze up toward the sky. To exit, press into your feet, lift back to center, and lower your arms.","breathCue":"Inhale reach up, exhale bend to the side.","modifications":["Keep feet hip-width apart for balance","Bend the elbows slightly if shoulders are tight","Practice near a wall for support"],"props":["wall for balance support"],"muscleCue":"Notice the stretch in the sides of your waist and your lower back.","drishti":"Nasagrai or Nasagre (nose), Urdhva or Antara Drishti (up to the sky)","muscles":[]},"sukha-vrikshasana":{"name":"Easy Tree Pose Modification","goodFor":"Builds balance and focus while keeping the hips easy and open.","instructions":"Stand tall and shift your weight onto one foot. Bend the other knee and place the sole of that foot against your inner calf, keeping it off the knee. Rest both hands on your hips and lengthen your spine. Turn your gaze gently to one side or fix it on a steady point to help you balance. Breathe slowly and hold, then lower the foot and repeat on the other side.","breathCue":"Inhale tall, exhale steady as you balance.","modifications":["Keep the toes of the lifted foot on the floor","Stand next to a wall for support","Shorten the hold if you wobble"],"props":[],"muscleCue":"Notice the contraction in your outer hips.","drishti":"Parshva Drishti (to the right), Parshva Drishti (to the left)","modificationNote":"hands on the hips and foot on the inner calf","muscles":[]},"salamba-parivid-pada-bhujangasana":{"name":"Supported Twined Legs Cobra Pose","goodFor":"Good for opening the chest while gently stretching the thighs and knees.","instructions":"Lie face down and place your forearms on the mat with your elbows under your shoulders. Press down and slide your chest forward and up into a comfortable backbend. Bend both knees and lift your feet toward the ceiling. Cross one shin over the other so the lower legs twine behind you. Keep your hips heavy on the floor, gaze softly forward, and breathe steadily. To release, untwine the legs and lower down slowly.","breathCue":"Inhale to lift the chest, then breathe slow and even.","modifications":["Rest the forehead on a block if the neck tires","Keep both feet low and simply cross the ankles","Slide the elbows forward to soften the backbend"],"props":["Folded blanket under the thighs for comfort","Block under the forehead"],"muscleCue":"Notice the stretch in your quadriceps and your hip flexors. Notice the contraction in your glutes.","drishti":"Bhrumadhye or Ajna Chakra (third eye, between the eyebrows)","modificationNote":"Supported version that rests on the forearms instead of pressing up on the hands.","muscles":[]},"raja-kapotasana":{"name":"King Pigeon Pose","goodFor":"Opens tight hips and shoulders while stretching the quads and building a healthy backbend.","instructions":"Start on all fours and slide one knee forward, resting the outer shin on the mat with the other leg extended behind. Keep the hips square and let the back thigh rest heavy on the floor. Bend the back knee and lift the foot up toward your head. Reach both arms up and back to hold the back foot, elbows pointing skyward. Open the chest, keep the crown of the head lifting, and breathe steadily. To release, let go of the foot, lower the leg, and press back to all fours.","breathCue":"Inhale to lift the chest, exhale as you hold the foot","modifications":["Use strap to reach back foot","Block or blanket under hips","Bend front leg more","Bring heel closer to pelvis"],"props":["strap","block","blanket"],"muscleCue":"Notice the stretch in your quadriceps and your hip flexors. Notice the contraction in your forearms and your hands.","drishti":"Forward, gazing straight ahead","modificationNote":"both hands reach back to hold the lifted back foot, adding a deep backbend","muscles":[]},"tadasana-namaskar":{"name":"Mountain Pose with Hands in Prayer","goodFor":"Improves posture, balance, and body awareness while calming the mind.","instructions":"Stand with feet together, toes spread softly to the floor. Place hands at heart center, palms pressed together with fingers pointing up. Lengthen the spine upward from the base of the pelvis; gaze forward and soft around the neck. Keep the knees slightly bent if needed to support spinal alignment. To exit, release the hands, unclench the fingers, and step or slide feet apart.","breathCue":"Inhale to lengthen tall, exhale to soften the shoulders.","modifications":["Bend the knees slightly if the back strains","Stand with feet hip-width apart for balance","Practice near a wall for support"],"props":["Wall nearby for balance support"],"drishti":"Nasagrai or Nasagre (nose)","modificationNote":"hands pressed together in Anjali Mudra at the heart center instead of arms hanging at the sides","muscles":[]},"parivritta-parshva-konasana":{"name":"Revolved Side Angle Pose","goodFor":"Builds leg strength and balance while opening the chest and improving spinal twist.","instructions":"Stand with your feet wide apart and turn one foot out so the front knee bends over the ankle. Keep the back leg strong and straight with the back foot grounded. Exhale and twist your torso toward the bent knee, bringing the opposite hand down to the floor beside your foot. Reach the other arm straight up and let your chest turn open toward the sky. Gaze up at your raised hand, breathe steadily, then unwind and switch sides.","breathCue":"Breathe deeply into the side of your rib cage","modifications":["Drop the back knee to the mat","Place the lower hand on a block","Keep a slight bend in the back leg"],"props":[],"muscleCue":"Notice the stretch in your inner thighs. Notice the contraction in your quadriceps.","drishti":"Hastagrai or Hastagre (hands)","modificationNote":"Twisted version of Side Angle Pose - the torso revolves so the opposite arm reaches up while the lower hand grounds beside the front foot.","muscles":[]},"tadasana-urdhva-baddha-hastasana":{"name":"Mountain Pose—Raised Bound Hands","goodFor":"Opens the shoulders and builds tall, steady standing posture.","instructions":"Stand tall with your feet together and your weight even on both feet. Interlace your fingers and extend both arms straight up overhead. Turn your palms toward the ceiling and reach up through the heels of your hands. Keep your shoulders relaxed and your legs active. Gaze forward and breathe steadily. To release, lower your arms and unlace your fingers.","breathCue":"Inhale as you reach the arms up, then breathe steadily while holding tall","modifications":["Hold a strap between the hands if fingers will not interlace","Keep the arms a little wider if the shoulders are tight","Stand near a wall for extra balance support"],"props":["yoga strap"],"muscleCue":"Notice the stretch in the sides of your back.","drishti":"Nasagrai or Nasagre (nose)","modificationNote":"Builds on tadasana by interlacing the fingers and extending the arms straight overhead with palms facing up.","muscles":[]},"utthita-pada-vishama-salamba-bhujangasana":{"name":"Leg Extended Uneven Supported Cobra Pose","goodFor":"Builds back strength and opens the chest while working the legs unevenly.","instructions":"Lie face down and rise onto your forearms. Keep one forearm on the floor with the elbow under the shoulder, and reach the other hand forward to rest on the floor. Stretch one leg long behind you along the floor. Bend the other knee and open it out to the side, rolling onto that hip so the pelvis turns sideways and the foot lifts behind you. Keep the chest lifted and open, and gaze forward. To exit, lower the bent leg, roll the hips back down and gently settle your torso.","breathCue":"Inhale to lift the chest and foot, exhale to hold steady","modifications":["keep both legs on the floor","lift the bent knee only partway","rest a folded blanket under the lower hip"],"props":["folded blanket under the hips"],"muscleCue":"Notice the stretch in your shins and the tops of your feet. Notice the contraction in your quadriceps and your hip flexors.","drishti":"forward and slightly up","modificationNote":"one knee bent and opened out to the side with the hips turned sideways, while the other leg stays extended on the floor","muscles":[]},"vrikshasana-namaskar":{"name":"Tree Pose with Hands in Prayer","goodFor":"Builds balance and focus while strengthening the standing leg and opening the hips.","instructions":"Stand tall with your feet together and bring your palms together at your heart. Shift your weight onto one foot and bend the other knee out to the side. Place the sole of that foot against your inner thigh and press the heel gently in. Keep your spine long and your hips level as you find your balance. Soften your gaze forward and breathe steadily. To exit, release the foot back to the floor and lower your hands.","breathCue":"Inhale to grow tall, exhale to root down","modifications":["Place foot on ankle instead","Keep toes on the floor for support","Stand near a wall for balance"],"props":[],"muscleCue":"Notice the stretch in your quadriceps. Notice the contraction in your outer hips.","drishti":"A steady forward gaze at a fixed point ahead","modificationNote":"Hands stay in prayer at the heart instead of reaching overhead as in the base tree pose.","muscles":[]},"tandavasana":{"name":"Pose Inspired by Shiva’s Vigorous Cycle of Life Dance","goodFor":"Builds balance and side-body strength while opening the ribs and shoulders.","instructions":"Stand tall and shift your weight onto one leg. Cross the other leg behind it and rest the back toes lightly on the floor. Bend both elbows and bring your hands together above your head. Lean into a gentle side bend and let a small twist come through the chest. Tip your head back and gaze up toward your hands. Hold for a few breaths, then uncross the leg and return to standing.","breathCue":"Inhale as you reach up, exhale as you lean into the bend.","modifications":["Keep the standing leg straight and bend the other knee to 90 degrees","Bring the knee toward the tricep on the same side","Rest fingertips on a wall for balance"],"props":["wall"],"muscleCue":"Notice the stretch in the front of your neck. Notice the contraction in your quadriceps.","drishti":"Hastagiri or Hastagare (hands)","modificationNote":"legs crossed with the back toes resting on the floor instead of the knee bent out to the side","muscles":[]},"mat-eagle-arms":{"name":"Mat Eagle Arms","goodFor":"Crossed-arm shoulder stretch while sitting on the floor; wrap as far as comfortable.","instructions":"Sit cross-legged on the floor with a tall spine. Stretch both arms forward and cross one elbow over the other. Wrap the forearms so the palms meet, or hold opposite shoulders if that is easier. Lift the elbows to chest height and relax the shoulders down. Hold and breathe, then unwrap and switch the cross.","breathCue":"Exhale and soften the shoulders","modifications":["Cross the forearms without a full wrap","Sit on a folded blanket if the hips are tight","Keep the back supported against a wall"],"props":["folded blanket or cushion"],"muscleCue":"Notice the stretch in your shins and the tops of your feet.","drishti":"forward past the hands","modificationNote":"Seated cross-legged on the floor instead of the standing balancing version.","muscles":["shoulders","upper back","rhomboids"]},"bhujangasana-1":{"name":"Cobra Pose 1","goodFor":"Strengthens the back, opens the chest, and improves spinal flexibility.","instructions":"Lie face down with the tops of your feet on the floor and your hands under your shoulders, fingers pointing forward. Press your palms down and straighten your arms to lift your head and chest, keeping your hips, legs, and feet grounded. Roll the shoulders back and down and open the chest forward. Keep the neck long and gaze softly ahead. To exit, bend the elbows and lower the torso back down with control.","breathCue":"Inhale to lift the chest, exhale to lower","modifications":["lift only the head and shoulders off the floor","come down to the forearms for a gentler lift","rest a folded blanket under the hips"],"props":[],"muscleCue":"Notice the stretch in your forearms. Notice the contraction in the muscles along your spine.","drishti":"Nasagre (tip of the nose) or a soft forward gaze","modificationNote":"elbows bent, lifting the chest lower than the classic straight-arm cobra","muscles":["erector spinae","glutes","triceps","shoulders","chest","abdominals"]},"standing-hinge":{"name":"Standing Hinge","goodFor":"Loosens tight hamstrings and hips while teaching a safe hinge pattern.","instructions":"Stand beside a sturdy chair with your feet about hip-width apart. Place one hand lightly on the chair back. Stay mostly tall and add just a small tip forward from the hips. Let your other arm relax and hang by your side. Keep the legs soft, gaze gently up, and breathe slowly.","breathCue":"Exhale to tip forward, then breathe easy","modifications":["Hold the chair with both hands for more support","Stand closer to the chair","Make the hinge smaller if hamstrings feel tight"],"props":["chair"],"drishti":"up","modificationNote":"Gentle variation of the unsupported standing hinge, using a chair back for light hand support.","muscles":["hamstrings","glutes","low back","core"]},"paripurna-bhujangasana":{"name":"Complete Cobra Pose","goodFor":"Deeply opens the chest, spine, and entire front of the body.","instructions":"Lie face down with your hips resting on the mat. Arch your chest and shoulders up and back into a deep curve, and bend your knees so the feet lift toward your head. Reach both hands back to hold the outsides of your thighs (or knees) and use that hold to steady the shape. Keep the hips heavy, let the spine curve evenly, and breathe steadily. To exit, release the hold and lower your legs and torso slowly.","breathCue":"Inhale to arch up, exhale to soften deeper into the bend","modifications":["Hold one shin at a time","Keep feet lower with less knee bend","Practice regular cobra first","Loop a strap around the ankles"],"props":["Mat","Yoga strap"],"muscleCue":"Notice the stretch in your hip flexors and your abdominals. Notice the contraction in the muscles along your spine and your forearms.","drishti":"Up and back, following the arch of the spine","modificationNote":"Hands reach back to hold the thighs while the knees bend and the feet lift toward the head, making it a much deeper backbend than regular cobra","muscles":[]},"baddha-virabhadrasana-1":{"name":"Humble Warrior","goodFor":"Opens tight shoulders and hips while building leg strength and balance.","instructions":"Come into a warrior 1 stance with the front knee bent deeply and the back leg straight and strong. Interlace your fingers behind your back and draw the shoulder blades together to lift the arms. Hinge forward from the hips and lower the torso inside the front knee, letting the head hang heavy. Keep the back foot pressing down and the hips square as you settle. Let the clasped arms reach up and over toward the floor to deepen the shoulder stretch. To exit, keep the legs engaged and slowly rise back up to standing.","breathCue":"Exhale to fold, then breathe slow and steady.","modifications":["rest the hands on the hips or a block instead of clasping","use a strap between the hands if the shoulders are tight","bend the back knee slightly for better balance"],"props":["strap","yoga block"],"muscleCue":"Notice the stretch in your hamstrings and the sides of your waist. Notice the contraction in your quadriceps.","drishti":"Padayoragrai or Padayoragre (toes/feet)","modificationNote":"hands interlaced behind the back, torso folded inside the front knee, arms reaching up overhead","muscles":["hamstrings","quadriceps","glutes","shoulders","hip flexors"]},"bird-dog":{"name":"Bird Dog","goodFor":"Builds core stability, balance, and a steady, supported spine.","instructions":"Come onto hands and knees with the wrists under the shoulders and the knees under the hips. Brace the belly gently so the back stays flat. Reach one arm straight forward and the opposite leg straight back, both level with the floor. Keep the hips square to the mat and the neck long, gaze down. Hold for a few breaths. To exit, lower the hand and knee back to the floor and switch sides.","breathCue":"Inhale as you reach out, then breathe steadily while holding","modifications":["keep the back toes on the floor for balance","extend the leg only before adding the arm","kneel on a folded blanket for comfort"],"props":["folded blanket under the knee"],"muscleCue":"Notice the stretch in your shins and the tops of your feet. Notice the contraction in your glutes.","drishti":"Nasagrai or Nasagre (nose)","modificationNote":"from hands and knees, one arm reaches straight forward and the opposite leg reaches straight back, both level with the floor","muscles":["abdominals","lower back","glutes","hamstrings","shoulders"]},"bound-side-angle":{"name":"Bound Side Angle","goodFor":"Opens the hips and chest while building leg strength and balance.","instructions":"Come into a wide stance with one knee bent deeply and the other leg straight. Lean the torso forward and thread the lower arm under the front thigh. Sweep the other arm behind the back and clasp the hands or wrists. Keep the front knee over the ankle and press the back foot down. Roll the top shoulder back and turn the chest toward the sky. Hold with steady breath, then release the bind and switch sides.","breathCue":"Inhale to open the chest, exhale to settle into the bind.","modifications":["use a strap if the hands cannot clasp","keep the back hand on the hip instead of binding","bend the back knee slightly for balance"],"props":["yoga strap to bridge the hands"],"muscleCue":"Notice the stretch in your inner thighs and your chest. Notice the contraction in your quadriceps.","drishti":"Urdhva or Antara Drishti (up to the sky)","modificationNote":"lower arm wraps under the front thigh, top arm wraps behind the back, hands clasp, chest open","muscles":["quadriceps","hamstrings","glutes","inner thighs","obliques","chest"]},"eka-pada-utkatasana-1":{"name":"Standing Figure Four","goodFor":"Builds single-leg strength and balance while opening the outer hip.","instructions":"Stand tall and shift your weight onto one leg. Cross the other ankle over the standing thigh just above the knee and flex that foot. Bend the standing leg and sit your hips back into a one-legged chair, letting the chest lean slightly forward. Bring your palms together at your chest in prayer. Keep the spine long and gaze forward or softly down as you breathe steadily. To exit, straighten the standing leg and lower the crossed foot back to the floor.","breathCue":"Exhale as you sit deeper into the standing leg","modifications":["keep the toes of the crossed leg lightly touching the floor","stand near a wall for balance","stay higher in the standing leg bend"],"props":["wall or sturdy chair nearby for balance"],"muscleCue":"Notice the stretch in the deep muscles of your hips. Notice the contraction in your quadriceps and your outer hips.","drishti":"forward or slightly down toward the floor","modificationNote":"standing on one bent leg, other ankle crossed over the standing knee, hips sitting back, hands in prayer","muscles":["glutes","quadriceps","hamstrings","core","outer hips","ankles"]},"half-handstand":{"name":"Half Handstand","goodFor":"Builds shoulder and core strength while getting comfortable upside down before trying a full handstand.","instructions":"Sit with your back to the wall and stretch your legs out, then place your hands where your heels were. Come onto all fours there, facing away from the wall. Walk your feet up the wall until they reach hip height with the legs straight and level. Keeping one foot on the wall, lift the other leg straight up to the ceiling. Stack your hips over your shoulders and your shoulders over your wrists, and press the floor away. To exit, lower the lifted leg back to the wall, walk the feet down and rest in Child's Pose.","breathCue":"Exhale as you press the floor away, then breathe evenly while you hold","modifications":["keep both feet on the wall at hip height instead of lifting one leg","bend the lifted knee slightly if the hamstrings are tight","have someone stand close by for support","hold for just a few breaths at first"],"props":["wall"],"muscleCue":"Notice the stretch in your forearms. Notice the contraction in your hands.","drishti":"Hastagrai or Hastagre (hands)","modificationNote":"a handstand variation where one foot stays on the wall at hip height while the other leg reaches straight up, so the body forms an L instead of a straight vertical line","muscles":["shoulders","triceps","core","wrists and forearms","upper back"]},"headstand-prep":{"name":"Headstand Prep","goodFor":"Building shoulder strength and confidence on the way to a full headstand.","instructions":"Kneel and place the crown of the head and both forearms on the floor, hands flat beside the head. Tuck the toes, lift the knees and raise the hips up over the shoulders. Draw one knee in toward the chest and let the other leg float back and up. Press the forearms down so the neck stays light and breathe steadily. To exit, lower the extended leg, then the tucked foot, and rest.","breathCue":"Exhale as you lift the hips and hug one knee in","modifications":["Practice with the heels against a wall","Keep both toes down and just lift the hips","Tuck both knees in before extending one leg"],"props":["wall"],"muscleCue":"Notice the stretch in the soles of your feet. Notice the contraction in the front of your shoulders and your triceps.","drishti":"down toward the floor","modificationNote":"A headstand prep variation: hands stay flat beside the head instead of interlaced, one knee is tucked toward the chest and the other leg reaches back and up rather than both feet walking in with straight legs.","muscles":["shoulders","triceps","core","hip flexors","upper back"]},"low-lunge-quad":{"name":"Low Lunge Quad Stretch","goodFor":"Great for releasing tight quads and hip flexors after running or long periods of sitting.","instructions":"Come into a low lunge with one foot forward and the back knee resting on the floor. Bend the back knee and reach back with the same-side hand to hold the lifted foot. Rest the other hand on the front thigh for balance. Gently draw the heel toward the hip while the front knee stays over the ankle. Lift the chest and sink the hips forward as you breathe steadily. To exit, release the foot slowly and switch sides.","breathCue":"Inhale to lift the chest, exhale to sink the hips forward.","modifications":["loop a strap around the back foot if the hand cannot reach","keep both hands on the floor or blocks and skip the foot grab","rest the back knee on a folded blanket","stay tall with hands on the front thigh for a gentler stretch"],"props":["folded blanket under the back knee","yoga strap","blocks under the hands"],"muscleCue":"Notice the stretch in your quadriceps and your shins. Notice the contraction in your glutes and your forearms.","drishti":"forward","modificationNote":"back knee down, back shin lifted, same-side hand draws the back foot toward the hip","muscles":["quads","hip flexors","glutes","hamstrings","core"]},"parivritta-anjaneyasana":{"name":"Revolved Low Lunge","goodFor":"Opens tight hips and the chest while building a healthy spinal twist.","instructions":"Step one foot forward into a low lunge and lower the back knee to the floor. Bring your palms together at your chest. Lean forward and twist toward the front leg, hooking the elbow outside the front knee. Press the palms firmly and lift the chest, turning your gaze up toward the sky. Keep the back leg active and hold with slow, steady breaths.","breathCue":"Inhale to lengthen the spine, exhale to twist a little deeper.","modifications":["keep palms at the chest without hooking the elbow","tuck the back toes for extra stability","place a blanket under the back knee"],"props":["blanket under the back knee"],"muscleCue":"Notice the stretch in the deep muscles of your hips and your hip flexors. Notice the contraction in your quadriceps and the sides of your waist.","drishti":"Urdhva or Antara Drishti (up to the sky)","modificationNote":"back knee on the floor with the top of the back foot down; palms pressed together at the chest with the elbow hooked outside the front knee; twisting toward the front leg while gazing up","muscles":["hip flexors","quadriceps","glutes","obliques","spinal rotators","chest"]},"parivritta-janu-shirshasana":{"name":"Revolved Head-to-Knee","goodFor":"Opens the side body and stretches the hamstrings after sitting or running.","instructions":"Sit tall with both legs stretched out in front. Bend one knee and let it drop open to the side, foot resting near the thigh. Side bend over the straight leg and reach the top arm overhead toward the extended foot. Let the other hand rest on the bent knee and turn the chest up toward the sky. Keep the neck soft and breathe slowly. To come out, press down through the seat and rise back to center.","breathCue":"Exhale and lengthen deeper over the straight leg.","modifications":["bend the knee less if it strains","loop a strap around the extended foot","rest the lower hand on the bent knee","sit on a folded blanket for tight hips"],"props":["strap","folded blanket"],"muscleCue":"Notice the stretch in your hamstrings and your inner thighs. Notice the contraction in your forearms and your hands.","drishti":"Urdhva or Antara Drishti (up to the sky)","modificationNote":"seated with one leg straight and the other bent, side bending toward the straight leg with the chest turned up, top arm reaching overhead","muscles":["hamstrings","obliques","latissimus dorsi","inner thighs","spinal rotators"]},"prapadasana":{"name":"Tiptoe Squat","goodFor":"Builds ankle and foot strength while sharpening balance.","instructions":"Squat down with the feet together and come up onto the balls of the feet so the heels lift. Let the knees open wide out to the sides as you settle. Bring the palms together in prayer at the chest and let the elbows gently press the knees out. Keep the spine long and the gaze forward. Hold here, breathing slowly and steadily.","breathCue":"Exhale as you sink down, then breathe steadily while balancing.","modifications":["Fingertips on the floor for balance","One hand on a wall for support","Feet slightly apart if heels feel unstable"],"props":["Wall or chair nearby for balance"],"muscleCue":"Notice the stretch in your inner thighs and the soles of your feet.","drishti":"forward","modificationNote":"full squat on the balls of the feet, heels together and lifted, knees open wide, hands in prayer at the chest","muscles":["calves","ankles and feet","quadriceps","inner thighs","core"]},"supta-virasana":{"name":"Reclined Hero","goodFor":"Great for releasing tight quads and hip flexors after lots of standing or running.","instructions":"Start seated in Hero Pose with your knees together and feet just outside your hips. Lean back onto your hands, lower onto your elbows, then slowly settle your back and head onto the floor. Keep the thighs and knees heavy on the floor. Rest your arms alongside your body with your hands on your thighs. Soften your face and breathe steadily. To exit, press up on your elbows and return to seated.","breathCue":"Exhale as you settle your back onto the floor","modifications":["rest the back on a bolster","sit on a block between the heels before reclining","lean back only partway with hands on the floor"],"props":["bolster under the back","folded blanket under the head","block under the sit bones"],"muscleCue":"Notice the stretch in your quadriceps and your shins. Notice the contraction in your glutes.","drishti":"eyes closed or gaze soft toward the ceiling","muscles":["quadriceps","hip flexors","ankles","knees","lower back"]},"anahata-chakra-natarajasana":{"name":"Open Heart Dancer Pose","goodFor":"Builds balance and focus while opening the chest and stretching the thighs.","instructions":"Stand tall and shift your weight onto one foot. Bend the other knee and reach back with the same-side hand to hold the foot. Stretch the other arm forward at shoulder height. Press the foot into the hand and lift it toward the head as the chest lifts and the back gently arches. Keep the standing leg strong and the hips level. To exit, release the foot and stand tall, then switch sides.","breathCue":"Inhale to lift the chest and breathe steadily as you balance.","modifications":["Loop a strap around the back foot","Keep the lifted foot lower","Stand beside a wall for support","Hold the ankle if the foot is out of reach"],"props":["Yoga strap","Wall"],"muscleCue":"Notice the stretch in your quadriceps and your hip flexors. Notice the contraction in your outer hips and the muscles along your spine.","drishti":"Forward, toward the extended hand (Hastagrai)","modificationNote":"one hand grips the back foot high toward the head while the other arm reaches forward, keeping the chest lifted and open","muscles":[]},"ardha-matsyendrasana-2":{"name":"Half Lord of The Fishes Pose 2","goodFor":"Loosens a stiff spine and hips while giving the digestive organs a gentle squeeze.","instructions":"Sit tall with both legs stretched out in front. Bend one leg and tuck its heel in close to the opposite hip. Cross the other foot over and plant it flat on the floor outside that thigh. Ground one hand on the floor behind you and lift the other arm up with the palm facing forward. Inhale to lengthen, then exhale and rotate your belly and chest toward the raised knee. Keep both sit bones down and hold the twist for a few slow breaths.","breathCue":"Inhale to lengthen the spine, exhale to twist deeper","modifications":["Keep the bottom leg extended if the tuck feels too tight","Rest the back hand on a block for more lift","Hold the raised knee with the hand instead of lifting the arm"],"props":["block","folded blanket"],"muscleCue":"Notice the stretch in the sides of your waist and your chest. Notice the contraction in your quadriceps.","drishti":"over the back shoulder","modificationNote":"Unlike the classic version, the top arm stays lifted with the palm facing forward instead of pressing the elbow into the knee.","muscles":[]},"ardha-ushtrasana":{"name":"Half Camel Pose","goodFor":"Opens the chest and shoulders while stretching the thighs and hip flexors.","instructions":"Kneel with the knees hip-width apart and the hips over the knees. Lift the chest and bend back, reaching one hand back to the heel. Stretch the other arm up and back. Press the hips forward and keep the neck long. To exit, bring the arm forward, lift the chest back up and switch sides.","breathCue":"Inhale to lengthen spine, exhale to draw in deep abdominal muscles","modifications":["Rest hand lightly on heel","Hand on lower back instead","Use strap for reach"],"props":[],"muscleCue":"Notice the stretch in your shins and the tops of your feet. Notice the contraction in your glutes and the front of your shoulders.","drishti":"Up and back, toward the camera","modificationNote":"one hand to the heel, other arm extended","muscles":[]},"baddha-malasana":{"name":"Bound Garland Pose","goodFor":"Opens the hips and ankles while stretching the lower back.","instructions":"Squat with the heels down and the knees wide. Lean forward and wrap the arms around the outside of the legs. Reach behind the back and clasp the hands. Lift the chest and keep the heels down. To exit, release the hands and stand up.","breathCue":"Exhale and sink your hips a little deeper.","modifications":["Heels down on floor","Widen the feet for balance","Use a strap if the hands don't meet","Sit on a block if the heels lift"],"props":["block","strap"],"muscleCue":"Notice the stretch in your inner thighs and your calves.","drishti":"Nasagrai or Nasagre (nose)","modificationNote":"arms wrapped around the legs, binding behind the back","muscles":[]},"eka-pada-raja-kapotasana-1-b":{"name":"One-Legged King Pigeon Pose 1 Version B","goodFor":"Great for opening tight hips and quads while building chest and shoulder flexibility.","instructions":"Kneel and fold one leg in front so the knee and shin rest on the floor with the foot flat. Bend the back knee and lift the back foot off the floor. Reach back with both hands and take hold of the back foot. Keep the hips low and square as you lift the chest and gently draw the foot in. Hold with slow even breaths, then release and switch sides.","breathCue":"Inhale to lift the chest, exhale to settle the hips","modifications":["Loop a strap around the back foot","Pad the knees with a blanket","Hold the foot with one hand only","Stay more upright if the backbend feels deep"],"props":["strap","blanket"],"muscleCue":"Notice the stretch in your quadriceps and your hip flexors. Notice the contraction in your glutes.","drishti":"gaze forward, eyes soft","modificationNote":"both hands hold the bent back foot behind while the hips stay low, instead of hands on the floor","muscles":[]},"eka-pada-utkatasana-2":{"name":"One-Legged Fierce Pose 2","goodFor":"Builds single-leg strength and balance while opening the outer hip.","instructions":"Stand tall and shift your weight onto one foot. Bend that knee and sink into a squat. Cross the other ankle over the standing thigh just above the knee and flex that foot. Fold your torso forward and bring your palms together at your chest. Keep your weight in the standing heel and breathe steadily, then switch sides.","breathCue":"Exhale as you fold forward, then breathe steadily","modifications":["Stay more upright with a smaller fold","Keep hands on hips for less load","Use a wall for balance support"],"props":["Wall"],"muscleCue":"Notice the stretch in the deep muscles of your hips. Notice the contraction in your quadriceps and your outer hips.","drishti":"Forward and slightly down, toward the floor ahead","modificationNote":"one-legged squat with the ankle crossed over the standing knee in a figure four","muscles":[]},"gherandasana-6":{"name":"Sage Gheranda Pose 6","goodFor":"Opens the shoulders and stretches the thighs while building flexibility in the spine.","instructions":"Lie on your belly with the head in a relaxed, forward-facing position. Bend both knees and lift the feet toward the ceiling. Reach both arms back and take hold of the tops of the feet. Gently pull the feet so the knees rise and the back arches, keeping the chest and hips grounded. Breathe steadily, then release the feet slowly and lower the legs.","breathCue":"Inhale as you draw the feet in and lift the knees","modifications":["hold one foot at a time if both feels like too much","loop a strap around each ankle if the feet are out of reach","bend the knees without holding the feet to start"],"props":["yoga strap","folded blanket"],"muscleCue":"Notice the stretch in your quadriceps and your hip flexors. Notice the contraction in the muscles along your spine.","drishti":"Nasagrai (tip of the nose) or a soft point on the floor just ahead","modificationNote":"both feet are gripped with deeply bent knees while the chest stays close to the floor","muscles":[]},"gorakshasana":{"name":"Cowherd Pose","goodFor":"Opens the hips and inner thighs while building a tall, calm seated posture.","instructions":"Sit on the floor and bring the soles of the feet together with knees wide. Let the feet cross and settle in front of you as the knees sink down. Sit up tall on the sitting bones with a straight spine. Rest both hands on the feet. Soften the shoulders and gaze forward. Hold with slow, even breaths.","breathCue":"Inhale to lengthen the spine, exhale to let the hips soften.","modifications":["Sit on a folded blanket to lift the hips","Keep the feet a little further away if the knees strain","Rest hands on the ankles instead of the feet"],"props":["folded blanket under the hips","blocks under the knees"],"muscleCue":"Notice the stretch in your quadriceps and the deep muscles of your hips. Notice the contraction in your forearms and your hands.","drishti":"forward","modificationNote":"In this variation the hands rest on the feet instead of gripping the toes.","muscles":[]},"hindolasana":{"name":"Baby Cradle Pose","goodFor":"Opens tight outer hips and stretches the hamstring of the extended leg.","instructions":"Sit tall with both legs straight out in front. Bend one knee and lift the shin, cradling it in the arms with the foot in one elbow and the knee in the other. Keep the other leg straight on the floor and the spine upright. Rock the shin gently from side to side to open the hip, then hug it toward the chest. To exit, lower the foot, straighten the leg and switch sides.","breathCue":"Exhale as you rock the shin side to side","modifications":["Sit on a folded blanket","Bend the extended knee slightly","Hold the shin instead of the full cradle"],"props":["folded blanket"],"muscleCue":"Notice the stretch in the deep muscles of your hips. Notice the contraction in your forearms and your hands.","drishti":"Padayoragrai or Padayoragre (toes of the extended foot)","modificationNote":"other leg extended straight on the floor instead of cross-legged","muscles":[]},"kalyasana":{"name":"Kali Pose","goodFor":"Opens the hips while building strength in the legs.","instructions":"Stand with the feet wide and the toes turned out. Bend the knees deeply, keeping the heels down and the knees over the toes. Raise the arms to head height, bend the elbows and turn the palms to the sky. Keep the chest upright and the tailbone pointing down. To exit, lower the arms and straighten the legs.","breathCue":"Exhale as you sink into the squat.","modifications":["make the squat shallower","hold the arms a little lower","rest a hand on a wall for balance"],"props":[],"muscleCue":"Notice the stretch in your inner thighs. Notice the contraction in your quadriceps.","drishti":"Nasagrai or Nasagre (nose)","modificationNote":"elbows bent, palms facing the sky, heels down","muscles":[]},"kapotasana":{"name":"Kneeling Pigeon Backbend","goodFor":"Opens the chest and shoulders while stretching the whole front of the body.","instructions":"Kneel with the knees hip-width apart and the hands on the lower back. Lift the chest and bend back, then take the arms over the head and lower the palms to the floor behind you. Walk the hands toward the feet, letting the head drop back and the feet come toward the head. Keep pressing the hips forward over the knees. To exit, walk the hands away from the feet, lift the chest with control and rest in Child's Pose.","breathCue":"Inhale to lift the chest, exhale to press the hips forward","modifications":["Start from bridge pose","Use forearm wheel","Drop to knees from wheel"],"props":[],"muscleCue":"Notice the stretch in your shins and the tops of your feet. Notice the contraction in your glutes.","drishti":"toward the floor behind the head","modificationNote":"arms over the head, palms to the floor, feet toward the head","muscles":[]},"khanjanasana":{"name":"Wagtail Bird Pose","goodFor":"Builds leg and core strength while opening the hips and improving balance.","instructions":"Squat down low with the feet a little apart and the heels as close to the floor as you can. Fold the torso forward between the thighs and let the shoulders press behind the knees. Reach both arms back between the legs and bring the fingertips toward the heels. Let the head hang heavy and the back round. Hold for a few breaths, then release the hands to the floor and slowly roll up to standing.","breathCue":"Exhale as you fold down into the squat","modifications":["Rest the fingertips on the floor behind you","Sit on a block if the heels lift","Keep the hands on the floor in front instead of reaching back"],"props":["yoga block"],"muscleCue":"Notice the stretch in your calves. Notice the contraction in your quadriceps.","drishti":"Nasagra (tip of the nose)","modificationNote":"shoulders to the back of the knees, fingertips to the heel","muscles":[]},"makarasana":{"name":"Crocodile Pose","goodFor":"Good for gentle core and shoulder strength while easing tension in the lower back.","instructions":"Lie face down and bend your elbows so your forearms rest on the floor under your shoulders. Hold opposite elbows or clasp your hands and let your head rest heavy on your arms. Press through your forearms and the balls of your feet to lift your chest and hips into one straight line. Keep your legs straight and reach back through your heels. Breathe slowly, hold for several breaths, then lower your body back down to rest.","breathCue":"Breathe slowly and evenly as you hold","modifications":["Lower the knees to the floor","Rest the chest flat and relax","Stack the hands and rest the head lower"],"props":[],"modificationNote":"active variation: body held lifted in a straight line on forearms and toes instead of resting flat on the floor","muscles":[]},"niralamba-sarvangasana":{"name":"Unsupported Shoulder Stand","goodFor":"Tones the whole body and boosts blood flow to the neck, brain and thyroid.","instructions":"Lie on your back with the legs together and the arms resting along your sides. Lift the legs toward the ceiling, then raise the hips and back so the weight rests on the shoulders. Keep the hands away from the back and let the arms stay along the body. Straighten the legs and stack the hips over the shoulders in one tall line. To exit, bring the hands back to support the lower back and roll down slowly.","breathCue":"Exhale as you lift, then breathe slow and steady while you hold","modifications":["practice beside a wall for support","keep the hands on the lower back until steady","use a folded blanket under the shoulders"],"props":["folded blanket under the shoulders"],"muscleCue":"Notice the stretch in the top of your shoulders.","drishti":"Soft gaze toward the third eye, between the eyebrows","modificationNote":"hands off the back, arms along the body","muscles":[]},"niralamba-vyaghrasana":{"name":"Unsupported Tiger Pose","goodFor":"Builds balance and body awareness while stretching the thigh and opening the chest.","instructions":"Start on hands and knees. Bend one knee and lift that foot toward the ceiling. Reach the same-side hand back under the shoulder and hold the foot, then let the back arch and the chest lift. Balance on the other hand and knee. To exit, release the foot, return to hands and knees and switch sides.","breathCue":"Inhale as you lift the foot, breathe steadily as you balance","modifications":["Hold the shin instead of the foot","Use a strap around the foot if you cannot reach","Keep the lifted foot lower to soften the arch"],"props":["Folded blanket under the knee"],"muscleCue":"Notice the stretch in your quadriceps and your hip flexors.","drishti":"Angushtamadhye or Angushta Ma Dyai (thumbs)","modificationNote":"grabbing onto the foot with under-head grip on the same side","muscles":[]},"padangushta-dhanurasana":{"name":"Big Toe Bow Pose","goodFor":"Opens the chest and shoulders while strengthening the back and legs.","instructions":"Lie on your belly and bend both knees. Reach your hands back over your shoulders and take hold of the big toes, elbows pointing up. Kick the feet into the hands to lift your chest and thighs off the floor. Keep the head neutral and gaze forward. To exit, release the toes slowly, lower down, and rest with the head to one side.","breathCue":"inhale to lift the chest and legs","modifications":["hold the ankles instead of the toes","loop a strap around the feet","lift only the chest at first"],"props":["yoga strap"],"muscleCue":"Notice the stretch in your quadriceps and your hip flexors. Notice the contraction in the muscles along your spine.","drishti":"forward, toward the horizon","modificationNote":"holding the big toes instead of the ankles, as in the base bow pose","muscles":[]},"paripurna-navasana":{"name":"Complete Boat Pose","goodFor":"Builds core strength, hip flexor power and balance.","instructions":"Sit with the knees bent and the feet on the floor, hands beside the hips. Lean back, lift the chest and raise the feet. Straighten both legs so the body forms a V, keeping the back long. Stretch the arms straight forward, parallel to the floor. To exit, bend the knees, lower the feet to the floor and sit up.","breathCue":"Exhale as you lift, then breathe steadily while holding","modifications":["Lean back slightly","Keep feet flat on floor","Hold arms at chest level"],"props":[],"muscleCue":"Notice the contraction in your quadriceps and your hip flexors.","drishti":"Forward and slightly up","muscles":[]},"parivritta-balasana":{"name":"Revolved Child’s Pose","goodFor":"Gently releases the lower back, waist, and shoulders.","instructions":"Start kneeling and sink your hips back toward your heels. Fold forward and rotate your torso to one side. Reach one arm out along the floor in front of you. Let the same-side shoulder and your head rest down on the floor. Bend the other arm and relax it near your chest. Breathe slowly, then lift and switch sides.","breathCue":"Exhale and soften a little deeper into the twist","modifications":["Rest the head on a block or folded blanket","Keep the twist small and chest only halfway down","Widen the knees and pad them with a blanket"],"props":["Folded blanket under the knees","Block under the head"],"muscleCue":"Notice the stretch in your quadriceps and your shins. Notice the contraction in your outer hips and the sides of your waist.","modificationNote":"Twisted take on child's pose: the torso rotates so one shoulder and the head come to the floor, one arm reaches out along the floor and the other bends near the chest","muscles":[]},"parivritta-krounchasana":{"name":"Revolved Heron Pose","goodFor":"Opens the hips and hamstrings while giving the spine a deep, cleansing twist.","instructions":"Sit with one leg folded under you so the foot rests beside the opposite hip. Bend the other knee and hold the foot with both hands. Straighten that leg up toward the sky and keep it strong. Revolve your torso toward the raised leg, leading with the chest. Lengthen the spine, grip the foot firmly, and hold for a few breaths.","breathCue":"Inhale to lengthen the spine, exhale to revolve deeper.","modifications":["Keep the raised knee bent and hold the knee or shin","Loop a strap around the foot if the hands cannot reach","Stay more upright and twist only partway"],"props":["strap around the raised foot","folded blanket under the sitting bones"],"muscleCue":"Notice the stretch in your quadriceps and your hamstrings. Notice the contraction in the sides of your waist.","drishti":"up toward the raised foot","modificationNote":"Adds a revolve to Heron Pose: the torso twists toward the raised leg while both hands hold the foot overhead.","muscles":[]},"parivritta-virasana":{"name":"Revolved Hero Pose","goodFor":"Loosens the spine and stretches the thighs, ankles and waist after long sitting.","instructions":"Kneel and sit between or on the heels in Hero Pose. Lengthen the spine and turn the torso to one side. Place the hands on the floor beside the hips to help the turn. Keep both knees together and the sitting bones down. To exit, turn back to the centre and repeat to the other side.","breathCue":"Inhale to lengthen the spine, exhale to twist deeper.","modifications":["Sit on a block or folded blanket if the hips are tight","Rest one hand on the knee instead of the floor","Keep the twist smaller with the chest more forward"],"props":["Yoga block to sit on","Folded blanket under the knees"],"muscleCue":"Notice the stretch in your quadriceps. Notice the contraction in the sides of your waist and the front of your shoulders.","drishti":"Parshva Drishti (to the right), Parshva Drishti (to the left)","modificationNote":"twisting, hands to the floor","muscles":[]},"parshva-anjaneyasana":{"name":"Sideways Low Lunge","goodFor":"Opens tight hip flexors while giving the whole side body a long stretch.","instructions":"Step one foot forward and lower the back knee to the floor. Keep the front knee bent over the ankle and the hips square. Lean into a side bend over the front leg and let the top arm arc up and over the head. Reach the lower hand down toward the back foot. Keep the hips sinking forward, breathe, then switch sides.","breathCue":"Exhale and sink a little deeper into the side bend.","modifications":["Rest the lower hand on the back thigh","Put a blanket under the back knee","Keep the top hand on the hip for a gentler bend"],"props":["mat"],"muscleCue":"Notice the stretch in your hip flexors and your inner thighs. Notice the contraction in your quadriceps.","drishti":"down toward the floor","modificationNote":"a side-bending version of low lunge — the top arm arcs overhead while the lower hand reaches down toward the back foot, with the back knee resting on the floor","muscles":[]},"parshva-uttanasana":{"name":"Sideways Intense Stretch","goodFor":"Stretches the hamstrings and hips while calming the mind.","instructions":"Stand with the feet wide apart and the legs straight. Turn the torso to face one leg and fold forward from the hips. Place both palms flat on the floor on either side of the front foot. Let the head hang down toward the shin. Keep the hips level and the weight even in both feet. To exit, walk the hands back to centre and roll up slowly.","breathCue":"Exhale to fold deeper and breathe slowly in the hold.","modifications":["Bend the front knee slightly if hamstrings are tight","Rest hands on blocks if the floor feels far","Take a shorter stance for less intensity"],"props":["yoga blocks under the hands"],"muscleCue":"Notice the stretch in your hamstrings and your forearms.","drishti":"toward the front shin","modificationNote":"wide stance with the torso folded sideways over one leg and both palms flat on the floor","muscles":[]},"parshva-vrikshasana":{"name":"Sideways Tree Pose","goodFor":"Opens the side body while building single-leg balance and focus.","instructions":"Stand tall on one leg and rest the other sole against the inner thigh of the standing leg, knee pointing out. Sweep one arm up overhead and let the other arm float out to the side. Bend sideways toward the bent knee, keeping the standing leg straight and strong. Keep the hips facing forward and the chest open. To exit, come back to centre, lower the foot and switch sides.","breathCue":"Inhale to lengthen, exhale to bend deeper.","modifications":["Keep the bent-leg toes on the floor for support","Place the foot on the calf instead of the thigh","Stand near a wall and touch it for balance"],"props":["wall for balance support"],"muscleCue":"Notice the stretch in the sides of your waist and your lower back. Notice the contraction in your outer hips.","drishti":"forward","modificationNote":"side bend toward the bent knee","muscles":[]},"prasarita-padottanasana-5":{"name":"Wide-Legged Forward Bend V","goodFor":"Stretches the hamstrings, hips and shoulders while calming the mind.","instructions":"Stand with the feet wide and parallel. Bring the hands behind the back and press the palms together in reverse prayer, fingers pointing up. Lengthen the spine, then fold forward from the hips, letting the head drop toward the floor between the feet. Keep the weight even across both feet. To exit, bend the knees slightly, come up with a long back and release the hands.","breathCue":"Exhale to fold deeper and let the head release","modifications":["Bend knees slightly for tight hamstrings","Hold opposite elbows behind the back","Rest hands on hips if shoulders strain","Shorten the stance for better balance"],"props":["Yoga mat"],"muscleCue":"Notice the stretch in your hamstrings.","drishti":"Nasagrai or Nasagre (nose)","modificationNote":"hands in reverse prayer behind the back","muscles":[]},"sasangasana":{"name":"Rabbit Pose","goodFor":"Loosens the whole spine and releases tension in the back and neck.","instructions":"Kneel with your knees together and sit back on your heels. Fold forward and reach your hands back to hold your heels or the bottoms of your feet. Tuck your chin and let the crown of your head rest on the mat close to your knees. Lift your hips toward the ceiling and pull on your feet to round the back deeply. To come out, lower the hips back to the heels and rise up slowly.","breathCue":"Breathe between shoulder blades as you round back.","modifications":["Keep hands on thighs","Use strap to pull heels"],"props":["Forehead support"],"muscleCue":"Notice the stretch in the top of your shoulders. Notice the contraction in your forearms and your hands.","drishti":"Nabhi, Nabhicakre, or Nabi Chakra (belly button)","muscles":[]},"sayana-dandasana":{"name":"Repose Staff Pose","goodFor":"Builds core strength and whole-body stability while strengthening the shoulders and legs.","instructions":"Lie on the belly with the elbows under the shoulders. Tuck the toes and lift the knees and hips so the body forms one straight line. Bring the hands together and rest the chin in the palms, keeping the weight on the elbows and toes. Draw the belly in so the hips stay level. To exit, lower the knees and rest in Child's Pose.","breathCue":"Exhale as you lift, then breathe slowly and steadily","modifications":["Lower the knees to the floor for support","Place a folded blanket under the forearms","Hold for a few breaths at first and build up"],"props":["Yoga mat"],"drishti":"Gaze forward and slightly down toward the floor ahead","modificationNote":"plank on the elbows, chin resting in the hands","muscles":[]},"shalabhasana":{"name":"Locust Pose","goodFor":"Great for strengthening the back body and improving posture.","instructions":"Lie on your belly with your legs together and your forehead on the floor. Stretch your arms straight back beside your hips with the hands on the floor. On an inhale, lift your head, chest, arms, and both legs off the floor. Keep your knees straight and reach back through your toes. Roll your shoulders back, keep the neck long, and gaze slightly forward. To exit, lower everything down slowly and rest.","breathCue":"Breathe deeply into your back as you lift.","modifications":["keep feet on the floor and lift chest only","lift one leg at a time","rest forehead on a folded blanket"],"props":[],"muscleCue":"Notice the stretch in your hip flexors and your abdominals. Notice the contraction in your glutes.","drishti":"forward, slightly down","muscles":[]},"sukha-matsyasana":{"name":"Easy Fish Pose","goodFor":"Opens the chest and front of the body while gently strengthening the back and shoulders.","instructions":"Sit with the legs straight in front. Lean back onto the forearms, elbows under the shoulders. Lift the chest and draw the shoulders back, keeping the head off the floor. Keep the legs straight and active. To exit, slide the elbows forward and lower the back to the floor, or press up to sitting.","breathCue":"Breathe deeply, exhale to release tension","modifications":["Use a block under the mid-back","Tuck the hands under the hips for support","Bend the knees if the back complains","Lift the chest a little less"],"props":["block","bolster","yoga mat"],"muscleCue":"Notice the stretch in the front of your neck. Notice the contraction in the front of your shoulders and your triceps.","drishti":"Upward and slightly back, following the tilt of the head, or eyes closed","modificationNote":"head off the floor, forearms on the floor, legs straight","muscles":[]},"sukha-pashasana":{"name":"Easy Noose Pose","goodFor":"Opens the ankles and hips while giving the spine a deep twist.","instructions":"Squat down low with the feet together and the heels resting on the floor. Twist the torso to one side and lower the opposite shoulder toward the knees, placing that palm flat on the floor. Reach the other arm up and back, keeping it long and active. Keep the heels down and keep turning the chest as you hold. To come out, bring both hands to the floor, untwist back to the centre and repeat on the other side.","breathCue":"Exhale as you settle deeper into the twist","modifications":["Rest the lower hand on a block","Hold a chair or wall for balance","Keep the top hand on the hip","Place a folded blanket under the heels"],"props":["block","chair"],"muscleCue":"Notice the stretch in your calves and the muscles along your spine. Notice the contraction in the sides of your waist.","drishti":"down toward the floor","modificationNote":"An easier version of noose pose without the bind: one palm stays flat on the floor and the other arm reaches up and back instead of wrapping around the legs.","muscles":[]},"supta-padmasana":{"name":"Reclining Lotus Pose","goodFor":"Opens the hips deeply while calming the nervous system.","instructions":"Sit in lotus with each foot resting on the opposite thigh. Lie back slowly until your back and head rest flat on the floor. Let the knees stay heavy and relaxed. Hold the feet or rest the hands on the legs. Soften the whole body and breathe slowly. To exit, press up to sitting and release the legs one at a time.","breathCue":"Breathe slowly into the belly and soften with each exhale.","modifications":["use half lotus if full lotus strains the knees","place a folded blanket under the head","rest the hands on the knees instead of holding the feet"],"props":["folded blanket under the head"],"muscleCue":"Notice the stretch in your quadriceps and your shins.","drishti":"Bhrumadhye or Ajna Chakra (third eye, between the eyebrows)","muscles":[]},"tiryang-mukhottanasana":{"name":"Reverse Facing Intense Stretch Pose","goodFor":"Opens the chest and shoulders while stretching the whole front of the body.","instructions":"Stand with the feet hip-width apart and the hands on the lower back. Lift the chest and bend back, pressing the hips forward. Keep the legs straight and slide the hands down to hold the shins. Let the head drop back gently. To exit, slide the hands up the legs and lift the chest back to standing.","breathCue":"Inhale to lift the chest, exhale to arch a little deeper","modifications":["keep the hands on the lower back","bend the knees slightly for a tender back","stay higher on the thighs with a smaller bend"],"props":["wall behind for support"],"muscleCue":"Notice the stretch in your hip flexors and your abdominals. Notice the contraction in your forearms and your hands.","drishti":"Bhrumadhye or Ajna Chakra (third eye, between the eyebrows)","modificationNote":"grabbing onto the shins","muscles":[]},"tittibhasana-3-a":{"name":"Firefly Pose 3 A","goodFor":"Builds single-leg balance, hamstring flexibility and core strength.","instructions":"Stand tall with the feet hip-width apart and fold forward from the hips. Let one hand take hold of the ankle of the standing leg and place the other hand on the floor. Shift your weight into the standing foot and lift the other leg up and back. Let the head hang and draw the chest toward the thighs. To exit, lower the lifted foot, release the ankle and roll up slowly.","breathCue":"Exhale as you fold and lift the back foot","modifications":["Keep both hands on the ankles","Bend the standing knee slightly","Rest the free hand on a block"],"props":["Mat","Yoga block"],"muscleCue":"Notice the stretch in the muscles along your spine. Notice the contraction in your quadriceps and the front of your shoulders.","drishti":"Down toward the floor","modificationNote":"Standing prep: one hand holds the standing ankle, the other hand rests on the floor and one leg lifts off the floor","muscles":[]},"upavishta-prapadasana":{"name":"Seated Tip Toe Pose","goodFor":"Builds ankle strength and balance while opening the hips.","instructions":"Squat down and rise onto the balls of the feet so the heels lift. Let the knees spread apart and lower the hips toward the heels. Rest the elbows on the knees and interlock the fingers in front of the face. Keep the back long and the weight even over both feet. To exit, place the hands on the floor, lower the heels and stand up.","breathCue":"Exhale as you sink the hips down, inhale to lengthen the spine","modifications":["Rest the heels on a rolled blanket","Keep the hands on the floor instead of clasping them","Hold a wall or chair for extra balance"],"props":["rolled blanket under the heels","wall or chair nearby for balance"],"muscleCue":"Notice the stretch in your quadriceps and the soles of your feet.","drishti":"Angushtamadhye or Angushta Ma Dyai (thumbs)","modificationNote":"elbows resting on the knees, fingers interlocked in front of the face","muscles":[]},"viparita-shalabhasana":{"name":"Inverted Locust Pose","goodFor":"Builds strong back, hip and shoulder muscles while giving the spine a deep extension.","instructions":"Lie on your belly with the chin and chest on the floor and the arms spread wide out to the sides. Bend the knees and lift the legs up, letting the hips rise as the feet travel toward the head. Keep the weight on the chin, chest and arms and hold with the head still. To exit, lower the legs slowly with control and rest with the head turned to one side.","breathCue":"Inhale to lift the legs, then breathe steadily as you hold.","modifications":["practice locust pose with legs just past vertical first","keep the knees less bent and the feet lower","pad the chin and chest with a folded blanket"],"props":["folded blanket under the chin and chest"],"muscleCue":"Notice the stretch in your abdominals.","modificationNote":"legs lift past vertical toward the head with bent knees and arms spread wide","muscles":[]},"vishama-setu-bandha-sarvangasana":{"name":"Uneven Bridge Pose","goodFor":"Strengthens the glutes and hamstrings while building hip stability and balance.","instructions":"Lie on your back with knees bent and feet flat on the floor, hip-width apart, arms resting alongside your body. Press into the feet and lift the hips into bridge. Extend one leg straight out, keeping it level and the hips even. Press the standing foot down and squeeze the glutes to hold. To exit, lower the extended leg, roll the spine down and repeat on the other side.","breathCue":"Inhale to lift the hips, exhale to extend the leg","modifications":["Keep the extended leg lower or slightly bent","Rest the extended leg on a block or chair","Practice regular bridge first to build strength","Hold for fewer breaths and switch sides"],"props":["mat"],"muscleCue":"Notice the stretch in your chest and the front of your shoulders. Notice the contraction in your glutes.","drishti":"Bhrumadhye or Ajna Chakra (third eye, between the eyebrows)","modificationNote":"one leg stays straight and lifted while the other foot supports the bridge","muscles":[]},"janu-garudasana":{"name":"Kneeling Eagle Pose","goodFor":"Opens the chest and shoulders while stretching the thighs and building spinal flexibility.","instructions":"Kneel down and cross one shin over the other so the feet cross behind you. Sit up tall with the hips stacked over the knees. Reach both arms up overhead. Lift the chest and arch back into a deep backbend, letting the head drop back. Keep breathing steadily as you hold. To exit, lift the chest, lower the arms and uncross the legs.","breathCue":"Inhale to lift the chest, exhale to arch back","modifications":["Pad the knees with a folded blanket","Hands on the lower back instead of arms overhead","Arch less and keep the chest lifted","Cross just the ankles if the shins won't cross"],"props":["Folded blanket under the knees"],"muscleCue":"Notice the stretch in your shins and the tops of your feet. Notice the contraction in your quadriceps.","drishti":"Hastagrai or Urdhva (toward the hands, upward)","modificationNote":"Eagle pose adapted to kneeling, with the legs crossed on the floor and the torso arching back with arms reaching overhead instead of the standing wrap","muscles":[]},"jatara-parivartanasana":{"name":"Twisted Stomach Pose","goodFor":"Great for releasing lower back and hip tension and giving the abdominal organs a gentle massage.","instructions":"Lie on your back and hug both knees in toward your chest. Stretch one arm out from your shoulder along the floor and reach the other arm back overhead. Let both bent knees drop over to one side, keeping them stacked. Settle both shoulders and your upper back into the floor. Turn your head the other way if that feels comfortable. To come out, bring the knees back to centre and repeat on the other side.","breathCue":"Exhale as you let the knees lower to one side","modifications":["Rest the knees on a block or cushion","Keep the knees higher for a gentler twist","Soften the overhead arm if the shoulder strains"],"props":["block"],"muscleCue":"Notice the stretch in your outer hips. Notice the contraction in the sides of your waist.","drishti":"Bhrumadhye or Ajna Chakra (third eye, between the eyebrows)","modificationNote":"knees bent and lowered to one side, with one arm stretched overhead instead of both arms in a T","muscles":[]},"prapada-utkatasana":{"name":"Tip Toe Fierce Pose","goodFor":"Builds leg strength and balance while challenging ankle stability.","instructions":"Stand tall with your feet about hip width apart. Rise up onto the balls of your feet, lifting your heels high. Stretch your arms straight forward at shoulder height. Bend your knees and sink your hips down and back as if lowering into a low chair. Keep your spine long and chest lifted as you balance on your tiptoes.","breathCue":"Exhale as you sink the hips, inhale to lengthen the spine","modifications":["Practice near a wall for balance support","Squat less deeply at first","Hold the pose for fewer breaths"],"props":["wall or chair for balance"],"muscleCue":"Notice the stretch in the soles of your feet. Notice the contraction in your calves.","drishti":"forward","modificationNote":"Unlike regular chair pose, the heels stay lifted on tiptoes and the arms reach straight forward instead of overhead.","muscles":[]},"parshva-karnapidasana":{"name":"Sideways Ear Pressure Pose","goodFor":"Releases the spine and side body while deeply calming the nervous system.","instructions":"Lie on your back and swing your legs overhead into plow pose with toes resting on the floor. Bend both knees and walk them together toward one side of your head. Let the knees settle on the floor beside one ear, pressing softly against it. Keep your weight on the shoulders, head and hands, and relax the feet. Hold here with slow, steady breaths.","breathCue":"Exhale as the knees lower toward the ear, then breathe slowly","modifications":["Lower the knees only partway toward the ear","Rest hands flat on the floor for support","Use a folded blanket under the shoulders"],"props":["folded blanket under the shoulders"],"muscleCue":"Notice the stretch in your shins and the tops of your feet. Notice the contraction in the sides of your waist and the back of your shoulders.","drishti":"tip of the nose","modificationNote":"Unlike the base ear pressure pose where the knees frame both ears, here both bent knees drop together to one side so they rest beside a single ear.","muscles":[]},"vishama-ashtavakrasana":{"name":"Uneven Eight-Angle Pose","goodFor":"Builds arm and core strength while opening the hips and deepening the spinal twist.","instructions":"Sit tall and lean forward to plant both hands firmly on the floor. Hook one leg high over the same-side arm and let the other leg rest in front of it. Press down, lean your chest forward, and lift your hips off the floor. Stretch both legs out to the side, keeping them straight at different heights. Lower your torso until it hovers near the floor and gaze down. Hold for a few steady breaths, then lower down with control.","breathCue":"Exhale as you lift, then breathe steadily while holding","modifications":["Keep one foot lightly on the floor for support","Bend the lower knee slightly if the hamstrings are tight","Set a block under the hands for extra lift"],"props":["yoga block"],"muscleCue":"Notice the stretch in your hamstrings. Notice the contraction in the front of your shoulders and your triceps.","drishti":"down at the floor","modificationNote":"Unlike the base eight-angle pose, the legs stay uncrossed and staggered at different heights instead of stacked with the ankles crossed.","muscles":[]},"parshva-kukkutasana":{"name":"Side Rooster Pose","goodFor":"Builds wrist, arm and core strength while opening the hips and training balance through a twist.","instructions":"Sit in lotus, folding each foot on top of the opposite thigh. Plant both palms flat on the floor and lean your weight into your hands. Twist your torso to the side and hook your stacked folded legs over the outside of one upper arm. Shift your weight forward, press down, and lift your hips off the floor so one foot rises high. Keep your arms straight, engage your core, and breathe steadily as you hold.","breathCue":"Exhale as you twist and lift, then breathe steadily while balancing.","modifications":["practice the seated twist with folded legs first","build up from crow pose to learn the lift","keep one toe lightly on the floor for support"],"props":["folded blanket under the face for a soft landing"],"muscleCue":"Notice the stretch in your inner thighs and your forearms. Notice the contraction in the front of your shoulders and your triceps.","drishti":"down at the floor","modificationNote":"A twisted version of Rooster Pose: instead of resting the folded legs between both arms, they stack on the outside of one upper arm with the torso turned and one foot lifted high.","muscles":[]},"ardha-vayu-muktyasana":{"name":"Half Wind Relieving Pose","goodFor":"Releasing trapped gas and gently relaxing the lower back and hips.","instructions":"Lie on the back with both legs straight. Bend one knee and hug it to the chest with both hands. Keep the other leg straight and long on the floor. Relax the shoulders and the back of the neck. To exit, release the knee, straighten the leg and switch sides.","breathCue":"Inhale to lengthen, exhale and draw the knee a little closer","modifications":["Rest the head on a small blanket","Loop a strap around the knee if the arms feel short","Bend the extended knee with the foot flat if the low back is uncomfortable"],"props":["blanket under the head","strap around the knee"],"muscleCue":"Notice the stretch in the deep muscles of your hips and your hip flexors. Notice the contraction in your forearms and your hands.","drishti":"Nasagrai or Nasagre (nose)","modificationNote":"one knee hugged to the chest, other leg straight on the floor","muscles":[]},"trianga-mukhaikapada-paschimottanasana":{"name":"Three-Limbed Forward Bend","goodFor":"Stretches the hamstrings and the front of the bent leg while opening the hips.","instructions":"Sit tall with one leg stretched straight ahead. Bend the other knee and place the foot beside its hip, keeping the thigh close to the straight leg. Press the hips down and lengthen the spine. Exhale and fold forward over the straight leg. Hold the foot, ankle, or shin and keep breathing steadily.","breathCue":"Exhale as you fold, inhale to lengthen","modifications":["sit on a folded blanket if the hips feel tight","use a strap around the extended foot","bend the straight knee slightly for tight hamstrings","rest the hands on a block instead of reaching the foot"],"props":["folded blanket under the hips","strap around the extended foot"],"muscleCue":"Notice the stretch in your quadriceps and your shins. Notice the contraction in your forearms and your hands.","drishti":"toward the extended foot","modificationNote":"Unlike the base seated forward bend, one knee is bent with the foot beside the hip instead of both legs lying straight.","muscles":[]},"tulya-baddha-konasana-1":{"name":"Balancing Bound Angle Pose","goodFor":"Opens the hips and inner thighs while building balance and core steadiness.","instructions":"Sit on the floor and bring the soles of your feet together, letting your knees drop out to the sides. Hold your feet or toes with both hands. Lengthen your spine and lift your chest. Gently hover the feet off the floor and find your balance. Keep the shoulders relaxed and breathe steadily.","breathCue":"Inhale to lengthen the spine, exhale to soften the knees down.","modifications":["Keep the feet resting on the floor if balancing feels shaky","Sit on a folded blanket if the hips feel tight","Hold the ankles instead of the toes"],"props":["Folded blanket under the sit bones","Strap around the feet if they are hard to reach"],"muscleCue":"Notice the stretch in the deep muscles of your hips.","drishti":"forward","modificationNote":"Unlike regular bound angle, the feet are held just off the floor so you balance while keeping the knees wide.","muscles":[]},"anantasana":{"name":"Infinity Pose","goodFor":"Builds side-body strength, balance, and hamstring flexibility.","instructions":"Lie on one side with your whole body in a straight line. Bend your lower arm and rest your head in your hand. Bend your top knee and take hold of the big toe or foot with your top hand. Straighten the top leg up toward the ceiling, reaching through the heel. Keep the bottom leg pressing into the floor and hold while breathing steadily.","breathCue":"Breathe smoothly, exhale as you lift the leg","modifications":["keep the top knee bent and hold the knee instead of the foot","loop a strap around the foot if you cannot reach it","practice with your back near a wall for balance"],"props":["yoga strap","wall for balance"],"muscleCue":"Notice the stretch in your hamstrings and your inner thighs. Notice the contraction in your shoulders and your forearms.","drishti":"forward","muscles":[]},"parivritta-samakonasana":{"name":"Revolved Half Bound Equal Angle Pose","goodFor":"Opens the inner thighs and hamstrings while giving the spine a gentle twist.","instructions":"Sit with your legs spread wide and feet flexed. Press your sitting bones down and lengthen your spine. Turn your chest toward one leg while your hips stay facing forward. Reach both hands toward that foot, resting them wherever you can. Keep your legs active and hold the twist while breathing steadily.","breathCue":"Inhale to lengthen, exhale to twist a little deeper","modifications":["bend the knees slightly if the hamstrings are tight","hold the shin instead of the foot","sit on a folded blanket to help the hips","use a strap around the foot"],"props":["strap","folded blanket"],"muscleCue":"Notice the stretch in your hamstrings and your inner thighs. Notice the contraction in the sides of your waist.","drishti":"toward the foot you reach for","modificationNote":"This is the revolved version of Samakonasana - instead of sitting neutrally upright, the torso twists toward one leg and the hands reach for that foot.","muscles":[]},"konasana":{"name":"Angle Pose","goodFor":"Opens the side body and improves lateral flexibility.","instructions":"Stand with the feet wide apart and legs straight. Raise both arms overhead and clasp the hands together. Inhale to lengthen the spine tall. Exhale and bend sideways from the waist, keeping both legs straight and hips facing forward. Hold and breathe into the stretch along the side body, then rise up and repeat on the other side.","breathCue":"Inhale to lengthen, exhale to bend a little deeper","modifications":["use a narrower stance if balance is tricky","bend less deeply and keep hands on hips","practice near a wall for balance support"],"props":["yoga block under the lower hand","wall for balance"],"muscleCue":"Notice the stretch in the sides of your waist and your lower back.","drishti":"up toward the hands","muscles":[]},"viparita-kurmasana":{"name":"Inverted Tortoise Pose","goodFor":"Deeply opens the hips and spine while calming the nervous system.","instructions":"Lie on your back and lift your hips up and over your shoulders. Support your lower back with your hands as you settle. Fold your legs down over your head until your knees rest beside your ears. Reach your arms up and hold your feet in front of your face. Let your weight rest on your shoulders and upper arms and breathe slowly while you hold.","breathCue":"exhale as you fold deeper and keep the breath slow and steady","modifications":["rest hands on the lower back if the feet are out of reach","use a strap around the feet","pad the shoulders with a folded blanket"],"props":["folded blanket","strap"],"muscleCue":"Notice the contraction in your forearms and your hands.","drishti":"toward the feet","modificationNote":"This version lies on the upper back with hips high over the shoulders, knees beside the ears, and hands holding the feet in front of the face, unlike the classical seated version with the legs behind the head.","muscles":[]},"surya-yantrasana-1":{"name":"Compass","goodFor":"Opens tight hips and hamstrings while giving the side body a deep stretch.","instructions":"Sit with one leg bent in front of you, foot tucked in close. Lift the other knee and tuck the opposite shoulder under it, then hold the outer edge of that foot. Straighten the lifted leg up as far as it allows and turn the chest toward the ceiling. Reach the free hand down to hold the toes of the bent front leg. To exit, bend the knee, release the foot and switch sides.","breathCue":"Inhale to lengthen the lifted leg, exhale to soften the shoulders","modifications":["loop a strap around the foot if you cannot reach it","bend the lifted knee slightly","rest the free hand on the floor instead of holding the toes"],"props":["yoga strap"],"muscleCue":"Notice the stretch in your hamstrings. Notice the contraction in your forearms and your hands.","drishti":"Urdhva or Antara Drishti (up to the sky)","modificationNote":"free hand holds the toes of the bent front leg while the other leg is lifted straight up and held by the opposite hand, chest turning up","muscles":["hamstrings","hips","obliques","shoulders","groin"]},"makara-dandasana":{"name":"Forearm Plank","goodFor":"Builds core and shoulder strength without straining the wrists.","instructions":"Lie on your belly and set your elbows under your shoulders with the forearms resting on the floor. Tuck your toes and lift your knees and hips until your body forms one straight line from head to heels. Press the forearms down and broaden across the upper back. Draw the belly in and keep the hips level, neither sagging nor piking. To exit, lower your knees and rest in Child's Pose.","breathCue":"Exhale as you lift, then breathe steadily as you hold.","modifications":["Knees down on the mat","Forearms on a folded blanket"],"props":["Mat"],"muscleCue":"Notice the contraction in the front of your shoulders and your triceps.","drishti":"Nasagrai or Nasagre (nose)","modificationNote":"Same as plank but resting on the forearms instead of the hands.","muscles":["core","shoulders","upper back","glutes","quads"]},"ardha-purvottanasana":{"name":"Reverse Tabletop","goodFor":"Opens the chest and shoulders while building strength in the arms, glutes and legs.","instructions":"Sit with the knees bent and the feet flat, hip-width apart. Place the hands behind the hips, fingers pointing toward the feet. Press into the hands and feet and lift the hips until the torso and thighs form a flat table. Keep the knees over the ankles and the arms straight. To exit, lower the hips to the floor.","breathCue":"Breathe into any tension in shoulders","modifications":["keep hips a little lower while building strength","place a bolster under the hips for support","walk the feet closer to the hips"],"props":["bolster"],"muscleCue":"Notice the stretch in your forearms. Notice the contraction in your glutes.","drishti":"Urdhva or Antara Drishti (up to the sky)","modificationNote":"the bent-knee version of full reverse plank, with knees stacked over the ankles and hips level with shoulders and knees","muscles":["glutes","hamstrings","triceps","shoulders","core","quadriceps"]},"bharadvajasana-1":{"name":"Bharadvaja's Twist","goodFor":"A gentle seated twist that keeps the spine, hips and shoulders mobile and calms the nervous system.","instructions":"Sit with both knees bent and both feet folded to one side of the hips. Sit tall on both sitting bones and twist your torso away from your feet. Reach one arm behind your back to hold the top foot, and let the fingertips of the other hand rest on the floor behind you. Lengthen your spine on each inhale and twist a little further on each exhale, gazing over your back shoulder. To come out, unwind slowly to the centre and repeat with the feet folded to the other side.","breathCue":"Inhale to lengthen, exhale to twist deeper","modifications":["Keep foot on floor","Use strap to hold foot","Bend both knees more"],"props":[],"muscleCue":"Notice the stretch in your quadriceps and your inner thighs. Notice the contraction in the sides of your waist.","drishti":"Parshva Drishti (over the back shoulder)","modificationNote":"both legs folded to one side with the top foot in half lotus and one arm reaching behind the back to hold it","muscles":["obliques","spine","outer hips","neck","shoulders"]},"aranyasana":{"name":"Pose Dedicated to Goddess Arani","goodFor":"Good for opening the fronts of the thighs and hips while releasing the lower back.","instructions":"Lie face down with your legs stretched out behind you. Bend both knees and lift your feet up toward your head. Reach your arms back and wrap them around your legs, holding the shins. Keep your belly and chest settled on the floor as you hold on. Let your head rest turned to one side and breathe slowly.","breathCue":"Exhale and settle your chest as you hug the legs in","modifications":["hold one leg at a time if both is too much","loop a strap around the ankles if the legs are out of reach","rest the chest on a folded blanket for comfort"],"props":["folded blanket under the chest","strap around the ankles"],"muscleCue":"Notice the stretch in your quadriceps and your abdominals. Notice the contraction in your glutes and your forearms.","drishti":"Bhrumadhye or Ajna Chakra (third eye, between the eyebrows)","modificationNote":"1. grabbing onto the shins","muscles":[]},"wide-legged-forward-bend-arms-wrapped":{"name":"Wide-Legged Forward Bend, Arms Wrapped Behind the Legs","goodFor":"Opens the hamstrings and inner hips while giving the whole back body a deep stretch.","instructions":"Stand with the feet wide apart and parallel. Hinge forward from the hips and let the head lower between the feet. Reach the arms behind the legs and clasp the hands behind the back. Let the torso hang heavy while the legs stay strong and active. Breathe slowly and hold the fold.","breathCue":"Exhale to fold and soften a little deeper.","modifications":["bend the knees slightly if the hamstrings are tight","rest the hands on the floor or blocks instead of wrapping","shorten the stance if balance feels shaky"],"props":["blocks under the head for support","strap to link the hands if they don't reach"],"muscleCue":"Notice the stretch in your hamstrings and the muscles along your spine. Notice the contraction in your quadriceps.","drishti":"Nasagrai (nose)","modificationNote":"Arms thread back between the legs and wrap around the backs of the thighs, hands resting on the lower back, crown toward the floor.","muscles":[]},"paripurna-matsyendrasana":{"drishti":"Parshva Drishti (to the right), Parshva Drishti (to the left)","modificationNote":"bottom foot in half lotus in the hip crease, top foot over the knee, arms bound around the twist","muscles":[]},"urdhva-hasta-prapadasana":{"drishti":"Nasagrai or Nasagre (nose)","modificationNote":"arms extended straight up overhead, palms together","muscles":[]},"crow-prep":{"drishti":"Nasagrai or Nasagre (nose)","modificationNote":"Crow before take-off: both feet still on the floor (on tiptoes), hands planted shoulder-width, elbows bent, knees pressed into the backs of the upper arms","muscles":[]}}`),r=JSON.parse(`{"sun-a-foundation":{"name":"Sun Salutation Foundation","description":"Standard warm-up arc: mountain → fold → plank → dog cycles to build heat safely before standing work.","focus":"Vinyasa · heat"},"peak-warrior":{"name":"Peak: Warrior Strength","description":"Peak-pose method: warm spine → sun-salute heat → warriors as peak → hip openers → twist → savasana.","focus":"Peak pose · warriors"},"peak-wheel":{"name":"Peak: Wheel Backbend","description":"Progressive backbend prep (peak-pose pattern): hip flexors → gentle extension → bridge → wheel → counterfolds.","focus":"Peak pose · wheel"},"peak-crow":{"name":"Peak: Crow Arm Balance","description":"Wrist/core prep then crow peak (common arm-balance class template), with soft floor integration.","focus":"Peak pose · crow"},"standing-flow":{"name":"Standing Flow Classic","description":"Classic mid-class standing block: warriors, triangle, balance, wide folds — the heart of many vinyasa classes.","focus":"Standing · balance"},"yin-hips":{"name":"Yin: Hips & Groin","description":"Modern yin template: few shapes, long holds (use Gentle/45s+), rebound between poses, long savasana.","focus":"Yin · hips"},"yin-spine":{"name":"Yin: Spine & Side Body","description":"Yin spinal focus with gentle twists and side bends, ending in extended rest.","focus":"Yin · spine"},"restorative-evening":{"name":"Restorative Evening","description":"Nervous-system downshift: supported shapes, legs up, minimal effort — common evening best practice.","focus":"Restorative"},"mobility-morning":{"name":"Morning Mobility","description":"Short arrive → joint warm-up → easy standing → floor cool-down (popular short daily practice arc).","focus":"Full body · gentle"},"hamstring-flow":{"name":"Hamstring Focus Flow","description":"Progressive back-line release (reclined stretch → dog → half-split → pyramid → seated fold). Longer seated holds; no filler repeats.","focus":"Hamstrings"},"hip-opener-modern":{"name":"Hip Opener (Modern)","description":"Contemporary hip-focused class: lunges and pigeons mid-practice after warm-up, yin-ish finish.","focus":"Hips"},"core-and-twist":{"name":"Core & Twist","description":"Heat + core + twists (popular athletic class theme), then neutralizing folds.","focus":"Core"},"inversion-prep":{"name":"Inversion Prep","description":"Shoulder/hamstring prep into supported inversions — never skip cool-down after upside-down work.","focus":"Inversions"},"full-vinyasa-arc":{"name":"Full Vinyasa Arc (60-style)","description":"Condensed 60-minute class arc from teacher guides: center → warm → stand → peak balance → hips → savasana.","focus":"Full body"},"gentle-floor":{"name":"Gentle Floor Flow","description":"Floor-heavy recovery day with light standing balance.","focus":"Full body · gentle"},"sun-b-heat":{"name":"Sun Salutation B Heat","description":"Classic Sun B building block used in Ashtanga/vinyasa: chair + Warrior I cycles before standing work.","focus":"Vinyasa · heat"},"peak-half-moon":{"name":"Peak: Half Moon","description":"Yoga Journal peak-pose method for Ardha Chandrasana: triangle/side-body prep → balance → soft landing.","focus":"Peak pose · balance"},"peak-revolved-triangle":{"name":"Peak: Revolved Triangle","description":"Peak template for Parivrtta Trikonasana: hamstring + twist components separately, then combine.","focus":"Peak pose · twist"},"shoulders-and-heart":{"name":"Shoulders & Heart Open","description":"Body-part sequencing (YJ approach): gradual shoulder opening and heart extension with counterfolds.","focus":"Shoulders · chest"},"grounding-root":{"name":"Grounding Strength","description":"Modern grounding class arc: heavy standing shapes, balance, then hips and long savasana.","focus":"Standing · grounding"},"desk-reset":{"name":"Desk Reset (15-style)","description":"Popular short daily reset: neck/shoulder/hip openers without a long standing peak — a compact micro-practice pattern.","focus":"Mobility · short"},"chair-morning-wakeup":{"name":"Chair Morning Wake-Up","description":"Desk-friendly chair class: tall sit, seated cat-cow, shoulder openers, soft twist, and seated rest — no floor work.","focus":"Chair · morning"},"chair-hips-circulation":{"name":"Chair Hips & Circulation","description":"Seated hip openers, marches, and supported calf work to keep hips and legs moving — all from or holding a sturdy chair.","focus":"Chair · hips"},"chair-calm-breath":{"name":"Chair Calm Breath","description":"Evening-friendly chair settle: breath, soft twists, gentle hinge, and a long seated rest — anxiety-soft and floor-free.","focus":"Chair · calm"},"chair-full-body-soft":{"name":"Chair Full Body Soft","description":"Showcase chair class covering spine, shoulders, hips, light standing support, and seated rest — one soft full-body practice.","focus":"Chair · full body"},"senior-steady-supported":{"name":"Steady & Supported","description":"Confidence-building chair balance: tall sit, supported standing hinge and calf raises, soft twist — never needs the floor.","focus":"Senior · balance"},"senior-sit-to-stand":{"name":"Sit-to-Stand Strength","description":"Short functional practice for rising and sitting with control, plus supportive standing — built for movement difficulties.","focus":"Senior · strength"},"senior-evening-soft-seat":{"name":"Evening Soft Seat","description":"Calm breath-forward evening seat: no balance challenges, soft spine and shoulders, long seated rest — stay off the floor.","focus":"Senior · restorative"},"playful-animal-parade":{"name":"Animal Parade","description":"Short family story class: cat-cow, puppy, frog squat, cobra snake, and a child’s-pose nest — playful holds, not a lecture.","focus":"Playful · animals"},"playful-tree-house":{"name":"Tree House","description":"Be a tree, a hero warrior, and an airplane — short standing play with a hammock fold and quiet finish. Great beside a grown-up.","focus":"Playful · balance"},"playful-bedtime-wind-down":{"name":"Bedtime Wind-Down","description":"Parent-led evening settle: soft cat-cow, child’s pose, easy twist, happy baby, and quiet rest — short holds for sleepy attention.","focus":"Playful · evening"},"breath-and-settle":{"name":"Breath & Settle","description":"Gentlest short practice: easy seat, soft floor shapes, legs-up, and savasana — all low-demand poses for max-ease days.","focus":"Restorative · gentle"},"breath-focus":{"name":"Breath Focus","description":"Short pranayama session: easy seat, three-part breath, equal breath, alternate nostril, humming bee, and savasana.","focus":"Breath · settle"},"legs-up-restore":{"name":"Legs-Up Restore","description":"Ten-minute downshift built on restorative shapes only — waterfall, banana, reclining butterfly, long savasana.","focus":"Restorative · gentle"},"seated-soft-spine":{"name":"Seated Soft Spine","description":"Mostly seated and supine ease: staff, gentle folds alternatives, twists, and resting poses — friendly at the lowest difficulty setting.","focus":"Full body · gentle"},"floor-calm-flow":{"name":"Floor Calm Flow","description":"Twenty-minute all-floor calm practice with no standing peaks — cat-cow, sphinx, child’s, twists, legs-up, savasana.","focus":"Full body · gentle"},"yin-evening-soft":{"name":"Yin Evening Soft","description":"Long soft evening yin without deep intensity peaks — extended floor holds, banana, butterfly, waterfall, and a generous savasana.","focus":"Yin · gentle"},"midday-restore":{"name":"Midday Restore","description":"Twenty-minute restorative break: easy seat, child’s, sphinx, reclining butterfly, legs-up, savasana — stays available at the gentlest difficulty.","focus":"Restorative · gentle"},"supine-soft-flow":{"name":"Supine Soft Flow","description":"All-supine and floor calm for mid-length practice days — no standing peaks, friendly when max pose difficulty is low.","focus":"Full body · gentle"},"hamstring-short":{"name":"Hamstring Soft Fold","description":"Short supine and seated folds to ease tight hamstrings without standing heat.","focus":"Hamstrings"},"hips-desk-open":{"name":"Hips: Desk Opener","description":"Quick hip openers on the floor — figure-four and gentle lunges, then rest.","focus":"Hips"},"shoulders-reset-10":{"name":"Shoulders Soft Reset","description":"Puppy, thread-the-needle, and gentle chest openers for desk-tight shoulders.","focus":"Shoulders · chest"},"standing-root-10":{"name":"Standing Root Mini","description":"Mountain and short warrior vignette both sides, then floor settle.","focus":"Standing · grounding"},"yin-hips-10":{"name":"Yin Hips Mini","description":"Longish floor holds for hips in a short yin window.","focus":"Yin · hips"},"core-steady-20":{"name":"Core Steady Flow","description":"Plank and side-body work with a mirrored standing block, cooling twists.","focus":"Core"},"hamstring-flow-20":{"name":"Hamstring Mid Flow","description":"Pyramid and half-splits both sides with seated fold finish.","focus":"Hamstrings"},"inversion-prep-20":{"name":"Inversion Prep Mid","description":"Shoulder and core prep toward legs-up and supported inversion shapes.","focus":"Inversions"},"mobility-midday":{"name":"Mobility Midday","description":"Cat-cow, thread-needle, and gentle standing to reset the whole body.","focus":"Mobility · short"},"yin-spine-20":{"name":"Yin Spine Soft","description":"Forward folds, gate, and twists held yin-style.","focus":"Yin · spine"},"core-power-40":{"name":"Core Power Arc","description":"Full warm-up, side plank and boat work, standing twist block both sides.","focus":"Core"},"hips-deep-40":{"name":"Hips Deep Open","description":"Lunges, lizard, and pigeon both sides with long cool-down.","focus":"Hips"},"inversion-journey-40":{"name":"Inversion Journey","description":"Progressive inversion prep with peak balance work and soft landing.","focus":"Inversions"},"mobility-full-40":{"name":"Mobility Full Sweep","description":"Extended joint-friendly flow through spine, hips, and shoulders.","focus":"Mobility · short"},"shoulders-heart-40":{"name":"Shoulders and Heart Long","description":"Puppy, sphinx, and heart openers with mirrored thread-needle.","focus":"Shoulders · chest"},"standing-balance-40":{"name":"Standing Balance Long","description":"Extended warrior and balance vignettes both sides, then floor.","focus":"Standing · balance"},"vinyasa-heat-40":{"name":"Vinyasa Heat Long","description":"Sun-salute heat, standing series both sides, twist cool-down.","focus":"Vinyasa · heat"},"core-gentle-10":{"name":"Core Gentle Floor","description":"Floor core without planks — twists and boat prep soft.","focus":"Core"},"core-twist-10":{"name":"Core Twist Mini","description":"Short plank and revolved shapes both sides.","focus":"Core"},"core-flow-20-soft":{"name":"Core Soft Mid","description":"Gentler mid-length core with seated twists.","focus":"Core"},"core-side-40":{"name":"Core Side Body","description":"Side plank vignettes and gate work both sides.","focus":"Core"},"hamstring-yinish-10":{"name":"Hamstring Floor Soft","description":"Supine hamstring stretch and legs-up only — gentlest.","focus":"Hamstrings"},"hamstring-stand-20":{"name":"Hamstring Standing Mid","description":"Standing pyramid block both sides with seated finish.","focus":"Hamstrings"},"hamstring-deep-40":{"name":"Hamstring Deep Fold","description":"Long progressive folds standing and seated.","focus":"Hamstrings"},"hips-gentle-10":{"name":"Hips Gentle Soft","description":"Bound angle and figure-four style soft hip release.","focus":"Hips"},"hips-flow-20":{"name":"Hips Flow Mid","description":"Lunge and pigeon both sides with savasana.","focus":"Hips"},"hips-restore-40":{"name":"Hips Restore Long","description":"Long restorative hip shapes without intensity.","focus":"Hips"},"inversion-soft-10":{"name":"Legs Up Soft","description":"Gentle legs-up and waterfall only — inversion light.","focus":"Inversions"},"inversion-prep-10":{"name":"Inversion Prep Mini","description":"Dolphin and dog prep with short legs-up finish.","focus":"Inversions"},"inversion-shoulder-20":{"name":"Shoulder Stand Prep","description":"Bridge and plow prep toward supported inversion.","focus":"Inversions"},"inversion-calm-40":{"name":"Inversion Calm Long","description":"Long legs-up practice with spine-friendly prep.","focus":"Inversions"},"inversion-peak-40":{"name":"Inversion Peak Long","description":"Full inversion journey with advanced peak options.","focus":"Inversions"},"mobility-wake-10":{"name":"Mobility Wake","description":"Cat-cow and easy spinal waves to wake the body.","focus":"Mobility · short"},"mobility-stand-20":{"name":"Mobility Stand Soft","description":"Standing sweeps and floor mobility mid-length.","focus":"Mobility · short"},"mobility-floor-40":{"name":"Mobility Floor Long","description":"Floor-focused mobility for all major joints.","focus":"Mobility · short"},"shoulders-soft-10":{"name":"Shoulders Soft Mini","description":"Puppy and easy arm sweeps only.","focus":"Shoulders · chest"},"shoulders-thread-20":{"name":"Shoulders Thread Mid","description":"Thread-needle both sides with sphinx and puppy.","focus":"Shoulders · chest"},"shoulders-heart-20":{"name":"Shoulders Heart Mid","description":"Chest openers and gentle backbends mid-length.","focus":"Shoulders · chest"},"shoulders-restore-40":{"name":"Shoulders Restore Long","description":"Restorative chest and shoulder release.","focus":"Shoulders · chest"},"standing-soft-10":{"name":"Standing Soft Root","description":"Mountain and easy standing folds — low demand.","focus":"Standing · grounding"},"standing-warrior-20":{"name":"Standing Warrior Mid","description":"Warrior II vignette both sides.","focus":"Standing · balance"},"standing-ground-40":{"name":"Standing Ground Long","description":"Long grounding standing series both sides.","focus":"Standing · grounding"},"vinyasa-soft-10":{"name":"Vinyasa Soft Mini","description":"Gentle salute without chaturanga intensity.","focus":"Vinyasa · heat"},"vinyasa-pulse-20":{"name":"Vinyasa Pulse Mid","description":"Classic heat-building mid flow both sides.","focus":"Vinyasa · heat"},"vinyasa-strong-20":{"name":"Vinyasa Strong Mid","description":"Stronger sun-salute and standing peak mid-length.","focus":"Vinyasa · heat"},"vinyasa-full-40":{"name":"Vinyasa Full Arc","description":"Extended vinyasa arc with standing series.","focus":"Vinyasa · heat"},"vinyasa-gentle-40":{"name":"Vinyasa Gentle Long","description":"Longer soft salute without advanced transitions.","focus":"Vinyasa · heat"},"yin-calm-10":{"name":"Yin Calm Mini","description":"Short yin floor holds ending in savasana.","focus":"Yin · gentle"},"yin-hips-20":{"name":"Yin Hips Mid","description":"Mid-length yin for hips and groin.","focus":"Yin · hips"},"yin-deep-40":{"name":"Yin Deep Long","description":"Extended yin with long rebounds and savasana.","focus":"Yin · gentle"},"peak-triangle-10":{"name":"Peak: Triangle Mini","description":"Short peak toward triangle both sides.","focus":"Peak pose · twist"},"peak-warrior-20":{"name":"Peak: Warrior Mid","description":"Mid-length warrior peak with cool-down.","focus":"Peak pose · warriors"},"restore-morning-10":{"name":"Restore Morning Soft","description":"Short restorative downshift to start or reset.","focus":"Restorative · gentle"},"restore-afternoon-20":{"name":"Restore Afternoon","description":"Mid restorative with legs-up and long savasana.","focus":"Restorative · gentle"},"restore-deep-40":{"name":"Restore Deep Long","description":"Extended restorative holds for nervous system rest.","focus":"Restorative"},"fullbody-soft-40":{"name":"Full Body Soft Long","description":"Gentle full-body arc at longer length.","focus":"Full body · gentle"},"core-soft-5":{"name":"Core Soft Micro","description":"Floor twists and wind-removing — a five-minute soft core settle.","focus":"Core"},"core-plank-5":{"name":"Core Plank Micro","description":"Brief plank, side plank, and boat with a soft landing.","focus":"Core"},"fullbody-soft-5":{"name":"Full Body Soft Micro","description":"Gentle salute-shaped floor and rest in five minutes.","focus":"Full body · gentle"},"fullbody-flow-5":{"name":"Full Body Flow Micro","description":"Short standing-to-floor arc when you only have five minutes.","focus":"Full body"},"hamstring-soft-5":{"name":"Hamstring Soft Micro","description":"Supine hamstring reach and waterfall — desk-tight legs, short window.","focus":"Hamstrings"},"hamstring-fold-5":{"name":"Hamstring Fold Micro","description":"Standing fold and pyramid snapshot ending in seated fold.","focus":"Hamstrings"},"hips-soft-5":{"name":"Hips Soft Micro","description":"Bound angle and figure-four both sides, then rest.","focus":"Hips"},"hips-open-5":{"name":"Hips Open Micro","description":"Lunge, lizard, and pigeon tastes in a five-minute opener.","focus":"Hips"},"inversions-soft-5":{"name":"Inversions Soft Micro","description":"Waterfall and legs-up only — inversion calm without load.","focus":"Inversions · gentle"},"inversions-dolphin-5":{"name":"Inversions Dolphin Micro","description":"Dog and dolphin prep into waterfall, quick cool-down.","focus":"Inversions"},"mobility-soft-5":{"name":"Mobility Soft Micro","description":"Cat-cow, child’s pose, and soft extension for a joint reset.","focus":"Mobility · short"},"mobility-sweep-5":{"name":"Mobility Sweep Micro","description":"Thread-needle, lunge, and side bend in a compact sweep.","focus":"Mobility · short"},"peak-triangle-5":{"name":"Peak: Triangle Micro","description":"Warriors into triangle peak — five-minute standing snapshot.","focus":"Peak pose · triangle"},"peak-warrior-5":{"name":"Peak: Warrior Micro","description":"Strong warrior line with warrior III peak in a micro window.","focus":"Peak pose · warriors"},"restore-soft-5":{"name":"Restore Soft Micro","description":"Child’s pose, butterfly, legs-up, and savasana — five quiet minutes.","focus":"Restorative · gentle"},"restore-legs-5":{"name":"Restore Legs-Up Micro","description":"Legs-up and waterfall emphasis for a nervous-system downshift.","focus":"Restorative"},"shoulders-soft-5":{"name":"Shoulders Soft Micro","description":"Puppy and sphinx for desk-tight shoulders in five minutes.","focus":"Shoulders · chest"},"shoulders-thread-5":{"name":"Shoulders Thread Micro","description":"Thread-the-needle both sides with puppy and child’s pose.","focus":"Shoulders · chest"},"standing-soft-5":{"name":"Standing Soft Micro","description":"Mountain and fold only — rooted standing without heat.","focus":"Standing · grounding"},"standing-warrior-5":{"name":"Standing Warrior Micro","description":"Warrior I/II and triangle in a five-minute standing block.","focus":"Standing · balance"},"vinyasa-soft-5":{"name":"Vinyasa Soft Micro","description":"Gentle salute without chaturanga — quick warm flow.","focus":"Vinyasa · heat"},"vinyasa-heat-5":{"name":"Vinyasa Heat Micro","description":"Short sun-salute heat with chaturanga and warriors.","focus":"Vinyasa · heat"},"yin-soft-5":{"name":"Yin Soft Micro","description":"Bound angle and butterfly holds squeezed into five minutes.","focus":"Yin · gentle"},"yin-hips-5":{"name":"Yin Hips Micro","description":"Fire-log and pigeon tastes with a short yin rebound.","focus":"Yin · hips"},"pulse-core-5":{"name":"Pulse: Core Shuttle","description":"Fast floor–stand travel with plank, side plank, and boat — short holds.","focus":"Core · pulse"},"pulse-core-10":{"name":"Pulse: Core Circuit","description":"Two salute cycles around a core pulse — vigorous without long holds.","focus":"Core · pulse"},"pulse-fullbody-5":{"name":"Pulse: Full Body Sprint","description":"Sun-salute shuttles and standing peaks packed into five busy minutes.","focus":"Full body · pulse"},"pulse-fullbody-10":{"name":"Pulse: Full Body Loop","description":"Repeated floor ↔ standing travel with warrior peaks and a short land.","focus":"Full body · pulse"},"pulse-hamstring-5":{"name":"Pulse: Hamstring Snap","description":"Fold–dog–pyramid bursts with quick supine hamstring reaches.","focus":"Hamstrings · pulse"},"pulse-hamstring-10":{"name":"Pulse: Hamstring Circuit","description":"Double salute around hamstring pulse — standing and floor in quick turns.","focus":"Hamstrings · pulse"},"pulse-hips-5":{"name":"Pulse: Hips Shuttle","description":"Lunges and lizards between dog and mountain — hips without long sits.","focus":"Hips · pulse"},"pulse-hips-10":{"name":"Pulse: Hips Circuit","description":"Standing–floor hip openers with salute bookends and a brief cool-down.","focus":"Hips · pulse"},"pulse-inversions-5":{"name":"Pulse: Inversion Prep","description":"Dog–dolphin–bridge pulse with standing bookends — short holds.","focus":"Inversions · pulse"},"pulse-inversions-10":{"name":"Pulse: Inversion Circuit","description":"Traveling inversion prep with plow option and quick floor–stand links.","focus":"Inversions · pulse"},"pulse-mobility-5":{"name":"Pulse: Mobility Sweep","description":"Side bends, thread-needle, and lunges moving between mountain and dog.","focus":"Mobility · pulse"},"pulse-mobility-10":{"name":"Pulse: Mobility Circuit","description":"Joint sweeps with salute loops — keep moving through major lines.","focus":"Mobility · pulse"},"pulse-peak-5":{"name":"Pulse: Peak Warriors","description":"Salute into a fast warrior–triangle peak, then a short floor land.","focus":"Peak pose · pulse"},"pulse-peak-10":{"name":"Pulse: Peak Circuit","description":"Two travel cycles around a strong standing peak — vigorous and brief holds.","focus":"Peak pose · pulse"},"pulse-shoulders-5":{"name":"Pulse: Shoulders Open","description":"Puppy and thread-needle between dog and mountain — desk reset, fast.","focus":"Shoulders · pulse"},"pulse-shoulders-10":{"name":"Pulse: Shoulders Circuit","description":"Shoulder openers threaded through salute shuttles and a short cool-down.","focus":"Shoulders · pulse"},"pulse-standing-5":{"name":"Pulse: Standing Fire","description":"Warrior vignettes with salute bookends — little time on the mat floor.","focus":"Standing · pulse"},"pulse-standing-10":{"name":"Pulse: Standing Circuit","description":"Double standing peaks linked by dog and fold — continuous travel.","focus":"Standing · pulse"},"pulse-vinyasa-5":{"name":"Pulse: Vinyasa Snap","description":"Chaturanga-capable salute burst and standing peak in five dense minutes.","focus":"Vinyasa · pulse"},"pulse-vinyasa-10":{"name":"Pulse: Vinyasa Circuit","description":"Stacked salute loops and warrior peaks — the vigorous end of the catalog.","focus":"Vinyasa · pulse"}}`),i=JSON.parse(`{"breath":{"title":"Breath — when and how","summary":"Match effort to breath: natural for restore, steady for strength, and never hold to push through.","body":"Breath is the metronome of practice. When the breath is easy, the nervous system tends to settle; when it stalls or becomes ragged, the pose is usually too intense for today. Treat breath as information, not as something to conquer. If you need one rule to carry onto every mat, make it this: keep the breath continuous and soften the face before you deepen anything else.\\n\\nNatural breath means soft nose breathing with an easy belly and ribs. Use it in restorative and yin, at the start of class, and whenever you feel rushed or self-critical. There is nothing “less yogic” about an ordinary inhale. SynthYoga’s free breath pattern leaves you alone on purpose so you can find your own pace without chasing a cue.\\n\\nA steady or ujjayi-style breath adds a light throat constriction that can warm and focus a standing or strength sequence. Keep it gentle — never strain the neck or force a loud ocean sound. Link movement to breath in simple ways: inhale to lift, lengthen, or open; exhale to fold, twist, or settle. In sun salutations that pairing becomes a rhythm you can trust even when the mind wanders.\\n\\nAvoid holding the breath to “push through” a hard pose, forced retention in twists or inversions, and gasping through the mouth when you could simply shorten the hold. If breath falls apart, exit with control, rest, and return when you can speak in full sentences again. Enable announce-breath cues in Settings if soft inhale and exhale reminders help you stay present during longer holds.\\n\\nWant to go deeper? Read Pranayama basics and Breath practices in Learn, open Breath with poses for inhale–exhale pairings, and browse the Breath filter in the pose library for seated and reclined techniques you can practice on their own."},"pranayama-basics":{"title":"Pranayama basics","summary":"Start with awareness and soft belly breath; nose breathing, slow tempos, and never forcing are the foundation.","body":"Pranayama is the yogic art of working with breath and attention. You do not need advanced techniques to begin. The first skill is awareness: notice the natural inhale and exhale without changing them. Many teachers start class this way so the nervous system can arrive before shapes get interesting.\\n\\nAnatomy in plain English helps. Air enters through the nose, travels the airways, and fills the lungs while the diaphragm — a dome under the ribs — descends on the inhale and rises on the exhale. Soft belly movement often means the diaphragm is free to work; chronic upper-chest breathing can leave the neck and shoulders doing overtime. Three-dimensional rib movement (front, sides, and back) is a quiet goal, not a performance.\\n\\nNose breathing is the default in classical practice unless a technique says otherwise. The nose filters, warms, and humidifies air and usually supports a steadier rhythm than mouth breathing. Soften the jaw and tongue; if the nostrils are blocked, rest rather than forcing alternate-nostril work.\\n\\nSlow, easy breathing with a slightly longer exhale often feels settling. Faster or forceful techniques feel stimulating and belong later — if at all — with clear guidance. Practice on an empty or light stomach. Sit tall or recline with a soft belly. Stop if you feel dizzy, short of breath, chest pain, tingling that worries you, or rising panic. This is educational yoga content, not medical advice; conditions such as pregnancy, uncontrolled hypertension, glaucoma, or recent surgery call for a qualified teacher or clinician before anything beyond gentle awareness breath.\\n\\nBuild duration slowly. Quality beats count. A few honest minutes of diaphragmatic or three-part breath serve better than straining toward impressive ratios. When you are ready for named techniques, open Breath practices and the Breath filter in the library."},"breath-practices":{"title":"Breath practices","summary":"Safe starter techniques — Dirga, belly breath, Ujjayi, alternate nostril, Bhramari, cooling breath, and equal breath — plus what to leave for a teacher.","body":"SynthYoga’s Breath library entries are seated or reclined practices you can run like any other pose. They use soft coaching and, where helpful, a gentle inhale–exhale pace. None of them ask you to hold the breath or pump the belly hard. Always stop if the breath feels forced.\\n\\nThree-Part Breath (Dirga) fills belly, then ribs, then upper chest on the inhale, and empties in reverse on the exhale — smooth, not strained. Many people learn it reclined first. Belly Breath keeps the focus on soft diaphragmatic movement with a quiet chest. Ocean Breath (Ujjayi) adds a light throat constriction so the breath sounds like a distant ocean; keep it quiet and never scrape the throat.\\n\\nAlternate Nostril (Nadi Shodhana) balances and settles for many practitioners: close the right nostril, inhale left; close left, exhale right; inhale right; exhale left. Skip retention as a beginner; skip the practice if congestion makes sniffing forceful. Humming Bee (Bhramari) exhales on a soft “mmm,” often with ears lightly covered — traditionally calming before meditation or sleep. Cooling Breath (Sheetali) inhales through a curled tongue (or Sheetkari through the teeth if you cannot curl) and exhales through the nose. Equal Breath (Sama Vritti) matches inhale and exhale counts — for example four and four — without holding at the top or bottom.\\n\\nTypical sessions last a few minutes or a handful of rounds. Prefer morning or midday for anything mildly energizing; save humming, equal breath, and extended soft exhales for evening wind-down. Pregnancy and high blood pressure generally stay with slow, non-forceful options only.\\n\\nSome famous techniques sit in the Breath library at high difficulty for a reason. Kapalabhati (kapala = skull, bhati = shine — “skull-shining”) uses rapid active exhales with passive inhales; many lineages call it a kriya. Bhastrika (from bhastrā, bellows) forces both inhale and exhale like a forge bellows and is strongly stimulating. Kumbhaka (from kumbha, pot) means retention — holding after inhale (antara) or after exhale (bahya). SynthYoga’s introductory kumbhaka uses only a short soft hold after inhale, with no empty-lung holds or bandhas. Open those poses only if your max pose difficulty allows intensity 5, read the Avoid notes (pregnancy, hypertension, glaucoma, hernia, epilepsy, panic), keep rounds short, and prefer learning first with a qualified teacher. They are not casual wake-up hacks."},"breath-with-poses":{"title":"Breath with poses","summary":"Inhale to lift and open; exhale to fold, twist, and settle — and never hold the breath to push intensity.","body":"Linking breath to movement turns a sequence into a rhythm you can trust when the mind wanders. The simplest map teachers use: inhale when you expand, lift, reach, or open the chest; exhale when you fold, twist, lower, ground, or settle. Holds usually keep a steady, even breath — often a soft ujjayi in standing work, or natural breath in restorative shapes.\\n\\nFamiliar pairings show the pattern. Mountain to arms overhead: inhale. Forward fold: exhale into the fold; inhale to lengthen the spine in a half lift. Plank to Chaturanga: exhale. Cobra or upward-facing dog: inhale. Downward-facing dog: exhale to settle, then breathe freely in the hold. Rising into Warrior shapes often rides an inhale; deepening or transitioning out often rides an exhale. In twists, lengthen on the inhale and explore a little more rotation on the exhale without yanking.\\n\\nSynthYoga’s breath patterns echo this coaching. Steady keeps an even pace. Inhale-lift and exhale-fold bias the cue toward opening or folding. Long-soft stretches the cycle for quieter holds. Free leaves timing alone — useful in savasana and some breath practices where your own rhythm matters more than a metronome.\\n\\nSide bends and teacher styles vary; consistency inside a session matters more than dogma. What does not vary: do not hold the breath to “get deeper,” especially in twists, balances, or inversions. If the breath breaks, the pose is too intense for this moment. Exit with control, rest, and return when you can speak in full sentences again. For technique deep-dives beyond asana pairing, see Pranayama basics and Breath practices."},"safety":{"title":"Safety & red flags","summary":"Stretchy or warm sensation is usually fine; sharp, electrical, dizzy, or breath-breaking signals mean back off.","body":"This is general practice guidance, not medical advice — if you have injuries or conditions, ask a qualified teacher or clinician before pushing into new shapes.\\n\\nSensation that is stretchy, warm, or muscularly tired is usually workable. Sharp, electrical, dizzy, or nauseating signals mean back off. Pain that makes you hold your breath, clench your jaw, or lose the ability to leave the pose with control is not a badge of progress. Leaving early is skill. Resting in child’s pose or savasana is still practice.\\n\\nStop or modify if you feel sharp joint pain, especially in knees, wrists, neck, or low back; numbness or tingling that intensifies; shooting pain down a limb; dizziness; vision changes; or shortness of breath beyond ordinary effort. If you cannot keep a steady breath, the intensity is too high for this moment. Come down, breathe, and choose a simpler shape.\\n\\nCommon caution zones deserve extra patience. For wrists in planks and arm balances, try fists, forearms, or skip the pose. For the neck in shoulderstand, plow, or deep camel, never turn the head — prefer legs-up-the-wall. For knees in lotus, hero, or deep pigeon, do not force; use a figure-four or a supported variation. For the lumbar in deep backbends, pad under the hips, bend the knees, or stay in bridge.\\n\\nOpen any pose in the library for Avoid and Modify notes. Props are not a consolation prize; they are tools that keep joints spacious while you build strength and awareness over time. When in doubt, choose the version you could repeat tomorrow without bracing against fear.\\n\\nAn app cannot see you. Timed cues and videos help you practice between classes, but they cannot adjust your shoulders or notice a collapsing knee. For load-bearing poses — planks, arm balances, deep backbends, inversions — consider occasional feedback from an in-person teacher or clinician, especially if something feels unclear or repeatedly irritable."},"sequencing":{"title":"How classes are built","summary":"Most modern classes follow a warm-up, peak, counterpose, and savasana arc that teachers learn in training.","body":"A well-built class feels like a story with a beginning, middle, and end. You arrive, you warm the body, you explore a focus, you neutralize, and you rest. Skipping the bookends — centering and savasana — is like editing the first and last pages of a novel: the middle still happens, but the integration does not.\\n\\nMost modern vinyasa classes follow a simple arc. Arrive and center with an easy seat, breath, and gentle spinal movement. Warm with cat-cow, downward dog, and sun salutations until the breath is awake and the joints feel oiled. Standing and peak work introduce the focus pose with preparation shapes that teach its parts — hips, shoulders, balance, or strength — without dumping you into the hardest version first.\\n\\nFloor work and counterposes follow: hips, folds, and twists that neutralize the peak. Twists after backbends, gentle folds after deep hip openers, and something that lets the nervous system downshift. Savasana is integration, not an optional nap. Even three quiet minutes help the practice settle into the body.\\n\\nWhen you build your own sessions, ask what the peak needs. A crow needs warm wrists, open hips, and core; a wheel needs thoracic mobility and strong legs; a long yin hold needs heat already soft enough that you can stay without bracing. SynthYoga built-ins follow this logic — Sun A Foundation, Peak Warrior, Wheel, Crow, Yin, Restorative — and the Wizard picks from that menu using time of day and your history so you are not reinventing the arc from scratch every morning."},"effort":{"title":"When to push harder","summary":"Progress one variable at a time — range, hold time, or load — and let steady breath be the green light.","body":"Effort in yoga is not the same as maxing out at the gym. The useful question is not “Can I force this?” but “Can I stay kind and clear while I explore a little further?” Progress one variable at a time: range of motion, hold time, or load. Changing all three at once is how form collapses and resentment creeps in.\\n\\nGreen lights that you may deepen include a steady breath, a soft face and jaw, joints that feel spacious rather than pinched, stable form for several breaths, and the ability to leave the pose with control. If those are present, you can explore a half-inch more, a few more seconds, or a slightly stronger variation — then reassess.\\n\\nYellow and red lights mean ease off. Breath that holds or becomes ragged, shaking that collapses alignment, ego driving the pose (“I should be able to…”), or pain that is sharp or neural are all invitations to simplify. There will be other days. The practice that lasts is the one that leaves you curious rather than broken.\\n\\nAfter a session, log effort on the summary screen when you can. Patterns matter more than any single heroic hour. The Wizard uses your history to suggest shorter days after gaps, which is a quiet kindness to future-you. Strength grows in recovery as much as in the hold; treat rest days as part of the training, not as failure to show up."},"savasana-hardest":{"title":"Why savasana is the hardest pose","summary":"Lying still asks the mind to stop performing — and that can feel harder than any balance or backbend.","body":"People laugh when teachers say savasana is the hardest pose, then spend the final minutes twitching, planning dinner, or peeking at the clock. The joke lands because it is true. After forty minutes of doing, the nervous system is asked to undo — and undoing has no scoreboard.\\n\\nIn asana we can hide inside effort. Muscle burn feels productive. A deep fold looks like achievement. Savasana offers nowhere to perform. You lie down, arrange the limbs so nothing needs gripping, and meet whatever the mind brings: restlessness, boredom, the urge to skip “just this once.” That meeting is the pose.\\n\\nHard does not mean grim. Soften the eyes under closed lids. Let the tongue rest. If thoughts arrive, notice them the way you notice clouds — present, moving, not a problem to solve on the mat. If you need a bridge into stillness, take a longer child’s pose or a supported reclined twist first, then settle. Three honest minutes beat ten minutes of fidgeting while pretending you are fine.\\n\\nSkipping savasana to rush into the day teaches the body that practice ends in urgency. Keeping it, even briefly, teaches that effort has a landing place. If you only change one habit this month, protect the final rest. Leave your phone outside the room and give the practice a chance to finish speaking."},"beginner-ego":{"title":"Beginner ego and the comparison trap","summary":"Wanting to “keep up” is human; mistaking someone else’s shape for your homework is how joy leaks out.","body":"Every room has a silent ranking system if you let it: who balances longer, whose heels touch the floor, who floats into crow without a second thought. Beginner ego is not vanity alone — it is the tender wish to belong, mixed with the fear of being seen as behind. That mix can push people into shapes their joints are not ready for.\\n\\nComparison steals information. Your neighbor’s handstand says almost nothing about your wrists, sleep, stress, or decade of desk work. What looks effortless may be years of practice, lucky proportions, or a body that has not yet met its limits. Your job is not to match their silhouette. Your job is to notice your breath and choose the version you can leave with dignity.\\n\\nTeachers can accidentally feed the trap by praising only the deepest expression. Good rooms celebrate modifications out loud. If you are new, claim the block, the knee down, the shorter hold. That is not lesser yoga; it is accurate yoga. Accuracy builds trust, and trust is what lets you deepen later without bracing against shame.\\n\\nWhen ego spikes — “I should be able to by now” — pause and rename the goal. Today’s success might be staying for the whole class, keeping the neck soft in a backbend, or leaving before pain arrives. Progress often looks sideways: more ease in a familiar pose, less rush between shapes, a kinder inner narrator. Those wins do not photograph well. They travel well."},"home-vs-studio":{"title":"Home practice vs studio","summary":"Studios offer community and structure; home offers flexibility — most lasting practices borrow from both.","body":"Studio practice hands you a container: a time, a teacher, other bodies breathing nearby. That container makes showing up easier on days when motivation is thin. You borrow someone else’s sequencing, music, and pacing, and you leave the laundry in another room. For many people, that external structure is how a habit begins.\\n\\nHome practice offers a different gift. You can practice at dawn in pajamas, shorten a session when life is loud, and explore poses without an audience. You also meet every excuse personally: the email, the snack, the sudden need to reorganize a drawer. Without a plan, home practice dissolves into stretching while thinking about work.\\n\\nA durable approach often mixes both. Use studio or live classes to learn alignment, discover new sequences, and feel the lift of shared effort. Use home days for consistency — even fifteen focused minutes — so practice does not depend on a schedule or a commute. Write a tiny ritual: same corner, same first three poses, phone away, timer set.\\n\\nIf home feels lonely, add light structure from tools you trust: a familiar routine, breath cues, or a short peak you already know. If studio feels performative, choose restorative or beginner rooms and stand near the back until the nervous system settles. Neither setting is morally superior. The question is which mix keeps you practicing with curiosity instead of dread."},"roots-of-asana":{"title":"Roots of asana","summary":"Classical yoga emphasized stillness and meditation; the athletic asana vocabulary many know is largely modern.","body":"When people say “yoga,” they often picture a sequence of standing postures, balances, and flows. That image is recent. Classical texts such as the Yoga Sutras mention asana mainly as a steady, comfortable seat for meditation — a posture that supports stillness rather than a catalog of athletic shapes. The body was prepared so the mind could settle, not displayed as the main event.\\n\\nMedieval hatha traditions expanded physical practice: purification, breath control, and postures meant to steady energy for deeper work. Even then, the lists of poses were smaller than a modern studio schedule, and the goal remained transformation of attention and vitality, not calorie burn or Instagram lines. Context matters: these practices lived inside lineages, vows, and philosophies that rarely fit a lunch-break class.\\n\\nThe twentieth century changed the map. Teachers in India — among them figures associated with Mysore and related lineages — systematized dynamic asana, often influenced by gymnastics, wrestling, and military drill as well as older hatha. Photography, print manuals, and later global travel carried those systems abroad. What many Western students inherited was a vigorous postural yoga that still used Sanskrit names and older frames, but prioritized strength, flexibility, and sequenced movement.\\n\\nKnowing this history does not make your downward dog less real. It invites humility. Asana can be devotion, therapy, sport, or moving meditation depending on how you hold it. When you practice today, you stand in a long conversation — some pages ancient, some barely a century old. Honor the seat and the sweat both, and remember that stillness was the original destination."},"hatha-vs-vinyasa":{"title":"Hatha vs vinyasa","summary":"Hatha often means slower, held postures; vinyasa links breath to movement — both can be strong or gentle.","body":"In studio marketing, “hatha” and “vinyasa” get used as shorthand for slow versus flowing. The words are older and wider than that. Hatha historically pointed to the broader physical and energetic path — postures, breath, and related practices — not a single class style. On a modern schedule, a hatha class usually means poses held for several breaths with more time for alignment and less continuous movement.\\n\\nVinyasa, in contemporary usage, emphasizes linking breath to movement and transitioning between shapes. Sun salutations are the familiar engine. Classes can be athletic or moderate; the common thread is rhythm. Some lineages use precise counts; others leave timing more open. Either way, the nervous system tends to stay warmer and more mobile than in a long-hold room.\\n\\nNeither label guarantees intensity. A “gentle vinyasa” can be softer than a demanding hatha class stacked with deep stands and long balances. Read the description, ask the teacher, and notice your breath after ten minutes. If you need grounding, longer holds and fewer transitions may help. If you need to shake off mental fog, a steady flow with clear inhale-exhale links may serve better.\\n\\nFor home practice, you can borrow both. Warm with a short flow, then settle into held standing or floor work. Or reverse it: explore a peak pose slowly, then use a few breath-linked transitions to integrate. The useful distinction is not brand loyalty — it is whether today’s body wants rhythm, stillness, or a conversation between the two."},"yin-origins":{"title":"Where yin yoga comes from","summary":"Yin’s long floor holds draw on Taoist ideas and modern teaching; it complements, rather than replaces, yang styles.","body":"Yin yoga, as popularized in the late twentieth century, asks you to settle into shapes for minutes at a time, usually on the floor, with muscles soft rather than engaged for show. The aim is to stress connective tissue gently and give the nervous system a long exhale. It looks quiet from the outside and can feel intensely honest on the inside.\\n\\nTeachers associated with the style drew on Taoist yin-yang language and on ideas about fascial and energetic pathways, weaving them with asana shapes familiar from hatha. Exact historical claims vary by teacher, and scholars debate how directly modern yin maps onto older Chinese practices. For practitioners, the lived method matters more than the brochure: arrive, find an appropriate edge, stay, breathe, and leave without yanking.\\n\\nYin is not a contest to suffer longest. Props, padding, and early exits are wise. Sharp joint pain is still a stop sign. Because holds are long, small misalignments add up — support the knees, keep the neck easy, and choose variations that let muscles melt instead of grip. Heat beforehand can help, but many people practice yin cool and still benefit.\\n\\nThink of yin as a complement to yang styles like vinyasa or power classes. Strength and heat build capacity; long passive holds teach patience and recovery. A week that includes both often feels more complete than doubling down on only intensity. If your mind races in stillness, shorten the holds and keep the principle: less muscular effort, more listening."},"sanskrit-naming":{"title":"Sanskrit naming on the mat","summary":"Pose names carry images and lineage; learning a few roots makes the room feel less like a secret code.","body":"Sanskrit pose names can feel like a wall if you are new. Teachers alternate between “downward-facing dog” and adho mukha svanasana, and the brain scrambles. The names are not there to gatekeep. They are compact images and lineage markers — a shared map that travels across languages when English translations diverge.\\n\\nMany names are built from parts you can learn like Lego. Adho means downward; mukha means face; svana means dog. Tri means three; kona means angle — hence triangle. Ardha means half; chandra means moon. Once a handful of roots click, unfamiliar names stop being noise and start being clues about shape and direction.\\n\\nYou do not need fluency to practice well. English cues are enough for safety and breath. Still, tasting the Sanskrit can deepen respect for the tradition’s texture, especially when a name points to a myth, animal, or sage. Say what you can pronounce kindly; correct yourself without shame. Teachers differ on accent and exact forms — consistency inside a lineage matters more than winning a pronunciation contest.\\n\\nIf memorization overwhelms you, pick five poses you love and learn both names. Use them in your home practice so the sound attaches to sensation. Over months the glossary grows without flashcards. The goal is not to impress the room. The goal is to feel at home in a vocabulary that has carried these shapes across generations."},"eight-limbs":{"title":"Eight limbs overview","summary":"Asana is one limb among eight — ethics, breath, senses, concentration, and meditation complete the map.","body":"Patanjali’s eight-limbed path is a classic map many teachers still reference. It does not demand that every gym-class warrior sequence become a philosophy seminar. It does remind us that postures sit inside a wider project: how we treat others, how we treat ourselves, how we breathe, and how we steady attention.\\n\\nThe first two limbs, yama and niyama, sketch ethical and personal disciplines — honesty, non-harming, contentment, and related commitments interpreted differently across eras. Asana, the third, is the embodied seat or posture. Pranayama works with breath and energy. Pratyahara turns the senses inward so attention is less yanked by every sound and itch.\\n\\nThe final three — dharana, dhyana, and samadhi — describe concentration, meditation, and deep absorption. Few modern classes claim to deliver the last limb in forty-five minutes, and that humility is healthy. What they can offer is practice in returning: notice distraction, come back to breath or sensation, repeat without scolding.\\n\\nOn a practical Tuesday, the limbs show up quietly. Choosing not to force a painful knee is non-harming. Showing up when you said you would is discipline. Softening the gaze in balance is a taste of sensory quiet. You do not have to master the list. Let it widen the frame so asana is more than shapes — a training ground for attention and care that leaves the mat with you."},"modern-yoga-west":{"title":"Modern yoga in the West","summary":"Travel, books, and studios transformed postural yoga into a global wellness culture with many dialects.","body":"Yoga did not arrive in the West as a single package. Lectures, books, visiting teachers, and later immigration carried philosophies, breath practices, and postural systems into Europe and North America across the twentieth century. Some audiences wanted mysticism; others wanted health, flexibility, or calm. The marketplace answered with many dialects under one popular name.\\n\\nBy the late twentieth century, yoga studios, teacher trainings, and media turned asana into a recognizable lifestyle. Branding, fashion, and fitness culture amplified certain vigorous styles while quieter practices continued in smaller rooms. Commercial success brought access and also distortion: spiritual language used as marketing, thinness mistaken for advancement, and lineages flattened into trends.\\n\\nCritique and renewal grew alongside popularity. Teachers and scholars asked harder questions about cultural appropriation, accessibility, injury, and who feels welcome in the room. Trauma-informed language, body-positive spaces, chair yoga, and online classes widened the door. None of that erases harm automatically — it is ongoing work — but it shows the tradition adapting in public.\\n\\nFor a practitioner today, “Western yoga” is less a verdict than a landscape. You can seek lineage depth, therapeutic care, athletic challenge, or simple weekly movement. Choose teachers who cite sources honestly, prioritize safety, and leave room for questions. The global story is still being written every time someone rolls out a mat with curiosity instead of a costume."},"props-history":{"title":"A short history of props","summary":"Blocks, straps, and blankets moved from inventive supports to standard tools that make asana more accessible.","body":"Props look modern — colorful foam blocks, cotton straps, bolsters stacked like furniture — but the impulse is old: use what helps the body find a sustainable shape. Ropes, walls, and household objects have long stood in when a pose asked for length or leverage the unaided body could not offer yet.\\n\\nIn the twentieth century, teachers such as B.K.S. Iyengar made systematic prop use famous: bricks, belts, chairs, and blankets to refine alignment and include students who could not approximate a photograph. What some rooms once treated as remedial became, in that approach, intelligent design. Accessibility and precision shared the same toolkit.\\n\\nToday most studios keep a prop wall without apology. A block under the hand in triangle is not a demotion; it is a way to keep the spine long while hamstrings catch up. A strap in a forward fold teaches the shape of the pose without rounding into strain. Bolsters in restorative practice let the nervous system believe it is safe to rest.\\n\\nIf ego whispers that props are for beginners, answer with longevity. Joints prefer spaciousness. Strength still builds when the foundation is honest. Keep a block and strap near your home mat the way a kitchen keeps a cutting board — ordinary tools for better work. The advanced move is choosing the support that lets you breathe."},"nervous-system":{"title":"Stimulate vs settle","summary":"Match practice to your nervous system: when to build heat and when to downshift with breath, yin, and rest.","body":"Your nervous system sets the weather for practice. Some days call for heat, standing strength, and a little challenge. Other days call for longer exhales, floor work, and permission to do less. Matching the session to the weather is skill — not laziness.\\n\\nStimulating practices raise heart rate and alertness: sun salutations, peak standing poses, stronger pranayama. Use them when you feel foggy, stiff from sitting, or ready to build capacity — and only while breath stays conversational. If you finish jittery or unable to sleep, you overshot.\\n\\nSettling practices downshift: yin, restorative, humming breath, equal breath with soft exhales, legs-up-the-wall, savasana. Use them when anxious, overstimulated, sore, or short on sleep. A ten-minute settle session still counts as practice.\\n\\nHome intents on the splash screen — Wake up, Desk stiff, Calm, Wind down, Breath only — are shortcuts into this choice. You can also pick manually. After a hard peak day, prefer yin or restorative the next session so tissues and attention recover.\\n\\nIf you are unsure, start with breath for two minutes and notice: does the body want to move bigger, or get quieter? Let that answer pick the routine. Effort & ahimsa and Breath — when and how deepen the same idea from other angles."},"anatomy-basics":{"title":"Anatomy basics for yogis","summary":"Joints, muscles, and fascia in plain language — enough body literacy to practice with curiosity instead of force.","body":"You do not need a medical degree to practice yoga wisely. A few anatomy ideas go a long way: bones meet at joints; muscles pull on bones to create movement; connective tissue (including fascia) links the system so tension in one place can show up somewhere else. Asana asks this system to move through ranges of motion with enough control that breath stays easy.\\n\\nThink in planes. Forward and back folds travel the sagittal plane. Side bends and some hip openers explore the frontal plane. Twists rotate through the transverse plane. A balanced practice visits more than one plane so the spine and hips are not trained in a single direction. That is why sequences that only chase deeper forward folds feel incomplete — and why your low back may complain.\\n\\nMuscles work by contracting; they do not “stretch themselves longer” in a single heroic session the way a rubber band myth suggests. Length and ease accumulate when tissue is loaded kindly and often, then given recovery. Strength and flexibility are partners: weak areas often feel tight because the body is guarding. Chasing only stretch without stability can leave joints feeling loose and unhappy.\\n\\nFascia and nervous system tone matter as much as muscle length. Fear, cold, and rushing raise protective tension. Warm-ups, steady breath, and permission to back off change how far a pose feels available today. Two people in the same shape can be loading very different tissues depending on proportions, prior injury, and how they organize the pose.\\n\\nUse this map as literacy, not diagnosis. SynthYoga’s coaching notes highlight common careful zones; they are not a substitute for a clinician or an in-person teacher who can see you. When something feels sharp, pinching, or nerve-like, exit. Dull stretch or honest muscular work is information; pain that makes you hold your breath is a stop sign. Continue with Biomechanics & safety and Flexibility progress for how this shows up on the mat."},"biomechanics-safety":{"title":"Biomechanics & safety","summary":"How load, leverage, and common risk zones (wrists, knees, low back, neck) relate to pain-versus-stretch decisions.","body":"Biomechanics is the study of forces on the body. In yoga, every pose is a negotiation between gravity, your base of support, and how you stack joints. Longer levers (straight arms or legs far from the body) increase demand. Props shorten levers and reduce load — that is intelligence, not cheating. A block under the hand in triangle keeps the spine long while the hamstrings catch up.\\n\\nPain and stretch are not the same. Muscle stretch often feels broad, dull, and breathable. Joint or nerve warning signs tend to be sharp, pinching, burning, or electric, and they often make the breath catch. Stop for the second category. Back out of depth, change the shape, or rest. Ego loves “push through”; joints do not.\\n\\nHigh-attention zones in many practices: wrists in planks and arm balances (spread fingers, soft micro-bend, skip if irritable); knees in lunges and lotus variations (track knee over mid-foot, never crank the joint into a bind); lumbar spine in deep backbends and forward folds (prefer length over collapse); cervical spine in shoulderstand and upward gazes (keep the neck as a quiet passenger, not a lever).\\n\\nLoad-bearing inversions and deep end-range poses are where apps are weakest: they cannot see your shoulders shrug toward your ears or your ribs flaring. Use the Avoid and Modify notes on each pose, prefer easier variations when Settings says so, and consider occasional in-person feedback for anything that puts body weight on the head, neck, or wrists in unfamiliar ways.\\n\\nThis article is educational, not medical advice. Pregnancy, recent surgery, osteoporosis, glaucoma, uncontrolled hypertension, and acute injury change what is wise. When in doubt, choose restorative shapes and breath. Pair this reading with the Safety & red flags guide and the Careful lines in the pose library."},"flexibility-progress":{"title":"Flexibility progress","summary":"Tissue adapts with time under stretch, consistency, and recovery — not with forcing a deeper shape today.","body":"Flexibility is the available range of motion at a joint. Mobility adds control through that range. Yoga can train both when you move with breath and strength, not only when you hang at an end range hoping gravity will do the work. Progress is usually quiet: the same pose feels less guarded, the breath stays longer, or you need less prop height than last month.\\n\\nTissue responds to repeated, moderate loading over weeks — not to one aggressive session. Yin and restorative styles use longer holds with soft effort so connective tissue and the nervous system can settle. Dynamic and vinyasa styles warm tissue with repetition. Both can increase ease; neither requires forcing. If you leave a stretch shaking, bruised, or unable to walk normally, you overshot.\\n\\nConsistency beats intensity. Ten honest minutes most days outperforms a monthly heroic split attempt. Alternate deeper stretch days with strength and neutral days so tissues recover. Sleep, hydration, and stress load change how “tight” you feel; honor the day you have.\\n\\nCompare yourself to your last month, not to a photo. Proportions differ: long femurs, stiff ankles, or a fused spinal segment change what a pose looks like from the outside. Props keep the spine honest while range grows. If ego whispers that depth equals worth, rename success as breath and kindness.\\n\\nWant structure? Use yin or gentle routines when the goal is ease, and pair stretch-focused weeks with Strength in yoga so openers do not outrun stability. Effort & ahimsa helps you dose intensity without quitting the long game."},"strength-in-yoga":{"title":"Strength in yoga","summary":"Isometrics, eccentric control, and standing balance are strength training — not a lesser cousin of the gym.","body":"Many people come to yoga for stretch and discover they are also building strength. Holding Warrior II, hovering in Chair, or lowering with control toward Chaturanga trains muscles isometrically and eccentrically — the kinds of work that stabilize joints and make flexibility usable.\\n\\nStrength here often looks quiet: the standing leg in Tree, the lower belly gently drawing in to support a twist, the shoulders integrating in Downward Dog so the wrists are not dumped. Peak poses that require pressing, balancing, or slow transitions are strength work even when the room is calm.\\n\\nProgress by adding time under tension before adding flashy variations. Stay in a solid Chair for more breaths before jumping to a bind. Prefer controlled lowers over collapsing. Use blocks to keep alignment while load increases. Prefer-easier Settings exist so you can build capacity without rehearsing a shape that currently asks too much.\\n\\nBalance strength and stretch across the week. A practice that only opens hips without training the outer hips and core can feel good short-term and unstable later. Sequencing that warms, peaks, and counters is already a strength-and-mobility plan when you follow it honestly.\\n\\nIf your goal is athletic strength, yoga can complement other training; it does not have to replace it. If your goal is resilient home practice, treat standing and core-integrated poses as training days, not as filler between stretches. Pair with Flexibility progress so range and control grow together."},"spine-and-core":{"title":"Spine & core","summary":"Neutral spine, six directions of movement, and a responsive core — the backbone of safe sequencing.","body":"The spine moves in six primary ways: flexion (forward fold), extension (backbend), lateral flexion (side bend) left and right, and rotation left and right. A well-built practice visits these directions across a session or a week so the back is not trained as a one-trick hinge. Teachers sometimes summarize related needs as covering major leg lines and both stabilizing and articulating the core — a checklist, not a dogma.\\n\\nNeutral spine means the natural curves are present without dumping into the low back or tucking aggressively. In planks and standing poses, think long crown-to-tail with ribs soft, not a hard military brace and not a sagging hammock. Breath should still move the belly and ribs; a core that never allows breath is armor, not support.\\n\\nTwists lengthen first, then rotate. Inhale to create space; exhale to explore rotation without yanking the neck or forcing the lumbar to do a thoracic job. After strong backbends, include gentle forward folds or neutral rest; after deep folds, a mild extension or prone rest can rebalance. Counterposes are manners for the spine.\\n\\nCore work in yoga is often integrated: Boat, plank variations, standing balances, and the transition strength between poses. Isolated crunches are optional; showing up for honest midsection engagement in familiar shapes is not. If the low back screams in a “core” pose, shorten the lever (bend knees) or rest — the back is telling you the strategy failed.\\n\\nUse Sequencing and Biomechanics & safety as companions. When you build your own routines, ask whether the spine got flexion, extension, side bend, and twist somewhere in the arc — and whether savasana gave the system time to integrate."},"shoulders-hips-wrists":{"title":"Shoulders, hips & wrists","summary":"Sticky joints and safer patterns for the areas home practitioners load most often.","body":"Shoulders, hips, and wrists absorb a lot of modern yoga — and a lot of desk life. They are also where impatience shows up as injury. Treat them as relationships to train, not problems to crank open in one session.\\n\\nShoulders: integrate the shoulder blades onto the back ribs in Down Dog and plank rather than dumping into the armpits. Soften the ribs if they flare in backbends. Avoid hanging the head as a lever. If overhead range is limited, keep a micro-bend in the elbows and use a wider stance or blocks. Sharp front-of-shoulder pain is a stop; mild posterior stretch with breath can be information.\\n\\nHips: external rotation, flexion, and extension all appear across standing poses, lunges, and seated opens. Move into sensation gradually. Knee pain in hip openers usually means the knee is doing the hip’s job — support the thigh with blankets, back out of the angle, or skip the bind. Square-looking hips are aesthetic; honest pelvis position with a soft breath is safer.\\n\\nWrists: spread the fingers, press through the base knuckles, and avoid collapsing into the heel of the hand. Take fist or forearm variations when the floor angle irritates. Reduce volume of vinyasa transitions on cranky days. Strength and mobility for wrists often improve when shoulders share the load correctly.\\n\\nProps and regressions are first-class. Chair and wall options exist in the library for a reason. If a joint is inflamed, choose restorative practice and breath until load feels welcome again. Read Careful notes on individual poses, and let Biomechanics & safety set the decision rules when ego argues for “just a little deeper.”"},"pilates-vs-yoga-core":{"title":"Pilates hundred vs yoga core: same goal, different loading","summary":"Both train the midsection — Pilates often emphasizes repetitive controlled load; yoga often pairs core with breath and multi-planar shapes.","body":"Core work shows up in both Pilates and yoga, but the loading story differs. Classic Pilates hundred asks for sustained curled abdominal work with rhythmic arm pumps and precise breath counts. Yoga core often appears as Boat, Plank, side plank, or as the quiet stabilizer inside standing poses — less repetition theater, more integrated timing with inhale and exhale.\\n\\nNeither is “better.” Pilates tends to isolate and endurance-train the anterior chain with clear form rules. Yoga tends to ask the core to cooperate with hips, shoulders, and balance while you also manage attention. If your low back complains in hundred-style curls, shorten the lever (higher legs, head down) or switch to yoga shapes that keep a longer spine. If Boat makes you grip the hip flexors, try knees bent and soft jaw.\\n\\nIn SynthYoga, filter the Library by pilates or yoga and read Avoid notes. Intensity 1–5 still applies across disciplines. Prefer easier variations when available if your weekly intention is calm rather than strength.\\n\\nUse breath as the shared rule: continuous nose breathing, no bracing into panic. When the breath breaks, the load is too high for this moment — whether the pose is called Hundred or Navasana.\\n\\nWant more? Read Strength in yoga, Spine & core, and Anatomy basics, then browse pilates and yoga core entries in the pose library."},"held-tai-chi-vs-vinyasa":{"title":"Why held tai chi shapes feel different from vinyasa","summary":"Tai chi holds train continuous soft attention and weight shift; vinyasa trains linked movement and heat — both are skillful when matched to the day.","body":"Held Yang-style shapes and simplified forms ask for slow weight transfer, soft knees, and arms that move as if through water. The nervous system often reads that as settling even when legs work. Vinyasa links breath to transitions — plank to Chaturanga to upward dog — and builds heat quickly.\\n\\nThe difference is not moral. It is pacing and intent. On wired days, a few minutes of cloud hands or a held bow stance can bridge you into floor work better than another peak standing series. On foggy mornings, a short sun salute may wake attention without needing a full power class.\\n\\nIn the app, use discipline filters for tai-chi versus yoga. Transition speed and hold timers change how held shapes feel; announce-breath cues keep soft pacing honest. Preview a mixed sequence before play so you are not surprised by a sudden intensity jump.\\n\\nKeep joints kind: soft knees, soft jaw, continuous breath. Sharp joint pain is still a stop signal in every discipline.\\n\\nSee Hatha vs vinyasa, Breath with poses, and Effort for related framing."},"qigong-warmup-for-asana":{"title":"Qigong as warm-up for asana","summary":"Baduanjin and related qigong can wake joints and breath before asana without demanding peak poses first.","body":"A short qigong segment — for example raising the hands, drawing the bow, or gentle spinal waves — can lubricate shoulders and wake diaphragmatic breath before Down Dog asks for load. Think of it as a nervous-system on-ramp rather than a separate sport you must master.\\n\\nKeep rounds few and soft. Stop if dizziness or forced breath appears. Pregnancy and some medical conditions call for clinician guidance before vigorous pumping techniques; stick to slow, non-forceful options when unsure.\\n\\nBuilder tip: place one or two qigong library entries at the start of a custom routine, then move into yoga standing or floor work. Announce-breath can stay on; intensity should stay modest for warm-up.\\n\\nThis is educational practice guidance, not medical advice. Match the warm-up to today’s joints, not yesterday’s ambition.\\n\\nRelated: Breath, Sequencing, and Stimulate vs settle."},"chair-practice":{"title":"Chair practice is real practice","summary":"Seated and chair-supported shapes train breath, strength, and mobility — they are not a lesser badge.","body":"Chair practice is skill, not consolation. A sturdy chair can support balance, reduce wrist load, and make forward folds and twists available when the floor feels far away. Older adults, desk workers, and anyone rehabbing load often thrive here.\\n\\nTreat the chair like a prop listed in Modify notes: sit toward the front edge for tall spine work, or use the seat for hands in a standing fold. Keep feet grounded. Soften the jaw. Leave with control.\\n\\nIn the Library, look for modifications and prefer easier variations when enabled in Personalisation. Intensity numbers still apply — a demanding chair sequence can be intensity 3 without ever touching the mat.\\n\\nEgo may argue that “real yoga” is on the floor. Ignore it. Continuous breath and workable sensation are the curriculum.\\n\\nSee Props & history, Safety, and Beginner ego."},"reading-breath-cue":{"title":"Reading your breath cue in the player","summary":"Breath cues and announce-breath settings turn holds into paced practice — use them as information, not as a whip.","body":"When a pose starts, Speech Settings can announce the name, a coaching cue, a from→to transition, and then inhale/exhale pacing. The cue is usually the breathCue field or the first how-to sentence — a short reminder, not a full class script.\\n\\nTurn announce-breath on when soft inhale/exhale reminders help you stay continuous. Turn it off in savasana if the metronome keeps you task-oriented. Transition speak helps when moving between shapes; skip it if you prefer quieter holds.\\n\\nIf the spoken cue disagrees with your body, trust sensation. The app cannot see your knee. Shorten the hold, take a modification, or exit.\\n\\nPreview the routine before play so cues and timings are not surprises. Settings → Voice holds the same Personalisation toggles as the player cog.\\n\\nDeeper breath literacy: Breath, Breath with poses, Pranayama basics."},"intensity-without-ego":{"title":"Intensity 1–5 without ego","summary":"Pose intensity is a planning tool for capacity — not a scoreboard for worth.","body":"Intensity 1–5 in the library describes typical load and complexity, not your character. Cap max pose difficulty in Personalisation when sleep is short or joints are irritable. That hides peaks you do not need today.\\n\\nEgo hears “3” and reaches for “5.” Skill hears “3” and asks whether breath stays conversational. Prefer easier variations when available. Leaving a peak pose is still practice.\\n\\nUse intensity with sequencing: warm lower numbers, one moderate peak, then settle. Tired Tuesdays stay honest by deleting show-off poses from a saved routine copy.\\n\\nSharp pain, numbness that intensifies, or breath-holding panic means back off regardless of the number on the card."},"hips-vs-low-back":{"title":"Hips vs low back: what the pose library can’t diagnose","summary":"Pose cards name regions and sensations — they cannot diagnose why your back or hip hurts. Use them as practice filters, not medical tools.","body":"Hip openers and forward folds often share real estate with the lumbar spine. When the hip is stiff, the low back may volunteer. That is common — and it is not a diagnosis. An app listing “hips” under muscles cannot tell disc from muscle from referred pain.\\n\\nPractice rules of thumb: keep a long spine in folds until hinge mechanics are clear; pad under knees in pigeon; stop for sharp, electrical, or breath-breaking signals. Prefer figure-four or supported variations when the knee complains in hip work.\\n\\nRead Careful / Avoid notes. Prefer modifications. If symptoms persist, escalate to a qualified clinician — this content is educational, not medical advice.\\n\\nJoint focus tags and Learn articles like Shoulders, hips & wrists exist to build literacy, not to replace assessment.\\n\\nSee Biomechanics & safety and Safety & red flags."},"counterposes-one-minute":{"title":"Counterposes in one minute","summary":"After a strong shape, give the spine and nervous system a brief honest opposite or neutral — without turning it into another peak.","body":"A counterpose is a short balancing response, not revenge stretching. After a backbend, a gentle forward fold or neutral lying shape can settle. After a long fold, a mild extension or walk may feel better than another aggressive stretch.\\n\\nKeep it brief — often under a minute — and keep breath easy. If you need a full second peak to “undo” the first, the first was probably too much.\\n\\nIn the builder, pair peaks with quieter neighbors. Preview before play. Transition speak can name the move into the counterpose when authored lines exist.\\n\\nSequencing literacy beats dogma: listen for workable sensation and exit with control.\\n\\nRelated: Sequencing, Spine & core, Stimulate vs settle."},"yin-vs-restore-vs-stretch":{"title":"Yin vs restore vs stretch","summary":"Long holds, supported stillness, and active stretching are different jobs — hire the right one for today’s nervous system.","body":"Yin-style practice often uses longer holds near comfortable tissue limits with less muscular gripping. Restorative prioritizes props and comfort so the nervous system can downshift — stretch is not the metric. Active stretching pairs strength and length with shorter stays and clearer muscular engagement.\\n\\nConfusing them creates strain: yin ambition in a restorative shape, or restorative passivity when you needed strength. Match the session to the weather — stimulate vs settle.\\n\\nLibrary filters and intensity help. Soften the jaw. Keep breath continuous. Stop for sharp or panicky sensation.\\n\\nEducational guidance only — conditions and injuries need qualified advice.\\n\\nSee Yin origins, Stimulate vs settle, Flexibility & progress."},"skip-inversions":{"title":"When to skip inversions (app Avoid notes)","summary":"Inversions are optional tools — Avoid notes, breath quality, and exit control decide whether today is a go.","body":"Shoulderstand, headstand, and handstand cousins carry higher risk when neck, shoulders, or blood pressure are irritable. Skipping them is skill. Legs-up-the-wall and gentle bridges often deliver settling without the load.\\n\\nRead Avoid notes before you press play. If announce cues begin and your jaw already clenched, choose the modification. Prefer easier variations when enabled.\\n\\nNever force the neck to turn in shoulderstand or plow. Come down with control. Dizziness, vision changes, or breath panic are exit signals.\\n\\nThis is not medical advice — glaucoma, hypertension, pregnancy, and recent surgery need clinician guidance before inverted load.\\n\\nRelated: Safety, Biomechanics & safety, Effort."},"builder-20-minute-session":{"title":"Building a 20-minute home session in the builder","summary":"A short custom routine needs a warm start, one clear focus, and a settle — preview before play.","body":"Twenty minutes is enough when the menu is small. Open with breath or cat-cow. Pick one focus — hamstrings, standing strength, or restore — not five. Close with savasana or a supported shape long enough that you cannot treat it as a blink.\\n\\nUse the builder to set holds you can keep with continuous breath. Cap intensity. Add props in Modify spirit even if the card does not list them. Save a “Tired Tuesday” copy so decision fatigue cannot push you into peaks.\\n\\nSpeech Settings: announce what helps, mute what distracts. Transition speak is useful when learning new links; optional once the sequence is familiar.\\n\\nPreview the full run before play. Leaving early still counts if honesty asked for it."},"soft-knees-soft-jaw":{"title":"Soft knees, soft jaw: the underrated safety cues","summary":"Micro-bends and an unclenched face keep joints and breath available when ambition gets loud.","body":"Locked knees and a clenched jaw are common when people chase depth. A soft micro-bend in standing poses often protects the joint line and lets hips hinge more honestly. A soft jaw usually frees the neck and lets breath drop lower.\\n\\nAudit mid-pose: unclench teeth, bend knees slightly, check whether the pose still stands without panic gripping. If it collapses, the intensity was riding on bracing — exit, rest, return shorter.\\n\\nPlayer cues cannot feel your molars. You can. Pair these checks with announce-breath if soft reminders help.\\n\\nSharp joint pain remains a stop. Soft does not mean collapsed — it means unarmored.\\n\\nRelated: Safety, Breath, Biomechanics & safety."}}`),a=JSON.parse(`{"calm-arrive":{"title":"Arrive & Settle","summary":"Soft landing into the present. Release the day and find your seat.","script":["Welcome.","Take a moment to arrive.","Find a comfortable seat, or lie down if that feels better.","Let your hands rest.","Allow your eyes to close, or soften your gaze.","Notice that you are here.","Nothing to fix right now.","Nothing to complete.","Take a slow breath in through the nose.","And a longer breath out.","Again. Soft inhale.","Gentle exhale.","Feel the weight of your body supported.","The floor, the chair, the earth holding you.","If thoughts wander, that is fine.","Simply notice, and return to this breath.","Inhale. Arrive.","Exhale. Settle.","One more easy breath.","When you are ready, open your eyes.","Carry this quiet with you."]},"body-scan":{"title":"Body Scan","summary":"Gentle attention from crown to toes. Notice without fixing.","script":["We will gently scan the body.","Lie down or sit with ease.","Close your eyes if that feels safe.","Begin at the crown of the head.","Notice any sensation there. Warmth. Coolness. Nothing at all.","No need to change it. Just notice.","Softly move to the forehead and the eyes.","Let the tiny muscles around the eyes soften.","Feel the jaw. Unclench if you can.","Tongue resting lightly.","Shoulders. Are they lifted? Let them drop a little.","Arms heavy. Hands open or soft.","Chest rising and falling with breath.","Belly soft. No forcing.","Hips and pelvis resting.","Thighs. Knees. Lower legs.","Feet. Soles touching the floor or the mat.","Now sense the whole body as one field of awareness.","Breath moving through it.","If a tense spot appears, send a kind exhale there.","Stay for three quiet breaths.","When you are ready, wiggle fingers and toes.","Open your eyes. Return gently."]},"breath-awareness":{"title":"Breath Awareness","summary":"Anchor to the natural breath. Count soft cycles without forcing.","script":["Settle into a steady posture.","Spine tall but not rigid.","Bring attention to the breath as it already is.","Do not change it yet. Just watch.","Feel the coolness of the inhale at the nostrils.","Feel the warmth of the exhale.","Or notice the rise and fall of the belly.","Choose one place to rest your attention.","When the mind wanders, kindly return.","No judgment. Just return.","Now, if it feels easy, count soft cycles.","Inhale. One.","Exhale. One.","Inhale. Two.","Exhale. Two.","Continue up to five, then begin again at one.","If you lose the count, start over with kindness.","The returning is the practice.","Let the breath be natural. No strain.","A few more cycles in silence.","Release the counting.","Rest in open awareness for a moment.","When ready, open your eyes."]},"loving-kindness":{"title":"Loving-Kindness Lite","summary":"Short phrases of goodwill for yourself and someone you care about.","script":["Sit comfortably. Soften the face.","Place a hand on the heart if that helps.","We will offer simple phrases of kindness.","First, toward yourself.","Silently repeat after me, or just listen.","May I be safe.","May I be well.","May I be at ease.","Say them again, slowly.","May I be safe.","May I be well.","May I be at ease.","If that feels hard, that is okay. Stay with the wish itself.","Now bring to mind someone who is easy to care about.","A friend, a pet, a kind stranger.","Picture them briefly.","May you be safe.","May you be well.","May you be at ease.","Once more.","May you be safe.","May you be well.","May you be at ease.","Feel any warmth that arises. Or simply rest in the words.","Return to your own breath.","Thank yourself for practicing.","Gently open your eyes."]},"evening-wind-down":{"title":"Evening Wind-Down","summary":"Release the day. Slow the nervous system before sleep.","script":["This practice is for the end of the day.","Dim the lights if you can.","Lie down or recline with support.","Let the day be finished, even if the mind still lists tasks.","You can set them down for now.","Inhale softly for a count of four.","Exhale for a count of six.","Again. Four in. Six out.","Longer exhales tell the body it is safe to rest.","Scan for leftover tension in the face.","Soften the brow. Soften the jaw.","Drop the shoulders away from the ears.","Imagine the day settling like dust after a breeze.","What happened, happened.","What remains can wait until morning.","Feel the mattress or the floor holding you.","Breath quieter. Body heavier.","If sleep comes, let it.","If not, rest in this softness anyway.","Three more slow breaths.","In. Out.","In. Out.","In. Out.","Good night to the day. Peace to the night."]},"anxiety-soft-landing":{"title":"Anxiety Soft-Landing","summary":"Ground through the senses. A short reset when nerves run high.","script":["If you feel activated or worried, you are welcome here.","You do not need to feel calm yet.","Just follow along.","Plant both feet on the floor if you can.","Feel the contact. Heels. Balls of the feet. Toes.","Press down gently. Notice the push back from the ground.","Name five things you can see.","Quietly. No rush.","Name four things you can touch.","Clothes. Chair. Air on skin.","Name three sounds, near or far.","Name two scents, or simply notice the air.","Name one taste, or the feeling in the mouth.","You are here. In this body. In this room.","Now breathe in for four.","Hold softly for two.","Out for six.","Again if you like.","Place a hand on the chest or belly.","Feel movement under your hand.","Anxiety may still be present. That is allowed.","You have given the nervous system a softer landing.","Take one more breath.","When ready, open your eyes and continue your day."]},"morning-energy-5":{"title":"Morning Energy","summary":"Five minutes to wake the body, clear the mind, and meet the day with intention.","script":["Good morning.","Welcome to a short practice to meet the day.","Sit tall, or stand if that feels better.","Let your eyes soften, or close them.","Feel your feet on the floor.","Take a slow breath in through the nose.","And a fuller breath out through the mouth.","Again. Soft inhale.","Complete exhale.","One more. Fill the chest.","Empty completely.","[pause:4]","Look ahead to the day without gripping it.","You do not need the whole map yet.","Just the next honest step.","[pause:5]","Breathe in for four.","Two. Three. Four.","Breathe out for four.","Two. Three. Four.","Again, at your own pace.","[pause:6]","Feel warmth in the hands.","Feel readiness in the legs.","[pause:4]","Roll the shoulders up, back, and down.","Unclench the jaw.","Soften the belly.","Notice any leftover sleep in the body.","No need to push it away.","Breathe into the sides of the ribs.","And let them narrow on the exhale.","[pause:5]","Now bring a little brightness to the breath.","Inhale as if you are waking from the inside.","Exhale anything heavy from yesterday.","Inhale possibility.","Exhale effort that is not needed yet.","[pause:4]","Place a hand on the heart, or rest both hands in the lap.","Silently, or just listening, try these phrases.","I am here.","I begin again.","I have enough for this morning.","[pause:4]","I move with steadiness.","I meet what comes with a clear mind.","I am allowed to take up space today.","[pause:5]","I choose one clear intention for today.","It can be simple.","Kindness. Focus. Patience. Energy.","Hold that word for a breath.","[pause:6]","See yourself moving through the morning with that quality.","[pause:5]","[pause:5]","Stretch the fingers wide, then soft.","Lift the corners of the mouth just a little, if it feels true.","[pause:3]","Feel the spine lengthen on the next inhale.","Feel the shoulders settle on the exhale.","One more bright breath in.","And a long, easy breath out.","Wiggle the fingers.","When you are ready, open the eyes.","Carry this quiet energy into your day."]},"progressive-release-10":{"title":"Progressive Release","summary":"Tense and release through the body to soften residual stress. About ten minutes.","script":["Welcome.","This practice uses gentle tension and release.","Lie down if you can, or sit with support.","Close the eyes if that feels safe.","Nothing to force. Stay in a comfortable range.","Take a slow breath in.","And a longer breath out.","[pause:19]","Bring attention to both feet.","Curl the toes and tighten the feet.","Hold.","[pause:19]","Release.","Feel the difference.","[pause:21]","Tighten the calves.","Hold.","[pause:19]","Release.","Let the lower legs grow heavy.","[pause:21]","Tighten the thighs.","Hold.","[pause:19]","Release.","Soft legs. Soft hips.","[pause:21]","Gently draw the belly in.","Hold without strain.","[pause:19]","Release.","Let the belly move freely with breath.","[pause:21]","Make soft fists. Tighten the hands and forearms.","Hold.","[pause:19]","Release.","Fingers open. Arms heavy.","[pause:21]","Shrug the shoulders up toward the ears.","Hold.","[pause:19]","Drop them.","Feel space across the upper back.","[pause:21]","Gently scrunch the face. Eyes, brow, jaw.","Hold.","[pause:19]","Release.","Forehead smooth. Jaw soft. Tongue resting.","[pause:23]","Now tense the whole body lightly, as one.","Hold for a breath.","[pause:35]","Let everything go.","[pause:8]","Once more, a lighter whole-body squeeze.","Hold briefly.","[pause:5]","And release completely.","Heavier now. Softer now.","Feel the body settle into the surface beneath you.","[pause:39]","Rest here.","Breath quiet. Body soft.","If thoughts return, that is fine.","Return to the feeling of release.","[pause:50]","Stay soft.","[pause:40]","Wiggle fingers and toes.","Take one more easy breath.","When ready, open the eyes.","Carry this softness with you."]},"deep-rest-20":{"title":"Deep Rest","summary":"A spacious twenty-minute practice for nervous-system rest. Ideal lying down.","script":["Welcome to a practice of deep rest.","Lie on your back if you can.","Support the head and knees if that helps.","Let the arms rest by your sides, palms soft.","Close the eyes.","There is nowhere else to be.","[pause:23]","Feel the points of contact with the floor or bed.","Heels. Hips. Shoulder blades. Head.","Allow the body to be held.","[pause:23]","Notice the natural breath.","No need to change it.","Inhale arrives.","Exhale leaves.","[pause:25]","If the mind is busy, that is allowed.","You can rest anyway.","Simply keep returning to sensation.","[pause:23]","Bring awareness to the right foot.","Toes. Sole. Heel.","[pause:21]","Right lower leg.","Knee.","Thigh.","[pause:21]","Right hip.","Whole right leg, heavy and quiet.","[pause:23]","Left foot.","Toes. Sole. Heel.","[pause:21]","Left lower leg.","Knee.","Thigh.","[pause:21]","Left hip.","Whole left leg, heavy and quiet.","[pause:23]","Pelvis and low belly.","Soft.","[pause:21]","Chest rising and falling.","Heart space open and easy.","[pause:23]","Right hand.","Fingers. Palm. Wrist.","[pause:14]","Right arm. Elbow. Shoulder.","[pause:21]","Left hand.","Fingers. Palm. Wrist.","[pause:14]","Left arm. Elbow. Shoulder.","[pause:23]","Throat soft.","Jaw unclenched.","Tongue resting.","[pause:21]","Eyes resting in their sockets.","Forehead smooth.","Scalp and crown of the head.","[pause:23]","Sense the whole body as one field of stillness.","Breath moving through it like a quiet tide.","[pause:62]","Stay with the whole body.","[pause:105]","Soft. Spacious. Still.","[pause:55]","If a thought appears, let it pass like a cloud.","[pause:50]","Return to the feeling of being held.","[pause:55]","Rest here.","Nothing to solve.","Nothing to complete.","[pause:110]","If you drift, that is fine.","If you stay aware, that is fine too.","Both are rest.","[pause:130]","Rest.","[pause:115]","Begin to notice the breath again.","A little more vivid now.","[pause:23]","Feel the room around you.","Sounds near and far.","[pause:21]","Wiggle the fingers.","Wiggle the toes.","Roll the wrists and ankles if you like.","[pause:21]","Take a deeper breath in.","And a long sigh out.","When you are ready, open the eyes.","Return slowly.","Carry a little of this quiet with you."]},"forest-clearing-5":{"title":"Forest Clearing","summary":"Arrive in the body, then rest in a sunlit woodland clearing.","script":["Welcome.","Take a comfortable seat, or lie down if that feels better.","Let your hands rest.","Allow your eyes to close, or soften your gaze.","Notice the weight of your body being held.","Take a slow breath in through the nose.","And a longer, easier breath out.","Again. Soft inhale.","Gentle exhale.","If thoughts wander, that is fine. Return to the breath.","Now, imagine a path beneath soft leaf litter.","You walk without hurry into a quiet forest.","Dappled light moves across your forearms.","Feel the gentle warmth of the sun wherever it finds skin.","A cool freshness rides the breeze between the trees.","Smell green earth, bark, and a clean mineral dampness.","The path opens into a small clearing.","Moss cushions a fallen log. You sit.","Sunlight pools in the center like quiet gold.","Feel that warmth on your face, slow and kind.","A breeze touches your hair and cools your temples.","Birdsong arrives from far away, then fades.","Your breath matches the hush of the leaves.","Inhale the freshness. Exhale any leftover haste.","Notice how safe the ground feels under you.","How wide the sky seems above the canopy.","A beetle crosses a sunlit patch of bark, unhurried.","You have nowhere to be but here.","Warmth pools again on your closed eyelids.","Cool air slips under your collar like a kind hand.","Stay with the warmth on your cheeks.","Stay with the cool air on your lips as you breathe out.","This clearing asks nothing. It simply holds you.","Let one more breath travel all the way to the belly.","And leave again, soft as the leaves.","Wander your attention slowly around the clearing’s edge.","Fern. Shadow. A pale mushroom at the base of a stump.","Everything is vivid because you are not rushing.","Feel sun-warmth again where it lands on the knee.","Feel breeze-coolness where it slips across the throat.","You could stay here all afternoon. For now, a few breaths are enough.","Now rest in the breath alone for a little while.","Inhale slowly.","Exhale slowly.","Inhale.","Exhale.","Feel warmth wherever the body is warm.","Feel coolness wherever the air is cool.","Inhale.","Exhale.","Nowhere to go. Nothing to fix.","Inhale.","Exhale.","Rest here for a few quiet breaths.","Know that you can return to this place anytime.","When you are ready, deepen the breath.","Wiggle fingers and toes.","Open your eyes softly.","Carry a little of this peace with you."]},"lakeside-dawn-5":{"title":"Lakeside Dawn","summary":"Breath awareness into a still lake morning of warmth and cool air.","script":["Welcome.","Take a comfortable seat, or lie down if that feels better.","Let your hands rest.","Allow your eyes to close, or soften your gaze.","Notice the weight of your body being held.","Take a slow breath in through the nose.","And a longer, easier breath out.","Again. Soft inhale.","Gentle exhale.","If thoughts wander, that is fine. Return to the breath.","Picture yourself at the edge of a still lake at dawn.","The water holds a pale silver sky.","Cool air brushes your cheeks with a clean freshness.","A soft ribbon of sun begins to warm your shoulders.","Feel that warmth spreading slowly across your back.","You step closer. Soft sand gives under your feet.","Dip your fingertips into the water. Cool. Clear.","Ripples travel outward and disappear.","The breeze smells faintly of water plants and morning.","Listen. Almost nothing. A distant bird. Your own breath.","Sit on a smooth stone warmed just enough by the rising light.","Feel the stone’s quiet heat beneath you.","Feel the freshness of the air entering your lungs.","The lake mirrors soft pink and gold.","You watch light move across the surface like slow breathing.","A fish rises, rings widen, then the mirror returns.","Warmth on your closed eyelids.","Coolness on the backs of your hands.","Somewhere far off, a boat rope ticks once against wood.","Then silence again, wide and kind.","Inhale the cool morning. Exhale into the open water.","Peace settles the way mist lifts from water — gently, completely.","You are allowed to take up space in this quiet.","One more breath tasting of dawn.","Look again at the silver path of light on the water.","Follow it with soft eyes toward the far shore.","Trees over there are blue with distance and morning mist.","Warmth grows a little on your shoulders as the sun climbs.","The breeze stays fresh — lake-born and clean.","Let that freshness rinse the mind the way light rinses the surface.","Sit for three more breaths of warmth and cool air together.","Now rest in the breath alone for a little while.","Inhale slowly.","Exhale slowly.","Inhale.","Exhale.","Feel warmth wherever the body is warm.","Feel coolness wherever the air is cool.","Inhale.","Exhale.","Nowhere to go. Nothing to fix.","Inhale.","Exhale.","Rest here for a few quiet breaths.","Know that you can return to this place anytime.","When you are ready, deepen the breath.","Wiggle fingers and toes.","Open your eyes softly.","Carry a little of this peace with you."]},"meadow-breeze-5":{"title":"Mountain Meadow","summary":"Settle, then lie in warm grass under an easy alpine breeze.","script":["Welcome.","Take a comfortable seat, or lie down if that feels better.","Let your hands rest.","Allow your eyes to close, or soften your gaze.","Notice the weight of your body being held.","Take a slow breath in through the nose.","And a longer, easier breath out.","Again. Soft inhale.","Gentle exhale.","If thoughts wander, that is fine. Return to the breath.","Imagine a wide mountain meadow in late morning.","Tall grasses sway in easy waves.","The sun is warm without being sharp.","Feel it on the crown of your head, kind and steady.","A fresh breeze moves through the grass and finds your face.","It smells of wildflowers and sun-dried earth.","You walk slowly, fingertips brushing seed heads.","Soft tickle. Soft sound.","Butterflies lift and settle again, unhurried.","You find a place to lie back in the grass.","The earth holds your whole length.","Warmth along your front. Cool soil-shadow at your sides.","The breeze comes and goes like a friendly tide.","Inhale freshness. Exhale into the open sky.","A cloud slides across the sun for a moment.","Coolness. Then warmth returns to your face.","Notice how large the quiet feels.","How small any worry seems in this wide field.","Your hands rest in the grass. Tiny stems press kindly.","Stay with the warmth of the sun on your closed eyes.","Stay with the soft press of grass against your arms.","You are allowed to be this still.","Let the meadow breathe you for a few more cycles.","Roll your attention from the warm crown of the head","down through a soft face, a soft throat,","into a chest that rises easily under open sky.","The breeze finds the inside of your wrists.","Cool. Alive. Friendly.","Somewhere bees work without urgency.","Their hum is another kind of quiet.","Stay until warmth and freshness feel like one fabric.","Now rest in the breath alone for a little while.","Inhale slowly.","Exhale slowly.","Inhale.","Exhale.","Feel warmth wherever the body is warm.","Feel coolness wherever the air is cool.","Inhale.","Exhale.","Nowhere to go. Nothing to fix.","Inhale.","Exhale.","Rest here for a few quiet breaths.","Know that you can return to this place anytime.","When you are ready, deepen the breath.","Wiggle fingers and toes.","Open your eyes softly.","Carry a little of this peace with you."]},"cove-shore-5":{"title":"Sheltered Cove","summary":"Body and breath, then a quiet beach cove of sun and salt air.","script":["Welcome.","Take a comfortable seat, or lie down if that feels better.","Let your hands rest.","Allow your eyes to close, or soften your gaze.","Notice the weight of your body being held.","Take a slow breath in through the nose.","And a longer, easier breath out.","Again. Soft inhale.","Gentle exhale.","If thoughts wander, that is fine. Return to the breath.","See yourself arriving at a sheltered cove.","Cliffs curve around soft pale sand.","The sea moves in low, patient waves.","A mild sun warms the tops of your shoulders.","A salty breeze cools your lips and eyelids.","Feel the freshness of that air filling your chest.","Walk to the waterline. Wet sand hugs your feet.","Cool foam touches your ankles and slips away.","The rhythm is simple. Arrive. Soften. Leave.","Sit where dry sand is warm beneath you.","Lean back on your hands. Feel the grainy heat.","Listen to the hush and rush of the cove.","Smell salt, sun, and clean stone.","Warmth on your skin. Coolness in every inhale.","Far out, light sparkles like quiet laughter.","You do not need to chase it. It is already here.","A wave reaches farther, cools your toes, then retreats.","Warm sand reclaims your feet.","Let your breath move with the waves — slow in, longer out.","Peace is the cove itself. You are inside it.","Rest your attention on the warmth between your shoulder blades.","And on the fresh salt air at the tip of the nose.","Trace the cliff line with soft imagination.","Stone warmed by day. Shadow cool in the folds.","A tide pool nearby holds a tiny clear world.","You do not need to lean in. Knowing it is there is enough.","Another wave. Cool ankles. Warm sand. Soft breath.","The cove keeps offering the same simple kindness.","Receive it once more before you leave.","Now rest in the breath alone for a little while.","Inhale slowly.","Exhale slowly.","Inhale.","Exhale.","Feel warmth wherever the body is warm.","Feel coolness wherever the air is cool.","Inhale.","Exhale.","Nowhere to go. Nothing to fix.","Inhale.","Exhale.","Rest here for a few quiet breaths.","Know that you can return to this place anytime.","When you are ready, deepen the breath.","Wiggle fingers and toes.","Open your eyes softly.","Carry a little of this peace with you."]},"garden-dusk-5":{"title":"Garden at Dusk","summary":"Soft arrival into a walled garden cooling from a warm day.","script":["Welcome.","Take a comfortable seat, or lie down if that feels better.","Let your hands rest.","Allow your eyes to close, or soften your gaze.","Notice the weight of your body being held.","Take a slow breath in through the nose.","And a longer, easier breath out.","Again. Soft inhale.","Gentle exhale.","If thoughts wander, that is fine. Return to the breath.","Imagine a quiet walled garden at soft dusk.","Stone paths hold the last warmth of the day.","Feel that gentle heat through the soles of your feet.","Lavender and evening roses release a calm fragrance.","A cool breeze slips over the wall and cools your neck.","The air is fresh after a warm afternoon.","You walk slowly between hedges trimmed soft as breath.","Your fingers brush leaves still holding sun.","Warm. Smooth. Alive.","A wooden bench waits beneath a quiet tree.","You sit. The wood is pleasantly warm against your back.","Above, the sky turns lavender and rose.","Birds settle. The garden grows hush.","Feel warmth fading kindly from stone and wood.","Feel the freshening cool of evening on your face.","Inhale scent and stillness.","Exhale the day you carried in.","A moth passes through the last gold light.","Nothing here is urgent. Everything is enough.","Rest in that enoughness.","Let your belly soften into the dusk air.","Let your next breath be the quietest of the day.","Walk one slow loop of the path before you finish.","Warm stones cooling underfoot.","Hedges releasing the day’s stored perfume.","The breeze now has an evening edge — fresh, almost sweet.","Pause at the gate without opening it yet.","Feel how calm has settled into the shoulders.","Carry the garden’s hush like a small lantern inward.","Now rest in the breath alone for a little while.","Inhale slowly.","Exhale slowly.","Inhale.","Exhale.","Feel warmth wherever the body is warm.","Feel coolness wherever the air is cool.","Inhale.","Exhale.","Nowhere to go. Nothing to fix.","Inhale.","Exhale.","Rest here for a few quiet breaths.","Know that you can return to this place anytime.","When you are ready, deepen the breath.","Wiggle fingers and toes.","Open your eyes softly.","Carry a little of this peace with you."]},"forest-path-10":{"title":"Deep Forest Path","summary":"Longer journey through an old forest to moss, stream, and stillness.","script":["Welcome.","Find a posture that asks nothing of you.","Sit, or lie down, with whatever support you need.","Let your hands rest open or soft.","Allow your eyes to close, or keep a soft gaze.","Feel the places where your body meets the ground.","The heels, the sit bones, the back of the head, or the length of the spine.","Nothing to hold up right now.","Take a slow breath in through the nose.","Feel the coolness of the air arriving.","And breathe out a little longer.","Feel the warmth of the exhale leaving.","Again. Soft inhale.","Unhurried exhale.","Let the shoulders drop a fraction.","Let the jaw unclench.","Let the belly be soft.","Stay with three quiet breaths, just as they are.","Inhale. Arrive.","Exhale. Settle.","If the mind wanders, notice it kindly, and come back to this breath.","Now begin a slow walk into an old forest.","The path is soft with needles and fallen leaves.","Each step makes a quiet sound, then silence returns.","Sunlight threads through high branches in warm ribbons.","Feel a patch of sun on your forearm — sudden gentle heat.","Then shade again, cool and green.","A breeze moves the canopy. Fresh air finds your face.","Smell resin, damp soil, and the clean sweetness of moss.","Pause. Place a palm on rough bark.","Feel the tree’s stillness enter your hand.","Continue deeper. The sounds of the outer world fall away.","Somewhere a stream speaks in small bright syllables.","You follow until water appears between stones.","Kneel. Dip your hands. Cool clarity.","Splash a little on your wrists. Freshness wakes the skin.","Sit on a flat rock warmed by a narrow column of sun.","Feel that warmth in your sit bones and the backs of your thighs.","Feel the cool breath of the stream against your shins.","Birds call once, then leave the quiet whole again.","Breathe in the forest’s freshness.","Breathe out into the patient trunks around you.","Notice how your shoulders have dropped without being asked.","How the jaw softens when there is nowhere else to be.","Stand when you are ready and walk a little farther.","Ferns brush your calves with cool green fingertips.","A clearing opens — round as a held breath.","Lie back on deep moss.","The earth receives your weight completely.","Warmth of filtered sun on your face.","Coolness of moss along your spine.","The breeze arrives, leaves, arrives again.","Stay with the feeling of being held by a living place.","Safe. Quiet. Belonging without effort.","Count five slow breaths here, each one softer.","Notice scent again — green, damp, honest.","Notice sound again — almost none, and that is plenty.","If a thought appears, let it drift like a leaf on the stream.","Return to warmth on the skin wherever the sun finds you.","Return to coolness in the shade between those warm ribbons.","You have walked far enough inward.","Let three slow breaths seal this in the body.","Before you leave, stand once more at the stream.","Watch clear water braid around stones.","Cool air rises from the moving surface.","Warm light still finds a strip of your forearm.","Cup water and wet the brow if you like — in imagination, cool and kind.","The forest does not applaud. It simply continues.","That continuance is a teacher.","Walk the path outward a few quiet steps in the mind.","Needles underfoot. Soft sound. Soft return.","Yet the clearing’s peace stays in the chest like stored sun.","Feel it there — warmth behind the sternum.","Feel freshness still at the nostrils.","You can bring both into ordinary rooms.","One last look up through branches to a coin of sky.","Enough.","Now let the story rest, and stay with sensation.","Inhale the freshness of this place.","Exhale into its warmth and quiet.","Inhale.","Exhale.","Again. Soft inhale.","Longer exhale.","Feel the body held by the ground of this imagined world.","Inhale.","Exhale.","If thoughts wander, return to warmth on the skin.","Or to cool air at the nose.","Inhale.","Exhale.","Inhale.","Exhale.","Stay. Soften. Continue.","Inhale.","Exhale.","One more easy cycle.","Inhale.","Exhale.","Linger in this feeling for a few more breaths.","Warmth. Softness. Enoughness.","You can return to this place whenever you need it.","It lives in your attention, not only in imagination.","Begin to deepen the breath.","Feel the room around you again.","Wiggle the fingers. Soften the toes.","When you are ready, open your eyes.","Take one more easy breath.","Carry this calm into whatever comes next."]},"lake-wander-10":{"title":"Lake Shore Wander","summary":"A full lakeside walk of warm stone, cool water, and open sky.","script":["Welcome.","Find a posture that asks nothing of you.","Sit, or lie down, with whatever support you need.","Let your hands rest open or soft.","Allow your eyes to close, or keep a soft gaze.","Feel the places where your body meets the ground.","The heels, the sit bones, the back of the head, or the length of the spine.","Nothing to hold up right now.","Take a slow breath in through the nose.","Feel the coolness of the air arriving.","And breathe out a little longer.","Feel the warmth of the exhale leaving.","Again. Soft inhale.","Unhurried exhale.","Let the shoulders drop a fraction.","Let the jaw unclench.","Let the belly be soft.","Stay with three quiet breaths, just as they are.","Inhale. Arrive.","Exhale. Settle.","If the mind wanders, notice it kindly, and come back to this breath.","Imagine waking beside a wide quiet lake.","Morning light lies soft on the water.","Cool air touches your cheeks with a clean freshness.","The first sun warms the tops of your feet.","You begin a slow walk along the shore.","Sand and small smooth stones shift gently underfoot.","Each step is a quiet conversation with the ground.","A breeze comes off the water — fresh, lightly cool.","It lifts the hair at your temples.","Smell cedar, wet stones, and open morning.","Watch a heron stand in the shallows, perfectly still.","You match that stillness for a few breaths.","Warmth grows on your shoulders as the sun climbs.","Find a sunlit boulder and sit.","Feel heat stored in the stone rising into your body.","Feel the fresher air moving across your lips with each inhale.","The lake’s surface wrinkles, then goes glass again.","Light trembles there like quiet joy.","Continue around a curve of shore into a little bay.","Reeds whisper. Water ticks softly against wood.","An old dock stretches out. You walk to the end.","Sit with feet dangling above cool water.","Sun on your back. Breeze on your shins.","Dip a toe. Gentle chill. A smile you do not need to show.","Lie back on the warm boards.","Hear water under you. Sky above you.","Your breath becomes as wide as the lake.","Inhale freshness. Exhale into endless blue.","Nothing to solve. Only this warmth, this air, this peace.","Feel the dock’s heat along your spine.","Feel a cooler ribbon of air whenever the breeze turns.","A dragonfly stitches the air and is gone.","Stay until the feeling sinks into muscle and bone.","If the mind lists tasks, set them on the far shore for now.","They can wait. The lake is not waiting for anything.","One hand on the belly. Rise. Fall.","Warmth under the palm of the other hand on wood.","Rest in this double holding — body and place.","Stand and walk a little farther in imagination.","Pebbles click softly. Water brightens near a fallen branch.","Sun finds the back of your neck with friendly heat.","Shade from a willow cools your eyelids for a few steps.","Alternating warmth and freshness becomes a walking prayer.","No words required. Only sensation and breath.","Find a patch of warm sand and sit facing open water.","Let the eyes go soft on the horizon line.","Inhale the lake’s cool perfume.","Exhale toward the distant hills.","Whatever you carried here can rest on the shore beside you.","It does not need carrying in the water.","Stay until the next three breaths feel complete on their own.","Now let the story rest, and stay with sensation.","Inhale the freshness of this place.","Exhale into its warmth and quiet.","Inhale.","Exhale.","Again. Soft inhale.","Longer exhale.","Feel the body held by the ground of this imagined world.","Inhale.","Exhale.","If thoughts wander, return to warmth on the skin.","Or to cool air at the nose.","Inhale.","Exhale.","Inhale.","Exhale.","Stay. Soften. Continue.","Inhale.","Exhale.","One more easy cycle.","Inhale.","Exhale.","Linger in this feeling for a few more breaths.","Warmth. Softness. Enoughness.","You can return to this place whenever you need it.","It lives in your attention, not only in imagination.","Begin to deepen the breath.","Feel the room around you again.","Wiggle the fingers. Soften the toes.","When you are ready, open your eyes.","Take one more easy breath.","Carry this calm into whatever comes next."]},"coastal-walk-10":{"title":"Coastal Path","summary":"Cliff path to beach — sun, salt breeze, and tide-paced breath.","script":["Welcome.","Find a posture that asks nothing of you.","Sit, or lie down, with whatever support you need.","Let your hands rest open or soft.","Allow your eyes to close, or keep a soft gaze.","Feel the places where your body meets the ground.","The heels, the sit bones, the back of the head, or the length of the spine.","Nothing to hold up right now.","Take a slow breath in through the nose.","Feel the coolness of the air arriving.","And breathe out a little longer.","Feel the warmth of the exhale leaving.","Again. Soft inhale.","Unhurried exhale.","Let the shoulders drop a fraction.","Let the jaw unclench.","Let the belly be soft.","Stay with three quiet breaths, just as they are.","Inhale. Arrive.","Exhale. Settle.","If the mind wanders, notice it kindly, and come back to this breath.","See a coastal path along low cliffs.","The ocean breathes below in long, steady rolls.","Sunlight warms the crown of your head and the bridge of your nose.","A salt breeze cools your eyelids with bright freshness.","Smell the sea — mineral, clean, awake.","You walk slowly. Grasses lean inland in the wind.","Feel sun on one cheek, cool air on the other.","That contrast is itself a kind of calm.","A wooden stair leads down toward a hidden beach.","Each step is sure. Your hand rests on a weathered rail.","Warm wood under your palm.","At the bottom, sand receives your feet like a soft yes.","Walk to where waves write and erase white lines.","Cool water folds over your ankles.","Warm sand higher on the shore waits when you step back.","Sit. Dig your hands into sun-heated grains.","Feel that dry warmth against cool damp sand beneath.","Watch light shatter across open water.","Breathe in the freshness of the breeze.","Breathe out any tightness still held in the ribs.","A gull cries once and becomes part of the hush.","Lie back. Close your eyes.","Warmth across your front. Cool earth-shadow at your sides.","The tide’s rhythm coaches your heart toward ease.","You are small in the best way — held by something vast and kind.","Stay with the warmth of the sun on your closed eyes.","Stay with the cool kiss of spray on your skin when the wind turns.","Peace is not elsewhere. It is this shore, this breath, this body.","Dig your heels a little deeper into warm sand.","Feel how the earth answers with steady support.","Breathe in salt freshness to the bottom of the lungs.","Breathe out anything that has been bracing for impact.","There is no impact here. Only arrival after arrival of waves.","Let five breaths ride that same patient rhythm.","Then rest in the afterglow of sun on skin.","Rise and walk the waterline a short way.","Left foot cool and wet. Right foot warm and dry. Then switch.","The body learns contrast as comfort, not conflict.","Pick up a smooth stone warmed by light.","Feel its heat in the palm. Its density. Its quiet.","Set it down with thanks — no need to keep it.","The keeping is inward.","Look out past the breakers to calmer color.","Breathe as if you could taste blue.","Fresh breeze. Warm cheek. Soft belly.","Let the next inhale be the deepest of the practice.","Let the exhale empty without force.","The cove, the cliff, the path home — all wait without pressure.","Now let the story rest, and stay with sensation.","Inhale the freshness of this place.","Exhale into its warmth and quiet.","Inhale.","Exhale.","Again. Soft inhale.","Longer exhale.","Feel the body held by the ground of this imagined world.","Inhale.","Exhale.","If thoughts wander, return to warmth on the skin.","Or to cool air at the nose.","Inhale.","Exhale.","Inhale.","Exhale.","Stay. Soften. Continue.","Inhale.","Exhale.","One more easy cycle.","Inhale.","Exhale.","Linger in this feeling for a few more breaths.","Warmth. Softness. Enoughness.","You can return to this place whenever you need it.","It lives in your attention, not only in imagination.","Begin to deepen the breath.","Feel the room around you again.","Wiggle the fingers. Soften the toes.","When you are ready, open your eyes.","Take one more easy breath.","Carry this calm into whatever comes next."]},"canyon-gold-10":{"title":"Golden Canyon","summary":"Warm stone and fresh canyon air in late-day gold light.","script":["Welcome.","Find a posture that asks nothing of you.","Sit, or lie down, with whatever support you need.","Let your hands rest open or soft.","Allow your eyes to close, or keep a soft gaze.","Feel the places where your body meets the ground.","The heels, the sit bones, the back of the head, or the length of the spine.","Nothing to hold up right now.","Take a slow breath in through the nose.","Feel the coolness of the air arriving.","And breathe out a little longer.","Feel the warmth of the exhale leaving.","Again. Soft inhale.","Unhurried exhale.","Let the shoulders drop a fraction.","Let the jaw unclench.","Let the belly be soft.","Stay with three quiet breaths, just as they are.","Inhale. Arrive.","Exhale. Settle.","If the mind wanders, notice it kindly, and come back to this breath.","Imagine a wide canyon painted in soft gold and rose.","It is late afternoon. The light is generous.","Warmth radiates from stone that has held the sun all day.","Feel that radiant heat on your shins and the backs of your hands.","A dry, fresh breeze moves down the canyon floor.","It cools your face without taking the comfort of the warmth.","You walk a sandy path between quiet walls.","Footsteps whisper. Echoes are soft, almost polite.","Smell sunbaked earth, sage, and clean dust.","Place your palm on smooth stone.","Feel stored daylight there — steady, patient heat.","A ribbon of shade offers coolness for a few steps.","Then sun again, warm across your shoulders like a shawl.","You come to a place where the canyon opens.","Sit on a flat rock still holding golden warmth.","Feel it rise through your seat and spine.","Feel the fresher air of altitude in every inhale.","Far above, a hawk turns slow circles without hurry.","You borrow that unhurried quality.","Breath long. Body heavy. Mind wide as the sky between walls.","Watch shadow climb the far cliff as the sun lowers.","Colors deepen. Warmth softens but does not vanish.","The breeze smells cooler now, evening-fresh.","Wrap your arms around yourself for a moment.","Warmth of your own body. Warmth of stone. Enough.","Lie back carefully and watch the first quiet star.","The canyon holds you the way a cupped hand holds water — gently, without spill.","Rest in that held feeling.","Notice the last heat rising from rock into the cooling air.","Notice how the breeze now smells of evening and dust and sage.","Your breath has slowed to match the wide quiet.","If tension remains in the brow, soften it in this gold light.","If the jaw is tight, let it hang loose as the hawk’s easy turn.","Stay for a few more cycles of warm stone and fresh air.","You are not late. You are here.","Walk a few more steps along warm sand between canyon walls.","Your shadow stretches long and unworried.","Place both palms on stone again.","Heat enters the hands like a blessing you do not have to earn.","The breeze combs coolness through your hair.","Sage scent. Dust scent. Sun scent.","Sit. Knees soft. Spine easy.","Watch color deepen from gold toward rose.","Warmth softens. Freshness increases. Balance remains.","This is how evenings teach the nervous system to downshift.","Borrow the lesson without effort.","Three breaths for the stone.","Three for the sky.","Three for the quiet animal of your own body, resting.","Now let the story rest, and stay with sensation.","Inhale the freshness of this place.","Exhale into its warmth and quiet.","Inhale.","Exhale.","Again. Soft inhale.","Longer exhale.","Feel the body held by the ground of this imagined world.","Inhale.","Exhale.","If thoughts wander, return to warmth on the skin.","Or to cool air at the nose.","Inhale.","Exhale.","Inhale.","Exhale.","Stay. Soften. Continue.","Inhale.","Exhale.","One more easy cycle.","Inhale.","Exhale.","Linger in this feeling for a few more breaths.","Warmth. Softness. Enoughness.","You can return to this place whenever you need it.","It lives in your attention, not only in imagination.","Begin to deepen the breath.","Feel the room around you again.","Wiggle the fingers. Soften the toes.","When you are ready, open your eyes.","Take one more easy breath.","Carry this calm into whatever comes next."]},"bamboo-garden-10":{"title":"Bamboo Garden","summary":"After-rain garden walk of cool freshness and soft returning sun.","script":["Welcome.","Find a posture that asks nothing of you.","Sit, or lie down, with whatever support you need.","Let your hands rest open or soft.","Allow your eyes to close, or keep a soft gaze.","Feel the places where your body meets the ground.","The heels, the sit bones, the back of the head, or the length of the spine.","Nothing to hold up right now.","Take a slow breath in through the nose.","Feel the coolness of the air arriving.","And breathe out a little longer.","Feel the warmth of the exhale leaving.","Again. Soft inhale.","Unhurried exhale.","Let the shoulders drop a fraction.","Let the jaw unclench.","Let the belly be soft.","Stay with three quiet breaths, just as they are.","Inhale. Arrive.","Exhale. Settle.","If the mind wanders, notice it kindly, and come back to this breath.","Picture a bamboo garden after rain.","Stone is dark and clean. Leaves shine.","Cool freshness fills the air like a soft bell.","A break in the clouds lets sun through.","Feel sudden gentle warmth on your forehead and cheekbones.","Steam lifts faintly from the path — earth breathing out.","You step onto stepping-stones set in moss.","Each stone is cool and sure underfoot.","Bamboo creaks and whispers in a light breeze.","The sound is green. The sound is calm.","Smell wet leaves, stone, and a faint sweetness of tea plants nearby.","Pause beside a small pond.","Koi move like slow thoughts beneath the surface.","Sun flecks warm your wrists as you rest them on the rail.","A breeze cools the dampness at your temples.","Freshness in. Softness out.","Follow a covered walkway of worn wood.","The boards are cool in shade, warmer where light falls.","You sit on a bench facing raked gravel and one perfect stone.","Nothing needs rearranging.","Feel the quiet geometry settle your mind.","Warmth returns as cloud thins — a kind hand on your shoulders.","Then shade again, cool and restful.","Sip imaginary tea. Taste warmth. Feel the cup’s heat in your palms.","Outside the garden, life continues. Inside, time loosens.","Walk once more beneath bamboo.","Let the tall stalks sway your breath into the same easy rhythm.","Cool drip from a leaf finds your wrist — a tiny fresh surprise.","Then sun again, warm on the same spot until it dries.","You belong to this peace for as long as you stay.","And a thread of it will come with you when you leave.","Sit once more. Hands open on your knees.","Warmth wherever light touches. Coolness in the shade of bamboo.","Inhale the after-rain freshness.","Exhale into the raked quiet of stone and gravel.","Nothing sharp remains. Only soft edges and enough air.","Return to the pond for a final pause.","Ripples from a fallen drop widen and vanish.","Sun flecks dance, then still.","Warmth on the cheekbone. Cool mist-memory in the nose.","Bow slightly to the garden — a small inward nod.","Walk the stepping-stones once more, slower than before.","Cool moss between stones. Warm wood of the bridge rail.","Bamboo speaks in leaf-language overhead.","You understand enough of it: stay, soften, continue.","At the threshold, feel both worlds — garden peace and ordinary day.","You may braid them.","Inhale freshness for the braid.","Exhale warmth into the hands, ready to meet what comes.","The garden remains, whether you are looking or not.","Now let the story rest, and stay with sensation.","Inhale the freshness of this place.","Exhale into its warmth and quiet.","Inhale.","Exhale.","Again. Soft inhale.","Longer exhale.","Feel the body held by the ground of this imagined world.","Inhale.","Exhale.","If thoughts wander, return to warmth on the skin.","Or to cool air at the nose.","Inhale.","Exhale.","Inhale.","Exhale.","Stay. Soften. Continue.","Inhale.","Exhale.","One more easy cycle.","Inhale.","Exhale.","Linger in this feeling for a few more breaths.","Warmth. Softness. Enoughness.","You can return to this place whenever you need it.","It lives in your attention, not only in imagination.","Begin to deepen the breath.","Feel the room around you again.","Wiggle the fingers. Soften the toes.","When you are ready, open your eyes.","Take one more easy breath.","Carry this calm into whatever comes next."]},"gratitude-5":{"title":"Simple Gratitude","summary":"Name what is already here. A short warmth practice.","script":["Welcome.","Find a comfortable seat, or lie down if that feels better.","Let the hands rest.","Soften the eyes, or close them.","Take a slow breath in.","And a longer breath out.","Bring to mind one small thing that helped you today, or this week.","It can be ordinary. Warm water. A message. Light on a wall.","[pause:21]","Hold it gently in awareness.","Notice any softening in the chest or face.","[pause:26]","Silently, thank this one thing.","Thank you for being here.","[pause:21]","Now a second thing. Another small good.","[pause:26]","Thank you.","[pause:15]","And one more. A third.","[pause:26]","Let gratitude be simple. Not forced. Just noticed.","[pause:31]","Rest in that warmth for a few breaths.","[pause:41]","Take one more easy breath.","Wiggle the fingers.","When you are ready, open the eyes.","Carry a little of this with you."]},"self-compassion-5":{"title":"Self-Compassion","summary":"Meet yourself as you would a good friend.","script":["Welcome.","Find a comfortable seat, or lie down if that feels better.","Let the hands rest.","Soften the eyes, or close them.","Take a slow breath in.","And a longer breath out.","Place a hand on the heart, or rest both hands in the lap.","Notice how you are, without fixing it.","[pause:31]","If there is struggle, acknowledge it.","This is a moment of difficulty.","Difficulty is part of being human.","[pause:39]","Offer yourself kindness the way you would offer it to a friend.","May I be kind to myself.","May I give myself the compassion I need.","[pause:39]","Again, slowly.","May I be kind to myself.","May I give myself the compassion I need.","[pause:45]","Breathe into the hand on the heart, if it is there.","[pause:39]","You do not have to earn this softness.","Take one more easy breath.","Wiggle the fingers.","When you are ready, open the eyes.","Carry a little of this with you."]},"senses-grounding-5":{"title":"Five Senses Grounding","summary":"Orient to sight, touch, sound, scent, and taste.","script":["Welcome.","If you feel scattered or activated, this practice can help.","Keep the eyes open for now, if that feels safer.","Plant both feet on the floor.","[pause:17]","Name five things you can see.","Quietly. Take your time.","[pause:45]","Name four things you can feel or touch.","Clothes. Chair. Air on skin. Feet on floor.","[pause:39]","Name three sounds.","Near or far. Soft or clear.","[pause:39]","Name two scents, or simply notice the quality of the air.","[pause:28]","Name one taste, or the feeling inside the mouth.","[pause:23]","You are here. In this body. In this room.","Breathe in for four.","Out for six.","[pause:23]","Take one more easy breath.","Wiggle the fingers.","When you are ready, open the eyes.","Carry a little of this with you."]},"midday-reset-5":{"title":"Midday Reset","summary":"A five-minute clearing between tasks.","script":["Welcome.","Find a comfortable seat, or lie down if that feels better.","Let the hands rest.","Soften the eyes, or close them.","Take a slow breath in.","And a longer breath out.","Let the morning end here, even if the day continues.","Drop the shoulders.","Unclench the jaw.","[pause:30]","Inhale through the nose.","Exhale through the mouth, as if fogging a window.","Again.","[pause:30]","Imagine setting down whatever you were carrying.","It can wait on the table beside you.","[pause:37]","Feel the spine tall.","Feel the belly soft.","[pause:30]","Ask quietly: what matters in the next hour?","One clear next step is enough.","[pause:44]","Breathe that simplicity in.","Breathe effort out.","[pause:37]","Take one more easy breath.","Wiggle the fingers.","When you are ready, open the eyes.","Carry a little of this with you."]},"box-breath-5":{"title":"Box Breath","summary":"Equal inhale, hold, exhale, hold. Steady the system.","script":["Welcome.","Find a comfortable seat, or lie down if that feels better.","Let the hands rest.","Soften the eyes, or close them.","Take a slow breath in.","And a longer breath out.","We will breathe in a simple box.","In for four. Hold for four. Out for four. Hold for four.","Stay gentle. Never strain.","[pause:20]","Inhale. Two. Three. Four.","Hold. Two. Three. Four.","Exhale. Two. Three. Four.","Hold. Two. Three. Four.","[pause:20]","Again. Inhale.","Hold.","Exhale.","Hold.","[pause:26]","Continue at your own count for a few rounds.","If four is too long, use three.","[pause:45]","One more full box.","Inhale.","Hold.","Exhale.","Hold.","[pause:26]","Return to natural breath.","Notice the quiet that follows.","[pause:33]","Rest here.","[pause:33]","Take one more easy breath.","Wiggle the fingers.","When you are ready, open the eyes.","Carry a little of this with you."]},"focus-clarity-5":{"title":"Focus & Clarity","summary":"Single-point attention for a clearer mind.","script":["Welcome.","Find a comfortable seat, or lie down if that feels better.","Let the hands rest.","Soften the eyes, or close them.","Take a slow breath in.","And a longer breath out.","Choose one anchor. The breath at the nostrils, or the rise of the belly.","Rest attention there.","[pause:23]","When the mind wanders, notice where it went.","Then return. Kindly. Cleanly.","[pause:29]","The returning is the training.","Inhale. Stay.","Exhale. Stay.","[pause:34]","If helpful, count breaths up to five, then begin again.","One.","[pause:17]","Two.","[pause:17]","Three.","[pause:17]","Four.","[pause:17]","Five.","[pause:23]","Release the count.","Rest in clear, open attention for a moment.","[pause:34]","Take one more easy breath.","Wiggle the fingers.","When you are ready, open the eyes.","Carry a little of this with you."]},"confidence-5":{"title":"Quiet Confidence","summary":"Stand in your own ground without forcing bravado.","script":["Welcome.","Find a comfortable seat, or lie down if that feels better.","Let the hands rest.","Soften the eyes, or close them.","Take a slow breath in.","And a longer breath out.","Feel the sit bones, or the feet.","A steady base beneath you.","[pause:22]","Lengthen the spine without hardening.","Soft face. Soft belly. Strong center.","[pause:22]","Silently try these phrases, or just listen.","I can meet what is mine to meet.","[pause:22]","I do not need to rush my becoming.","[pause:22]","I trust my next honest step.","[pause:28]","Breathe confidence as warmth in the chest, not as armor.","[pause:28]","See yourself handling one ordinary challenge with steadiness.","[pause:33]","Return to the breath.","Steady. Enough.","[pause:28]","Take one more easy breath.","Wiggle the fingers.","When you are ready, open the eyes.","Carry a little of this with you."]},"soft-belly-5":{"title":"Soft Belly Breathing","summary":"Release bracing in the belly and nervous system.","script":["Welcome.","Find a comfortable seat, or lie down if that feels better.","Let the hands rest.","Soften the eyes, or close them.","Take a slow breath in.","And a longer breath out.","Rest a hand on the lower belly if you like.","Notice if the belly is holding.","[pause:20]","On the next inhale, allow the belly to expand.","On the exhale, let it fall without squeezing.","[pause:20]","Again. Soft belly in.","Soft belly out.","[pause:25]","If the mind argues, let the body lead.","Expansion. Release.","[pause:29]","Shoulders drop.","Jaw soft.","Belly free.","[pause:25]","Stay with ten quiet soft-belly breaths.","[pause:45]","Notice any ease that arrived.","[pause:20]","Rest here.","[pause:27]","Take one more easy breath.","Wiggle the fingers.","When you are ready, open the eyes.","Carry a little of this with you."]},"desk-unclench-5":{"title":"Desk Unclench","summary":"Undo screen tension in the face, neck, and hands.","script":["Welcome.","Stay seated. This is for the middle of work.","Unhook the gaze from the screen for a moment.","Look farther away, if you can.","[pause:28]","Roll the shoulders up, back, and down.","Twice more.","[pause:38]","Open and close the hands.","Shake them lightly.","[pause:28]","Soften the brow.","Unclench the jaw. Let the tongue rest.","[pause:38]","Inhale into the sides of the ribs.","Exhale and let the chest settle.","[pause:38]","Blink slowly three times.","[pause:28]","One more full breath.","Return when ready, a little less braced.","[pause:28]","Take one more easy breath.","Wiggle the fingers.","When you are ready, open the eyes.","Carry ease back to the next task."]},"kindness-hard-day-5":{"title":"Kindness for a Hard Day","summary":"When the day has been a lot. Soft landing.","script":["Welcome.","Find a comfortable seat, or lie down if that feels better.","Let the hands rest.","Soften the eyes, or close them.","Take a slow breath in.","And a longer breath out.","You do not need to pretend it was easy.","Let the truth of tiredness be allowed.","[pause:31]","Breathe in care.","Breathe out the demand to be fine.","[pause:31]","May I be gentle with myself tonight.","May I rest as I am.","[pause:31]","May tomorrow ask only what I can give.","[pause:31]","Feel the body supported.","Nothing more required in this minute.","[pause:45]","Hand on heart, if it helps.","You made it through.","[pause:38]","Take one more easy breath.","Wiggle the fingers.","When you are ready, open the eyes.","Carry a little of this with you."]},"open-awareness-5":{"title":"Open Awareness","summary":"Widen attention beyond a single point.","script":["Welcome.","Find a comfortable seat, or lie down if that feels better.","Let the hands rest.","Soften the eyes, or close them.","Take a slow breath in.","And a longer breath out.","Start with the breath for a few cycles.","[pause:28]","Now widen. Include sounds.","Near. Far. Changing. Steady.","[pause:28]","Include sensations in the body.","Contact points. Temperature. Soft pulse.","[pause:28]","Include the space of the room.","Awareness like open sky.","[pause:34]","Thoughts may appear like weather.","No need to chase or push them.","Sky remains.","[pause:45]","Rest in this open field.","[pause:45]","Take one more easy breath.","Wiggle the fingers.","When you are ready, open the eyes.","Carry a little of this with you."]},"rain-window-5":{"title":"Rain at the Window","summary":"A short imagery rest with soft weather.","script":["Welcome.","Find a comfortable seat, or lie down if that feels better.","Let the hands rest.","Soften the eyes, or close them.","Take a slow breath in.","And a longer breath out.","Imagine sitting by a window on a quiet rainy day.","Glass cool. World soft outside.","[pause:30]","Hear the rain without needing a story.","Small taps. Occasional heavier falls.","[pause:36]","Smell clean damp air.","See grey light, gentle and unhurried.","[pause:30]","There is nowhere to go in the rain.","Permission to pause.","[pause:36]","Breathe with the rhythm of water on the glass.","[pause:45]","Let the nervous system take the cue: soften.","[pause:36]","Take one more easy breath.","Wiggle the fingers.","When you are ready, open the eyes.","Carry a little of this with you."]},"post-practice-5":{"title":"After Practice Settle","summary":"Integrate movement. Transition out gently.","script":["Welcome.","You have practiced. Now let the body receive it.","Lie down or sit with ease.","Close the eyes.","[pause:31]","Scan for warmth, vibration, or quiet fatigue.","No grading. Just notice.","[pause:45]","Long exhale.","Again.","[pause:38]","Thank the body for showing up.","[pause:31]","Let effort drain into the floor.","[pause:45]","One clear breath in.","One complete breath out.","[pause:38]","Take one more easy breath.","Wiggle the fingers.","When you are ready, open the eyes.","Carry a little of this with you."]},"cool-anger-5":{"title":"Cool the Heat","summary":"When irritation is high. Lengthen the exhale.","script":["Welcome.","If anger or irritation is present, you are welcome here.","You do not need to make it disappear.","Just give it more room.","Feel the feet.","[pause:25]","Inhale for four.","Exhale for six or eight.","Longer out-breaths cool the system.","[pause:33]","Again.","[pause:33]","Name the heat without feeding the story.","Heat in the chest. Tight jaw. Fast mind.","[pause:41]","Soften the hands.","Drop the shoulders.","[pause:33]","You can respond later from a clearer place.","For now, breathe.","[pause:45]","Take one more easy breath.","Wiggle the fingers.","When you are ready, open the eyes.","Carry a little of this with you."]},"sleep-gate-5":{"title":"Sleep Gate","summary":"A short doorway into night rest.","script":["This practice is for the edge of sleep.","Dim the lights. Lie down.","Nothing left to finish in this moment.","[pause:24]","Inhale softly.","Exhale longer.","[pause:24]","Release the forehead.","Release the eyes.","Release the jaw.","[pause:29]","Heavy arms. Heavy legs.","[pause:29]","If thoughts visit, let them drift past like night cars.","You stay with the breath.","[pause:45]","Body sinking.","Breath quiet.","[pause:45]","If sleep comes, let it.","If not, rest anyway.","[pause:35]","Good night to the day."]},"anxiety-ease-10":{"title":"Anxiety Ease","summary":"A longer soft landing when worry is loud.","script":["Welcome.","Take time to arrive.","Sit or lie down with support.","Close the eyes if that feels safe.","Feel contact with the ground.","Slow breath in.","Longer breath out.","[pause:20]","Again.","[pause:20]","Let the shoulders drop.","Let the belly soften.","[pause:25]","Anxiety may still be here. That is allowed.","We are not fighting it. We are befriending the body.","[pause:25]","Press the feet gently into the floor.","Feel the floor press back.","[pause:25]","Name three things you can see behind closed eyes, or with soft gaze.","Dark. Light. Shape of eyelids.","[pause:25]","Name three sensations.","Clothes. Temperature. Breath.","[pause:25]","Breathe in for four.","Hold for two.","Out for six.","[pause:20]","Again.","[pause:25]","Place a hand on the chest or belly.","Feel movement under the hand.","Say quietly: right now, I am breathing.","[pause:30]","If the mind races ahead, thank it for trying to protect you.","Then return to this breath.","[pause:41]","Scan the face. Soften.","Scan the hands. Soften.","[pause:30]","Rest in the rhythm of longer exhales.","[pause:76]","You have given the nervous system a wider shore.","[pause:41]","[pause:30]","Begin to deepen the breath.","Feel the room again.","Wiggle fingers and toes.","When ready, open the eyes.","Move slowly into what comes next."]},"body-scan-10":{"title":"Body Scan Deep","summary":"Crown to toes with room to notice.","script":["Welcome.","Take time to arrive.","Sit or lie down with support.","Close the eyes if that feels safe.","Feel contact with the ground.","Slow breath in.","Longer breath out.","[pause:21]","Again.","[pause:21]","Let the shoulders drop.","Let the belly soften.","[pause:27]","Begin at the crown of the head.","Notice sensation, or the lack of it.","[pause:27]","Forehead. Eyes. Cheeks. Jaw.","Let the face melt a little.","[pause:27]","Throat. Neck. Shoulders.","Invite the shoulders to drop.","[pause:32]","Arms. Elbows. Wrists. Hands. Fingers.","[pause:32]","Chest rising and falling.","Heart space soft.","[pause:27]","Belly. Low back. Hips.","[pause:32]","Thighs. Knees. Calves. Ankles. Feet. Toes.","[pause:38]","Sense the whole body as one field.","Breath moving through it.","[pause:54]","If a tense place remains, send an exhale there.","[pause:43]","Rest in whole-body awareness.","[pause:81]","[pause:32]","Begin to deepen the breath.","Feel the room again.","Wiggle fingers and toes.","When ready, open the eyes.","Move slowly into what comes next."]},"gratitude-expand-10":{"title":"Gratitude Expanded","summary":"From one small good to a wider field of thanks.","script":["Welcome.","Take time to arrive.","Sit or lie down with support.","Close the eyes if that feels safe.","Feel contact with the ground.","Slow breath in.","Longer breath out.","[pause:27]","Again.","[pause:27]","Let the shoulders drop.","Let the belly soften.","[pause:34]","Begin with one small concrete good.","Hold it. Thank it.","[pause:40]","A second. A person, place, or comfort.","Thank you.","[pause:40]","A third. Something about your body that works today.","Thank you.","[pause:40]","Widen to the people who have been kind, even briefly.","[pause:54]","Widen to the place you are in. Shelter. Air. Ground.","[pause:54]","If gratitude feels hard, thank the effort of showing up.","That counts.","[pause:40]","Rest in any warmth that arose.","Or rest in the intention itself.","[pause:90]","[pause:40]","Begin to deepen the breath.","Feel the room again.","Wiggle fingers and toes.","When ready, open the eyes.","Move slowly into what comes next."]},"self-compassion-10":{"title":"Self-Compassion Deep","summary":"Common humanity, mindfulness, and kindness.","script":["Welcome.","Take time to arrive.","Sit or lie down with support.","Close the eyes if that feels safe.","Feel contact with the ground.","Slow breath in.","Longer breath out.","[pause:26]","Again.","[pause:26]","Let the shoulders drop.","Let the belly soften.","[pause:32]","Hand on heart, if that helps.","Notice your state without judgment.","[pause:32]","This is a moment of suffering, or of ordinary human strain.","Others feel this too.","[pause:39]","May I be kind to myself in this moment.","[pause:32]","May I accept myself as I am.","[pause:32]","May I give myself the compassion I need.","[pause:39]","Repeat the phrases that land. Leave the ones that do not.","[pause:52]","Imagine speaking to yourself as a wise friend would.","What tone would they use?","Offer yourself that tone now.","[pause:65]","Breathe kindness in.","Breathe harshness out.","[pause:78]","[pause:39]","Begin to deepen the breath.","Feel the room again.","Wiggle fingers and toes.","When ready, open the eyes.","Move slowly into what comes next."]},"heart-space-10":{"title":"Heart Space","summary":"Warm attention in the center of the chest.","script":["Welcome.","Take time to arrive.","Sit or lie down with support.","Close the eyes if that feels safe.","Feel contact with the ground.","Slow breath in.","Longer breath out.","[pause:25]","Again.","[pause:25]","Let the shoulders drop.","Let the belly soften.","[pause:31]","Bring attention to the center of the chest.","Not forcing feeling. Just locating the space.","[pause:31]","Breathe as if the inhale enters through the heart.","As if the exhale softens the heart from inside.","[pause:37]","If emotion arises, let it move like weather.","[pause:37]","Silently: may my heart be at ease.","[pause:31]","May I be patient with my own timing.","[pause:31]","Bring to mind someone easy to care about.","Wish them ease.","May you be at ease.","[pause:37]","Return to your own heart space.","Warm. Spacious. Human.","[pause:75]","Rest here.","[pause:90]","[pause:37]","Begin to deepen the breath.","Feel the room again.","Wiggle fingers and toes.","When ready, open the eyes.","Move slowly into what comes next."]},"evening-unload-10":{"title":"Evening Unload","summary":"Set the day down before night.","script":["Welcome.","Take time to arrive.","Sit or lie down with support.","Close the eyes if that feels safe.","Feel contact with the ground.","Slow breath in.","Longer breath out.","[pause:26]","Again.","[pause:26]","Let the shoulders drop.","Let the belly soften.","[pause:33]","Let the day be finished for now.","What happened, happened.","What remains can wait until morning.","[pause:33]","On the exhale, imagine placing tasks on a shelf.","One by one. No drama. Just set down.","[pause:53]","Inhale four. Exhale six.","[pause:33]","Soften the face.","Drop the shoulders.","Heavy arms. Heavy legs.","[pause:40]","If the mind lists again, nod to it, and return to the shelf.","[pause:53]","Feel the mattress or chair holding you.","[pause:66]","Breath quieter. Body heavier.","[pause:90]","[pause:40]","Begin to deepen the breath.","Feel the room again.","Wiggle fingers and toes.","When ready, open the eyes.","Move slowly into what comes next."]},"forgiveness-soft-10":{"title":"Soft Forgiveness","summary":"Loosen the grip of resentment, without forcing absolution.","script":["Welcome.","Take time to arrive.","Sit or lie down with support.","Close the eyes if that feels safe.","Feel contact with the ground.","Slow breath in.","Longer breath out.","[pause:27]","Again.","[pause:27]","Let the shoulders drop.","Let the belly soften.","[pause:34]","Forgiveness here means releasing your own clenched fist.","Not pretending harm did not matter.","[pause:34]","Start with something small you hold against yourself.","A mistake. A shortcoming.","[pause:34]","Silently: I forgive myself for being human.","I release what I no longer need to carry.","[pause:54]","If it feels right, bring to mind a mild difficulty with another.","Not the hardest story. A lighter one.","[pause:34]","I release what I can.","I keep my boundaries. I put down extra weight.","[pause:54]","Breathe into the places that clenched.","[pause:68]","Rest in the space that opens when the fist softens.","[pause:81]","[pause:41]","Begin to deepen the breath.","Feel the room again.","Wiggle fingers and toes.","When ready, open the eyes.","Move slowly into what comes next."]},"sound-listening-10":{"title":"Listening Meditation","summary":"Let sound be the anchor.","script":["Welcome.","Take time to arrive.","Sit or lie down with support.","Close the eyes if that feels safe.","Feel contact with the ground.","Slow breath in.","Longer breath out.","[pause:23]","Again.","[pause:23]","Let the shoulders drop.","Let the belly soften.","[pause:29]","Open the ears.","Notice the nearest sound.","[pause:29]","Notice the farthest sound you can hear.","[pause:29]","Notice silence between sounds.","[pause:35]","Sounds arise and pass. You do not need to name them.","Hearing hears.","[pause:47]","When the mind wanders, return to listening.","[pause:35]","Include the sound of your own breath.","[pause:35]","Rest in the whole soundscape.","A living field of vibration.","[pause:90]","Nothing to solve in the listening.","[pause:70]","[pause:35]","Begin to deepen the breath.","Rest here.","[pause:27]","Feel the room again.","Wiggle fingers and toes.","When ready, open the eyes.","Move slowly into what comes next."]},"mountain-still-10":{"title":"Mountain Stillness","summary":"Imagery of a mountain: steady through weather.","script":["Welcome.","Take time to arrive.","Sit or lie down with support.","Close the eyes if that feels safe.","Feel contact with the ground.","Slow breath in.","Longer breath out.","[pause:28]","Again.","[pause:28]","Let the shoulders drop.","Let the belly soften.","[pause:36]","Imagine yourself as a mountain.","Base wide. Peak quiet. Vast patience.","[pause:43]","Weather moves across the mountain.","Sun. Wind. Cloud. Storm.","The mountain remains.","[pause:57]","Thoughts and moods are weather.","You are the mountain.","[pause:57]","Feel the base of your body rooted.","Feel height in the spine without strain.","[pause:43]","Breathe as sky around the mountain.","[pause:71]","Steady. Unhurried. Enough.","[pause:90]","[pause:43]","Begin to deepen the breath.","Feel the room again.","Wiggle fingers and toes.","When ready, open the eyes.","Move slowly into what comes next."]},"focus-steady-10":{"title":"Steady Focus","summary":"Build concentration with breath counting and returns.","script":["Welcome.","Take time to arrive.","Sit or lie down with support.","Close the eyes if that feels safe.","Feel contact with the ground.","Slow breath in.","Longer breath out.","[pause:21]","Again.","[pause:21]","Let the shoulders drop.","Let the belly soften.","[pause:26]","Choose the breath at the nostrils as your point.","Stay with the feeling of air.","[pause:26]","Count each exhale from one to ten.","If you lose the count, begin again at one without blame.","[pause:21]","One.","[pause:21]","Two.","[pause:21]","Three.","[pause:21]","Four.","[pause:21]","Five.","[pause:21]","Continue silently to ten, then start at one.","[pause:90]","Release the counting.","Rest in bare attention on the breath.","[pause:79]","Clarity without hardness.","[pause:42]","[pause:32]","Begin to deepen the breath.","Rest here.","[pause:44]","Feel the room again.","Wiggle fingers and toes.","When ready, open the eyes.","Move slowly into what comes next."]},"sleep-descent-15":{"title":"Sleep Descent","summary":"A longer glide toward sleep.","script":["Welcome to a practice for sleep.","Lie down. Make the dark your friend.","You may fall asleep before the end. That is success.","[pause:22]","Slow breath in.","Longer breath out.","[pause:22]","Release the forehead.","[pause:18]","Release the eyes.","[pause:18]","Release the jaw and tongue.","[pause:22]","Shoulders melt.","[pause:22]","Arms heavy. Hands open.","[pause:22]","Chest soft. Belly soft.","[pause:22]","Hips heavy.","[pause:22]","Legs heavy. Feet heavy.","[pause:27]","The whole body sinking into the bed.","[pause:36]","Thoughts like distant traffic.","You do not follow them.","[pause:45]","Breath quieter.","[pause:45]","Darker. Softer. Slower.","[pause:67]","Nothing to finish.","[pause:54]","Safe to rest.","[pause:89]","Safe to sleep.","[pause:112]","If you are still awake, keep resting in the exhale.","[pause:89]","Good night.","[pause:67]"]},"compassion-circle-20":{"title":"Compassion Circle","summary":"Kindness for self, a friend, a neutral person, and all beings.","script":["Welcome.","Take time to arrive.","Sit or lie down with support.","Close the eyes if that feels safe.","Feel contact with the ground.","Slow breath in.","Longer breath out.","[pause:27]","Again.","[pause:27]","Let the shoulders drop.","Let the belly soften.","[pause:34]","We will offer kindness in a widening circle.","Phrases are invitations, not commands.","[pause:34]","Toward yourself.","May I be safe.","[pause:27]","May I be well.","[pause:27]","May I live with ease.","[pause:41]","Again, slowly.","May I be safe.","May I be well.","May I live with ease.","[pause:69]","Bring to mind a friend or someone easy to care about.","May you be safe.","[pause:27]","May you be well.","[pause:27]","May you live with ease.","[pause:69]","Bring to mind a neutral person. Someone you barely know.","May you be safe.","May you be well.","May you live with ease.","[pause:69]","If it feels possible, include someone difficult, lightly.","Or return to yourself if that is wiser today.","May you be free from suffering.","[pause:55]","Widen to all beings, near and far.","May all beings be safe.","[pause:34]","May all beings be well.","[pause:34]","May all beings live with ease.","[pause:82]","Return to your own body and breath.","Rest in the afterglow of the phrases.","[pause:150]","Nothing to force. Softness is enough.","[pause:137]","[pause:41]","Begin to deepen the breath.","Rest here.","[pause:26]","Feel the room again.","Wiggle fingers and toes.","When ready, open the eyes.","Move slowly into what comes next."]},"quit-smoking-free-10":{"title":"I Am Free","summary":"Identity affirmations for a non-smoker. Rest in the decision that is already final.","script":["Welcome.","This practice is for you as a non-smoker.","Find a comfortable seat, or lie down if that feels better.","Let the hands rest.","Soften the eyes, or close them.","Take a slow breath in.","And a longer breath out.","[pause:16]","Feel the body supported.","Nothing to prove. Nowhere to rush.","[pause:16]","We will work with clear statements of freedom.","Listen, or silently repeat what lands true.","[pause:18]","I am a non-smoker now.","[pause:16]","I am so happy to be rid of the nicotine disease.","[pause:18]","Smoking is no longer a part of my life or my identity.","[pause:18]","I am getting these triggers because of past memories or watching other smokers.","[pause:18]","These triggers can't do anything to me, because I have freed myself from the slavery of addiction.","[pause:22]","I feel sorry for smokers who are still stuck with their smoking deceptions.","Who are trapped in the miserable cycle of nicotine depletion, urge, and refilling.","[pause:18]","I don't suffer like them anymore.","[pause:14]","Now I know the truth.","There is absolutely no benefit of smoking.","[pause:18]","The urine stick has never helped anyone, and it never will.","[pause:18]","Smoking has created a lot of problems for me.","[pause:14]","I took the best decision of my life to never smoke another puff of that disgusting poison.","That decision was final.","[pause:22]","Now, I respect the Law of Smoking.","[pause:18]","Now, all my situations are getting better.","I am becoming happier, healthier, and more confident.","[pause:22]","I am free.","[pause:28]","Rest in that freedom for a few breaths.","Triggers may still visit as old memory.","They cannot return you to slavery.","[pause:36]","I am a non-smoker now.","I am free.","[pause:28]","Take one more easy breath.","Wiggle the fingers.","When you are ready, open the eyes.","Carry this freedom with you."]},"quit-smoking-urge-5":{"title":"Riding the Urge","summary":"When a craving wave rises, ride it without smoking until it passes.","script":["Welcome.","If an urge is here, you are in the right place.","You do not need to fight it or feed it.","Find a steady seat, or stand with both feet on the ground.","Soften the eyes, or keep a soft gaze.","Take a slow breath in.","And a longer breath out.","[pause:12]","Name what is happening, simply.","An urge is present.","It is a wave in the body and mind.","It is not a command.","[pause:14]","Notice where you feel it.","Chest. Throat. Hands. Restlessness.","No need to make it bigger. Just locate it.","[pause:16]","Breathe into that place.","Inhale soft space.","Exhale without acting.","[pause:16]","Urges rise, crest, and fall.","You are the shore. The wave moves through.","[pause:18]","If the mind offers a story about needing a cigarette, thank it and return.","Return to the breath.","Return to the feet on the floor.","[pause:16]","Silently, if it helps.","This is temporary.","I can ride this without smoking.","[pause:18]","Again. Soft inhale.","Longer exhale.","[pause:16]","Notice any easing, even a little.","Or notice that you stayed with yourself.","Both count.","[pause:16]","You are a non-smoker meeting an old echo.","The urge can visit. It cannot own you.","[pause:14]","Take one more easy breath.","Wiggle the fingers.","When you are ready, open the eyes.","Continue your day free."]},"quit-smoking-clear-5":{"title":"Clear Breath","summary":"Reclaim clean air and a free body. Feel what smoking no longer takes.","script":["Welcome.","This is a practice of clear breath.","Find a comfortable seat, or lie down if that feels better.","Let the hands rest.","Soften the eyes, or close them.","Take a slow breath in through the nose.","And a longer breath out.","[pause:10]","Notice the air as it is.","Cool on the inhale.","Warm on the exhale.","No smoke. No poison. Just breath.","[pause:12]","Feel the chest expand without effort.","Feel the ribs widen a little.","[pause:12]","Place a hand on the heart, or rest both hands in the lap.","Sense a body that is healing.","Lungs clearing. Blood freer. Sense of smell returning, day by day.","[pause:16]","Silently try these phrases, or just listen.","My breath belongs to me.","[pause:12]","I choose clean air.","[pause:12]","I am done with that poison.","[pause:14]","Picture your next ordinary moment without a cigarette.","Coffee. A walk. A pause after a meal.","See yourself complete in that moment, already free.","[pause:22]","If a memory of smoking appears, let it be a picture, not a plan.","Return to this inhale.","Return to this exhale.","[pause:14]","Breathe in freedom.","Breathe out the old habit's story.","[pause:14]","You took the decision that matters.","Your body is catching up to that truth.","[pause:12]","Take one more clear breath in.","And a long, easy breath out.","Wiggle the fingers.","When you are ready, open the eyes.","Carry this clear air with you."]}}`),o={"soft-drone":{name:`Soft Drone`},"warm-pad":{name:`Warm Pad`},"ocean-hum":{name:`Ocean Hum`},"mixkit-109-deep-meditation":{name:`Deep Meditation`},"mixkit-324-smooth-meditation":{name:`Smooth Meditation`},"mixkit-365-relaxation-meditation":{name:`Relaxation Meditation`},"mixkit-18-singing-bowl-meditation":{name:`Singing Bowl Meditation`},"mixkit-21-indian-meditations":{name:`Indian Meditations`},"mixkit-345-nature-meditation":{name:`Nature Meditation`},"mixkit-442-nature-yoga":{name:`Nature Yoga`},"mixkit-139-spirit-in-the-woods":{name:`Spirit in the Woods`},"mixkit-148-forest-mist-whispers":{name:`Forest Mist Whispers`},"mixkit-138-forest-treasure":{name:`Forest Treasure`},"mixkit-127-valley-sunset":{name:`Valley Sunset`},"mixkit-444-yoga-song":{name:`Yoga Song`},"mixkit-325-yoga-tune":{name:`Yoga Tune`},"mixkit-27-serene-moments":{name:`Serene Moments`},"mixkit-669-harp-relax":{name:`Harp Relax`},"mixkit-168-staring-at-the-night-sky":{name:`Staring at the Night Sky`},"mixkit-419-pilates-and-yoga":{name:`Pilates and Yoga`}},s={"foundations-to-peak":{name:`Foundations → Peak Warrior`,description:`Build capacity over four weeks: gentle floor, Sun A heat, standing flow, then a longer warrior peak. Tap each week’s “use” when you are ready to advance.`,weeks:[{label:`Week 1 · Arrive`},{label:`Week 2 · Heat`},{label:`Week 3 · Stand`},{label:`Week 4 · Peak`}]},"calm-month":{name:`Calm Month`,description:`A quieter month for the nervous system: morning mobility, yin for hips and spine, then a restorative evening. Use one week at a time; stay longer on a week if you need it.`,weeks:[{label:`Week 1 · Mobility`},{label:`Week 2 · Yin hips`},{label:`Week 3 · Yin spine`},{label:`Week 4 · Restore`}]}},c=JSON.parse(`{"churning-ocean":{"title":"The Churning of the Ocean","story":"Before the nectar, there was thirst. The gods, once bright as sunrise on snow, grew pale. Their garlands wilted. Their weapons felt heavy in hands that had forgotten victory. Vishnu listened to their fear and pointed them toward a prize older than their quarrel with the asuras: amrita, the nectar of immortality, sleeping in the unmeasured deep of the cosmic ocean.\\n\\nThey could not churn those waters alone. Pride had to bend. So an uneasy pact was struck with their rivals — the asuras, fierce and glittering, who also longed to drink forever. Together they uprooted Mount Mandara to serve as a churning rod. Around it they wound Vasuki, the great serpent, living rope of scales and poison-breath. Gods took the tail; asuras, mistrustful, claimed the head. Back and forth they hauled. The mountain shuddered and began to sink. Vishnu became Kurma, the tortoise, and rose beneath the peak, a living foundation under the grinding weight of the world.\\n\\nAges passed in the pull and the roar. The ocean heaved like a chest drawing breath too deep. First rose not treasure but Halahala — a poison so terrible it threatened all that lived. Shiva caught it in his throat and held it there, turning his neck blue, buying the cosmos time. Only then did wonders climb from the foam: Kamadhenu, the wish-fulfilling cow; Airavata, the white elephant; the wish-tree; and Lakshmi herself, lotus-born, radiance walking on water. At last Dhanvantari appeared, physician of the gods, bearing the pot of nectar.\\n\\nThe asuras seized it. For a moment it seemed the long labor would end in their triumph. Vishnu took the form of Mohini — beauty so complete that eyes forgot purpose. Enchanted, the asuras yielded the pot; the gods drank and became deathless. What the story honors is not the final sleight of hand alone, but the shared endurance that brought the gift to the surface. Neither side could have churned the ocean alone. The deepest gifts arrive through patience, cooperation, and the willingness to keep pulling when the waters still look empty.","moral":"Great outcomes ask for patience, cooperation, and willingness to share the work — not domination of the other.","lessonSummary":"Stay with long effort beside others; the deepest gifts arrive through shared endurance, not shortcuts.","style":"patachitra"},"hanuman-leap":{"title":"Hanuman’s Leap to Lanka","story":"When Sita was carried across the sea to Lanka, Rama’s searchers came at last to the southern shore and stopped as if the world itself had drawn a line in salt. Water without end. Wind that tasted of distance. Gulls crying over a horizon that refused to arrive. Among them stood Hanuman — mighty of limb, loyal of heart — and for a moment even he felt small against that glittering waste.\\n\\nJambavan, the old bear-king, saw the doubt and spoke into it like someone waking a sleeper. He reminded Hanuman of the boons of his birth: that he could grow vast as a mountain, that no obstacle was meant to hold him, that he had forgotten his own strength. The words were not flattery. They were a key turning in a lock.\\n\\nPurpose returned like blood to cold hands. Hanuman climbed Mahendra hill. He bowed to the sun and to Rama. Then he sprang. The wind tore around him. Clouds parted like curtains. Mountains fell away beneath his feet as if the earth were a map being rolled up. Surasa, mother of serpents, rose from the sky to test him, jaws wide as destiny. He slipped through by becoming tiny as a thought, then vast again. A demoness seized at his shadow on the water; he struck her down and flew on, devotion louder than fear.\\n\\nAt last Lanka’s walls glittered ahead — gold and threat and promise under a hard sky. He landed, found Sita in the ashoka grove among sorrow and blossoms, gave her Rama’s ring, and carried her message home across the same impossible sea. The leap was not boast. It was memory becoming motion. Doubt had made him small; purpose made him large enough for the ocean.","moral":"Remembering your true capacity can dissolve false limits; devotion turns courage into action.","lessonSummary":"When doubt shrinks you, recall your purpose and leap — service-fueled courage outruns fear.","style":"kerala-mural"},"nachiketa-yamas":{"title":"Nachiketa and Yama","story":"Nachiketa watched his father give away cattle so worn they could barely stand — gifts that looked like generosity and smelled of contempt. The boy’s question was simple and sharp as a new blade. “Father, to whom will you give me?” Twice he was ignored. A third time he asked. “To Death!” his father snapped — and the word, once loosed, could not be called back.\\n\\nSo Nachiketa walked the road to Yama’s house. The Lord of Death was away. For three nights the boy waited at the door without food, water, or welcome, a guest the universe had forgotten. When Yama returned and saw the breach of hospitality, shame moved even Death. He offered three boons.\\n\\nFirst Nachiketa asked that his father’s anger be calmed and that he be received with love when he returned — healing before glory. Second, he asked to learn the fire-ritual that leads to heaven. Third — when Yama tried to buy him off with sons, cattle, elephants, gold, and a long life of pleasures — Nachiketa refused with a clarity that startled the dark. “These things wear out,” he said. “Tell me what lies beyond death. That is the only boon I want.”\\n\\nYama tested him and was pleased. He taught of the eternal Self — smaller than an atom, greater than the great — which neither birth nor death can touch. In the Katha Upanishad the boy remains the one who chose the lasting question over every glittering distraction. True wisdom does not fill its hands with what fades. It keeps asking what endures.","moral":"True wisdom chooses the lasting question over temporary pleasures.","lessonSummary":"Prefer truth over comfort; the hard question outranks glittering distractions.","style":"ink-wash"},"savitri-satyavan":{"title":"Savitri and Satyavan","story":"Princess Savitri traveled to choose a husband and found Satyavan in the forest — noble in bearing, skilled with his hands, and, though she did not yet know it, walking toward a fixed dusk. Narada warned her with the bluntness of the divine: the young man would die within a year. Savitri did not turn away. She married him and carried the knowledge like a stone held warm against her heart.\\n\\nAs the year thinned toward its end she undertook a fierce vow of fasting and prayer. On the fated day she followed Satyavan into the woods while he cut timber. The forest was green and ordinary until it was not. He grew faint, laid his head in her lap, and Yama himself appeared — dark, noose in hand — to take the soul.\\n\\nSavitri rose and walked after Death. Through forest and failing light she kept pace, speaking with a courage that did not shout. She praised dharma, loyalty, and the duty of a wife who will not abandon her husband even at the end of the road. Yama, moved despite himself, offered boons — anything but Satyavan’s life. She asked for her father-in-law’s sight and kingdom restored, for sons for her own father, and at last, carefully worded, for sons born of herself and Satyavan. Trapped by the logic of his own gift, Yama returned her husband’s life.\\n\\nSatyavan woke as if from a deep, strange sleep. They walked home together under trees that suddenly seemed newly made. The tale is not that love denies death, but that steadfast love and lucid speech can meet even the hardest fate without turning away.","moral":"Loyal love and clear courage can meet even the hardest fate without turning away.","lessonSummary":"Stand by what you love with clarity; persistence born of devotion reshapes destiny.","style":"rajasthani-miniature"},"krishna-arjuna":{"title":"Krishna and Arjuna on the Field","story":"On the plain of Kurukshetra the armies faced each other — cousins, teachers, friends divided by a quarrel that had hardened into war. Dust hung in the air. Conches waited. Arjuna asked Krishna to drive the chariot between the lines so he could see whom he must fight. What he saw broke him: grandfathers, uncles, beloved teachers arrayed against him. His bow slipped from his hands. His body trembled. “I will not fight,” he said. “Better to live as a beggar than to kill my kin for a kingdom.”\\n\\nKrishna spoke then — not to flatter despair, but to teach through it. He spoke of the Self that neither slays nor is slain; of bodies that come and go like worn clothes; of the duty that belongs to one’s station when injustice has gone too far. He taught action without clinging to the fruit of action — yoga as skill in action, steadiness in success and failure alike. And he revealed his cosmic form, so Arjuna might see that the field of time is larger than one man’s grief, that countless mouths and eyes and worlds turn within a single vast becoming.\\n\\nArjuna’s fog lifted. He took up the bow again — not because violence was sweet, but because clarity had returned. The Bhagavad Gita begins in collapse and turns toward courage that is not cruelty: do what is yours to do without being owned by fear or by craving for results.","moral":"Do what is yours to do without being owned by fear or by craving for results.","lessonSummary":"Act from clarity, not panic or greed for outcomes — that is skillful practice.","style":"relief-linework"},"ganesha-wisdom":{"title":"Ganesha and the Broken Tusk","story":"Vyasa, composer of the Mahabharata, stood before a task the size of a world. He needed a scribe equal to an endless dictation — a mind that could hold oceans of verse without spilling a drop, a hand that would not tire when the story turned from love to war and back again. He called on Ganesha.\\n\\nThe elephant-headed god agreed on one condition: once the telling began, it must never pause. Vyasa must speak without break, as if speech itself were a river that could not be dammed. Vyasa accepted, then added his own condition: Ganesha must understand every verse before writing it down. So the poet gained moments to compose while the scribe reflected, and the scribe gained meaning instead of mere marks on leaves.\\n\\nThey began. Verse after verse filled the pages. Night and day blurred into the rhythm of voice and stylus — the smell of lamp oil, the scratch of writing, the long pulse of an epic being born. Midway, Ganesha’s writing tool snapped with a sound like a small betrayal. There was no time to search for another; the vow forbade pause. Without hesitation he broke off his own tusk and used it as a pen, writing on so the thread of the story would not be severed.\\n\\nThus the great epic was completed, and Ganesha is often shown holding that tusk — ivory turned into instrument. Wisdom finishes what it starts. When tools fail, ingenuity in service of commitment keeps the work alive. The broken tusk is not a wound to pity. It is a signature of resolve.","moral":"Wisdom finishes what it starts; ingenuity serves commitment when tools fail.","lessonSummary":"Keep the vow of continuity — adapt creatively rather than abandon the work.","style":"folk-kalighat"},"prahlada-faith":{"title":"Prahlada’s Faith","story":"Hiranyakashipu, king of the asuras, had won a boon that made him nearly untouchable: he could not be killed by man or beast, by day or night, indoors or outdoors, on earth or in the sky, by any weapon. Safety of that kind can become a kind of madness. Drunk on it, he ordered the world to worship him alone.\\n\\nHis own son, Prahlada, would not. From childhood the boy praised Vishnu with a calm no threat could shake. Teachers failed to convert him. Guards failed to frighten him. He was thrown from heights, cast among serpents, cast into fire — and still he spoke the name of the Lord with love rather than defiance for its own sake. His faith was not a weapon. It was a home he refused to leave.\\n\\nAt last Hiranyakashipu dragged the boy into the palace hall and struck a pillar. “If your Vishnu is everywhere, is he in this?” he mocked. The pillar split with a sound like the world changing its mind. From it stepped Narasimha — neither fully man nor fully beast — at twilight, neither day nor night. He drew the tyrant across his lap on the threshold, neither indoors nor out, and ended him with claws, not weapons — every clause of the boon turned inside out.\\n\\nPrahlada was crowned in his father’s place and ruled with devotion. The tale is less about spectacle than about an inner altar no tyrant can command. Sincere faith outlasts intimidation.","moral":"Sincere devotion outlasts intimidation; tyranny cannot command the inner altar.","lessonSummary":"Hold your truth calmly under pressure; false power eventually meets its limit.","style":"madhubani"},"markandeya-shiva":{"title":"Markandeya and Shiva","story":"The sage Mrikandu and his wife longed for a child until longing itself became prayer, rising like incense through years of waiting. Shiva offered them a choice that cut like truth: a son who would live long but without great virtue, or a son brilliant in devotion who would live only sixteen years. They chose the second — love choosing intensity over duration. Markandeya was born, and from childhood he loved Shiva with his whole heart, as if each dawn were both gift and soft countdown.\\n\\nAs his sixteenth year approached, his parents wept beside temple lamps. Markandeya went alone to the shrine, embraced the Shiva linga, and poured his fear into prayer until fear and devotion became one flame. The stone was cool; his breath was hot; the world outside the sanctum seemed suddenly far away. When Yama’s messengers could not take him from that refuge, Yama himself came — dark, inexorable — and cast his noose. The noose fell around the boy and the linga together, binding mortality to the sacred.\\n\\nThen Shiva arose from the linga in fierce compassion — Kalantaka, the ender of Death’s claim. He struck Yama aside and declared that Markandeya would remain sixteen in youth and live beyond the ordinary count of years. Death withdrew into shadow. The boy’s devotion had rewritten the calendar of fear.\\n\\nThe story is told wherever people cling to practice when despair tightens its grip. Refuge in the sacred can interrupt what seemed inevitable — not by denying darkness, but by holding fast to what light still answers.","moral":"Deep refuge in the sacred can interrupt the grip of despair.","lessonSummary":"When fear tightens its noose, cling to practice — devotion can change the story.","style":"tanjore-embossed"},"draupadi-vastra":{"title":"Draupadi’s Cry","story":"In the Kaurava court, after the rigged dice game, the air smelled of victory gone rotten. Draupadi was staked and lost as if a person were a coin. Duhshasana dragged her by the hair into the assembly — a queen in a single cloth, menstruating, before kings who should have risen like walls. Torches flickered on faces that would not meet her eyes. She asked whether a man who had already lost himself could stake a wife. The question hung like a blade. The elders sat largely silent. Bhishma spoke of the complexity of dharma and did not rise to stop the shame.\\n\\nThen Duhshasana began to pull at her sari. Cloth whispered against cloth; cruelty became theater. Draupadi called on every human protector present. When they failed, she released her last grip on self-reliance and cried out to Krishna — not as theater, but as the last true door left standing. Tradition says the cloth lengthened without end — blue and endless, a river of fabric — until Duhshasana’s arms ached and the hall’s cruelty stood exposed and unfinished. He fell back exhausted. Her dignity had not been granted by the court; it had been defended when the court collapsed.\\n\\nThe episode is one of the Mahabharata’s hardest mirrors. When pride and politics abandon the vulnerable, calling for higher help is not weakness. It is clarity about where help still lives.","moral":"When pride and politics abandon the vulnerable, calling for higher help is not weakness — it is clarity.","lessonSummary":"Ask for help when systems fail you; dignity can still be defended.","style":"bengal-pata"},"rama-bridge":{"title":"The Bridge to Lanka","story":"Rama’s army of vanaras and bears reached the edge of the sea and felt despair arrive like weather. Wind tore at fur and banners. Lanka lay beyond water no ordinary crossing could bridge — a glitter of towers on the far rim of impossibility. Vibhishana advised seeking the ocean’s leave; after prayer and a show of Rama’s resolve, the ocean agreed to bear a causeway, as if the deep itself had consented to be walked upon.\\n\\nNala, son of the divine architect, knew how stones might float when set with skill and sacred name. The host went to work under a hard bright sky. Monkeys and bears hauled rocks and trees from the hills, their chants rising with the spray. They wrote Rama’s name upon the stones and cast them into the waves; the stones held. Day after day the Setu lengthened — a road growing under thousands of hands, salt on every back, hope measured in each new span of rock.\\n\\nRama and Lakshmana walked the rising bridge. The far shore drew near through sweat and song and the slap of water against new-laid stone. No single hero carried the sea; the army did. When at last they reached Lanka, the crossing itself had already taught them what the war would require: impossible distances become passable when many share one purpose and keep laying the next stone.","moral":"Impossible crossings become possible when many hands share one purpose.","lessonSummary":"Build the path together — collective dedication spans what individuals cannot.","style":"south-indian-temple"},"dama-yanti":{"title":"Nala and Damayanti","story":"Damayanti, princess of Vidarbha, and Nala, king of Nishadha, loved each other by reputation before they met — a love made of stories traveling on the wind. Gods also desired Damayanti. At her swayamvara they took Nala’s form to confuse her choice, multiplying the beloved until the eye might fail. Damayanti looked carefully: the gods did not blink or sweat or touch the earth as men do. She chose the true Nala. The gods blessed them — yet Kali, spirit of strife, vowed to trouble their fortune.\\n\\nYears later Kali entered Nala during a dice game. Kingdoms can fall faster than pride admits. Nala lost his throne, wandered in exile, and in a dark hour abandoned Damayanti while she slept, believing he would only bring her ruin. She woke alone and searched the world for him. Nala, transformed and unrecognizable, took service as a charioteer under another name, learning the shape of humility from the seat of a servant.\\n\\nThrough messengers, riddles, and a second gathering, Damayanti tested the strangers who claimed knowledge of Nala. She recognized her husband not by crown or beauty but by the essence that misfortune and disguise could not erase. They reunited; Nala mastered dice, reclaimed his throne, and Kali was driven out.\\n\\nTheir story is a long arc of love that survives gods’ tests, exile, and the fog of misfortune — partnership that knows the beloved beneath changed faces and hard seasons.","moral":"True partnership recognizes essence through change, loss, and return.","lessonSummary":"See through appearances; loyalty looks for the person, not the costume of fortune.","style":"mughal-miniature"},"shakuntala":{"title":"Shakuntala’s Ring","story":"In Kanva’s forest ashram lived Shakuntala, raised among birds and sages, her days measured in blossom and birdcall. King Dushyanta, hunting nearby, met her and they married in the gandharva way — a union of hearts under living green. Before returning to his capital he gave her a royal ring as token, promising to send for her. The forest held their secret like a cupped hand.\\n\\nLost in thoughts of him, Shakuntala failed to notice the arrival of the hot-tempered sage Durvasa. Feeling slighted, he cursed her: the one she dreamed of would forget her entirely. Her friends begged mercy. Durvasa softened the curse — remembrance would return when the king saw the ring.\\n\\nWhen Shakuntala went to court, pregnant with Dushyanta’s child, the king did not know her. The ring was gone — lost in a river during the journey. Humiliation bloomed where recognition should have been. She left. Years later a fisherman found the ring in a fish’s belly and brought it to the palace. At the sight of it, Dushyanta’s memory flooded back like a river reclaiming its bed. He sought Shakuntala and their son Bharata, from whom a lineage of kings would take its name.\\n\\nKalidasa’s telling makes the wound clear: attention and remembrance are fragile. Mindfulness protects what love builds; distraction can cost a recognition you must later reclaim.","moral":"Mindfulness protects what love builds; neglect invites forgetting.","lessonSummary":"Stay present to your vows — distraction can cost recognition you must later reclaim.","style":"company-school"},"aharavan-indra":{"title":"Ahalya Restored","story":"Ahalya, wife of the sage Gautama, was famed for beauty and purity — a presence like clear water in a quiet ashram, where birds nested without fear and morning light arrived soft through leaves. Indra, king of the gods, desired her and came in Gautama’s form while the sage was away. Accounts differ on Ahalya’s knowledge — some say she was deceived; some say she knew and still erred. When Gautama returned and saw the truth, his curse fell hard: Ahalya would become stone, invisible to the world, until Rama’s feet touched the ashram ground.\\n\\nAges passed. Seasons walked over her silence — rain, heat, the long green returning of forests. Ahalya waited as living stillness, neither fully punished nor free, a story paused mid-breath inside the shape of rock. When Rama, walking the forest with Lakshmana and Vishwamitra, stepped upon that earth, the curse broke. Stone became woman. Dust fell away from her form like a long night ending. She bowed to Rama and was received again into the life of the ashram and her husband’s peace.\\n\\nThe Ramayana places this restoration early in Rama’s journey, as if to say: the path of the righteous is also a path of release. Severity froze her; compassion completed what punishment alone could not heal.","moral":"Compassion can release what severity alone cannot heal.","lessonSummary":"Mercy restores; rigid punishment without grace leaves life unfinished.","style":"ajanta-fresco"},"sudama-krishna":{"title":"Sudama’s Handful of Rice","story":"Sudama and Krishna had been students together when the world was still soft with youth. Years later Sudama lived in deep poverty with his wife, while Krishna ruled in splendor at Dwarka — one life bare as a bone, the other bright as a festival. Sudama’s wife urged him to visit his old friend — not to beg, she said, but because Krishna’s heart was large. She tied a small bundle of beaten rice, the only offering they could spare, into a cloth for him to take.\\n\\nSudama walked to Dwarka ashamed of the gift’s size. Palace walls rose like judgment. Guards might have turned him away, but Krishna saw him, ran to embrace him, washed his feet, and seated him with honor. When Krishna asked what he had brought, Sudama hesitated. Krishna snatched the little bundle with delight and ate the rice as if it were a feast of the gods, as if love itself had flavor.\\n\\nSudama could not bring himself to ask for wealth. He left with his heart full and his hands empty — yet when he reached home, his hut had become a mansion, his storehouses full. He understood: friendship had weighed the heart, not the parcel. The sincere offering had mattered more than display. Prosperity, in this tale, follows love that does not meter gifts by size.","moral":"Sincere offering matters more than display; friendship does not meter wealth.","lessonSummary":"Give what you have with an open heart — love measures intention, not size.","style":"warli-ornate"},"bhagiratha-ganga":{"title":"Bhagiratha Brings the Ganga","story":"King Sagara’s sixty thousand sons were burned to ash by the sage Kapila’s wrath when they accused him of stealing a sacrificial horse. Their souls could not rise to peace without the touch of sacred water. Generation after generation tried and failed to bring that water from heaven. Then Bhagiratha was born — a prince who made their liberation his life’s vow, as if his spine were a ladder meant for rivers.\\n\\nHe practiced fierce tapas for years until Brahma granted that the Ganga might descend. But the river’s fall from heaven would shatter the earth. Bhagiratha prayed again, this time to Shiva. Shiva agreed to catch Ganga in his matted locks, tangling her force into gentleness, and release her in streams the land could bear.\\n\\nGanga fell — a white roar of sky becoming water. Shiva received her. Bhagiratha drove his chariot ahead, and the river followed him across the plains to the sea and to the ashes of his ancestors. Where her waters touched them, they were freed. The Ganga is still called Bhagirathi in his honor — perseverance carving a river of grace, and wise containment keeping heaven’s power from becoming mere destruction.","moral":"Patient austerity and wise containment can bring heaven’s help to earth without destroying it.","lessonSummary":"Persist in purification; channel powerful forces carefully so they heal rather than overwhelm.","style":"himalayan-thangka"},"harishchandra":{"title":"Harishchandra’s Truth","story":"Harishchandra was a king whose word was absolute — a vow made of iron and light. The sage Vishwamitra, testing him, demanded the gift of his entire kingdom — and Harishchandra gave it. Then the sage demanded the ritual fee that sealed such a gift. Having nothing left, the king sold himself, his wife Shaivya, and their son Rohitashva into servitude to raise the sum.\\n\\nHe became a worker at a cremation ground, taking the cloak of the dead as his wage, living among smoke and ash and the long honesty of endings. His wife served in another household. When their child died of a snakebite, she brought the body to the burning ground — too poor for the fee. Harishchandra, bound by his master’s rule, refused to cremate his own son without payment. Shaivya offered half her sari. In that extremity the gods revealed the test. Vishwamitra and Dharma restored the boy’s life, the kingdom, and the family’s honor.\\n\\nHarishchandra had kept his word when it cost crown, family comfort, and freedom. Truth had been his only remaining kingdom — and in the end it was enough to restore the rest. Integrity may strip every comfort and still remain the one possession worth keeping.","moral":"Integrity may strip every comfort and still remain the one possession worth keeping.","lessonSummary":"Keep your word when it costs; character outranks status.","style":"shadow-puppet"},"vibhishana-choice":{"title":"Vibhishana’s Choice","story":"Vibhishana was Ravana’s brother, a rakshasa who loved dharma more than the glitter of Lanka. Golden towers could not buy his silence; jeweled courts could not make wrong look fair. When Ravana stole Sita and refused every counsel to return her, Vibhishana spoke in the assembly with dangerous honesty. He warned that Rama was no ordinary prince, that wrong piled on wrong would burn the golden city from within. Ravana insulted him, accused him of cowardice and betrayal, and finally drove him out into the wide, cold choice of exile — sea wind on his face, brotherhood behind him like a closed door.\\n\\nVibhishana flew across the water and sought refuge in Rama’s camp. Some of Rama’s allies distrusted a brother of the enemy — blood as evidence, they thought, suspicion as prudence. Rama welcomed him, judging the man by his choice, not only by his lineage. Vibhishana was crowned in exile as a righteous claimant to Lanka and shared knowledge of the city’s defenses that helped free Sita.\\n\\nAfter Ravana’s fall, Vibhishana ruled Lanka with a different spirit. His story is the hard hinge of loyalty: when kin demand injustice, conscience may require leaving what is familiar — even if you walk alone at first toward what is right.","moral":"Loyalty to what is right may require leaving what is familiar.","lessonSummary":"When kin demand injustice, choose conscience — even if you walk alone at first.","style":"deccani"},"dhruva-pole":{"title":"Dhruva the Pole Star","story":"King Uttanapada had two wives. The favored one sat with him while her son played in his lap, warm and claimed. When little Dhruva, son of the less-favored Suniti, tried to climb up as well, the stepmother pushed him away. “You were not born of me,” she said. “You have no place here.” The boy ran weeping to his mother. Suniti could offer no courtly revenge — only a harder path. “If you want a seat that cannot be taken,” she told him, “seek Vishnu through devotion.”\\n\\nDhruva left the palace for the forest. Narada met him and taught him a mantra and the discipline of meditation. The child sat unmoving through hunger, weather, and fear, a small figure under a vast sky learning stillness the way others learn swordplay. His focus grew so steady that the worlds themselves seemed to tremble. Vishnu appeared, lifted him with grace, and granted a place that would not be shaken: Dhruva would shine as the pole star — the still point around which the sky turns — for an age beyond ordinary lifetimes.\\n\\nThe wound of rejection became a landmark for others. Steady practice had turned hurt into guidance; constancy became a light navigators could trust.","moral":"Steady practice turns wound into guidance; constancy becomes a landmark.","lessonSummary":"Channel hurt into disciplined seeking — steadfastness can light the way for others.","style":"contemporary-folk"},"kannappa-eye":{"title":"Kannappa’s Offering","story":"In the forests near Kalahasti lived a hunter later called Kannappa. Leaf-shadow moved over his path; birds warned and fell silent. He knew little of priestly ritual — no polished chants, no careful codes of purity. When he found a Shiva linga under the trees, he worshipped in the only way his heart knew: he poured water from his mouth, offered flowers stuck in his hair, and laid before the linga the meat of his hunt. Brahmins who saw this were scandalized. Shiva received the love beneath the rough form.\\n\\nOne day Kannappa saw blood streaming from one eye of the linga — red against stone, wrong against the quiet green. He tried herbs and water; the bleeding would not stop. In anguish he tore out his own eye and set it upon the stone. The bleeding ceased — then the other eye of the linga began to bleed. Kannappa placed his foot gently on the linga to mark the place and raised his hands to give his remaining eye, a devotion so fierce it looked like madness to anyone measuring manners.\\n\\nBefore he could, Shiva appeared and caught his hands, restored his sight, and embraced him. The hunter’s fierce sincerity outweighed polished etiquette. The measure of worship, the story says, is the heart that will give everything — not the manners that impress the watching world.","moral":"The measure of worship is sincerity, not polish of ritual form.","lessonSummary":"Bring your whole heart, not perfect manners — earnest love outweighs etiquette.","style":"chola-bronze-study"},"samudra-lakshmi":{"title":"Lakshmi Rising","story":"When gods and asuras churned the cosmic ocean for the nectar of immortality, the deep answered with more than one gift. First came terrors and wonders in turn — poison, treasures, living miracles climbing from foam and night. Among them, from light and water, came Lakshmi — radiant, lotus-born, clothed in grace as if grace itself had taken a body and learned how to smile upon a trembling world.\\n\\nThe gods gazed in wonder. Waves still shuddered from the churning; spray glittered like scattered stars. Lakshmi looked upon the assembly and chose Vishnu as her eternal home, garlanding him and taking her place at his side. Where Vishnu preserves the world, Lakshmi’s presence means abundance that is not mere hoarding — wealth joined to balance, generosity, and the upkeep of life. Prosperity with a conscience. Beauty with responsibility.\\n\\nThe Puranas remember that prosperity wanders from those who treat her as loot and settles where she is honored with care. She rose from shared struggle, not from a single hand’s greed. True abundance, the story suggests, dwells where preservation and generous order are kept — not where grasping alone stirs the waters.","moral":"True abundance settles where care, balance, and right relationship are kept.","lessonSummary":"Invite prosperity by cultivating steadiness and generosity, not by grasping alone.","style":"orchid-batik"}}`),l={"breath-dirga":{"in-belly":{say:`Inhale into the belly.`},"in-ribs":{say:`Ribs widen to the sides.`},"in-chest":{say:`Soft into the upper chest.`},"out-chest":{say:`Exhale from the chest.`},"out-ribs":{say:`Ribs soften.`},"out-belly":{say:`Belly settles.`}},"breath-belly":{in:{say:`Inhale — soft belly rises.`},out:{say:`Exhale — belly falls.`}},"breath-ujjayi":{in:{say:`Inhale with a soft ocean sound.`},out:{say:`Exhale — quiet ocean sound.`}},"breath-sama-vritti":{in:{say:`Inhale for six.`},"hold-top":{say:`Soft pause.`},out:{say:`Exhale for six.`},"hold-bottom":{say:`Soft pause.`}},"breath-bhramari":{in:{say:`Inhale quietly through the nose.`},out:{say:`Exhale with a soft humming mmm.`}},"breath-sheetali":{in:{say:`Cool inhale through the tongue or teeth.`},out:{say:`Exhale through the nose.`}},"breath-nadi-shodhana":{"in-left":{say:`Close right nostril — inhale left.`},"out-right":{say:`Close left — exhale right.`},"in-right":{say:`Inhale right.`},"out-left":{say:`Exhale left.`}},"breath-kapalabhati":{ready:{say:`Gentle pumps — sharp soft exhales. Stop if dizzy.`},p05:{say:`Pump.`},p10:{say:`Pump.`},p15:{say:`Pump.`},rest:{say:`Rest — breathe normally.`}},"breath-bhastrika":{ready:{say:`Bellows breath — forceful inhale and exhale. Stop if dizzy.`},b01:{say:`In and out.`},b05:{say:`In and out.`},b10:{say:`In and out.`},rest:{say:`Rest — breathe normally.`}},"breath-kumbhaka":{in:{say:`Inhale gently.`},hold:{say:`Soft hold — never strain.`},out:{say:`Exhale fully.`},rest:{say:`Brief rest.`}}},u=JSON.parse(`{"pose-name-is-not-the-pose":{"title":"The pose name is not the pose","summary":"A Sanskrit or English label is a map pin, not the territory — your body still has to negotiate today’s joints, breath, and mood.","body":["The first time I heard “Utthita Trikonasana,” I thought I had failed a language quiz. Then someone said “Triangle,” and I thought I had failed geometry. The shape on the mat was neither a triangle nor a password. It was a set of relationships: feet to floor, hand to shin or block, ribs to pelvis, gaze somewhere that did not yank the neck.","Pose names are useful the way street names are useful. They help teachers cue a room, help apps list a library, and help you find the same entry next week. They are terrible as scoreboards. “I did Warrior II” does not mean your front knee tracked over the ankle, or that your back foot grounded, or that your breath stayed conversational. It means you occupied a region of space that the tradition and your app agree to call by that name.","Home practice makes this sharper. In a studio, a teacher can see the difference between the name and the pose. Alone with a silhouette and a timer, it is easy to chase the label — deeper fold, higher leg, longer hold — because the word feels unfinished until the picture matches Instagram. Soften that habit. Ask smaller questions: Can I leave with control? Is the breath still a full sentence? Did the jaw unclench when I stopped trying to look impressive?","Sanskrit and English both carry poetry and history. They do not carry your MRI. Two people in “the same” Down Dog can be loading wrists, hamstrings, and shoulders completely differently. Intensity numbers and Avoid notes in a library exist because the name alone cannot keep you safe. Treat the name as a starting point for inquiry, then practice the inquiry.","When a name intimidates you — especially advanced Sanskrit compounds — remember that many classical names describe an animal, a sage, or a tool. They were mnemonic, not medical. You are allowed to use the English, the Sanskrit, or “that lunge with the arms.” Clarity beats purity. What matters is returning tomorrow without bracing against fear.","Names also shape how we filter a library. Search for “dog” and you find a family; search for a Sanskrit compound you half-remember and you may miss the English entry you actually need. That is another reason the name is not the pose: discovery depends on aliases, not on purity. Good catalogs list both, plus cues that talk about load. Your job is to use the label to arrive, then practice the relationships the label cannot fully describe — feet, breath, exit, and tomorrow’s willingness to return."]},"classical-animal-asana-names":{"title":"Why classical animal asana names help beginners","summary":"Dog, crow, camel, and pigeon give beginners a picture; intermediates can get stuck performing the mascot instead of the mechanics.","body":["Beginners often brighten when a teacher says Downward-Facing Dog. An animal is a story. A story is easier to remember than a list of joint angles. Crow suggests a perched bird; Camel suggests a lifted chest; Pigeon suggests a folded leg and a long spine. Classical yoga used these nicknames as teaching shortcuts long before apps needed slug-friendly English titles.","That gift has a shadow. Once you know the mascot, you may start acting it out. Crow becomes a scramble to hop both feet off the floor before the shoulders have learned to stack. Camel becomes a neck hang because “camels look up.” Pigeon becomes a hip dump because the bird on the poster looked dramatic. The animal name invited you in; the animal fantasy can take you past your current capacity.","Intermediates get confused in a second way: they assume the English animal maps one-to-one with a single “correct” shape. Lineages disagree about hand placement in dog, about how much external rotation belongs in pigeon, about whether crow and crane are cousins or rivals. The catalog name is a family address, not a court verdict. Your job is to feel the family traits — weight in the hands, length in the spine, honesty in the breath — not to win a costume contest.","Use animal names as on-ramps, then graduate to cues that talk about load. Where is the weight? What softens? What stays strong? If a playful book renames a classic (“Eagle Perch,” “Hang Time”), enjoy the creativity, then ask which traditional shape it is pointing at. The nickname is still a map pin.","And keep the distinction clear in your own mind: classical animal *asanas* are yoga shapes with long teaching histories. They are not a separate locomotion sport. On the mat, let the dog, crow, and camel remain invitations to organize bones and breath — not characters you must perform.","If you teach or self-cue, try a two-step habit: say the animal once for memory, then replace it with one mechanical cue for the next three breaths. “Crow — shift weight into the hands.” “Camel — lift the chest without dumping the neck.” “Dog — press the floor away and soften the knees if the spine rounds hard.” Beginners keep the story. Intermediates keep the story and add the physics. That is how a nickname stays useful instead of becoming a costume."]},"soft-belly-soft-jaw":{"title":"Soft belly, soft jaw","summary":"Before you deepen anything, check whether the belly and jaw are still negotiating with the pose — or bracing against it.","body":["I used to collect dramatic cues. “Root down to rise.” “Breathe into the back body.” They sound wise in a playlist. The cue that changed my practice was almost rude in its simplicity: soften the belly, soften the jaw.","A gripped jaw is rarely about the mouth. It is a whole-system tell. When the bite sets, the breath often climbs into the upper chest, the eyes harden, and the pose becomes a argument you are determined to win. Softening the jaw does not mean going limp. It means unhooking the face so the neck can stop doing overtime and the ribs can move again.","A soft belly is equally misunderstood. People hear “soft” and think “weak core” or “give up the pose.” In many standing and seated shapes, a soft belly means the diaphragm can descend. You can still engage the deep support that keeps the lumbar from dumping; you simply stop armored bracing that turns every hold into a plank competition. In restorative work, soft belly is half the point. In strength work, it is the difference between organized effort and panic gripping.","Try it as a mid-pose audit. Pause the ambition to go deeper. Unclench the teeth. Let the tongue rest. Feel whether the lower belly can receive a little breath without collapsing the posture. If the pose falls apart when you do this, the intensity was riding on bracing, not on skill. That is useful information. Exit, rest, return shorter.","I teach this cue early because it scales. It works in Warrior II, in forward folds, in balances, in savasana. Apps can announce inhale and exhale; they cannot feel your molars. You can. Make soft belly and soft jaw the metronome underneath every other instruction. Depth that arrives after the face softens tends to be depth you can keep.","You can practice the cue off the mat too. At a desk, before a hard email, unclench the teeth and feel whether the belly can move. The same pattern shows up in poses that scare you. Fear grips the face first. If you only chase foot placement while the jaw is iron, you are training bracing. Make the soft-face check as automatic as looking at your front knee in a lunge. Over weeks, the cue becomes less of a reminder and more of a baseline — which is when depth starts arriving without a fight."]},"week-of-only-forward-folds":{"title":"A week of only forward folds","summary":"Limiting the menu to folds taught me more about hamstrings, breath, and ego than another month of peak-pose chasing.","body":["I once spent a week practicing almost nothing but forward folds — standing, seated, wide-legged, supported with a chair or strap. No arm balances. No dramatic backbends. It sounded like a demotion. It felt like a microscope.","Forward folds expose the difference between stretch and negotiation. On Monday my hamstrings bargained loudly. By Wednesday the bargain moved into the low back whenever I collapsed the chest to “get deeper.” By Friday I had learned to hinge from the hips, keep a long spine for part of the fold, and only round when the belly could stay soft. The pose names stayed the same. The quality did not.","Breath became unavoidable. In folds it is easy to hold the breath as if apnea were a stretch technique. I used soft, slightly longer exhales and shorter holds when the breath frayed. Some days I barely folded at all — hands to blocks, knees bent, forehead on a stacked blanket. Those days still counted. The week was about relationship, not range.","Ego hated the experiment. Forward folds do not photograph like a handstand. Friends asked what I was “working on.” I said hamstrings and honesty. The quieter win was nervous-system literacy: folds can settle when you stop yanking, and they can irritate when you chase a forehead-to-shin fantasy. Matching the fold to the day’s tissue was the real curriculum.","If you try a constrained week, pick a family of shapes, keep intensity modest, and write one sentence after each session about sensation and mood. You will learn sequencing from the inside — what needs a counterpose, when a walk helps more than another Uttanasana, when to stop. Variety is wonderful. So is depth that only arrives when the menu gets small.","A constrained week also clarifies sequencing tools you already own. After a heavy fold day, a short walk or gentle back extension felt better than another stretch contest. Mild strength — bridges, standing thigh work — made the next day’s fold feel less fragile. That is the same logic Learn articles use for stimulate versus settle, applied to one pose family. You do not need a monastery retreat. You need a small menu and honest notes. Try it once; keep what teaches you; return to variety when curiosity, not guilt, asks for it."]},"warrior-ii-feet":{"title":"Warrior II feet","summary":"Warrior II got easier when I stopped performing the arms and started listening to how the feet shared the floor.","body":["For years my Warrior II looked busy on top and vague underneath. Arms reached. Gaze flared. The front knee wobbled wherever ambition sent it. Teachers said “strong legs,” and I squeezed everything. What I wish I had heard earlier: the pose is a conversation between two feet and a pelvis that can stay relatively level.","The front foot points roughly down the mat; the knee tracks toward the middle toes without collapsing inward. That tracking is more important than how deep the lunge looks. The back foot angles according to your hip structure and the lineage you are visiting — what matters is that the outer edge and heel participate so the back leg is not a decorative stick. When the back foot goes mute, the front knee and low back often pay the bill.","I also wish someone had told me that “square the hips to the long side of the mat” is a direction, not a threat. Some bodies open more easily than others. Forcing a textbook pelvis can irritate SI joints and groins. Find a version where you can breathe, keep the front knee honest, and still feel both feet. Blocks are not required in Warrior II, but a shorter stance is a legitimate prop made of space.","Arms are the last chapter, not the first. Once the feet organize, the torso can rise without leaning into the front thigh, and the arms can float to shoulder height without hiking the shoulders into the ears. Soften the jaw. Check the breath. Then, if you want, deepen an inch.","In an app library, Warrior II often carries a moderate intensity and familiar English name. That familiarity is dangerous; it invites autopilot. Pause on the feet every time you meet the pose. The warriors in the stories stood their ground. Your ground is the mat under two honest feet.","One more foot detail I wish I had practiced earlier: the front heel and back heel do not need to live on a rigid “heel-to-arch” dogma if your hips disagree. Lineages argue; bodies differ. What travels well is shared pressure and a pelvis that is not yanked into a photograph. Film yourself from the front for one breath. If the front knee dives inward while the arms look heroic, fix the foot and thigh first. Warrior II becomes kinder when the foundation gets the attention the arms used to steal."]},"savasana-sabotage":{"title":"Savasana sabotage","summary":"The hardest part of corpse pose is rarely the lying down — it is letting the session end without stealing the quiet back.","body":["Savasana looks like nothing. That is why we sabotage it. The phone waits face-up beside the mat “just for the timer.” The clock on the wall becomes a second job. Pride rehearses what we will tell someone we practiced. The body is horizontal; the mind is already in the hallway.","I have shortened savasana to ninety seconds because I felt busy. I have also stretched it while scrolling under the blanket, which is not rest — it is horizontal distraction. Real sabotage is subtler: keeping the jaw clenched, planning tomorrow’s workout, grading the class you just taught yourself. Corpse pose asks for a different skill than Warrior. It asks you to stop improving for a few minutes.","Practical un-sabotage is boring and effective. Put the phone in another room or face-down on airplane mode. Choose a hold long enough that you cannot treat it as a blink. Cover the eyes. Soften the belly. If announce-breath cues help you arrive, use them; if they keep you task-oriented, turn them off for this pose only. Leaving early because the hip complains is wisdom. Leaving early because silence feels awkward is a habit worth noticing.","Pride sabotages by demanding a peak pose before rest is “earned.” Rest is part of the training load, not a dessert. Nervous systems adapt to downshifts the way muscles adapt to load. Skip the downshift often enough and your “strong” practice starts to feel brittle.","When savasana ends, roll to the side before you sit. Give the blood pressure a moment. Thank the part of you that wanted to bolt. Then meet the day. The pose name means corpse. The practice means you briefly stopped arguing with life. That is harder than it looks — which is why it matters.","Teachers sometimes rush savasana because class ran long. Home practitioners rush it because life is loud. Build a personal minimum — even three quiet minutes — and protect it the way you protect a peak pose you care about. If you teach yourself with an app timer, put savasana in the sequence on purpose rather than “if there is time.” There is rarely leftover time. Rest that is scheduled is rest that happens. That single habit undoes more sabotage than any scented candle."]},"teaching-yourself":{"title":"Teaching yourself without becoming your worst student","summary":"Self-practice needs a kind teacher voice — the same one you would offer a nervous beginner, not the coach that lives in your critic.","body":["At home you are both teacher and student. That dual role is powerful and dangerous. The teacher plans the sequence, sets the timer, chooses difficulty. The student feels knees, breath, and mood. Trouble starts when the teacher voice turns into the worst student you ever met: sarcastic, impatient, convinced that modifications are moral failures.","I notice the takeover in language. “You should be able to…” “Everyone online can…” “Only five more breaths, don’t be weak.” Those lines would get a studio teacher fired. They somehow feel motivational when you whisper them to yourself. They are not motivational. They are fear wearing workout clothes.","A kinder self-teacher uses the same tools a good app and a good human share: clear structure, adjustable intensity, permission to rest, and curiosity instead of verdicts. Preview the sequence before you press play. Cap peak poses when sleep was short. Read Avoid notes as care, not as insults. If the breath breaks, exit — that is the teacher succeeding, not the student failing.","It also helps to separate planning time from practice time. Build the routine when you are calm. Practice when you are in the body. Mid-pose is a bad moment to redesign your identity. Keep a short list of “always allowed” exits: child’s pose, legs up, seated breath, stopping the session. Write them down if your critic is loud.","Community and occasional in-person feedback still matter. An app cannot see your collapsing knee. Self-teaching is a craft you refine, not a vow of isolation. Be the teacher who would make a beginner feel safe. Then be willing to be that beginner on the hard days. Progress follows respect more reliably than it follows shame.","A simple structure helps the dual role. Opening: breath and easy mobility. Middle: one or two focuses, not ten. Closing: something that settles. Write the focus in one sentence before you start — “steady warriors, kind knees” — and refuse to add a surprise handstand mid-session because a video tempted you. The worst student loves surprises that inflate identity. The good teacher loves a plan that matches today’s capacity. You can revise the plan tomorrow. Mid-pose is for sensing, not for rewriting your personality."]},"stretch-vs-strain-hamstrings":{"title":"Stretch vs strain in hamstrings","summary":"Warm, workable length is stretch; sharp, breath-holding insistence is strain — and forward folds will teach you the difference if you listen.","body":["Hamstrings are ambitious tissues. They also complain in a vocabulary people misread as inspiration. A stretch often feels like warm lengthening, sometimes with mild intensity that eases as you breathe. Strain tends to feel sharp, electric, or panic-inducing. The breath shortens. The jaw sets. You start bargaining with the timer.","Forward folds and hand-to-big-toe variations make this vivid. Rounding the spine to chase the toes can dump load into the low back while the hamstrings barely participate. Bending the knees, elevating the hands on blocks, or using a strap can actually increase hamstring honesty because the pelvis can tip forward without a lumbar emergency. Depth that requires apnea is usually strain wearing a Sanskrit name.","Time under tension matters. Yin-style long holds can be wonderful when sensation stays conversational and you support the shape. They become risky when you use minutes as a dare. Strength work matters too: eccentric control and standing strength help hamstrings tolerate length. Flexibility without capacity is a brittle plan.","Red flags deserve exit, not pep talks: shooting pain, numbness that intensifies, a “ping,” or pain that makes you unable to leave with control. Mild next-day soreness can be ordinary. Sharp joint or nerve-like symptoms are not a badge. This is practice guidance, not diagnosis — persistent issues belong with a qualified clinician.","In a pose library, read Modify notes before you treat the silhouette as a contract. Soften the belly. Keep a little bend in the knees until hinge mechanics are clear. Prefer repeats you could do tomorrow. Stretch is relationship. Strain is an argument you are trying to win on a deadline.","Warm-ups change the conversation. Cold, aggressive folds are where strain loves to dress up as dedication. Spend a few minutes moving the hips and bending the knees before you ask for length. Strength before stretch on some days — sit-to-stands, gentle bridges — can make the same fold feel clearer. If you use long holds, keep a slight exit strategy: hands that can walk up, knees that can bend, a block already in reach. Listening is easier when the pose is not a trap. Keep a training log of what intensity felt workable; patterns beat single dramatic sessions."]},"cat-cow-isnt-a-throwaway":{"title":"Cat-cow isn’t a throwaway","summary":"The warm-up everyone rushes is a laboratory for spine articulation, breath pairing, and the day’s honest range.","body":["Cat-cow sits at the start of so many classes that it becomes wallpaper. People wave the spine around while planning the “real” poses. I used to do the same. Then a week of cranky lumbar taught me that the throwaway was the curriculum.","Cat-cow is where you learn whether today’s spine wants big waves or small ones. It is where inhale and exhale can map to flexion and extension without drama. It is where wrists report for duty before plank asks for a full shift. Rushing it is like skipping the first page of a contract.","Quality markers are simple. Move segment by segment when you can — tailbone, low back, mid-back, upper back — instead of hinging only at one noisy joint. Keep the belly soft enough to breathe. Let the neck participate without yanking. If wrists complain, take fists, forearms, or a seated version. The shape family matters more than the Instagram twin.","Teachers use cat-cow diagnostically even when they do not say so. Asymmetry, breath holding, and grimacing show up early. Home practitioners can steal that habit. Two slow rounds with attention beat ten decorative ones. If one direction feels great and the other feels sharp, do not force symmetry theater. Stay where sensation is workable and skip what is not.","Link the warm-up to what follows. A backbending day might linger on the cow side with support. A forward-fold day might emphasize rounded cat with bent knees. A restorative day might make the whole thing tiny. Cat-cow is not a throwaway. It is the spine’s chance to vote before you cast a harder ballot.","If you only have five minutes, cat-cow plus breath may be the whole practice — and that still counts. Pair it with a soft belly and a jaw check. Notice whether one side of the back feels quieter. You are not trying to invent a medical diagnosis; you are collecting today’s weather report before you ask the spine for harder work. Throwaway warm-ups become throwaway attention. Keep the attention and the warm-up starts earning its place at the top of every tired-day sequence. Treat those first rounds as sacred minutes, not leftover seconds before the “real” class begins.","On travel days, when a full sequence will not happen, I still do cat-cow on a hotel towel. It keeps the relationship with my spine alive without demanding a performance. That alone convinced me the pose was never filler."]},"cloud-hands-taught-me":{"title":"When cloud hands taught me more than a power class","summary":"Slow tai chi arm circles recalibrated my nervous system in a way another sweaty peak sequence could not.","body":["I came to cloud hands suspicious. I liked heat, playlists, and the feeling of having “earned” rest. A simple tai chi pattern — shifting weight side to side while the arms brushed soft circles — looked like waiting room choreography. Then I tried practicing it when I was too wired for another power class and too restless for pure savasana.","Cloud hands refused my usual metrics. There was no deeper. There was only smoother. Weight transferred through the feet. The gaze softened. The arms moved as if through water. Whenever I rushed, the pattern got ugly in an honest way. Whenever I softened the jaw, the whole shape organized. It was feedback without humiliation.","What I learned was not that power classes are bad. It was that stimulation without a downshift makes my practice brittle. Held and slow shapes train a different kind of strength: the ability to stay continuous, to feel the sole of the foot, to let breath set the tempo instead of the ego. Yang-style sequences and simplified forms package that lesson in choreography you can repeat.","I started putting a few minutes of cloud hands or related held tai chi shapes before asana on anxious days, or after intense standing work when my nervous system needed a bridge to floor poses. The app’s discipline filters make that easy to browse without pretending tai chi is “just gentle yoga.” Different pacing, different intent, same body learning attention.","If your habit is to solve every mood with more heat, try one slow pattern and treat boredom as data. Sometimes the class that teaches you most is the one that refuses to impress you.","You do not need a full form to borrow the lesson. Two minutes of slow weight shifts and soft arm arcs can sit between a standing series and floor work like a palate cleanser. Keep the shoulders low. Let the eyes rest on a gentle horizon. If you get bored, that boredom is often the mind asking for a louder stimulus — which is useful data on tired or anxious days. Choose the quieter stimulus on purpose sometimes. Power classes will still be there when you want heat. Cloud hands taught me to want range in my nervous system, not only range in my hamstrings."]},"props-are-not-cheating":{"title":"Props are not cheating","summary":"Blocks, straps, chairs, and blankets are load-management tools — using them is skill, not a lesser badge of practice.","body":["Somewhere along the way, props got a reputation problem. “I should be able to do it without.” That sentence has ruined more shoulders and low backs than any block ever did. A prop is not a participation trophy. It is a way to change angles, shorten levers, and keep joints spacious while you build awareness.","Blocks under the hands in a fold often increase hamstring honesty. A strap in a bind protects the rotator cuff from ambition. A chair for warrior variations or seated work is still yoga — gravity did not leave the room. Blankets under knees or head turn restorative from endurance test into nervous-system training. The silhouette in a library is a suggestion. Your equipment is part of how you interpret it.","Iyanagar-influenced teaching normalized props in many studios; home practitioners sometimes feel embarrassed without an audience to impress. Flip the script. Choose the prop that lets breath stay continuous. If you can do the “full” shape but only by bracing and glaring, the propped version may be the more advanced choice today.","Apps that list Modify notes are inviting you to invent props from furniture: couch for legs up, wall for handstand prep, towel as a strap. Preview a pose, read Avoid, then set the room up before you press play. That is teaching yourself well.","Stop treating props as a phase you graduate from. Strong practitioners keep using them for recovery days, for tight seasons, for teaching clarity. Cheating would be ignoring pain to protect an identity. Using a block to keep the spine long is the opposite of cheating. It is craft.","If embarrassment shows up when you reach for a block, name it and use the block anyway. Embarrassment is a social reflex; tissue is not impressed. Teachers who normalize props in demos make whole rooms safer. Solo practitioners can normalize them privately by setting props out before press play, the way a cook sets out ingredients. When the timer starts, the decision is already kind. That is not a lesser practice. That is a prepared one. Over time, the embarrassment fades and only the better angles remain — which is the whole point of a tool."]},"courage-for-balance-at-home":{"title":"Building courage for balance poses at home","summary":"Home balances get braver when you shorten holds, use a wall without shame, and treat falling as information.","body":["Balance poses at home feel riskier than in a studio. There is no shared energy, no teacher to joke about wobbly ankles, and a coffee table with opinions. Courage here is not fearlessness. It is a plan for falling and a willingness to look unimpressive while the nervous system learns.","Start with time, not height. Three honest breaths in tree with a toe on the floor beat thirty seconds of panic hopping. Use the wall. Touch it lightly with fingertips, or stand close enough that a sway is recoverable. Near a wall is not “cheating.” It is how adults learn skills without collecting bruises for pride.","Gaze matters. Pick a still point that does not require cranking the neck. Soften the jaw. Keep a micro-bend in the standing knee if locking turns you into a rigid tower. Engage the standing foot’s contact with the floor — triad of big toe, little toe, heel — before you sculpt the arms into mythology.","Build a progression inside your library filters: ankle mobility and standing strength before long one-leg holds; supported warrior variations before full dancer. If a peak balance keeps scaring you, it may be sequenced too early in the session. Warm the feet. Wake the hips. Then ask for balance.","When you fall, step down with control if you can, laugh if you can, and reset without a speech about your character. Courage accumulates across repetitions that end safely. An app timer will not catch you. Your setup and your kindness will.","Strength elsewhere supports bravery in balances. Feet and calves that have worked in simple standing shapes wobble less when you lift a foot. Hips that have woken up in easy warriors offer a clearer center. Courage is partly conditioning. It is also environmental design: clear the coffee table, wear shoes if bare feet slip, practice when you are not already furious at the day. Bravery grows in conditions you arrange, not only in pep talks you recite while shaking. Repeat the same easy balance for a week before you add drama; boredom is often where balance actually arrives.","Finally, celebrate boring balance. Holding tree for five calm breaths near a wall is a win worth logging. Courage is often quiet competence repeated until the scare shrinks."]},"breath-before-depth":{"title":"Breath before depth","summary":"If the breath breaks, the pose is too intense for this moment — depth can wait; continuity cannot.","body":["I keep one stubborn rule on the mat: breath before depth. It has saved me from heroic mistakes more often than any alignment cue. When the inhale becomes a sip and the exhale a grunt, I am no longer practicing — I am negotiating with fear using range of motion as currency.","Depth is seductive because it is visible. Breath quality is quieter. People praise a deeper fold; almost nobody applauds a boring, continuous nose breath in a middle-of-the-road shape. Yet the nervous system tracks the breath relentlessly. Ragged breathing is a system-wide alert. Ignoring it to “get the pose” trains the opposite of yoga’s attention skills.","Practically, the rule means I exit or modify when I cannot speak in full sentences. I shorten holds. I bend knees. I take a block. I switch to a restorative sibling of the pose. I enable announce-breath cues when soft reminders keep me honest, and I turn them off when I need silence — but I never treat apnea as a technique for stretching further.","Linking breath to movement helps: inhale to lift or lengthen, exhale to fold or settle, steady breath in holds. Those pairings are maps, not dogma. What stays non-negotiable is continuity. Forced retention to push intensity belongs in the “not today” pile for most home practitioners, especially in twists, balances, and inversions.","Stubborn rules sound austere. This one is actually generous. It lets you return tomorrow. Depth that arrives after the breath settles tends to stay available. Depth stolen from a panicked nervous system tends to collect interest as irritation later. Choose the debt you want.","Share the rule with anyone you practice beside. It gives permission without drama: we leave when breath breaks. In self-practice, say it out loud once at the start of a hard pose. Hearing yourself set the boundary makes it easier to keep. Depth culture will keep selling you images. Your stubborn rule sells you longevity. Longevity is the only depth that compounds. Write the rule at the top of a custom routine name if you need a reminder when ambition gets loud.","I have left peak poses early in workshops because of this rule and never regretted it. The people who looked impressed with their depth were not living in my joints. My breath was. That is the only vote that counts in the moment."]},"quiet-strength-isometrics":{"title":"The quiet strength of isometric holds","summary":"Holding still is not passive — isometric effort builds capacity, teaches tremor honesty, and pairs beautifully with soft breath.","body":["Isometric work looks uneventful on camera. You are simply there: chair pose humming in the thighs, plank shaking, bridge hovering, a tai chi shape quietly organized. Under the skin, muscles produce force without a big concentric show. That quiet is a kind of strength training yoga already owns — we just forget to respect it when we chase flows.","Holds teach honesty. Tremor is information, not failure. Softening the jaw while the legs work is a skill. Matching a steady breath to a still shape trains the nervous system to stay present under load. Time under tension can build capacity for standing sequences and for daily life that asks you to wait without collapsing.","Not every hold should be long. Intensity and joint positions matter. A high plank for ten breaths may be plenty. A deep knee angle that irritates should be raised, padded, or skipped. Restorative “holds” are a different category — supported stillness for downshifting, not grit. Know which job you hired the pose to do.","In an app player, hold timers make isometrics explicit. Use that without turning every pose into a dare. Preview durations. Cap difficulty on tired days. Pair strength holds with counterposes and something that settles the system afterward. Quiet strength still needs recovery.","I love a sweaty flow. I also trust the sessions where I stayed in fewer shapes longer, listened to the shake, and left with legs that felt used rather than punished. Stillness is not the absence of training. It is training with the volume turned down so you can hear the details.","If you track practice, note holds differently from flows. “Three poses, long and steady” is a complete session entry. It resists the bias that only continuous movement counts. On days when joints want less travel, isometrics keep training available. Pair them with soft belly and soft jaw so effort does not become armor. Quiet strength should still look like a person who can breathe. End isometric days with something that settles so strength does not steal your sleep.","Try a mini protocol: two isometric stands, one short plank variation, one restorative close. No flow required. You will feel whether quiet strength was what your Tuesday needed all along."]},"stopped-chasing-deepest-pigeon":{"title":"Why I stopped chasing the deepest pigeon","summary":"Pigeon became useful again when I traded forehead-to-floor ambition for supported shapes, honest hips, and an exit plan.","body":["Pigeon was my ego’s favorite billboard. The poster version looked serene. My version looked like a negotiation with the front knee and a low back that kept volunteering for work the hip should have done. I chased depth because the name seemed to require drama: chest down, back leg straight, peaceful face performing peace.","What changed was not a miracle stretch session. It was permission to make pigeon boring. I started elevating the hip on a blanket. I kept the front shin more parallel only when the knee agreed. I used figure-four on the back as a sibling shape. I stopped treating the forehead-to-floor photo as the adult version.","Sensation literacy improved immediately. Warm outer-hip stretch with steady breath stayed. Sharp knee complaints ended the pose. Low-back pinching meant I was dumping instead of hinging and supporting. Sometimes the best pigeon was three breaths and a reset. Sometimes it was skipping pigeon for a reclined variation that taught the same family of sensations with less joint politics.","Counterposes and context mattered too. After pigeon, I needed gentle neutral spine and often a mild strength or walk, not another aggressive hip opener stacked for content. Intensity filters and Avoid notes exist because deep hip postures are not universal citizenship tests.","I still practice pigeon. I no longer chase the deepest one. The pose I can repeat tomorrow without bracing against fear is the advanced variation. Serenity that depends on tissue panic is just good lighting.","Teaching the pose to beginners later confirmed the lesson. Nobody needed my deepest pigeon. They needed options, props, and a way out. The student I had been finally got the class he required: less theater, more support, same hip story told at a volume the joint could hear. Keep the poster if you like it. Practice the version that keeps you curious instead of braced. If a photo still hooks you, practice the propped version beside it until your nervous system believes both are allowed.","Curiosity replaced conquest. I ask what the hip needs today, not what the photo demands. Some days the answer is figure-four. Some days it is a walk. Pigeon became one option among many, which is how a pose stays sustainable."]},"restorative-nervous-system":{"title":"Restorative is training for the nervous system","summary":"Supported stillness is not a consolation prize — it is deliberate practice for downshifting, recovery, and attention without performance.","body":["Restorative yoga gets marketed as “gentle,” which some people hear as “optional.” I hear something else: specific training for a nervous system that spends the week in notifications. Supported poses with blankets, bolsters, and time are not the absence of work. They are a different workload — one measured in letting go rather than producing shape.","In restorative practice, the props do the holding so your muscles can stop auditioning. Breath tends to soften. The mind may still race; that does not mean you failed. It means you are watching the race without chasing it down the street. Sessions can feel uneventful and still leave you more human afterward. Uneventful is often the point.","This is not the same as yin, though they can overlap in pace. Yin often stresses tissues with long holds in less supported shapes. Restorative prioritizes comfort and support for settling. Stretch for stretch’s sake is not the metric. If you are fidgeting to make the pose “do more,” you may have hired the wrong job.","Home restorative works best when you set up before you start: layers for warmth, eye cover, phone away, a timer that does not buzz like an alarm fire. Choose a few shapes and stay. Legs up a wall, supported bound angle, a gentle reclined twist with padding — simple menus beat ambitious sequences when the goal is downshift.","Stimulating practice has a place. So does deliberately practicing the off-switch. Athletes cross-train. Yogis can too — not with more heat every day, but with sessions that teach recovery as a skill. Restorative is training. Treat it with the same respect you give a hard standing series.","If “doing nothing” triggers guilt, schedule restorative like strength work: same days, same respect, same refusal to apologize. Put it on the calendar. Prepare the props. Let the session be short if needed, but protected. Guilt is often just stimulation culture talking. You are allowed to train the off-switch with the same seriousness you bring to a peak pose — because recovery is part of capacity, not a retreat from it. Measure success by how you speak afterward, not by how dramatic the shapes looked."]},"sanskrit-as-poetry":{"title":"Sanskrit as poetry, not password","summary":"Sanskrit pose names carry image and history — they are meant to open doors, not to gatekeep who belongs on the mat.","body":["Sanskrit in yoga class can feel like a velvet rope. If you know the words, you belong; if you stumble, you are a tourist. I prefer another frame: many names are compact poems. Adho Mukha Svanasana sketches a dog facing down. Tadasana evokes a mountain. Savasana names a corpse so you remember to stop performing. The language is older and richer than a quiz.","Poetry still needs translation for real rooms. Good teaching offers Sanskrit and clear English, then coaches the body. An app library that lists both serves curiosity without demanding fluency before you are allowed to bend your knees. Memorizing lists does not make anyone safer. Understanding that names are maps does.","There is also history to hold lightly. Some names honor sages or mythic figures; some describe tools or animals; modern branding sometimes invents English nicknames that sit beside classical ones. None of that obligates you to perform piety. Respect can look like learning a story behind a name you love. It can also look like using the English while you focus on not collapsing a knee.","Gatekeeping shows up when Sanskrit becomes a purity test, or when English-only cues are mocked. Both miss the point. The practice is what happens in attention and tissue. Language is a bridge. Bridges exist to be crossed in both directions.","If a name intimidates you, ask what image it offers, try saying it once without shame, and then practice the relationships the pose actually requires. Poetry invites. Passwords exclude. Choose the invitation.","When you meet a new name in the library, spend ten seconds on the image before you chase the silhouette. What does the word sketch? What English cousin sits beside it? Then put the poetry down and feel your feet. Language opens the door. Practice is what you do in the room. Keeping those jobs separate keeps Sanskrit beautiful instead of bureaucratic. Fluency can come later, or never; belonging on the mat does not require a linguistics degree.","If you love language, learn stories behind a few favorite names for joy. If you do not, you are still welcome. The mat does not check credentials at the door — only whether you can breathe and leave with control."]},"letter-to-stiff-beginner":{"title":"A letter to the stiff beginner I was","summary":"Stiffness was never a moral failure — it was a starting climate, and kindness would have gotten me further than forcing.","body":["Dear earlier me,","You thought tight hamstrings meant you were bad at yoga. You apologized to strangers for your heels not touching the floor. You skipped classes when you felt inflexible, which is like skipping meals because you are hungry. I need you to hear this sooner: stiffness is a climate, not a character flaw.","You do not need to earn props. You do not need to keep up with the person on the next mat who seems made of taffy. You need breath you can keep, a teacher voice that is not cruel, and repetitions you could repeat tomorrow. Bend your knees in forward folds. Put hands on blocks. Choose intensity as if you plan to still like yourself in the evening.","Also, stop treating every sensation as a problem to erase by Christmas. Strength and tissue capacity grow on a calendar that ignores your impatience. Some days the win is showing up for twenty minutes and leaving without self-hate. That win compounds.","You will love more athletic seasons later. You will also need restorative seasons, stiff seasons after travel, and humble seasons after arrogance. The beginner skill of modifying without shame is not something you outgrow. It is something you graduate into.","When you meet other stiff beginners, tell them the truth kindly. Show them the library filters and Avoid notes. Remind them that savasana counts. Remind them that “listen to your body” means something concrete: continuous breath, workable sensation, exits with control.","You were never behind. You were at the start. Stay there as long as honesty requires — and return there whenever pride gets loud.","With warmth, Someone who finally bent the knees","One more thing: stop comparing your day-one fold to someone else’s year-ten photo. Comparison steals the exact reps that would have helped you. Measure progress by kinder exits, steadier breath, and fewer apologies. Stiffness will visit again in other decades. When it does, reread this letter. You will need the same friendliness more than you need a new trick. And drink water. You would be amazed how often “stiff” was partly “dehydrated and mean to yourself.”","P.S. The flexible people you envied had other struggles you could not see. You only saw range. Range was never the whole path. Kindness was."]},"sequencing-tired-tuesday":{"title":"Sequencing for a tired Tuesday","summary":"A good tired-day sequence warms gently, skips the ego peak, and ends early enough that sleep still likes you.","body":["Tired Tuesdays expose whether your sequencing philosophy is real or decorative. Fresh Saturday-you wants peaks and playlists. Tired Tuesday-you needs a plan that respects sleep debt without turning into pure avoidance or pure grit.","I start with a shorter total time and a clear exit. Twenty to thirty minutes beats a heroic hour you will resent. Warm with cat-cow, easy breath, maybe a few half sun salutations if joints agree. Standing work stays moderate: short warriors, triangle with a block, no balance circus. Floor strength can be brief — a restrained bridge or dead bug beats a max plank contest.","Skip the identity peak. Handstands and deep backbends can wait for a less brittle day. If you crave a “something,” choose one skill at easy volume rather than five ambitions. Insert a counterpose mindset early: after folds, neutralize; after mild backbends, give the spine a soft opposite or rest. End with longer restorative or savasana than your pride prefers.","App tools help if you use them as care. Wizard intents that aim for calm or mobility beat “crush me.” Difficulty caps matter. Preview the run before play and delete the pose that is clearly yesterday’s ego. Announce-breath cues can keep you from rushing; turn them off if noise adds load.","Tired-day sequencing is not lower-class yoga. It is load management. Athletes recover on purpose. Your nervous system is not impressed by your streak calendar. Build the habit of matching the session to the weather, and Tuesday stops being a failure of motivation. It becomes a craft.","If you use community routines, duplicate and edit them for Tuesday instead of forcing a peak template. Delete the show-off poses. Lengthen the closer. Save the ambitious copy for a fresher day. Sequencing is curation. Tired Tuesdays are when curation becomes compassion. Compassion that still moves a little — that is a practice you can sustain for years. Tomorrow you can be ambitious again. Tonight, be sustainable.","Keep a saved “Tired Tuesday” routine so decision fatigue cannot push you into a peak template. When energy returns, open the ambitious copy. Sequencing tools exist so mood can choose wisely without inventing a plan from scratch every night. That is enough."]},"listen-to-your-body":{"title":"What listen to your body actually means","summary":"Listening is not mystical — it is a checklist of breath, sensation quality, exit control, and whether pride is writing the script.","body":["“Listen to your body” is the most printed and least specified cue in modern yoga. It can sound like a fortune cookie. On the mat it needs verbs. Listening means gathering signals and changing the plan when the signals say so — not waiting for a mystical telegram while you ignore a screaming knee.","Here is the checklist I actually use. Is the breath continuous enough that I could speak a sentence? Is sensation stretchy, warm, or muscly-tired rather than sharp, electric, or nauseating? Can I leave the pose with control, or am I trapped by pride and gravity? Did my jaw and face soften when I stopped performing? If three answers go sideways, I modify or stop. That is listening.","Listening also includes context outside the pose. Sleep, stress, hydration, and old injuries change the meaning of the same shape. A backbend that felt wise in March can be foolish after a week of moving boxes. Apps offer Avoid notes and intensity numbers because the silhouette cannot see your week. You can.","What listening is not: hypochondria that forbids all challenge, or spiritualized passivity that avoids strength forever. Capacity grows through workable stress plus recovery. The art is telling workable stress from strain. Learn articles on safety and effort exist to sharpen that art without pretending an app is your clinician.","When teachers say “honor your body,” translate it into actions: shorter hold, higher block, bent knee, different pose, earlier savasana, walking instead. Then notice how you talk to yourself after you choose care. If the critic starts a speech, that speech is also something to hear — and to decline. Listening includes the mind. It does not obey the mind’s worst student.","Make the checklist visible if you need to. A sticky note on a block works: breath, sensation, exit, jaw. Glance once mid-session. Listening becomes ordinary when it is concrete. Ordinary listening is what keeps “honor your body” from dissolving into posters. Your body is already speaking. The skill is answering with a change you can feel. Practice that answer enough times and “listen to your body” finally means something you can teach."]}}`),d={anatomy:{rectus_femoris:{name:`Rectus femoris`,group:`quads`},vastus_lateralis:{name:`Vastus lateralis`,group:`quads`},vastus_medialis:{name:`Vastus medialis`,group:`quads`},biceps_femoris:{name:`Biceps femoris`,group:`hamstrings`},medial_hamstrings:{name:`Semitendinosus and semimembranosus`,group:`hamstrings`},gluteus_maximus:{name:`Gluteus maximus`,group:`glutes`},gluteus_medius:{name:`Gluteus medius`,group:`outer_hips`},tensor_fasciae_latae:{name:`Tensor fasciae latae`,group:`outer_hips`},deep_hip_rotators:{name:`Piriformis and deep hip rotators`,group:`hip_rotators`},iliopsoas:{name:`Iliopsoas`,group:`hip_flexors`},adductors:{name:`Adductors`,group:`adductors`},gastrocnemius:{name:`Gastrocnemius`,group:`calves`},soleus:{name:`Soleus`,group:`calves`},tibialis_anterior:{name:`Tibialis anterior`,group:`shins`},fibularis:{name:`Fibularis (peroneals)`,group:`shins`},tibialis_posterior:{name:`Tibialis posterior`,group:`calves`},foot_intrinsics:{name:`Foot arch muscles`,group:`feet`},toe_extensors:{name:`Toe extensors`,group:`feet`},rectus_abdominis:{name:`Rectus abdominis`,group:`abdominals`},external_oblique:{name:`Obliques`,group:`obliques`},transversus_abdominis:{name:`Transversus abdominis`,group:`abdominals`},quadratus_lumborum:{name:`Quadratus lumborum`,group:`low_back`},erector_spinae:{name:`Erector spinae`,group:`spinal_extensors`},latissimus_dorsi:{name:`Latissimus dorsi`,group:`lats`},trapezius_upper:{name:`Upper trapezius`,group:`neck`},trapezius_middle:{name:`Middle trapezius`,group:`upper_back`},trapezius_lower:{name:`Lower trapezius`,group:`upper_back`},rhomboids:{name:`Rhomboids`,group:`upper_back`},infraspinatus:{name:`Rotator cuff (infraspinatus)`,group:`shoulders`},pectoralis_major:{name:`Pectoralis major`,group:`chest`},serratus_anterior:{name:`Serratus anterior`,group:`serratus`},deltoid_anterior:{name:`Front deltoid`,group:`shoulders`},deltoid_lateral:{name:`Side deltoid`,group:`shoulders`},deltoid_posterior:{name:`Rear deltoid`,group:`shoulders`},biceps_brachii:{name:`Biceps`,group:`arms`},triceps_brachii:{name:`Triceps`,group:`arms`},forearm_flexors:{name:`Forearm flexors`,group:`forearms`},forearm_extensors:{name:`Forearm extensors`,group:`forearms`},thenar:{name:`Thenar muscles`,group:`hands`},hand_intrinsics:{name:`Hand muscles`,group:`hands`},sternocleidomastoid:{name:`Sternocleidomastoid`,group:`neck`},diaphragm:{name:`Diaphragm`,group:`breath`},intercostals:{name:`Intercostals`,group:`breath`}}},f={poses:n,routines:r,learn:i,meditations:a,music:o,progressions:s,rewards:c,pranayama:l,blog:u,muscles:d};export{t as n,f as t};